#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_ADC_VALUE_MAX 1023
#define SPI_ADC_VALUE_MIN 0

void handle_spi_error(int error) {
    fprintf(stderr, "SPI error: %d\n", error);
    exit(EXIT_FAILURE);
}

void handle_sigint(int sig) {
    fprintf(stderr, "Received SIGINT, shutting down...\n");
    close_spi();
    exit(EXIT_SUCCESS);
}

void handle_sigterm(int sig) {
    fprintf(stderr, "Received SIGTERM, shutting down...\n");
    close_spi();
    exit(EXIT_SUCCESS);
}

void close_spi() {
    if (spi_opened) {
        spi_close();
        spi_opened = false;
    }
    pi_close();
}

