#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/ioctl.h>
#include <pigpio.h>

#define GPIO4 4
#define GPIO27 27
#define I2C_BUS 1
#define I2C_ADDR 0x48
#define ADC_CHANNEL 0
#define ADC_GAIN 4
#define ADC_SAMPLE_RATE 128
#define DEBOUNCE_TIME 50
#define BUZZER_ON_TIME 2000

#define LOG_FILE "fire_log.txt"

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
}

void log_event(const char *event, double temp) {
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        return;
    }
    fprintf(log, "%s %f\n", event, temp);
    fclose(log);
}

void log_error(const char *msg) {
    perror(msg);
}

void init_gpio() {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialization failed");
        return;
    }
    if (gpioSetMode(GPIO4, PI_INPUT) < 0) {
        log_error("GPIO4 mode set failed");
        return;
    }
    if (gpioSetPullUp(GPIO4, 1) < 0) {
        log_error("GPIO4 pull-up set failed");
        return;
    }
    if (gpioSetMode(GPIO27, PI_OUTPUT) < 0) {
        log_error("GPIO27 mode set failed");
        return;
    }
}

void init_adc() {
    if (gpioI2COpen(I2C_BUS, I2C_ADDR) < 0) {
        log_error("I2C open failed");
        return;
    }
    if (gpioI2CSetMode(I2C_BUS, I2C_ADDR, ADC_MODE) < 0) {
        log_error("I2C set mode failed");
        return;
    }
    if (gpioI2CSetChannel(I2C_BUS, I2C_ADDR, ADC_CHANNEL, ADC_GAIN, ADC_SAMPLE_RATE) < 0) {
        log_error("I2C set channel failed");
        return;
    }
    if (gpioI2CSetMode(I2C_BUS, I2C_ADDR, ADC_SINGLE_SHOT) < 0) {
        log_error("I2C set single-shot mode failed");
        return;
    }
}

void read_adc() {
    int16_t adc_value;
    if (gpioI2CReadSingle(ADC_CHANNEL, &adc_value) < 0) {
        log_error("ADC read failed");
        return;
    }
    double voltage = (adc_value * 3.3) / 4096.0;
    double temp = 20.0 + (voltage - 0.0) * (80.0 - 20.0) / (3.3 - 0.0);
    if (temp > 60.0) {
        log_event("Temperature above 60°C", temp);
    }
}

void handle_falling_edge() {
    static int last_event = 0;
    if (last_event == 0) {
        last_event = 1;
    } else if (last_event == 1) {
        if (gpioRead(GPIO4) == 0) {
            last_event = 0;
        }
    } else {
        if (gpioRead(GPIO4) == 1) {
            last_event = 1;
        }
    }
}

void main_loop() {
    while (running) {
        if (gpioRead(GPIO4) == 0) {
            handle_falling_edge();
        }
        if (running && last_event && gpioRead(GPIO4) == 1) {
            read_adc();
            if (temp > 60.0) {
                log_event("Fire detected!", temp);
                gpioWrite(GPIO27, 1);
                usleep(BUZZER_ON_TIME * 1000);
                gpioWrite(GPIO27, 0);
            } else {
                log_event("Flame detected!", temp);
            }
        }
        usleep(100000);
    }
    gpioTerminate();
}

int main() {
    signal(SIGINT, handle_sigint);
    init_gpio();
    init_adc();
    last_event = 0;
    while (1) {
        main_loop();
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <gpiod.h>
#include <gpiod/hwmon.h>
#include <gpiod/line.h>
#include <math.h>

#define SPI_CHANNEL 0
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_CMD 0x01
#define SPI_CS 0x80
#define SPI_DATA 0x00
#define ADC_CHANNEL 0
#define CURRENT_THRESHOLD 5.0
#define DEFAULT_SENSITIVITY 100
#define DEFAULT_FAN_PIN 18

#define FAN_PIN_NAME "gpiochip4:gpio18"

int spi_fd;
int fan_pin_fd;
int adc_fd;
int fan_pin;
int adc_chip;
int adc_line;
int current_threshold;
int sensitivity;

void init_spi() {
    spi_fd = open("/dev/spi0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }
    if (ioctl(spi_fd, SPI_SET_SPEED, SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
    if (ioctl(spi_fd, SPI_SET_MODE, SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
    if (ioctl(spi_fd, SPI_SET_CS, SPI_CS) < 0) {
        perror("Failed to set SPI CS");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

void init_gpio() {
    const char *gpio_name = FAN_PIN_NAME;
    int ret;
    gpio_device_t *gpio_device;
    gpio_line_t *gpio_line;
    gpio_request_one(gpio_name, GPIO_LINE, &gpio_device);
    if (gpio_device == NULL) {
        gpio_name = "gpiochip0:gpio18";
        gpio_request_one(gpio_name, GPIO_LINE, &gpio_device);
        if (gpio_device == NULL) {
            gpio_name = "gpiochip1:gpio18";
            gpio_request_one(gpio_name, GPIO_LINE, &gpio_device);
            if (gpio_device == NULL) {
                gpio_name = "gpiochip2:gpio18";
                gpio_request_one(gpio_name, GPIO_LINE, &gpio_device);
                if (gpio_device == NULL) {
                    gpio_name = "gpiochip3:gpio18";
                    gpio_request_one(gpio_name, GPIO_LINE, &gpio_device);
                    if (gpio_device == NULL) {
                        gpio_name = "gpiochip4:gpio18";
                        gpio_request_one(gpio_name, GPIO_LINE, &gpio_device);
                        if (gpio_device == NULL) {
                            gpio_name = "gpiochip0:gpio18";
                            gpio_request_one(gpio_name, GPIO_LINE, &gpio_device);
                        }
                    }
                }
            }
        }
    }
    if (gpio_device == NULL) {
        perror("Failed to request GPIO line");
        exit(EXIT_FAILURE);
    }
    ret = gpio_get_fd(gpio_device, &fan_pin_fd);
    if (ret < 0) {
        perror("Failed to get GPIO file descriptor");
        gpio_free_line(gpio_device, &gpio_line);
        exit(EXIT_FAILURE);
    }
    ret = gpio_get_chip(gpio_device, &adc_chip);
    if (ret < 0) {
        perror("Failed to get GPIO chip");
        gpio_free_line(gpio_device, &gpio_line);
        gpio_free_device(gpio_device);
        exit(EXIT_FAILURE);
    }
    ret = gpio_get_line(gpio_device, &adc_line);
    if (ret < 0) {
        perror("Failed to get GPIO line");
        gpio_free_line(gpio_device, &gpio_line);
        gpio_free_device(gpio_device);
        exit(EXIT_FAILURE);
    }
    fan_pin = gpio_get_number(gpio_device, &gpio_line);
    if (fan_pin < 0) {
        perror("Failed to get GPIO pin number");
        gpio_free_line(gpio_device, &gpio_line);
        gpio_free_device(gpio_device);
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    if (adc_fd > 0) {
        close(adc_fd);
    }
    if (fan_pin_fd > 0) {
        gpio_free_line(gpio_device, &gpio_line);
        gpio_free_device(gpio_device);
        close(fan_pin_fd);
    }
    if (spi_fd > 0) {
        close(spi_fd);
    }
}

int read_adc() {
    uint8_t rx[3];
    int ret;
    ret = ioctl(spi_fd, SPI_TRANSFER, (unsigned long)SPI_CMD | SPI_CS | SPI_DATA);
    if (ret < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    ret = read(spi_fd, rx, 3);
    if (ret < 0) {
        perror("Failed to read SPI data");
        return -1;
    }
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    if (adc_value == 0 || adc_value == 1023) {
        return -1;
    }
    return adc_value;
}

double convert_adc_to_current(int adc_value) {
    double voltage = (double)adc_value / 1024.0 * 3.3;
    return voltage / sensitivity;
}

void handle_current_threshold() {
    double current = convert_adc_to_current(read_adc());
    if (current > current_threshold) {
        int ret = gpio_set_value(fan_pin_fd, GPIO_LINE, GPIO_HIGH);
        if (ret < 0) {
            perror("Failed to set GPIO value");
        }
    } else {
        int ret = gpio_set_value(fan_pin_fd, GPIO_LINE, GPIO_LOW);
        if (ret < 0) {
            perror("Failed to set GPIO value");
        }
    }
}

void log_reading() {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[128];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, 128, "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s, %f A\n", buffer, convert_adc_to_current(read_adc()));
    FILE *log_file = fopen("current_log.txt", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s, %f A\n", buffer, convert_adc_to_current(read_adc()));
        fclose(log_file);
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s -t <threshold> -s <sensitivity>\n", argv[0]);
        return 1;
    }
    current_threshold = atof(argv[1]);
    sensitivity = atof(argv[2]);
    init_spi();
    init_gpio();
    while (1) {
        log_reading();
        handle_current_threshold();
        sleep(1);
    }
    cleanup();
    return 0;
}

