} ADCHandler;

void adc_init(ADCHandler *adc, int gain, int resolution, int sample_rate, int buffer_size) {
    adc->adc_gain = gain;
    adc->adc_resolution = resolution;
    adc->adc_sample_rate = sample_rate;
    adc->adc_buffer_size = buffer_size;
    adc->adc_buffer = mmap(NULL, adc->adc_buffer_size * sizeof(int), PROT_READ | PROT_WRITE, MAP_SHARED, adc->adc_fd, 0);
    adc->adc_buffer_size_bytes = adc->adc_buffer_size * sizeof(int);
    adc->adc_buffer_ptr = 0;
    adc->adc_buffer_full = 0;
    adc->adc_buffer_empty = 0;
    adc->adc_buffer_count = 0;
}

void adc_read(ADCHandler *adc, int channel) {
    int buf[1];
    int ret = ioctl(adc->adc_fd, I2C_RDWR, (unsigned char *)&buf, 1, I2C_SLAVE, adc->adc_addr);
    if (ret < 0) {
        fprintf(stderr, "ADC read failed: %d\n", ret);
        exit(EXIT_FAILURE);
    }
    int data = buf[0];
    int adc_value = (data & 0x3FF) << (adc->adc_resolution - 12);
    adc->adc_buffer[adc->adc_buffer_ptr] = adc_value;
    adc->adc_buffer_ptr = (adc->adc_buffer_ptr + 1) % adc->adc_buffer_size;
    if (adc->adc_buffer_ptr == 0) {
        adc->adc_buffer_full = 1;
    } else {
        adc->adc_buffer_empty = 0;
    }
    adc->adc_buffer_count++;
}

void adc_process(ADCHandler *adc) {
    if (adc->adc_buffer_full && adc->adc_buffer_empty) {
        int data = adc->adc_buffer[adc->adc_buffer_ptr];
        adc->adc_buffer_ptr = (adc->adc_buffer_ptr + 1) % adc->adc_buffer_size;
        if (adc->adc_buffer_ptr == 0) {
            adc->adc_buffer_full = 0;
        } else {
            adc->adc_buffer_empty = 1;
        }
        adc->adc_buffer_count--;
        int adc_value = data;
        int adc_value_scaled = adc_value * (adc->adc_gain / 2.0) + 0.5;
        adc->adc_buffer_data[adc->adc_buffer_ptr] = adc_value_scaled;
    }
}

void adc_log(ADCHandler *adc) {
    if (adc->adc_buffer_count > 0) {
        int adc_value = adc->adc_buffer_data[adc->adc_buffer_ptr];
        int ppm = adc_value * 0.0001; // Example conversion factor
        char line[100];
        sprintf(line, "%s %f\n", ctime(&time(NULL)), ppm);
        FILE *fp = fopen(CO_CONVERSION_LOG_FILE, "a");
        if (fp != NULL) {
            fprintf(fp, "%s", line);
            fclose(fp);
        } else {
            fprintf(stderr, "Failed to open log file\n");
        }
    }
}

void sensor_init() {
    int i2c_fd = open("/dev/i2c-ad0", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
    int ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }
    int sensor_fd = open("/dev/i2c-ad1", O_RDWR);
    if (sensor_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
    int ret = ioctl(sensor_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }
}

void sensor_read(ADCHandler *adc, int sensor_fd) {
    int ret = ioctl(sensor_fd, I2C_RDWR, (unsigned char *)&adc->adc_buffer[0], 1, I2C_SLAVE, CO_SENSOR);
    if (ret < 0) {
        fprintf(stderr, "Sensor read failed: %d\n", ret);
        exit(EXIT_FAILURE);
    }
}

void sensor_cleanup(ADCHandler *adc, int sensor_fd, int i2c_fd) {
    close(sensor_fd);
    close(i2c_fd);
    munmap(adc->adc_buffer, adc->adc_buffer_size_bytes);
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        sensor_cleanup(&adc, adc->sensor_fd, adc->i2c_fd);
        exit(EXIT_SUCCESS);
    }
}

int main() {
    ADCHandler adc;
    adc.fd = 0;
    adc.i2c_fd = 0;
    adc.adc_fd = 0;
    adc.adc_channel = ADC_CH;
    adc.adc_gain = 2;
    adc.adc_resolution = 16;
    adc.adc_sample_rate = 1000;
    adc.adc_buffer_size = 16;
    adc.adc_buffer = NULL;
    adc.adc_buffer_size_bytes = 0;
    adc.adc_buffer_ptr = 0;
    adc.adc_buffer_full = 0;
    adc.adc_buffer_empty = 0;
    adc.adc_buffer_count = 0;
    adc.adc_buffer_data[16] = {0};

    pigpio_start(NULL, 0);
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_init();

    adc_fd = open("/dev/adc1", O_RDWR);
    if (adc_fd < 0) {
        perror("Failed to open ADC device");
        exit(EXIT_FAILURE);
    }
    adc.adc_fd = adc_fd;
    adc.adc_channel = ADC_CH;
    adc.adc_gain = 2;
    adc.adc_resolution = 16;
    adc.adc_sample_rate = 1000;
    adc.adc_buffer_size = 16;
    adc_init(&adc, adc.adc_gain, adc.adc_resolution, adc.adc_sample_rate, adc.adc_buffer_size);

    sensor_fd = open("/dev/i2c-ad1", O_RDWR);
    if (sensor_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
    adc.i2c_fd = sensor_fd;
    sensor_read(&adc, adc.i2c_fd);

    while (1) {
        adc_read(&adc, ADC_CH);
        adc_process(&adc);
        adc_log(&adc);
        usleep(5000000); // 5 seconds
    }

    sensor_cleanup(&adc, adc.i2c_fd, adc.i2c_fd);
    pigpio_stop(NULL);
    return 0;
}

