#define SPI_CHANNEL 0
#define SPI_CE0 8
#define SPI_CE1 9
#define SPI_MISO 9
#define SPI_MOSI 10
#define SPI_SCLK 11
#define LED_PIN 27
#define THRESHOLD 0.7
#define WINDOW_SIZE 100
#define SAMPLE_RATE 1000
#define LOG_FILE "audio_events.csv"

volatile sig_atomic_t running = 1;

void handle_sigint(int signum) {
    printf("SIGINT received, exiting...\n");
    running = 0;
    piLock();
    piSetMode(LED_PIN, PI_OUTPUT);
    piWrite(LED_PIN, 0);
    piUnexport(SPI_CE0);
    piUnexport(SPI_CE1);
    piUnexport(SPI_CHANNEL);
    piUnexport(MIC1_CHANNEL);
    piUnexport(MIC2_CHANNEL);
    piUnexport(ADC_CHANNEL);
    piUnexport(ADC_CHANNEL_2);
    piUnexport(SPI_SCLK);
    piUnexport(SPI_MISO);
    piUnexport(SPI_MOSI);
    piUnexport(LED_PIN);
    piFinish();
    exit(0);
}

int main() {
    signal(SIGINT, handle_sigint);

    if (piInitialise() < 0) {
        perror("pigpio init failed");
        return 1;
    }

    if (piSetMode(SPI_CE0, PI_OUTPUT) < 0) {
        perror("SPI CE0 mode set failed");
        return 1;
    }

    if (piSetMode(SPI_CE1, PI_OUTPUT) < 0) {
        perror("SPI CE1 mode set failed");
        return 1;
    }

    if (piSetMode(SPI_CHANNEL, PI_OUTPUT) < 0) {
        perror("SPI channel mode set failed");
        return 1;
    }

    if (piSetMode(MIC1_CHANNEL, PI_INPUT) < 0) {
        perror("MIC1 channel mode set failed");
        return 1;
    }

    if (piSetMode(MIC2_CHANNEL, PI_INPUT) < 0) {
        perror("MIC2 channel mode set failed");
        return 1;
    }

    if (piSetMode(ADC_CHANNEL, PI_INPUT) < 0) {
        perror("ADC channel mode set failed");
        return 1;
    }

    if (piSetMode(ADC_CHANNEL_2, PI_INPUT) < 0) {
        perror("ADC channel mode set failed");
        return 1;
    }

    if (piSetMode(SPI_SCLK, PI_OUTPUT) < 0) {
        perror("SPI SCLK mode set failed");
        return 1;
    }

    if (piSetMode(SPI_MISO, PI_INPUT) < 0) {
        perror("SPI MISO mode set failed");
        return 1;
    }

    if (piSetMode(SPI_MOSI, PI_OUTPUT) < 0) {
        perror("SPI MOSI mode set failed");
        return 1;
    }

    if (piSetMode(LED_PIN, PI_OUTPUT) < 0) {
        perror("LED mode set failed");
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "w");
    if (!fp) {
        perror("file open failed");
        return 1;
    }

    fprintf(fp, "timestamp,mic1_rms,mic2_rms\n");

    while (running) {
        piLock();
        piDelay(SAMPLE_RATE);
        piUnlock();

        double mic1_rms = 0.0;
        double mic2_rms = 0.0;

        for (int i = 0; i < WINDOW_SIZE; i++) {
            piLock();
            int adc_value = piGetRawMedianValue(ADC_CHANNEL, 1);
            piUnlock();
            double voltage = (adc_value / 1024.0) * 3.3;
            mic1_rms += voltage * voltage;
            adc_value = piGetRawMedianValue(ADC_CHANNEL_2, 1);
            voltage = (adc_value / 1024.0) * 3.3;
            mic2_rms += voltage * voltage;
            piLock();
            piDelay(1);
            piUnlock();
        }

        mic1_rms /= WINDOW_SIZE;
        mic2_rms /= WINDOW_SIZE;

        if (mic1_rms > THRESHOLD || mic2_rms > THRESHOLD) {
            piLock();
            piSetMode(LED_PIN, PI_OUTPUT);
            piWrite(LED_PIN, 1);
            piUnlock();
            usleep(500000); // 500 ms
            piLock();
            piSetMode(LED_PIN, PI_OUTPUT);
            piWrite(LED_PIN, 0);
            piUnlock();
        }

        fprintf(fp, "%f,%f,%f\n", (double)time(NULL), mic1_rms, mic2_rms);

        piLock();
        piDelay(1);
        piUnlock();
    }

    fclose(fp);
