#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <pigpio.h>

#define I2C_ADDR 0x29
#define I2C_BUS 1
#define COLOR_LOG_FILE "color_log.csv"
#define COLOR_LOG_HEADER "YYYY-MM-DD HH:MM:SS,clear,red,green,blue"
#define COLOR_LOG_SEPARATOR ","

int main() {
    int i2c_fd;
    int status;
    int id;
    int clear, red, green, blue;
    int i2c_read_failures = 0;
    int i2c_write_failures = 0;
    int i2c_read_failures_threshold = 3;
    char timestamp[20];
    char *header = NULL;

    if (gpioInitialise() < 0) {
        perror("pigpioInitialise");
        exit(EXIT_FAILURE);
    }

    if ((i2c_fd = i2cOpen(I2C_BUS, I2C_ADDR, 0)) < 0) {
        perror("i2cOpen");
        exit(EXIT_FAILURE);
    }

    if (i2cReadReg(i2c_fd, 0x12, &id) < 0) {
        i2c_close(i2c_fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if ((id & 0x0F) != 0x44) {
        i2c_close(i2c_fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    header = strdup(COLOR_LOG_HEADER);
    if (header == NULL) {
        perror("strdup");
        exit(EXIT_FAILURE);
    }

    if (write(i2c_fd, header, strlen(header)) < 0) {
        i2c_close(i2c_fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    i2cWriteReg(i2c_fd, 0x01, 0xFF); // Set integration time to 0xFF (2.4 ms)
    i2cWriteReg(i2c_fd, 0x0F, 0x01); // Set gain to 0x01 (4x)

    if (i2cWriteReg(i2c_fd, 0x00, 0x01 | 0x02) < 0) {
        i2c_close(i2c_fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    while (1) {
        if (i2cReadReg(i2c_fd, 0x14, &clear) < 0) {
            i2c_read_failures++;
            if (i2c_read_failures >= i2c_read_failures_threshold) {
                i2c_close(i2c_fd);
                gpioTerminate();
                exit(EXIT_FAILURE);
            }
            continue;
        }
        if (i2cReadReg(i2c_fd, 0x15, &red) < 0) {
            i2c_read_failures++;
            if (i2c_read_failures >= i2c_read_failures_threshold) {
                i2c_close(i2c_fd);
                gpioTerminate();
                exit(EXIT_FAILURE);
            }
            continue;
        }
        if (i2cReadReg(i2c_fd, 0x16, &green) < 0) {
            i2c_read_failures++;
            if (i2c_read_failures >= i2c_read_failures_threshold) {
                i2c_close(i2c_fd);
                gpioTerminate();
                exit(EXIT_FAILURE);
            }
            continue;
        }
        if (i2cReadReg(i2c_fd, 0x17, &blue) < 0) {
            i2c_read_failures++;
            if (i2c_read_failures >= i2c_read_failures_threshold) {
                i2c_close(i2c_fd);
                gpioTerminate();
                exit(EXIT_FAILURE);
            }
            continue;
        }

        if (i2cReadReg(i2c_fd, 0x18, &status) < 0) {
            i2c_read_failures++;
            if (i2c_read_failures >= i2c_read_failures_threshold) {
                i2c_close(i2c_fd);
                gpioTerminate();
                exit(EXIT_FAILURE);
            }
            continue;
        }

        if (status & 0x80) {
            fprintf(stderr, "Sensor not ready\n");
            continue;
        }

        if (i2cReadReg(i2c_fd, 0x19, &status) < 0) {
            i2c_read_failures++;
            if (i2c_read_failures >= i2c_read_failures_threshold) {
                i2c_close(i2c_fd);
                gpioTerminate();
                exit(EXIT_FAILURE);
            }
            continue;
        }

        if (status & 0x80) {
            fprintf(stderr, "Sensor not ready\n");
            continue;
        }

        if (i2cReadReg(i2c_fd, 0x1A, &status) < 0) {
            i2c_read_failures++;
            if (i2c_read_failures >= i2c_read_failures_threshold) {
                i2c_close(i2c_fd);
                gpioTerminate();
                exit(EXIT_FAILURE);
            }
            continue;
        }

        if (status & 0x80) {
            fprintf(stderr, "Sensor not ready\n");
            continue;
        }

        if (i2cReadReg(i2c_fd, 0x1B, &status) < 0) {
            i2c_read_failures++;
            if (i2c_read_failures >= i2c_read_failures_threshold) {
                i2c_close(i2c_fd);
                gpioTerminate();
                exit(EXIT_FAILURE);
            }
            continue;
        }

        if (status & 0x80) {
            fprintf(stderr, "Sensor not ready\n");
            continue;
        }

        sprintf(timestamp, "%s %s", ctime(&time(NULL)), "000000");
        strcat(timestamp, COLOR_LOG_SEPARATOR);
        strcat(timestamp, "%d", clear);
        strcat(timestamp, COLOR_LOG_SEPARATOR);
        strcat(timestamp, "%d", red);
        strcat(timestamp, COLOR_LOG_SEPARATOR);
        strcat(timestamp, "%d", green);
        strcat(timestamp, COLOR_LOG_SEPARATOR);
        strcat(timestamp, "%d", blue);

        if (write(i2c_fd, timestamp, strlen(timestamp)) < 0) {
            i2c_close(i2c_fd);
            gpioTerminate();
            exit(EXIT_FAILURE);
        }

        sleep(1);
    }

    i2c_close(i2c_fd);
    gpioTerminate();
    return 0;
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (i2c_fd != -1) {
            i2c_close(i2c_fd);
        }
        if (header != NULL) {
            free(header);
        }
        if (fopen(COLOR_LOG_FILE, "r") == NULL) {
            header = strdup(COLOR_LOG_HEADER);
            if (write(i2c_fd, header, strlen(header)) < 0) {
                i2c_close(i2c_fd);
                gpioTerminate();
                exit(EXIT_FAILURE);
            }
        }
        if (fopen(COLOR_LOG_FILE, "w") == NULL) {
            perror("fopen");
            exit(EXIT_FAILURE);
        }
        if (fprintf(fopen(COLOR_LOG_FILE, "w"), header) < 0) {
            perror("fprintf");
            exit(EXIT_FAILURE);
        }
        if (fclose(fopen(COLOR_LOG_FILE, "r")) < 0) {
            perror("fclose");
            exit(EXIT_FAILURE);
        }
        if (fclose(fopen(COLOR_LOG_FILE, "w")) < 0) {
            perror("fclose");
            exit(EXIT_FAILURE);
        }
        if (gpioTerminate() < 0) {
            perror("gpioTerminate");
            exit(EXIT_FAILURE);
        }
    }
}

