int gpio27 = -1;

void handle_spi_error(int err) {
    fprintf(stderr, "SPI transfer error: %d\n", err);
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (current_log_fd != -1) {
        close(current_log_fd);
    }
    if (gpio27 != -1) {
        gpio27 = -1;
    }
    exit(EXIT_FAILURE);
}

void handle_adc_error(int err) {
    fprintf(stderr, "ADC read error: %d\n", err);
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (current_log_fd != -1) {
        close(current_log_fd);
    }
    if (gpio27 != -1) {
        gpio27 = -1;
    }
    exit(EXIT_FAILURE);
}

