    fprintf(stderr, "File I/O error: %d\n", err);
    if (current_log_fd != -1) {
        close(current_log_fd);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (gpio27 != -1) {
        gpio27 = -1;
    }
    exit(EXIT_FAILURE);
}

