    int channels[2];
    int *buffer;
    int buffer_size;
} AudioCapture;

void init_audio_capture(AudioCapture *ac) {
    ac->fd = gpio_open(DIGITAL);
    if (ac->fd < 0) {
        perror("gpio_open");
        exit(EXIT_FAILURE);
    }
    if (gpio_set_mode(ac->fd, INPUT) < 0) {
        perror("gpio_set_mode");
        exit(EXIT_FAILURE);
    }
    ac->channels[0] = gpio_number(0);
    ac->channels[1] = gpio_number(1);
    if (gpio_claim(ac->channels[0], 0) < 0) {
        perror("gpio_claim");
        exit(EXIT_FAILURE);
    }
    if (gpio_claim(ac->channels[1], 1) < 0) {
        perror("gpio_claim");
        exit(EXIT_FAILURE);
    }
    if (gpio_pull_up(ac->channels[0], 1) < 0) {
        perror("gpio_pull_up");
        exit(EXIT_FAILURE);
    }
    if (gpio_pull_up(ac->channels[1], 1) < 0) {
        perror("gpio_pull_up");
        exit(EXIT_FAILURE);
    }
    ac->buffer = (int *)mmap(0, 2 * 1024 * 1024, PROT_READ | PROT_WRITE, MAP_SHARED, ac->fd, 0);
    if (ac->buffer == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    ac->buffer_size = 1024 * 1024;
}

