        perror("SPI_SETMode");
        exit(EXIT_FAILURE);
    }
    if (ioctl(spi_fd, SPI_SETBitOrder(3)) < 0) {
        perror("SPI_SETBitOrder");
        exit(EXIT_FAILURE);
