#define LOG_FILE "moisture_log.txt"

void log_moisture(int adc_value) {
    char timestamp[26];
    struct tm *now;
    time_t t;

    t = time(NULL);
    now = localtime(&t);
    strftime(timestamp, 26, "%Y-%m-%dT%H:%M:%S.%06Z", now);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    fprintf(fp, "%s,%d\n", timestamp, adc_value);
    fclose(fp);
}

