#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_CS 8
#define SPI_FREQ 1000000
#define SPI_MODE 0
#define SPI_TIMEOUT 1000

#define LOG_FILE "soil_moisture.log"

void log_moisture(double moisture_percent) {
    char timestamp[24];
    struct tm *now;
    time_t t;

    t = time(NULL);
    now = localtime(&t);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now);

    fprintf(stderr, "Logging moisture: %f%%\n", moisture_percent);
    fprintf(stderr, "Timestamp: %s\n", timestamp);
    fprintf(stderr, "ADC Value: %d\n", adc_value);
    fprintf(stderr, "Moisture Level: %d%%\n", moisture_percent);
    fprintf(stderr, "\n");

    // Write to log file
    FILE *log = fopen(LOG_FILE, "a");
    if (log) {
        fprintf(log, "%s %d %f\n", timestamp, adc_value, moisture_percent);
        fclose(log);
    } else {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s [sample_rate]\n", argv[0]);
        return EXIT_FAILURE;
    }

    int sample_rate = atoi(argv[1]);
    if (sample_rate <= 0) {
        fprintf(stderr, "Sample rate must be a positive integer\n");
        return EXIT_FAILURE;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("pigpioInitialise failed");
        return EXIT_FAILURE;
    }

    // Set up SPI
    int spi_fd = spiOpen(SPI_CHANNEL, SPI_CS, SPI_FREQ, SPI_MODE, SPI_TIMEOUT);
    if (spi_fd < 0) {
        perror("spiOpen failed");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up GPIO for SPI CS
    if (gpioSetPullUpDnControl(SPI_CS, 0) < 0) {
        perror("gpioSetPullUpDnControl failed");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up SIGINT/SIGTERM handler
    struct sigaction sa;
    sa.sa_handler = sigIntHandler;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction failed");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Read SPI
        int adc_value;
        if (spiRead(spi_fd, &adc_value, 1) < 0) {
            fprintf(stderr, "SPI read failed\n");
            gpioTerminate();
            return EXIT_FAILURE;
        }

        // Calculate moisture percentage
        double moisture_percent = (adc_value / 1023.0) * 100.0;
        moisture_percent = fmax(0.0, fmin(moisture_percent, 100.0));

        // Log moisture
        log_moisture(moisture_percent);

        // Sleep for sample_rate seconds
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = sample_rate * 1000000;
        nanosleep(&ts, NULL);
    }

    // Cleanup
    gpioTerminate();
    return EXIT_SUCCESS;
}

void sigIntHandler(int signum) {
    fprintf(stderr, "Received signal %d, exiting...\n", signum);
    close(spi_fd);
    fclose(fopen(LOG_FILE, "a"));
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/signal.h>
#include <gpiod.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_MODE 0

#define DRY_ADC 700
#define WET_ADC 300

#define MAX_PERCENTAGE 100
#define MIN_PERCENTAGE 0

int spi_fd;
gpiod_device_t *spi_device;
gpiod_line_mfd_t *spi_line;
gpiod_line_t *spi_line_0;

void handle_spi_error(int err) {
    if (err < 0) {
        perror("SPI ioctl error");
        exit(EXIT_FAILURE);
    }
}

void handle_spi_bus_error(int err) {
    if (err < 0) {
        perror("SPI bus error");
        exit(EXIT_FAILURE);
    }
}

void handle_spi_close(int err) {
    if (err < 0) {
        perror("SPI close error");
        exit(EXIT_FAILURE);
    }
}

void handle_spi_open(int err) {
    if (err < 0) {
        perror("SPI open error");
        exit(EXIT_FAILURE);
    }
}

void handle_spi_read(int err) {
    if (err < 0) {
        perror("SPI read error");
        exit(EXIT_FAILURE);
    }
}

void handle_spi_write(int err) {
    if (err < 0) {
        perror("SPI write error");
        exit(EXIT_FAILURE);
    }
}

void handle_spi_release(int err) {
    if (err < 0) {
        perror("SPI release error");
        exit(EXIT_FAILURE);
    }
}

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (spi_fd >= 0) {
            close(spi_fd);
        }
        if (spi_device) {
            gpiod_device_close(spi_device);
            spi_device = NULL;
        }
        if (spi_line) {
            gpiod_line_unref(spi_line);
            spi_line = NULL;
        }
        if (spi_line_0) {
            gpiod_line_unref(spi_line_0);
            spi_line_0 = NULL;
        }
        exit(EXIT_SUCCESS);
    }
}

int main() {
    struct gpiod_chip_t *chip;
    struct gpiod_line_t *line;
    struct gpiod_line_mfd_t *mfd;
    struct gpiod_line_info_t info;
    int adc_value;
    int moisture_percent;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiod");
    if (!chip) {
        perror("gpiod_chip_open error");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, SPI_DEV, SPI_CHANNEL);
    if (!line) {
        perror("gpiod_chip_get_line error");
        exit(EXIT_FAILURE);
    }

    mfd = gpiod_line_get_mfd(line);
    if (!mfd) {
        perror("gpiod_line_get_mfd error");
        exit(EXIT_FAILURE);
    }

    info = gpiod_line_get_info(line);
    if (!info) {
        perror("gpiod_line_get_info error");
        exit(EXIT_FAILURE);
    }

    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        handle_spi_open(-1);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, SPI_MODE) < 0) {
        handle_spi_write(-1);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, SPI_BITS) < 0) {
        handle_spi_write(-1);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_SPEED_hz, SPI_SPEED) < 0) {
        handle_spi_write(-1);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MODE, SPI_MODE) < 0) {
        handle_spi_read(-1);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, SPI_BITS) < 0) {
        handle_spi_read(-1);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_RD_SPEED_hz, SPI_SPEED) < 0) {
        handle_spi_read(-1);
        exit(EXIT_FAILURE);
    }

    spi_device = gpiod_chip_get_device(chip, SPI_DEV);
    if (!spi_device) {
        perror("gpiod_chip_get_device error");
        exit(EXIT_FAILURE);
    }

    spi_line = gpiod_device_get_line(spi_device, SPI_CHANNEL);
    if (!spi_line) {
        perror("gpiod_device_get_line error");
        exit(EXIT_FAILURE);
    }

    spi_line_0 = gpiod_line_get_line(spi_line, 0);
    if (!spi_line_0) {
        perror("gpiod_line_get_line error");
        exit(EXIT_FAILURE);
    }

    gpiod_line_enable(spi_line_0, GPIOD_LINE_ENABLE_ON);

    while (1) {
        adc_value = 0;
        if (ioctl(spi_fd, SPI_IOC_READ, &adc_value) < 0) {
            handle_spi_read(-1);
            continue;
        }

        moisture_percent = (adc_value - DRY_ADC) * 100.0 / (DRY_ADC - WET_ADC);
        moisture_percent = fmax(moisture_percent, MIN_PERCENTAGE);
        moisture_percent = fmin(moisture_percent, MAX_PERCENTAGE);

        printf("Moisture: %d%%\n", moisture_percent);

        usleep(5000000); // 5 seconds
    }

    if (spi_fd >= 0) {
        close(spi_fd);
    }

    if (spi_device) {
        gpiod_device_close(spi_device);
        spi_device = NULL;
    }

    if (spi_line) {
        gpiod_line_unref(spi_line);
        spi_line = NULL;
    }

    if (spi_line_0) {
        gpiod_line_unref(spi_line_0);
        spi_line_0 = NULL;
    }

    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <math.h>

#define ADC_CHANNEL 0
#define SPI_BUS 0
#define SPI_CE 8
#define SPI_MISO 9
#define SPI_MOSI 10
#define SPI_SCLK 11

#define PRESSURE_MIN 10
#define PRESSURE_MAX 150
#define PRESSURE_MIN_VOLTAGE 0.5
#define PRESSURE_MAX_VOLTAGE 4.5

#define PRESSURE_TO_VOLTAGE(p) ((p) * (PRESSURE_MAX_VOLTAGE - PRESSURE_MIN_VOLTAGE) / (PRESSURE_MAX - PRESSURE_MIN) + PRESSURE_MIN_VOLTAGE)
#define VOLTAGE_TO_PRESSURE(v) ((v - PRESSURE_MIN_VOLTAGE) * (PRESSURE_MAX - PRESSURE_MIN) / (PRESSURE_MAX_VOLTAGE - PRESSURE_MIN_VOLTAGE) + PRESSURE_MIN)

int pressure_sensor_present = 0;
int pressure_sensor_init = 0;
int pressure_sensor_read = 0;
int pressure_sensor_error = 0;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        if (pressure_sensor_init) {
            printf("Shutting down...\n");
            pi_close();
            printf("Resources released.\n");
        }
        exit(EXIT_SUCCESS);
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpio_init() < 0) {
        perror("pigpio init failed");
        exit(EXIT_FAILURE);
    }

    if (gpio_spisubstream(SPI_BUS, SPI_CE, SPI_MISO, SPI_MOSI, SPI_SCLK) < 0) {
        perror("SPI bus initialization failed");
        exit(EXIT_FAILURE);
    }

    if (gpio_claim_spi(SPI_BUS, SPI_CE) < 0) {
        perror("SPI bus claimed failed");
        exit(EXIT_FAILURE);
    }

    if (gpio_claim_adc(ADC_CHANNEL) < 0) {
        perror("ADC channel claimed failed");
        exit(EXIT_FAILURE);
    }

    if (gpio_set_adc_channel(ADC_CHANNEL, 0) < 0) {
        perror("ADC channel set failed");
        exit(EXIT_FAILURE);
    }

    printf("Sensor initialized.\n");

    while (1) {
        if (!pressure_sensor_init) {
            if (pi_adc_read(ADC_CHANNEL) < 0) {
                perror("ADC read failed");
                exit(EXIT_FAILURE);
            }
            pressure_sensor_present = (pi_adc_read(ADC_CHANNEL) > 0);
            pressure_sensor_init = 1;
            printf("Sensor present: %d\n", pressure_sensor_present);
        }

        if (pressure_sensor_present) {
            if (pressure_sensor_read) {
                int adc_value = pi_adc_read(ADC_CHANNEL);
                if (adc_value < 0 || adc_value > 1023) {
                    printf("ADC value out of range: %d\n", adc_value);
                    pressure_sensor_error = 1;
                } else {
                    double voltage = (double) adc_value / 1023.0 * 3.3;
                    double pressure = VOLTAGE_TO_PRESSURE(voltage);
                    if (pressure < PRESSURE_MIN || pressure > PRESSURE_MAX) {
                        printf("Pressure out of range: %f\n", pressure);
                        pressure_sensor_error = 1;
                    } else {
                        printf("%s %f kPa\n", asctime(localtime(&time)), pressure);
                    }
                }
            } else {
                pressure_sensor_read = 1;
                int adc_value = pi_adc_read(ADC_CHANNEL);
                if (adc_value < 0 || adc_value > 1023) {
                    printf("ADC value out of range: %d\n", adc_value);
                    pressure_sensor_error = 1;
                } else {
                    double voltage = (double) adc_value / 1023.0 * 3.3;
                    double pressure = VOLTAGE_TO_PRESSURE(voltage);
                    if (pressure < PRESSURE_MIN || pressure > PRESSURE_MAX) {
                        printf("Pressure out of range: %f\n", pressure);
                        pressure_sensor_error = 1;
                    } else {
                        printf("%s %f kPa\n", asctime(localtime(&time)), pressure);
                    }
                }
            }
        }

        if (pressure_sensor_error) {
            printf("Error: Sensor present but ADC value out of range or pressure out of range.\n");
            pressure_sensor_error = 0;
        }

        sleep(1);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <gpiod.h>
#include <gpiod/substream.h>
#include <gpiod/cdev.h>
#include <gpiod/line.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spi.h>
#include <linux/spi/spidev.h>
#include <time.h>

#define SPI0_CE0 8
#define SPI0_MOSI 10
#define SPI0_MISO 9
#define SPI0_SCLK 11
#define SPI_MODE 0
#define SPI_SPEED 1000000

#define MIN_ADC_VALUE 300
#define MAX_ADC_VALUE 700

typedef struct {
    int fd;
    struct spi_ioc_transfer spi;
    struct gpiod_chip *chip;
    struct gpiod_line *cs;
    struct gpiod_substream *substream;
} spi_dev;

void spi_open(spi_dev *dev) {
    dev->fd = open("/dev/spi0.0", O_RDWR);
    if (dev->fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    dev->chip = gpiod_chip_new();
    if (!dev->chip) {
        perror("gpiod_chip_new");
        exit(EXIT_FAILURE);
    }

    dev->cs = gpiod_line_request(dev->chip, SPI0_CE0, GPIOD_LINE_DIR_OUTPUT);
    if (!dev->cs) {
        perror("gpiod_line_request");
        exit(EXIT_FAILURE);
    }

    if (gpiod_chip_request_line(dev->chip, dev->cs) < 0) {
        perror("gpiod_chip_request_line");
        exit(EXIT_FAILURE);
    }

    dev->substream = gpiod_substream_new(dev->chip, 0);
    if (!dev->substream) {
        perror("gpiod_substream_new");
        exit(EXIT_FAILURE);
    }

    dev->spi.transfer.iov_base = (unsigned long)&dev->spi;
    dev->spi.transfer.iov_len = sizeof(dev->spi);
    dev->spi.mode = SPI_MODE;
    dev->spi.speed_hz = SPI_SPEED;
    dev->spi.bits_per_word = 8;
    dev->spi.delay_us = 0;

    if (ioctl(dev->fd, SPI_IOC_WR_MODE, SPI_MODE) < 0) {
        perror("SPI_IOC_WR_MODE");
        exit(EXIT_FAILURE);
    }

    if (ioctl(dev->fd, SPI_IOC_WR_SCLK, SPI_SPEED) < 0) {
        perror("SPI_IOC_WR_SCLK");
        exit(EXIT_FAILURE);
    }

    if (ioctl(dev->fd, SPI_IOC_WR_MOSI, SPI_SPEED) < 0) {
        perror("SPI_IOC_WR_MOSI");
        exit(EXIT_FAILURE);
    }

    if (ioctl(dev->fd, SPI_IOC_WR_MISO, SPI_SPEED) < 0) {
        perror("SPI_IOC_WR_MISO");
        exit(EXIT_FAILURE);
    }

    if (ioctl(dev->fd, SPI_IOC_WR_CS, 1) < 0) {
        perror("SPI_IOC_WR_CS");
        exit(EXIT_FAILURE);
    }

    if (ioctl(dev->fd, SPI_IOC_RD_SCLK, SPI_SPEED) < 0) {
        perror("SPI_IOC_RD_SCLK");
        exit(EXIT_FAILURE);
    }

    if (ioctl(dev->fd, SPI_IOC_RD_MOSI, SPI_SPEED) < 0) {
        perror("SPI_IOC_RD_MOSI");
        exit(EXIT_FAILURE);
    }

    if (ioctl(dev->fd, SPI_IOC_RD_MISO, SPI_SPEED) < 0) {
        perror("SPI_IOC_RD_MISO");
        exit(EXIT_FAILURE);
    }

    if (ioctl(dev->fd, SPI_IOC_RD_CS, 1) < 0) {
        perror("SPI_IOC_RD_CS");
        exit(EXIT_FAILURE);
    }

    if (gpiod_substream_request(dev->substream, dev->cs) < 0) {
        perror("gpiod_substream_request");
        exit(EXIT_FAILURE);
    }

    if (gpiod_chip_free(dev->chip) < 0) {
        perror("gpiod_chip_free");
        exit(EXIT_FAILURE);
    }
}

void spi_close(spi_dev *dev) {
    if (dev->substream) {
        gpiod_substream_free(dev->substream);
    }

    if (dev->cs) {
        gpiod_line_free(dev->cs);
    }

    if (dev->chip) {
        gpiod_chip_free(dev->chip);
    }

    if (dev->fd) {
        close(dev->fd);
    }
}

int main() {
    spi_dev dev;
    dev.fd = 0;
    dev.chip = NULL;
    dev.cs = NULL;
    dev.substream = NULL;

    if (!spi_open(&dev)) {
        return 1;
    }

    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        printf("%ld.%09ld: ", ts.tv_sec, ts.tv_nsec / 1000000);

        int adc_value = 0;
        if (ioctl(dev.fd, SPI_IOC_RD_MOSI, &adc_value) < 0) {
            perror("SPI_IOC_RD_MOSI");
            continue;
        }

        double moisture = (adc_value - MIN_ADC_VALUE) / (MAX_ADC_VALUE - MIN_ADC_VALUE) * 100.0;
        printf("%.2f%%\n", moisture);

        if (adc_value == 0 || adc_value == 1023) {
            printf("Error: ADC value stuck at 0 or 1023\n");
        }
    }

    spi_close(&dev);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/sigaction.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/spi/spi.h>
#include <linux/spi/spidev.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_CHANNEL 0
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000  // 1 MHz

#define MCP3008_CMD 0x00
#define MCP3008_CMD_START 0x80
#define MCP3008_CMD_CONFIG 0x20
#define MCP3008_CMD_DONT_CARE 0x00

#define SPI_READ_CMD (MCP3008_CMD_START | MCP3008_CMD_CONFIG | MCP3008_CMD_DONT_CARE)

typedef struct {
    int fd;
    struct spi_ioc_transfer spi_transfer;
} SpiHandler;

void sigint_handler(int sig) {
    if (SpiHandler::instance->fd > 0) {
        close(SpiHandler::instance->fd);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction failed");
        return EXIT_FAILURE;
    }

    SpiHandler::instance = new SpiHandler();

    if ((SpiHandler::instance->fd = open(SPI_DEV, O_RDWR)) == -1) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    SpiHandler::instance->spi_transfer.multiple = 1;
    SpiHandler::instance->spi_transfer.tx_buf = NULL;
    SpiHandler::instance->spi_transfer.rx_buf = NULL;
    SpiHandler::instance->spi_transfer.len = 0;
    SpiHandler::instance->spi_transfer.cs = SPI_CHANNEL;
    SpiHandler::instance->spi_transfer.bits_per_word = SPI_BITS_PER_WORD;
    SpiHandler::instance->spi_transfer.speed_hz = SPI_SPEED;
    SpiHandler::instance->spi_transfer.mode = SPI_MODE;

    if (ioctl(SpiHandler::instance->fd, SPI_IOC_WR_MODE, SPI_MODE) == -1) {
        perror("Failed to configure SPI mode");
        return EXIT_FAILURE;
    }

    if (ioctl(SpiHandler::instance->fd, SPI_IOC_WR_BITS_PER_WORD, SPI_BITS_PER_WORD) == -1) {
        perror("Failed to configure SPI bits per word");
        return EXIT_FAILURE;
    }

    if (ioctl(SpiHandler::instance->fd, SPI_IOC_WR_SPEED_HZ, SPI_SPEED) == -1) {
        perror("Failed to configure SPI speed");
        return EXIT_FAILURE;
    }

    while (1) {
        SpiHandler::instance->spi_transfer.tx_buf = (unsigned char *) &SPI_READ_CMD;
        SpiHandler::instance->spi_transfer.len = 3;
        SpiHandler::instance->spi_transfer.delay_usecs = 0;
        SpiHandler::instance->spi_transfer.flags = SPI_IOC_TRANSFER_FLAG_NO_WAIT;

        if (ioctl(SpiHandler::instance->fd, SPI_IOC_RDWR, &SpiHandler::instance->spi_transfer) == -1) {
            perror("SPI transfer failed");
            return EXIT_FAILURE;
        }

        uint16_t result = SpiHandler::instance->spi_transfer.rx_buf[0] << 8 | SpiHandler::instance->spi_transfer.rx_buf[1];
        int moisture = (result * 100) / 1023;

        if (moisture < 0) {
            moisture = 0;
        } else if (moisture > 100) {
            moisture = 100;
        }

        printf("Moisture: %d%%\n", moisture);

        usleep(5000000); // 5 seconds
    }

    return EXIT_SUCCESS;
}

class SpiHandler {
public:
    static SpiHandler* instance;
    int fd;
    struct spi_ioc_transfer spi_transfer;
};

SpiHandler* SpiHandler::instance = nullptr;

