#define SPI_CE0 0
#define SPI_MOSI 10
#define SPI_MISO 9
#define SPI_SCLK 11
#define SPI_CLOCK 1000000
#define SPI_MODE 0
#define SPI_CHANNEL 0
#define VH400_CHANNEL 0
#define VH400_LOW_THRESHOLD 300
#define VH400_HIGH_THRESHOLD 600
#define PUMP_RELAY 17
#define PUMP_STATE_LOG_SIZE 20
#define PUMP_STATE_LOG_FORMAT "%ld %d %d\n"

typedef struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} PumpStateLogEntry;

PumpStateLogEntry pump_state_log[PUMP_STATE_LOG_SIZE];
int pump_state_log_index = 0;

void handle_sigint(int signum) {
    piTimerStop();
    piRelayRelease(PUMP_RELAY);
    piSPIclose();
    piGpioTerminate();
    exit(0);
}

void log_pump_state_change(int moisture_level, int pump_state) {
    PumpStateLogEntry entry;
    entry.timestamp = time(NULL);
    entry.moisture_level = moisture_level;
    entry.pump_state = pump_state;
    pump_state_log[pump_state_log_index] = entry;
    pump_state_log_index = (pump_state_log_index + 1) % PUMP_STATE_LOG_SIZE;
    printf(PUMP_STATE_LOG_FORMAT, entry.timestamp, entry.moisture_level, entry.pump_state);
}

