#define SPI0_MOSI 10
#define SPI0_MISO 9
#define SPI0_SCLK 11
#define SPI0_MODE 0
#define SPI0_SPEED 1000000
#define MCP3008_CMD 0x01
#define MCP3008_CHANNEL 0x08
#define MCP3008_RESULT_OFFSET 2
#define MCP3008_RESULT_MASK 0x3FF

typedef struct {
    int fd;
    int chip_fd;
    int cs_fd;
    int chip;
    int cs;
} spi_chip;

int spi_open(int spi_fd, int chip, int cs) {
    struct spi_ioc_transfer spi;
    spi_chip chip_info;
    int ret;

    chip_info.chip = chip;
    chip_info.cs = cs;

    spi_fd = open("/dev/spi0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, SPI0_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_SCLK, SPI0_SCLK);
    if (ret < 0) {
        perror("Failed to set SPI SCLK");
        close(spi_fd);
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MOSI, SPI0_MOSI);
    if (ret < 0) {
        perror("Failed to set SPI MOSI");
        close(spi_fd);
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MISO, SPI0_MISO);
    if (ret < 0) {
        perror("Failed to set SPI MISO");
        close(spi_fd);
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_SPD, SPI0_SPEED);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return -1;
    }

    spi_fd = ioctl(spi_fd, SPI_IOC_RD_SCLK, SPI0_SCLK);
    if (spi_fd < 0) {
        perror("Failed to read SPI SCLK");
        close(spi_fd);
        return -1;
    }

    spi_fd = ioctl(spi_fd, SPI_IOC_RD_MOSI, SPI0_MOSI);
    if (spi_fd < 0) {
        perror("Failed to read SPI MOSI");
        close(spi_fd);
        return -1;
    }

    spi_fd = ioctl(spi_fd, SPI_IOC_RD_MISO, SPI0_MISO);
    if (spi_fd < 0) {
        perror("Failed to read SPI MISO");
        close(spi_fd);
        return -1;
    }

    spi_fd = ioctl(spi_fd, SPI_IOC_RD_SPD, SPI0_SPEED);
    if (spi_fd < 0) {
        perror("Failed to read SPI speed");
        close(spi_fd);
        return -1;
    }

    spi = {0};
    spi.ccx = 1;
    spi.tx_buf = (unsigned long)&MCP3008_CMD;
    spi.rx_buf = (unsigned long)&0x00;
    spi.len = 3;
    spi.delay_usec = 0;
    spi.flags = SPI_IOC_TRANSFER_MODE_0;

    ret = ioctl(spi_fd, SPI_IOC_RDWR, &spi);
    if (ret < 0) {
        perror("Failed to configure SPI device");
        close(spi_fd);
        return -1;
    }

    chip_info.chip_fd = spi_fd;
    chip_info.cs_fd = open("/dev/gpi-diff/8", O_RDWR);
    if (chip_info.cs_fd < 0) {
        perror("Failed to open CS line");
        close(spi_fd);
        return -1;
    }

    ret = gpiod_request_line(chip_info.cs_fd, &chip_info.chip);
    if (ret < 0) {
        perror("Failed to request CS line");
        close(spi_fd);
        return -1;
    }

    ret = gpiod_request_chip(&chip_info.chip);
    if (ret < 0) {
        perror("Failed to request chip");
        close(spi_fd);
        return -1;
    }

    return 0;
}

