int main() {
    int spi_fd[3];
    int chip[3] = {0, 1, 2};
    int cs[3] = {8, 7, 25};
    int i;
    int ret;
    struct tm *timeinfo;
    time_t now;
    char buffer[100];
    FILE *fp;
    char header[100] = "timestamp,sensor1,sensor2,sensor3\n";

    fp = fopen("soil_moisture_log.csv", "r");
    if (fp == NULL) {
        fp = fopen("soil_moisture_log.csv", "w");
        if (fp == NULL) {
            perror("Failed to open log file");
            return -1;
        }
    }

    if (fread(header, 1, strlen(header), fp) == 0) {
        fprintf(fp, "%s", header);
    }

    fclose(fp);

    for (i = 0; i < 3; i++) {
        ret = spi_open(spi_fd[i], chip[i], cs[i]);
        if (ret < 0) {
            perror("Failed to open SPI device");
            return -1;
        }
    }

    while (1) {
        now = time(NULL);
        timeinfo = localtime(&now);
        snprintf(buffer, sizeof(buffer), "%d-%m-%Y %H:%M:%S", timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday, timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec);

        for (i = 0; i < 3; i++) {
            ret = spi_read(spi_fd[i], chip[i], cs[i]);
            if (ret < 0) {
                fprintf(stderr, "Failed to read sensor %d\n", i);
                fprintf(stderr, "Error: %d\n", ret);
            } else {
                fprintf(stderr, "Sensor %d: %d\n", i, ret);
            }
        }

        fprintf(fp, "%s,%d,%d,%d\n", buffer, spi_read_result[0], spi_read_result[1], spi_read_result[2]);

        sleep(5);
    }

    for (i = 0; i < 3; i++) {
        ret = gpiod_line_free(spi_fd[i]);
        if (ret < 0) {
            perror("Failed to free SPI line");
        }

        ret = gpiod_chip_free(chip[i]);
        if (ret < 0) {
            perror("Failed to free chip");
        }

        ret = close(spi_fd[i]);
        if (ret < 0) {
            perror("Failed to close SPI device");
        }

        ret = close(chip[i]);
        if (ret < 0) {
            perror("Failed to close CS line");
        }

        ret = close(cs[i]);
        if (ret < 0) {
            perror("Failed to close CS line");
        }
    }

    return 0;
}

