                return 1;
            }

            if (pi_read(pi_spi_num(SPI_CHANNEL), 0x00, 3, 0) < 0) {
                perror("SPI read failed");
                return 1;
            }

            double voltage = (double)pi_read(pi_spi_num(SPI_CHANNEL), 0x00, 3, 0) * VREF / 1024.0;
            char timestamp[20];
            sprintf(timestamp, "%.6f,%d,%f,%f", (double)time(NULL), i, voltage, voltage);

            if (fprintf(fp, "%s\n", timestamp) < 0) {
                perror("file write failed");
                return 1;
            }
        }

        if (fseek(fp, 0, SEEK_SET) < 0) {
            perror("file seek failed");
            return 1;
        }

        if (rewind(fp) < 0) {
            perror("file rewind failed");
            return 1;
        }

        if (pi_delay(SAMPLE_RATE) < 0) {
            perror("delay failed");
            return 1;
        }
    }

    fclose(fp);
    pi_close();
    return 0;
