#include <signal.h>
#include <pigpio.h>

#define SPI_FREQ 1000000
#define SPI_MODE 0
#define SPI_CS 8
#define SPI_CHANNEL 0
#define SPI_ADC_MAX 1023

int main() {
    if (gpio_init() < 0) {
        perror("pigpio init failed");
        return 1;
    }

    if (gpio setwpi2(0, SPI_FREQ, SPI_MODE) < 0) {
        perror("SPI setup failed");
        return 1;
    }

    if (gpio setwpi0(SPI_CS, 1) < 0) {
        perror("SPI CS setup failed");
        return 1;
    }

    if (gpio setwpi0(SPI_CS, 0) < 0) {
        perror("SPI CS setup failed");
        return 1;
    }

    if (gpio setwpi0(SPI_CHANNEL, 0) < 0) {
        perror("SPI channel setup failed");
        return 1;
    }

    int attempts = 0;
    int retry = 0;
    int last_error = 0;
    char buffer[256];
    FILE *fp = fopen("soil_data.txt", "a");

    signal(SIGINT, [](int sig) {
        if (fp) {
            fprintf(fp, "\n");
            fclose(fp);
        }
        gpioTerminate();
        return 0;
    });

    signal(SIGTERM, [](int sig) {
        if (fp) {
            fprintf(fp, "\n");
            fclose(fp);
        }
        gpioTerminate();
        return 0;
    });

    while (1) {
