#define SPI_MISO_PIN 9
#define SPI_CLK_PIN 11
#define SPI_MODE 0
#define SPI_FREQ 1000000
#define PUMP_PIN 18
#define THRESHOLD 300
#define LOG_FILE "irrigation.log"

void handle_sigint(int signum) {
    pi_set_mode(PUMP_PIN, PI_OUTPUT);
