int main() {
    int log_file = open(LOG_FILE, O_APPEND | O_CREAT, 0644);
    if (log_file < 0) {
        perror("Failed to open log file");
        return 1;
    }

    if (pi_init() < 0) {
        perror("Failed to initialize pigpio");
        close(log_file);
        return 1;
    }

    if (pi_set_mode(SPI_CS_PIN, PI_OUTPUT) < 0) {
        perror("Failed to set SPI CS pin mode");
        close(log_file);
        pi_close();
        return 1;
    }

    if (pi_set_mode(SPI_MOSI_PIN, PI_OUTPUT) < 0) {
        perror("Failed to set SPI MOSI pin mode");
        close(log_file);
        pi_close();
        return 1;
    }

    if (pi_set_mode(SPI_MISO_PIN, PI_INPUT) < 0) {
        perror("Failed to set SPI MISO pin mode");
        close(log_file);
        pi_close();
        return 1;
    }

    if (pi_set_mode(SPI_CLK_PIN, PI_OUTPUT) < 0) {
        perror("Failed to set SPI CLK pin mode");
        close(log_file);
        pi_close();
        return 1;
    }

    if (pi_set_mode(PUMP_PIN, PI_OUTPUT) < 0) {
        perror("Failed to set pump pin mode");
        close(log_file);
        pi_close();
        return 1;
    }

    if (pi_set_mode(SPI_CHANNEL, PI_INPUT) < 0) {
        perror("Failed to set SPI channel mode");
        close(log_file);
        pi_close();
        return 1;
    }

    if (pi_set_clock(SPI_CHANNEL, SPI_FREQ, SPI_MODE) < 0) {
        perror("Failed to set SPI clock");
        close(log_file);
        pi_close();
        return 1;
    }

    if (pi_set_pull_up(SPI_CS_PIN, 1) < 0) {
        perror("Failed to set SPI CS pull-up");
        close(log_file);
        pi_close();
        return 1;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    while (1) {
        int value;
        if (pi_read(SPI_CHANNEL, &value) < 0) {
            fprintf(stderr, "Error reading SPI channel: %s\n", pi_get_error());
            continue;
        }

        if (value < THRESHOLD) {
            pi_write(PUMP_PIN, 1);
        } else {
            pi_write(PUMP_PIN, 0);
        }

        char buffer[128];
        snprintf(buffer, sizeof(buffer), "%ld, %d, %d\n", time(NULL), value, pi_read(PUMP_PIN, 0));
        if (write(log_file, buffer, strlen(buffer)) < 0) {
            perror("Failed to write to log file");
        }

        usleep(60000000); // 60 seconds
    }

    close(log_file);
    pi_close();
    return 0;
}

