int potentiometer_fd;
int spi_fd;
int pwm1_fd;
int pwm2_fd;
int dir1_fd;
int dir2_fd;

int potentiometer_values[2];
int potentiometer_speeds[2];

int motor1_speed = MIN_SPEED;
int motor2_speed = MIN_SPEED;

void handle_sigint(int signum) {
    printf("Received SIGINT signal, exiting...\n");
    pi_stop();
    close(pwm1_fd);
    close(pwm2_fd);
    close(dir1_fd);
    close(dir2_fd);
    close(spi_fd);
    close(potentiometer_fd);
    exit(0);
}

void handle_sigterm(int signum) {
    printf("Received SIGTERM signal, exiting...\n");
    handle_sigint(signum);
}

int init_gpio() {
    if (pi_init() < 0) {
        perror("pigpio init failed");
        return -1;
    }
    return 0;
}

int init_pwm(int pin) {
    if (pi_set_mode(pin, PI_OUTPUT) < 0) {
        perror("pigpio set mode failed");
        return -1;
    }
    if (pi_set_pull_up_low(pin) < 0) {
        perror("pigpio set pull up low failed");
        return -1;
    }
    if (pi_set_pull_up_down(pin, PI_PUD_OFF) < 0) {
        perror("pigpio set pull up down failed");
        return -1;
    }
    if (pi_set_PWM_dutycycle(pin, 0) < 0) {
        perror("pigpio set pwm dutycycle failed");
        return -1;
    }
    return 0;
}

int init_dir(int pin) {
    if (pi_set_mode(pin, PI_OUTPUT) < 0) {
        perror("pigpio set mode failed");
        return -1;
    }
    if (pi_set_pull_up_low(pin) < 0) {
        perror("pigpio set pull up low failed");
        return -1;
    }
    if (pi_set_pull_up_down(pin, PI_PUD_OFF) < 0) {
        perror("pigpio set pull up down failed");
        return -1;
    }
    return 0;
}

int init_spi() {
    if (ioctl(spi_fd, I2C_SLAVE, POT_ADDR) < 0) {
        perror("ioctl failed");
        return -1;
    }
    return 0;
}

int init_potentiometer() {
    if ((potentiometer_fd = open("/dev/spi0.0", O_RDWR)) < 0) {
        perror("open failed");
        return -1;
    }
    if (ioctl(potentiometer_fd, I2C_SLAVE, POT_ADDR) < 0) {
        perror("ioctl failed");
        return -1;
    }
    return 0;
}

int read_potentiometer() {
    if (ioctl(potentiometer_fd, I2C_SMBUS_READ, 0) < 0) {
        perror("ioctl failed");
        return -1;
    }
    return 0;
}

int map_potentiometer(int value) {
    double log_value = log10((double)value) / LOG_SCALE + LOG_OFFSET;
    return (int)(log_value * MAX_SPEED / LOG_BASE);
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    if (!init_gpio()) {
        printf("pigpio init failed\n");
        return 1;
    }

    if (!init_pwm(PWM_PIN_1)) {
        printf("pigpio pwm init failed\n");
        return 1;
    }
    if (!init_pwm(PWM_PIN_2)) {
        printf("pigpio pwm init failed\n");
        return 1;
    }

    if (!init_dir(DIR_PIN_1)) {
        printf("pigpio dir init failed\n");
        return 1;
    }
    if (!init_dir(DIR_PIN_2)) {
        printf("pigpio dir init failed\n");
        return 1;
    }

    if (!init_spi()) {
        printf("pigpio spi init failed\n");
        return 1;
    }
    if (!init_potentiometer()) {
        printf("pigpio potentiometer init failed\n");
        return 1;
    }

    if (!init_potentiometer()) {
        printf("pigpio potentiometer init failed\n");
        return 1;
    }

    printf("Initialization complete\n");

    while (1) {
        if (read_potentiometer() < 0) {
            printf("Potentiometer read failed\n");
            continue;
        }

        for (int i = 0; i < 2; i++) {
            potentiometer_values[i] = (int)ioctl(potentiometer_fd, I2C_SMBUS_READ, 0) >> 8;
            potentiometer_speeds[i] = map_potentiometer(potentiometer_values[i]);
        }

        if (motor1_speed < MAX_SPEED && motor1_speed > MIN_SPEED) {
            motor1_speed = (int)(motor1_speed + 1);
        } else if (motor1_speed == MAX_SPEED) {
            motor1_speed = MIN_SPEED;
        }

        if (motor2_speed < MAX_SPEED && motor2_speed > MIN_SPEED) {
            motor2_speed = (int)(motor2_speed + 1);
        } else if (motor2_speed == MAX_SPEED) {
            motor2_speed = MIN_SPEED;
        }

        if (motor1_speed > MIN_SPEED) {
            pi_set_PWM_dutycycle(PWM_PIN_1, motor1_speed);
            pi_write(DIR_PIN_1, 1);
        } else {
            pi_set_PWM_dutycycle(PWM_PIN_1, 0);
            pi_write(DIR_PIN_1, 0);
        }

        if (motor2_speed < MAX_SPEED) {
            pi_set_PWM_dutycycle(PWM_PIN_2, motor2_speed);
            pi_write(DIR_PIN_2, 0);
        } else {
            pi_set_PWM_dutycycle(PWM_PIN_2, 0);
            pi_write(DIR_PIN_2, 1);
        }

        usleep(2000000); // 2 seconds

        if (motor1_speed > MIN_SPEED) {
            motor1_speed--;
        } else if (motor1_speed == MIN_SPEED) {
            motor1_speed = MAX_SPEED;
        }

        if (motor2_speed < MAX_SPEED) {
            motor2_speed++;
        } else if (motor2_speed == MAX_SPEED) {
            motor2_speed = MIN_SPEED;
        }

        usleep(2000000); // 2 seconds

        usleep(5000000); // 5 seconds

        usleep(2000000); // 2 seconds

        motor1_speed = MIN_SPEED;
        motor2_speed = MIN_SPEED;

        usleep(5000000); // 5 seconds
    }

    return 0;
}

