#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <sys/signal.h>
#include <gpiod.h>
#include <sys/spi/spidev.h>

#define MCP3008_CS_GPIO 8
#define MCP3008_SPI_DEV "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BIT_ORDER MSB
#define SPI_SPEED 1000000
#define SPI_WIDTH 8

#define LOG_FILE "audio_log.txt"
#define LOG_LINE_FORMAT "%llu|%u\n"

int spi_fd;
int spi_mode;
int spi_bits;
int spi_speed;
int spi_width;
int spi_channel;
int spi_cs_gpio;

void spi_open() {
    if ((spi_fd = open(MCP3008_SPI_DEV, O_RDWR)) < 0) {
        perror("open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, SPI_MODE) < 0) {
        perror("SPI mode write");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, SPI_WIDTH) < 0) {
        perror("SPI bits per word write");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_SPEED_hz, SPI_SPEED) < 0) {
        perror("SPI speed write");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MODE, &spi_mode) < 0) {
        perror("SPI mode read");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &spi_bits) < 0) {
        perror("SPI bits per word read");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_RD_SPEED_hz, &spi_speed) < 0) {
        perror("SPI speed read");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    spi_channel = 0;
}

void spi_close() {
    if (spi_fd > 0) {
        close(spi_fd);
    }
}

void spi_request_cs() {
    if (gpiod_request_line(&spi_cs_gpio, MCP3008_CS_GPIO, GPIOD_LINE_REQUEST_OUTPUT) < 0) {
        perror("request MCP3008_CS GPIO");
        exit(EXIT_FAILURE);
    }
}

void spi_release_cs() {
    if (gpiod_release_line(&spi_cs_gpio) < 0) {
        perror("release MCP3008_CS GPIO");
        exit(EXIT_FAILURE);
    }
}

void spi_transfer() {
    uint8_t buffer[3] = {0x01, 0x00, 0x00};
    uint32_t result = 0;

    if (gpiod_request_line(&spi_cs_gpio, MCP3008_CS_GPIO, GPIOD_LINE_REQUEST_OUTPUT) < 0) {
        perror("request MCP3008_CS GPIO");
        exit(EXIT_FAILURE);
    }

    if (write(spi_fd, buffer, 3) < 0) {
        perror("write SPI device");
        exit(EXIT_FAILURE);
    }

    if (gpiod_release_line(&spi_cs_gpio) < 0) {
        perror("release MCP3008_CS GPIO");
        exit(EXIT_FAILURE);
    }

    if (read(spi_fd, &result, 1) < 0) {
        perror("read SPI device");
        exit(EXIT_FAILURE);
    }

    if (read(spi_fd, &result, 1) < 0) {
        perror("read SPI device");
        exit(EXIT_FAILURE);
    }

    if (read(spi_fd, &result, 1) < 0) {
        perror("read SPI device");
        exit(EXIT_FAILURE);
    }

    uint32_t adc_value = (result & 0x3FF) << 8;
    uint32_t adc_value |= (result >> 8) & 0xFF;
    uint32_t adc_value = (result & 0x3FF) << 8 | (result >> 8) & 0xFF;
    uint32_t adc_value = (result & 0x3FF) << 8 | (result >> 8) & 0xFF;

    if (write(STDOUT_FILENO, LOG_LINE_FORMAT, strlen(LOG_LINE_FORMAT)) < 0) {
        perror("write log file");
        exit(EXIT_FAILURE);
    }

    if (clock_gettime(CLOCK_MONOTONIC_RAW, &ts) < 0) {
        perror("clock_gettime");
        exit(EXIT_FAILURE);
    }

    if (fprintf(stderr, LOG_LINE_FORMAT, (uint64_t)ts.tv_sec * 1000000ULL + ts.tv_nsec, adc_value) < 0) {
        perror("fprintf");
        exit(EXIT_FAILURE);
    }

    if (fflush(stderr) < 0) {
        perror("fflush");
        exit(EXIT_FAILURE);
    }
}

