#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define SPI_CLOCK 1000000
#define ADC_CHANNEL 0
#define VREF 3.3
#define PPM_MULTIPLIER 1000.0

int spi_fd;
int adc_read_count = 0;
int log_file_fd;

void handle_sigint(int signum) {
    if (signum == SIGINT) {
        printf("SIGINT received, closing SPI and exiting...\n");
        close(spi_fd);
        gpioTerminate();
        exit(0);
    }
}

int spi_init() {
    if (gpioInitialise() < 0) {
        perror("pigpio init failed");
        return -1;
    }

    spi_fd = spiOpen(0, SPI_CLOCK);
    if (spi_fd < 0) {
        perror("SPI open failed");
        return -1;
    }

    return 0;
}

int adc_read() {
    int result = 0;
    int retries = 0;

    while (retries < 3) {
        result = spiXfer(spi_fd, 0x01, 0x00, 0x00, 0x00);
        if (result == 0) {
            break;
        }
        usleep(100000); // 100 ms delay
        retries++;
    }

    if (retries == 3) {
        printf("ADC read failed after 3 retries\n");
        return -1;
    }

    return result;
}

int main() {
    struct timespec ts;
    char buffer[256];
    int adc_value;

    if (spi_init() < 0) {
        return -1;
    }

    if ((log_file_fd = fopen("gas_log.txt", "a")) == -1) {
        perror("log file open failed");
        return -1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        sprintf(buffer, "%ld, %d, %f\n", ts.tv_sec, adc_value, (float)adc_value * VREF / 1024.0 * PPM_MULTIPLIER);
        fprintf(log_file_fd, buffer);

        adc_value = adc_read();
        if (adc_value < 0) {
            continue;
        }

        printf("Voltage: %.2f V, PPM: %.2f\n", (float)adc_value * VREF / 1024.0, (float)adc_value * VREF / 1024.0 * PPM_MULTIPLIER);

        adc_read_count++;
        if (adc_read_count % 10 == 0) {
            printf("Read %d values\n", adc_read_count);
        }

        usleep(1000000); // 1 second delay
    }

    fclose(log_file_fd);
    return 0;
}

