#define LOG_FILE "watering.log"

void log_event(const char *event, const char *timestamp) {
    char buffer[256];
    struct tm *timeinfo;
    time_t rawtime;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s %s\n", buffer, event);
    FILE *log = fopen(LOG_FILE, "a");
    if (log) {
        fprintf(log, "%s %s\n", buffer, event);
        fclose(log);
    }
}

void handle_pump_on(int gpio, int level) {
    if (level == PUMP_ON) {
        log_event("Pump turned on", "Pump on");
    } else {
        log_event("Pump turned off", "Pump off");
    }
}

void handle_error(int error) {
    log_event("ADC read error", "Error reading ADC");
    if (error) {
        printf("ADC read error: %d\n", error);
    }
}

