#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <signal.h>
#include <gpiod.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_SPEED 1e6
#define SPI_BITS 8
#define SPI_CHANNEL_COUNT 3
#define SPI_CHANNELS 0x80

#define CSV_FILE "sensor_data.csv"

int spi_fd;
gpiod_handle_t spi_handle;
gpiod_line_mixin_t spi_line_mixin;
gpiod_line_t spi_line;
gpiod_line_state_t spi_line_state;
int channel_count = 0;
int channel = 0;
int channel_values[SPI_CHANNEL_COUNT];
int csv_fd;
char csv_buffer[1024];
char csv_header[1024] = "Channel,Value\n";

void handle_sigint(int signum) {
    if (csv_fd > 0) {
        close(csv_fd);
    }
    gpiod_line_mixin_free(&spi_line_mixin);
    gpiod_handle_free(&spi_handle);
    close(spi_fd);
    exit(0);
}

int main() {
    struct spi_ioc_transfer spi_transfer;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_state *state;
    struct gpiod_line_mixin *mixin;

    // Open SPI device
    if ((spi_fd = open(SPI_DEV, O_RDWR)) < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Set SPI mode
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_SPEED_hz, SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, SPI_BITS) < 0) {
        perror("Failed to set SPI bits per word");
        return 1;
    }

    // Initialize SPI transfer structure
    spi_transfer.ioctl = SPI_IOC_TRANSFER;
    spi_transfer.buffer = NULL;
    spi_transfer.len = 0;
    spi_transfer.delay_usec = 0;
    spi_transfer.speed_hz = SPI_SPEED;

    // Initialize gpiod chip
    if ((chip = gpiod_chip_open("/dev/spi0.0")) == NULL) {
        perror("Failed to open gpiod chip");
        return 1;
    }

    // Initialize gpiod line mixin
    if ((mixin = gpiod_line_mixin_new()) == NULL) {
        perror("Failed to create gpiod line mixin");
        return 1;
    }

    // Initialize gpiod line
    if ((line = gpiod_chip_get_line(chip, SPI_DEV, 0, 0)) == NULL) {
        perror("Failed to get gpiod line");
        return 1;
    }

    // Set line mixin
    if (gpiod_line_mixin_add(line, mixin) < 0) {
        perror("Failed to set gpiod line mixin");
        return 1;
    }

    // Initialize gpiod line state
    if ((state = gpiod_line_state_new()) == NULL) {
        perror("Failed to create gpiod line state");
        return 1;
    }

    // Set line state
    if (gpiod_line_state_set(line, state, GPIOD_LINE_STATE_ACTIVE) < 0) {
        perror("Failed to set gpiod line state");
        return 1;
    }

    // Set SPI line mixin
    if (gpiod_line_mixin_set(line, mixin, SPI_DEV, 0, 0) < 0) {
        perror("Failed to set SPI line mixin");
        return 1;
    }

    // Open CSV file
    if ((csv_fd = open(CSV_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644)) < 0) {
        perror("Failed to open CSV file");
        return 1;
    }

    // Write CSV header
    if (write(csv_fd, csv_header, strlen(csv_header)) < 0) {
        perror("Failed to write CSV header");
        return 1;
    }

    // Register SIGINT handler
    signal(SIGINT, handle_sigint);

    while (1) {
        // Initialize channel values
        for (channel = 0; channel < SPI_CHANNEL_COUNT; channel++) {
            channel_values[channel] = 0;
        }

        // Read SPI data
        for (channel = 0; channel < SPI_CHANNEL_COUNT; channel++) {
            // Set channel select
            spi_transfer.buffer = (unsigned char *)(&SPI_CHANNELS | (channel << 4));
            spi_transfer.len = 3;
            spi_transfer.delay_usec = 0;
            spi_transfer.speed_hz = SPI_SPEED;

            if (gpiod_line_mixin_transfer(line, mixin, SPI_DEV, 0, 0, &spi_transfer) < 0) {
                perror("Failed to read SPI data");
                return 1;
            }

            // Extract 10-bit value
            channel_values[channel] = ((spi_transfer.buffer[1] & 0x03) << 8) | spi_transfer.buffer[2];
        }

        // Log data
        if (write(csv_fd, ", ", 2) < 0) {
            perror("Failed to write CSV data");
            return 1;
        }

        for (channel = 0; channel < SPI_CHANNEL_COUNT; channel++) {
            if (write(csv_fd, "%d", channel_values[channel]) < 0) {
                perror("Failed to write CSV data");
                return 1;
            }
            if (write(csv_fd, ", ", 2) < 0) {
                perror("Failed to write CSV data");
                return 1;
            }
        }

        if (write(csv_fd, "\n", 1) < 0) {
            perror("Failed to write CSV data");
            return 1;
        }

        // Sleep for 1 second
        usleep(1000000);
    }

    return 0;
}

#include <stdio.h>
