#include <mosquitto.h>
#include <pigpio.h>

#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_QOS 0
#define MQTT_TOPIC "home/led_control"
#define GPIO_PIN 17

#define MAX_PAYLOAD_SIZE 256
#define JSON_PARSE_ERROR "Invalid JSON payload"

typedef struct {
    cJSON *json;
} mqtt_payload_t;

void mqtt_callback(const void *message, void *userdata) {
    mqtt_payload_t *payload = (mqtt_payload_t *)userdata;
    cJSON *json = cJSON_Parse((char *)message);
    if (json == NULL) {
        fprintf(stderr, "Error parsing JSON payload: %s\n", JSON_PARSE_ERROR);
        cJSON_Delete(json);
        return;
    }
    if (cJSON_GetBoolean(json, "led_state") == cJSON_FALSE) {
        gpioWrite(GPIO_PIN, 0);
    } else {
        gpioWrite(GPIO_PIN, 1);
    }
    cJSON_Delete(json);
}

void mqtt_disconnect_handler(void *userdata) {
    fprintf(stderr, "Disconnected from MQTT broker\n");
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d\n", signal);
    if (signal == SIGINT || signal == SIGTERM) {
        mosquitto_disconnect(mosquitto_loop_instance);
        mosquitto_loop_stop(mosquitto_loop_instance);
        gpioTerminate();
        exit(EXIT_SUCCESS);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing GPIO: %d\n", gpioInitialise());
        return EXIT_FAILURE;
    }
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);

    mosquitto_lib_init();
    mosquitto_options_t options = {0};
    options.connect_retries = 3;
    options.keepalive = 1;
    options.will = 1;
    options.will_topic = MQTT_TOPIC;
    options.will_msg = "Disconnected";
    mosquitto_create_options_t create_options = {0};
    create_options.keepalive = 1;
    create_options.will = 1;
    create_options.will_topic = MQTT_TOPIC;
    create_options.will_msg = "Disconnected";
    mosquitto_create(mosquitto_loop_instance, MQTT_CLIENT_ID, options, create_options, mqtt_callback, NULL);

    mosquitto_loop_start(mosquitto_loop_instance);
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        if (mosquitto_loop_pending(mosquitto_loop_instance)) {
            mosquitto_loop_run(mosquitto_loop_instance);
        }
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO17 17
#define GPIO18 18
#define SENSOR_PIN 17
#define LED_PIN 18
#define DELAY_MS 100
#define BLINK_DURATION 1000

int main() {
    int sensor_fd, led_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    struct gpiod_event *event;
    int status;

    // Initialize GPIO chip
    if ((chip = gpiod_chip_open("/dev/gpiod")) == NULL) {
        perror("gpiod_chip_open");
        return 1;
    }

    // Open GPIO17 (SENSOR_PIN)
    if ((sensor_fd = gpiod_chip_request_line(chip, GPIO17, 0)) == NULL) {
        perror("gpiod_chip_request_line");
        gpiod_chip_unexport(chip, GPIO17);
        return 1;
    }

    // Open GPIO18 (LED_PIN)
    if ((led_fd = gpiod_chip_request_line(chip, GPIO18, 0)) == NULL) {
        perror("gpiod_chip_request_line");
        gpiod_chip_unexport(chip, GPIO18);
        gpiod_chip_unexport(chip, GPIO17);
        return 1;
    }

    // Set up edge detection for GPIO17
    if ((line = gpiod_chip_get_line(chip, sensor_fd)) == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_chip_unexport(chip, GPIO17);
        gpiod_chip_unexport(chip, GPIO18);
        gpiod_chip_close(chip);
        return 1;
    }

    if ((edge = gpiod_line_request_edge(line, GPIOD_EDGE_FALLING)) == NULL) {
        perror("gpiod_line_request_edge");
        gpiod_line_free(line);
        gpiod_chip_unexport(chip, GPIO17);
        gpiod_chip_unexport(chip, GPIO18);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up event for edge detection
    if ((event = gpiod_edge_request_event(edge, GPIOD_EDGE_TRIGGER)) == NULL) {
        perror("gpiod_edge_request_event");
        gpiod_edge_free(edge);
        gpiod_line_free(line);
        gpiod_chip_unexport(chip, GPIO17);
        gpiod_chip_unexport(chip, GPIO18);
        gpiod_chip_close(chip);
        return 1;
    }

    // Start event
    if (gpiod_edge_enable_event(edge, event) < 0) {
        perror("gpiod_edge_enable_event");
        gpiod_edge_free(edge);
        gpiod_line_free(line);
        gpiod_chip_unexport(chip, GPIO17);
        gpiod_chip_unexport(chip, GPIO18);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor value
        if (gpiod_line_get_value(line) == 0) {
            printf("Sound detected\n");
            // Blink LED
            for (int i = 0; i < 2; i++) {
                gpiod_line_set_value(led_fd, 1);
                usleep(BLINK_DURATION);
                gpiod_line_set_value(led_fd, 0);
                usleep(BLINK_DURATION);
            }
        } else {
            printf("No sound\n");
        }

        // Delay
        usleep(DELAY_MS * 1000);

        // Handle SIGINT or SIGTERM
        if (signal(SIGINT, [](int) {
            gpiod_line_free(line);
            gpiod_edge_free(edge);
            gpiod_chip_unexport(chip, GPIO17);
            gpiod_chip_unexport(chip, GPIO18);
            gpiod_chip_close(chip);
            exit(0);
        }) == SIG_ERR) {
            perror("signal");
            return 1;
        }

        if (signal(SIGTERM, [](int) {
            gpiod_line_free(line);
            gpiod_edge_free(edge);
            gpiod_chip_unexport(chip, GPIO17);
            gpiod_chip_unexport(chip, GPIO18);
            gpiod_chip_close(chip);
            exit(0);
        }) == SIG_ERR) {
            perror("signal");
            return 1;
        }
    }

    return 0;
}

