    if (gpiod_line_request_event(line, EVENT_CONSUMER) < 0) {
        perror("gpiod_line_request_event");
        gpiod_chip_release(chip);
        gpiod_line_release(line);
        return 1;
    }

    // Set up event handler
    event = gpiod_line_event_get(line);
    if (event == NULL) {
        perror("gpiod_line_event_get");
        gpiod_chip_release(chip);
        gpiod_line_release(line);
        return 1;
    }

    // Set up event callback
    gpiod_line_event_set(line, event, gpiod_line_event_handler, NULL);

    // Open log file
    if ((fd = fopen(VIBRATION_SHUTDOWN_LOG, "a")) == NULL) {
        perror("fopen");
        gpiod_chip_release(chip);
        gpiod_line_release(line);
        gpiod_event_release(event);
        gpiod_chip_release(chip);
        return 1;
    }

    // Main loop
    while (!shutdown_flag) {
        // Wait for event
        if (gpiod_line_event_wait(line, event) < 0) {
            perror("gpiod_line_event_wait");
            gpiod_chip_release(chip);
            gpiod_line_release(line);
            gpiod_event_release(event);
            fclose(fd);
            return 1;
        }

        // Read event
        if (gpiod_line_event_read(line, event, &ts.tv_sec, &ts.tv_nsec) < 0) {
            perror("gpiod_line_event_read");
            gpiod_chip_release(chip);
            gpiod_line_release(line);
            gpiod_event_release(event);
            fclose(fd);
            return 1;
        }

        // Format and write to log
        if (strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec)) < 0) {
            perror("strftime");
            gpiod_chip_release(chip);
            gpiod_line_release(line);
            gpiod_event_release(event);
            fclose(fd);
            return 1;
        }
        sprintf(buffer + strnlen(buffer, sizeof(buffer) - 1), ".%ld", ts.tv_nsec / 1000);
        if (fprintf(fd, "%s\n", buffer) < 0) {
            perror("fprintf");
            gpiod_chip_release(chip);
            gpiod_line_release(line);
            gpiod_event_release(event);
            fclose(fd);
            return 1;
        }

        // Print to stdout
        printf("%s\n", buffer);

        // Shutdown
        if (system("sudo shutdown -h now") < 0) {
            perror("system");
            gpiod_chip_release(chip);
            gpiod_line_release(line);
            gpiod_event_release(event);
            fclose(fd);
            return 1;
        }
    }

    // Clean up
    gpiod_line_event_release(line, event);
    gpiod_line_release(line);
    gpiod_chip_release(chip);
    fclose(fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

#define BMP280_ADDR 0x76
#define BMP280_CHIP_ID 0xD0
#define BMP280_CALIBRATION_BLOCK_START 0x88
#define BMP280_CALIBRATION_BLOCK_END 0xA1
#define BMP280_CTRL_MEAS 0xF4
#define BMP280_TEMP_OFS 0xAA
#define BMP280_TEMP_VOFF 0xAC
#define BMP280_TEMP_SENS 0xAE
#define BMP280_PRES_OFS 0xB0
#define BMP280_PRES_VOFF 0xB2
#define BMP280_PRES_SENS 0xB4
#define BMP280_ALT_OFS 0xB6
#define BMP280_ALT_VOFF 0xB8
#define BMP280_ALT_SENS 0xBA
#define BMP280_TEMP_REG_START 0xFA
#define BMP280_TEMP_REG_END 0xFC
#define BMP280_PRESS_REG_START 0xFD
#define BMP280_PRESS_REG_END 0xFF
#define BMP280_LOG_FILE "altitude_log.txt"
#define LOG_TIMESTAMP_FORMAT "%Y-%m-%d %H:%M:%S"

void handle_sigint(int signum) {
    if (pi_is_initialized()) {
        pi_close();
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpio_init()) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    if (pi_init()) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_fd = pi_i2c_open(1, BMP280_ADDR, 100000);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        return EXIT_FAILURE;
    }

    if (pi_i2c_read(i2c_fd, BMP280_CHIP_ID, 1, NULL) < 0) {
        fprintf(stderr, "Failed to read BMP280 chip ID\n");
        return EXIT_FAILURE;
    }
    if (*(uint8_t *)pi_i2c_read(i2c_fd, BMP280_CHIP_ID, 1) != 0x58) {
        fprintf(stderr, "BMP280 chip ID is not 0x58\n");
        return EXIT_FAILURE;
    }

    uint8_t calibration_block[0x10];
    if (pi_i2c_read(i2c_fd, BMP280_CALIBRATION_BLOCK_START, 0x10, calibration_block) < 0) {
        fprintf(stderr, "Failed to read BMP280 calibration block\n");
        return EXIT_FAILURE;
    }

    uint32_t temp_off = calibration_block[BMP280_TEMP_OFS];
    uint32_t temp_voff = calibration_block[BMP280_TEMP_VOFF];
    uint32_t temp_sens = calibration_block[BMP280_TEMP_SENS];
    uint32_t pres_off = calibration_block[BMP280_PRES_OFS];
    uint32_t pres_voff = calibration_block[BMP280_PRES_VOFF];
    uint32_t pres_sens = calibration_block[BMP280_PRES_SENS];
    uint32_t alt_off = calibration_block[BMP280_ALT_OFS];
    uint32_t alt_voff = calibration_block[BMP280_ALT_VOFF];
    uint32_t alt_sens = calibration_block[BMP280_ALT_SENS];

    uint32_t temp_raw, temp_comp;
    uint32_t pres_raw, pres_comp;
    uint32_t alt_raw, alt_comp;
    double temp, pres, alt;

    FILE *log_file = fopen(BMP280_LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    while (1) {
        if (pi_i2c_read(i2c_fd, BMP280_CTRL_MEAS, 1, NULL) < 0) {
            fprintf(stderr, "Failed to read BMP280 control register\n");
            return EXIT_FAILURE;
        }
        uint8_t ctrl_meas = pi_i2c_read(i2c_fd, BMP280_CTRL_MEAS, 1)[0];
        if (ctrl_meas != 0x36) {
            fprintf(stderr, "BMP280 control register is not in normal mode\n");
            return EXIT_FAILURE;
        }

        if (pi_i2c_read(i2c_fd, BMP280_TEMP_REG_START, 5, NULL) < 0) {
            fprintf(stderr, "Failed to read BMP280 temperature registers\n");
            return EXIT_FAILURE;
        }
        if (pi_i2c_read(i2c_fd, BMP280_PRESS_REG_START, 5, NULL) < 0) {
            fprintf(stderr, "Failed to read BMP280 pressure registers\n");
            return EXIT_FAILURE;
        }

        if (pi_i2c_read(i2c_fd, BMP280_TEMP_REG_START, 5, &temp_raw) < 0) {
            fprintf(stderr, "Failed to read BMP280 temperature registers\n");
            return EXIT_FAILURE;
        }
        if (pi_i2c_read(i2c_fd, BMP280_PRESS_REG_START, 5, &pres_raw) < 0) {
            fprintf(stderr, "Failed to read BMP280 pressure registers\n");
            return EXIT_FAILURE;
        }

        temp = (temp_raw - temp_voff) * 0.0048828125 / temp_sens + temp_off;
        pres = (pres_raw - pres_voff) * 0.0048828125 / pres_sens + pres_off;
        alt = (pres - 101325) * 0.0000225577 / (temp + 273.15);

        char timestamp[128];
        strftime(timestamp, sizeof(timestamp), LOG_TIMESTAMP_FORMAT, localtime(&time(NULL)));
        fprintf(log_file, "%s %f\n", timestamp, alt);

        if (ferror(log_file)) {
            fprintf(stderr, "Error writing to log file\n");
            return EXIT_FAILURE;
        }

        if (pi_i2c_read(i2c_fd, BMP280_TEMP_REG_START, 5, NULL) < 0) {
            fprintf(stderr, "Failed to read BMP280 temperature registers\n");
            return EXIT_FAILURE;
        }
        if (pi_i2c_read(i2c_fd, BMP280_PRESS_REG_START, 5, NULL) < 0) {
            fprintf(stderr, "Failed to read BMP280 pressure registers\n");
            return EXIT_FAILURE;
        }

        if (pi_i2c_read(i2c_fd, BMP280_TEMP_REG_START, 5, &temp_raw) < 0) {
            fprintf(stderr, "Failed to read BMP280 temperature registers\n");
            return EXIT_FAILURE;
        }
        if (pi_i2c_read(i2c_fd, BMP280_PRESS_REG_START, 5, &pres_raw) < 0) {
            fprintf(stderr, "Failed to read BMP280 pressure registers\n");
            return EXIT_FAILURE;
        }

        temp = (temp_raw - temp_voff) * 0.0048828125 / temp_sens + temp_off;
        pres = (pres_raw - pres_voff) * 0.0048828125 / pres_sens + pres_off;
        alt = (pres - 101325) * 0.0000225577 / (temp + 273.15);

        char timestamp[128];
        strftime(timestamp, sizeof(timestamp), LOG_TIMESTAMP_FORMAT, localtime(&time(NULL)));
        fprintf(log_file, "%s %f\n", timestamp, alt);

        if (ferror(log_file)) {
            fprintf(stderr, "Error writing to log file\n");
            return EXIT_FAILURE;
        }

        usleep(5000000); // 5 seconds
    }

    if (log_file) {
        fclose(log_file);
    }

    pi_i2c_close(i2c_fd);
    pi_close();
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define ADC_CHANNELS 1
#define BUFFER_SIZE 120
#define LOG_FILE "temp_log.dat"
#define LOG_INTERVAL 5

float buffer[BUFFER_SIZE];
int buffer_index = 0;
FILE *log_file;

void handle_sigint(int signum) {
    printf("SIGINT received, closing SPI and exiting...\n");
    close_spi();
    terminate_pigpio();
    exit(0);
}

void handle_sigterm(int signum) {
    printf("SIGTERM received, closing SPI and exiting...\n");
    close_spi();
    terminate_pigpio();
    exit(0);
}

void terminate_pigpio() {
    printf("Terminating pigpio...\n");
    pigpioTerminate();
}

void close_spi() {
    printf("Closing SPI...\n");
    pigpio_close();
}

int spi_open() {
    printf("Opening SPI...\n");
    if (pigpio_open(0) < 0) {
        perror("pigpio_open");
        return -1;
    }
    return 0;
}

int spi_write(const char *buf, int len) {
    printf("Writing SPI buffer of %d bytes...\n", len);
    if (pigpio_write(buf, len) < 0) {
        perror("pigpio_write");
        return -1;
    }
    return 0;
}

int spi_read(int len, unsigned char *rx) {
    printf("Reading SPI buffer of %d bytes...\n", len);
    if (pigpio_read(rx, len) < 0) {
        perror("pigpio_read");
        return -1;
    }
    return 0;
}

void read_adc() {
    unsigned char spi_buf[3];
    spi_buf[0] = 0x01; // Start bit
    spi_buf[1] = 0x80 | SPI_CHANNEL; // Single-ended mode bit + channel number
    spi_buf[2] = 0x00; // Don't-care byte

    if (spi_open() < 0) {
        return;
    }

    if (spi_write(spi_buf, 3) < 0) {
        return;
    }

    if (spi_read(3, spi_buf) < 0) {
        return;
    }

    float voltage = (spi_buf[1] & 0x03) * 0.01024; // 10 mV/°C * 3.3 V / 1024
    float temperature = voltage / 0.01024; // Convert to °C

    buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;

    if (log_file) {
        fprintf(log_file, "%f\n", temperature);
    }
}

void log_to_file() {
    if (log_file) {
        rewind(log_file);
        fwrite(buffer, sizeof(float), BUFFER_SIZE, log_file);
    }
}

void cleanup() {
    if (log_file) {
        fclose(log_file);
    }
    printf("Cleanup complete.\n");
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    if (!(log_file = fopen(LOG_FILE, "wb+"))) {
        perror("fopen");
        return 1;
    }

    if (spi_open() < 0) {
        perror("pigpio_open");
        cleanup();
        return 1;
    }

    while (1) {
        read_adc();
        log_to_file();
        sleep(LOG_INTERVAL);
    }

    cleanup();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spi.h>
#include <linux/sensors.h>
#include <signal.h>
#include <time.h>

#define BH1750_ADDR 0x23
#define MAX4466_ADDR 0x40
#define MCP3008_CS 0
#define MCP3008_SPI_CHANNEL 0
#define MCP3008_SPI_SPEED 1000000
#define BH1750_REG 0x00
#define MAX4466_REG 0x00
#define MAX4466_ADC0 0x00

typedef struct {
    int i2c_fd;
    int spi_fd;
} SensorHandler;

void i2c_error_handler(int err, const char *msg) {
    if (err < 0) {
        perror(msg);
        exit(EXIT_FAILURE);
    }
}

void spi_error_handler(int err, const char *msg) {
    if (err < 0) {
        perror(msg);
        exit(EXIT_FAILURE);
    }
}

void handle_i2c_error(int err) {
    if (err < 0) {
        i2c_error_handler(err, "i2c");
    }
}

void handle_spi_error(int err) {
    if (err < 0) {
        spi_error_handler(err, "spi");
    }
}

void i2c_read_light(SensorHandler *handler) {
    char buf[32];
    int i2c_fd = handler->i2c_fd;
    int err = ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR);
    handle_i2c_error(err);

    err = ioctl(i2c_fd, I2C_SMBUS_READ, (unsigned long)&buf, 1, (unsigned long)BH1750_REG);
    handle_i2c_error(err);

    int lux = (buf[0] << 8) | buf[1];
    lux = lux / 10.0;

    printf("Light: %f\n", lux);
}

void spi_read_sound(SensorHandler *handler) {
    char buf[32];
    int spi_fd = handler->spi_fd;
    int err = ioctl(spi_fd, SPI_SET_SPEED, MCP3008_SPI_SPEED);
    handle_spi_error(err);

    err = ioctl(spi_fd, SPI_IOC_MESSAGE(1), buf);
    handle_spi_error(err);

    int adc_value = buf[0] << 8 | buf[1];
    adc_value = adc_value / 2;

    printf("Sound: %d\n", adc_value);
}

void log_entry(const char *date_time, double light, int sound) {
    char buffer[128];
    struct tm *time_info;
    time_t raw_time;
    time(&raw_time);
    time_info = localtime(&raw_time);
    strftime(buffer, 128, "%Y-%m-%d %H:%M:%S", time_info);
    printf("%s, Light: %f, Sound: %d\n", buffer, light, sound);
}

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Terminating...\n");
        close(handler->i2c_fd);
        close(handler->spi_fd);
        exit(EXIT_SUCCESS);
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = SA_RESTART;
    sigemptyset(&sa.sa_mask);

    SensorHandler handler;
    handler.i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (handler.i2c_fd < 0) {
        perror("Failed to open i2c bus");
        return EXIT_FAILURE;
    }

    handler.spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (handler.spi_fd < 0) {
        perror("Failed to open spi bus");
        close(handler->i2c_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(handler.i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set i2c slave address");
        close(handler->i2c_fd);
        close(handler->spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(handler.spi_fd, SPI_SET_SPEED, MCP3008_SPI_SPEED) < 0) {
        perror("Failed to set spi speed");
        close(handler->i2c_fd);
        close(handler->spi_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, SIG_IGN);
    signal(SIGTERM, SIG_IGN);

    while (1) {
        log_entry(ctime(&time(NULL)), i2c_read_light(&handler), spi_read_sound(&handler));
        sleep(1);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>

#define GPIO_PIN 17
#define LOG_FILE "flame_events.log"
#define LOG_FORMAT "timestamp,pin,state\n"

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    struct gpiod_event *event;
    struct timespec ts;
    char timestamp[128];
    int state;
    int alarm = 0;

    // Initialize signal handlers for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = [](int sig) {
        if (alarm) {
            printf("Flame detected! %s\n", ctime(&ts));
        }
        gpiod_line_free(line);
        gpiod_chip_free(chip);
        exit(EXIT_SUCCESS);
    };
    sa.sa_flags = SA_RESTART;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open the GPIO chip
    if ((chip = gpiod_chip_open("/dev/gpiod")) == NULL) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }

    // Find the GPIO line
    if ((line = gpiod_chip_get_line(chip, GPIO_PIN)) == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set the line to input with pull-down
    if (gpiod_line_set_mode(line, GPIOD_MODE_INPUT) == -1) {
        perror("gpiod_line_set_mode");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_set_pull(line, GPIOD_PULL_DOWN) == -1) {
        perror("gpiod_line_set_pull");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Create an edge for the line
    if ((edge = gpiod_line_create_edge(line, GPIOD_EDGE_BOTH)) == NULL) {
        perror("gpiod_line_create_edge");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Create an event for the edge
    if ((event = gpiod_edge_create_event(edge, 0)) == NULL) {
        perror("gpiod_edge_create_event");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set the event to trigger on both rising and falling edges
    if (gpiod_edge_set_event(edge, event, GPIOD_EDGE_BOTH) == -1) {
        perror("gpiod_edge_set_event");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Start the event
    if (gpiod_edge_start(edge) == -1) {
        perror("gpiod_edge_start");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Initialize the last state
    state = gpiod_line_get_value(line);

    // Log the initial state
    if (gpiod_line_get_value(line) == 1) {
        printf("Flame detected! %s\n", ctime(&ts));
    }

    while (1) {
        // Read the current state
        state = gpiod_line_get_value(line);

        // Log the state
        if (alarm) {
            printf("Flame detected! %s\n", ctime(&ts));
        }
        if (state == 1) {
            // Log the event
            snprintf(timestamp, sizeof(timestamp), "%ld,%d,1\n", (long)time(NULL), GPIO_PIN);
            FILE *log = fopen(LOG_FILE, "a");
            if (log != NULL) {
                fwrite(timestamp, sizeof(char), strlen(timestamp), log);
                fclose(log);
            } else {
                perror("fopen");
                exit(EXIT_FAILURE);
            }

            // Print the alarm message
            printf("Flame detected! %s\n", ctime(&ts));
        } else {
            // Log the event
            snprintf(timestamp, sizeof(timestamp), "%ld,%d,0\n", (long)time(NULL), GPIO_PIN);
            FILE *log = fopen(LOG_FILE, "a");
            if (log != NULL) {
                fwrite(timestamp, sizeof(char), strlen(timestamp), log);
                fclose(log);
            } else {
                perror("fopen");
                exit(EXIT_FAILURE);
            }
        }

        // Sleep for 1 second
        if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
            perror("clock_gettime");
            exit(EXIT_FAILURE);
        }
        if (nanosleep(&ts, NULL) == -1) {
            perror("nanosleep");
            exit(EXIT_FAILURE);
        }
    }

    // Cleanup GPIO resources
    gpiod_line_free(line);
    gpiod_chip_free(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define MCP3008_CS 0
#define SPI_FREQ 1000000
#define LOG_FILE "soil_data.txt"

void handle_sigint(int sig) {
    spiClose();
    fclose(log_file);
    gpioTerminate();
    printf("Goodbye!\n");
    exit(0);
}

int main() {
    int adc_values[3];
    char log_file_buffer[256];
    struct tm *time_info;
    time_t raw_time;
    pid_t pid;

    if (signal(SIGINT, handle_sigint) == SIG_ERR) {
        perror("signal");
        exit(1);
    }

    if (gpioInitialise(NULL) < 0) {
        perror("gpioInitialise");
        exit(1);
    }

    if (spiOpen(SPI_FREQ, MCP3008_CS, 0) < 0) {
        perror("spiOpen");
        exit(1);
    }

    while (1) {
        raw_time = time(NULL);
        time_info = localtime(&raw_time);
        strftime(log_file_buffer, sizeof(log_file_buffer), "%Y-%m-%d %H:%M:%S", time_info);

        for (int i = 0; i < 3; i++) {
            adc_values[i] = spiXfer(0, 0x01, 0x00, 3, 0x00);
            if (adc_values[i] < 0) {
                fprintf(stderr, "Error reading ADC value %d\n", i);
                continue;
            }
            float moisture = (1.0 - (adc_values[i] / 1023.0)) * 100.0;
            printf("%s, Sensor %d: %f%%\n", log_file_buffer, i, moisture);
            if (fputs(log_file_buffer, log_file) < 0) {
                perror("fputs");
                exit(1);
            }
        }

        gpioDelay(60000);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_PIN_17 17
#define GPIO_PIN_22 22
#define GPIO_PIN_23 23
#define GPIO_PIN_24 24

int main() {
    int line_fd;
    struct gpiod_line *line;
    struct gpiod_dir dir;
    struct gpiod_edge edge;
    struct gpiod_request request;

    // Initialize gpiod
    if (gpiod_init(NULL) < 0) {
        perror("gpiod_init");
        return 1;
    }

    // Open GPIO subsystem
    if ((line_fd = gpiod_open(NULL)) < 0) {
        perror("gpiod_open");
        gpiod_uninit(NULL);
        return 1;
    }

    // Set up GPIO direction for all lines
    for (int i = 0; i < 4; i++) {
        int pin = GPIO_PIN_17 + i;
        if ((line = gpiod_get_line(line_fd, pin, &dir, &edge)) == NULL) {
            perror("gpiod_get_line");
            gpiod_uninit(NULL);
            return 1;
        }

        // Set direction to output
        if (gpiod_line_request_output(line, &request) < 0) {
            perror("gpiod_line_request_output");
            gpiod_line_free(line);
            gpiod_uninit(NULL);
            return 1;
        }

        // Set initial value to LOW (assuming active-high relay modules)
        if (gpiod_line_set_value(line, 0) < 0) {
            perror("gpiod_line_set_value");
            gpiod_line_free(line);
            gpiod_uninit(NULL);
            return 1;
        }

        // Release the line
        gpiod_line_request_free(line, &request);
        gpiod_line_free(line);
    }

    // Signal handler for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = [](int signum) {
        // Deactivate all relays and release GPIO lines
        for (int i = 0; i < 4; i++) {
            int pin = GPIO_PIN_17 + i;
            if ((line = gpiod_get_line(line_fd, pin, &dir, &edge)) == NULL) {
                perror("gpiod_get_line");
                gpiod_uninit(NULL);
                return 1;
            }
            if (gpiod_line_set_value(line, 0) < 0) {
                perror("gpiod_line_set_value");
                gpiod_line_free(line);
                gpiod_uninit(NULL);
                return 1;
            }
            gpiod_line_request_free(line, &request);
            gpiod_line_free(line);
        }
        gpiod_uninit(NULL);
        printf("Exiting...\n");
        exit(0);
    };
    sa.sa_flags = SA_RESTART;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        gpiod_uninit(NULL);
        return 1;
    }

    // Main loop
    while (1) {
        for (int i = 0; i < 4; i++) {
            int pin = GPIO_PIN_17 + i;
            if ((line = gpiod_get_line(line_fd, pin, &dir, &edge)) == NULL) {
                perror("gpiod_get_line");
                gpiod_uninit(NULL);
                return 1;
            }
            if (gpiod_line_request_output(line, &request) < 0) {
                perror("gpiod_line_request_output");
                gpiod_line_free(line);
                gpiod_uninit(NULL);
                return 1;
            }
            if (gpiod_line_set_value(line, 1) < 0) {
                perror("gpiod_line_set_value");
                gpiod_line_request_free(line, &request);
                gpiod_line_free(line);
                gpiod_uninit(NULL);
                return 1;
            }
            printf("Relay %d activated\n", i);
            sleep(1);
            if (gpiod_line_set_value(line, 0) < 0) {
                perror("gpiod_line_set_value");
                gpiod_line_request_free(line, &request);
                gpiod_line_free(line);
                gpiod_uninit(NULL);
                return 1;
            }
            printf("Relay %d deactivated\n", i);
            sleep(1);
            gpiod_line_request_free(line, &request);
            gpiod_line_free(line);
        }
    }

    return 0;
}

