#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI0_CE0 8
#define SPI0_MOSI 10
#define SPI0_MISO 11
#define SPI0_SCLK 9
#define MCP3008_CHANNEL 0
#define VCC 3.3
#define THRESHOLD 10.0
#define LED_GPIO 21
#define LOG_FILE "magnetic_log.txt"

int adc_read(int channel) {
    int value;
    if (gpio_spisub_readadc(channel, SPI0, 0, 0, &value) < 0) {
        fprintf(stderr, "Error reading ADC: %d\n", gpio_errno());
        return -1;
    }
    return value;
}

void handle_sigint(int sig) {
    gpio_spisub_close();
    gpio_led_close(LED_GPIO);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    struct timespec ts;
    int adc_value;
    int field_mT;
    int led_state = 0;
    pid_t pid = fork();

    if (pid == 0) {
        // Child process: log and LED control
        while (1) {
            ts.tv_sec = time(NULL) / 1000;
            ts.tv_nsec = (time(NULL) % 1000) * 1000000;
            if (gpio_led_write(LED_GPIO, led_state) < 0) {
                fprintf(stderr, "Error writing LED: %d\n", gpio_errno());
                exit(EXIT_FAILURE);
            }
            adc_value = adc_read(MCP3008_CHANNEL);
            if (adc_value < 0) {
                fprintf(stderr, "Error reading ADC: %d\n", adc_value);
                exit(EXIT_FAILURE);
            }
            field_mT = (adc_value - (VCC / 2)) * 1000 / 1.65;
            if (field_mT > THRESHOLD) {
                led_state = 1;
            } else {
                led_state = 0;
            }
            if (fprintf(stderr, "Timestamp: %ld.%09ld, Field Strength: %.2f mT, LED: %d\n", 
                ts.tv_sec, ts.tv_nsec / 1000000000, (double)field_mT / 1000, led_state) < 0) {
                fprintf(stderr, "Error writing to stderr: %d\n", stderr_FILENO);
                exit(EXIT_FAILURE);
            }
            if (fprintf(stderr, "Timestamp: %ld.%09ld, Field Strength: %.2f mT, LED: %d\n", 
