#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <gpiod.h>
#include <sys/spi/spidev.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_MODE 0

#define GPIO_LINE 17
#define GPIO_CHIP 0

#define LOG_FILE "current_log.txt"
#define LOG_FORMAT "%s,%f\n"

typedef struct {
    int fd;
    struct gpiod_handle *handle;
    struct gpiod_line *line;
} GPIOController;

typedef struct {
    int fd;
    struct spi_ioc_transfer spi;
} SPIController;

void init_gpio(GPIOController *gpio) {
    int ret = gpiod_new(&gpio->handle);
    if (ret < 0) {
        perror("gpiod_new");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_request_line(gpio->handle, GPIO_LINE, &gpio->line);
    if (ret < 0) {
        perror("gpiod_request_line");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_request_chip(gpio->handle, GPIO_CHIP, &gpio->line);
    if (ret < 0) {
        perror("gpiod_request_chip");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_release_chip(gpio->handle, gpio->line);
    if (ret < 0) {
        perror("gpiod_release_chip");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_request_edge(gpio->handle, GPIO_LINE, GPIOD_EDGE_BOTH, &gpio->line);
    if (ret < 0) {
        perror("gpiod_request_edge");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_request_mode(gpio->handle, GPIO_LINE, GPIOD_MODE_INPUT, &gpio->line);
    if (ret < 0) {
        perror("gpiod_request_mode");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_release_mode(gpio->handle, gpio->line);
    if (ret < 0) {
        perror("gpiod_release_mode");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_release_line(gpio->handle, gpio->line);
    if (ret < 0) {
        perror("gpiod_release_line");
        exit(EXIT_FAILURE);
    }

    gpio->fd = gpiod_open(gpio->handle, gpio->line);
    if (gpio->fd < 0) {
        perror("gpiod_open");
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpio(GPIOController *gpio) {
    gpiod_close(gpio->handle);
    gpiod_free(gpio->handle);
}

void init_spi(SPIController *spi) {
    int ret = open(SPI_DEV, O_RDWR);
    if (ret < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    spi->fd = ret;

    spi->spi.bits = SPI_BITS;
    spi->spi.mode = SPI_MODE;
    spi->spi.speed_hz = SPI_SPEED;

    spi->spi.tx_buf = (unsigned long)&spi->spi.tx_buf;
    spi->spi.rx_buf = (unsigned long)&spi->spi.rx_buf;
    spi->spi.len = 8;
    spi->spi.cs = 0;
    spi->spi.delay_usec = 0;

    ret = ioctl(spi->fd, SPI_IOC_WR_MODE, spi->spi.mode);
    if (ret < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(spi->fd, SPI_IOC_WR_BITS_PER_FRAME, spi->spi.bits);
    if (ret < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(spi->fd, SPI_IOC_WR_MAX_SPEED_HZ, spi->spi.speed_hz);
    if (ret < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(spi->fd, SPI_IOC_RD_MODE, &spi->spi.mode);
    if (ret < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(spi->fd, SPI_IOC_RD_BITS_PER_FRAME, &spi->spi.bits);
    if (ret < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(spi->fd, SPI_IOC_RD_MAX_SPEED_HZ, &spi->spi.speed_hz);
    if (ret < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }
}

void cleanup_spi(SPIController *spi) {
    close(spi->fd);
}

void log_current(double current) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    double timestamp = tv.tv_sec + tv.tv_usec / 1000000.0;
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }
    fprintf(log_file, LOG_FORMAT, timestamp, current);
    fclose(log_file);
}

int main() {
    GPIOController gpio;
    SPIController spi;

    init_gpio(&gpio);
    init_spi(&spi);

    while (1) {
        double current;
        int ret = ioctl(spi.fd, SPI_IOC_RDWR, &spi);
        if (ret < 0) {
            perror("ioctl");
            continue;
        }

        ret = spi->spi.tx_buf[0] = 0x00;
        ret = spi->spi.tx_buf[1] = 0x01;
        ret = spi->spi.tx_buf[2] = 0x00;
        ret = spi->spi.tx_buf[3] = 0x00;
        ret = spi->spi.tx_buf[4] = 0x00;
        ret = spi->spi.tx_buf[5] = 0x00;
        ret = spi->spi.tx_buf[6] = 0x00;
        ret = spi->spi.tx_buf[7] = 0x00;

        ret = ioctl(spi.fd, SPI_IOC_IOC_WRITE, &spi->spi.tx_buf, 8 * sizeof(unsigned char));
        if (ret < 0) {
            perror("ioctl");
            continue;
        }

        ret = ioctl(spi.fd, SPI_IOC_RD_DATA0, &current);
        if (ret < 0) {
            perror("ioctl");
            continue;
        }

        log_current(current / 100.0);

        cleanup_spi(&spi);
        cleanup_gpio(&gpio);
        exit(EXIT_SUCCESS);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <pigpio.h>

volatile int exit_flag = 0;

void sigint_handler(int signum) {
    exit_flag = 1;
}

int main() {
    // Set up SIGINT handler
    signal(SIGINT, sigint_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("pigpioInitialise");
        exit(EXIT_FAILURE);
    }

    // Open SPI0
    if (spiOpen(0, 1000000, 0) < 0) {
        perror("spiOpen");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Open log file
    FILE *log_file;
    if ((log_file = fopen("current_log.txt", "w")) == NULL) {
        perror("fopen");
        spiClose(0);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (!exit_flag) {
        // Read MCP3008 channel 0
        uint8_t tx[3] = {0x01, 0x80, 0x00};
        uint8_t rx[3];
        if (spiXfer(0, tx, rx, 3) < 0) {
            fprintf(stderr, "SPI transfer error\n");
            continue;
        }

        // Compute 10-bit result
        int result = ((rx[1] & 0x03) << 8) | rx[2];

        // Convert to voltage
        double voltage = (result / 1023.0) * 5.0;

        // Check voltage range
        if (voltage < 0.0 || voltage > 5.0) {
            fprintf(stderr, "Voltage out of range\n");
            continue;
        }

        // Convert to current
        double current = (voltage - 2.5) * (50.0 / 2.5);

        // Append to log file
        char timestamp[20];
        struct tm *now = localtime(&time(NULL));
        strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", now);
        fprintf(log_file, "%s %.2f A\n", timestamp, current);
        fflush(log_file);

        // Delay
        gpioDelay(100000);
    }

    // Close log file
    fclose(log_file);

    // Close SPI
    spiClose(0);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO4 4
#define GPIO17 17
#define SAMPLES 5
#define DELAY_MS 2000
#define LOG_INTERVAL 1000

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line1, *line2;
    int line1_state, line2_state;
    int samples[5];
    int i, j, count0, count1;
    int detected;
    char log[256];

    if (signal(SIGINT, [](int) {
        if (chip) {
            gpiod_line_release(chip, line1);
            gpiod_line_release(chip, line2);
            gpiod_chip_close(chip);
        }
        exit(EXIT_SUCCESS);
    })) {
        perror("SIGINT handler setup failed");
        exit(EXIT_FAILURE);
    }

    if ((chip = gpiod_chip_open_by_number(GPIO4)) == NULL) {
        perror("Failed to open GPIO4 chip");
        exit(EXIT_FAILURE);
    }

    if ((line1 = gpiod_chip_get_line(chip, GPIO4)) == NULL) {
        perror("Failed to get GPIO4 line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(line1, NULL, NULL, NULL)) {
        perror("Failed to request input on GPIO4");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if ((chip = gpiod_chip_open_by_number(GPIO17)) == NULL) {
        perror("Failed to open GPIO17 chip");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if ((line2 = gpiod_chip_get_line(chip, GPIO17)) == NULL) {
        perror("Failed to get GPIO17 line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(line2, NULL, NULL, NULL)) {
        perror("Failed to request input on GPIO17");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    while (1) {
        detected = 0;
        for (i = 0; i < SAMPLES; i++) {
            gpiod_line_get_value(line1, &samples[i]);
            gpiod_line_get_value(line2, &samples[i]);
        }

        count0 = 0;
        count1 = 0;
        for (i = 0; i < SAMPLES; i++) {
            if (samples[i] == 0) {
                count0++;
            } else {
                count1++;
            }
        }

        if (count0 > SAMPLES / 2) {
            line1_state = 0;
        } else {
            line1_state = 1;
        }

        if (count1 > SAMPLES / 2) {
            line2_state = 0;
        } else {
            line2_state = 1;
        }

        if (line1_state == 0 && line2_state == 0) {
            detected = 1;
        }

        if (detected) {
            printf("ALERT: Both sensors detect object\n");
        } else {
            printf("Sensor 1: %d\n", line1_state);
            printf("Sensor 2: %d\n", line2_state);
        }

        sprintf(log, "Time: %d\nSensor 1: %d\nSensor 2: %d\n", time(NULL), line1_state, line2_state);
        printf("%s", log);

        if (time(NULL) % LOG_INTERVAL == 0) {
            printf("\n");
        }

        usleep(DELAY_MS * 1000);
    }

    return 0;
}

