void init_streamer(Streamer *s, const char *server_ip, int server_port) {
    s->server_ip = inet_addr(server_ip);
    s->server_port = server_port;
    s->sock_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (s->sock_fd < 0) {
        perror("socket");
        exit(EXIT_FAILURE);
    }
    s->server_addr.sin_family = AF_INET;
    s->server_addr.sin_port = htons(s->server_port);
    s->server_addr.sin_addr.s_addr = s->server_ip;
