    pan_button_fd = gpiod_get_line(chip, GPIO6, GPIOD_LINE_DIR_IN);
    if (pan_button_fd < 0) {
        perror("gpiod_get_line");
        gpiod_close(chip);
        exit(EXIT_FAILURE);
    }

    tilt_button_fd = gpiod_get_line(chip, GPIO7, GPIOD_LINE_DIR_IN);
    if (tilt_button_fd < 0) {
        perror("gpiod_get_line");
        gpiod_close(chip);
        exit(EXIT_FAILURE);
    }

    pan_button_value = gpiod_get_value(pan_button_fd);
    if (pan_button_value < 0) {
        perror("gpiod_get_value");
        gpiod_close(chip);
        exit(EXIT_FAILURE);
    }

    tilt_button_value = gpiod_get_value(tilt_button_fd);
    if (tilt_button_value < 0) {
        perror("gpiod_get_value");
        gpiod_close(chip);
        exit(EXIT_FAILURE);
    }

    pan_servo_request = gpiod_request_create(pan_servo_fd, GPIOD_EDGE_BOTH, GPIOD_STATE_ACTIVE);
    if (pan_servo_request < 0) {
        perror("gpiod_request_create");
        gpiod_close(chip);
        exit(EXIT_FAILURE);
    }

    tilt_servo_request = gpiod_request_create(tilt_servo_fd, GPIOD_EDGE_BOTH, GPIOD_STATE_ACTIVE);
    if (tilt_servo_request < 0) {
        perror("gpiod_request_create");
        gpiod_close(chip);
        exit(EXIT_FAILURE);
    }

    request_pwm = gpiod_request_create(pan_servo_fd, GPIOD_EDGE_BOTH, GPIOD_STATE_ACTIVE);
