        perror("gpiod_request_create");
        gpiod_close(chip);
        exit(EXIT_FAILURE);
    }

    request_pwm = gpiod_request_create(tilt_servo_fd, GPIOD_EDGE_BOTH, GPIOD_STATE_ACTIVE);
    if (request_pwm < 0) {
        perror("gpiod_request_create");
        gpiod_close(chip);
        exit(EXIT_FAILURE);
    }

