    if (state == NULL) {
        perror("gpiod_chip_get_state");
        gpiod_close(chip);
        exit(EXIT_FAILURE);
    }

    state->request = request_pwm;
    state->request->request = pan_servo_request;
    state->request->request->request = tilt_servo_request;

    gpiod_chip_request_set(chip, state, 0);
    if (gpiod_chip_request_submit(chip) < 0) {
        perror("gpiod_chip_request_submit");
        gpiod_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_chip_request_enable(chip, state);

    for (;;) {
        pan_button_value = gpiod_get_value(pan_button_fd);
        if (pan_button_value == 0) {
            pan_position += PWM_WIDTH_INCREMENT;
            if (pan_position > PWM_WIDTH_MAX_VALUE) {
                pan_position = PWM_WIDTH_MAX_VALUE;
            }
        } else {
            pan_position -= PWM_WIDTH_INCREMENT;
            if (pan_position < PWM_WIDTH_MIN_VALUE) {
                pan_position = PWM_WIDTH_MIN_VALUE;
            }
        }

        tilt_button_value = gpiod_get_value(tilt_button_fd);
        if (tilt_button_value == 0) {
            tilt_position += PWM_WIDTH_INCREMENT;
            if (tilt_position > PWM_WIDTH_MAX_VALUE) {
                tilt_position = PWM_WIDTH_MAX_VALUE;
            }
        } else {
            tilt_position -= PWM_WIDTH_INCREMENT;
            if (tilt_position < PWM_WIDTH_MIN_VALUE) {
                tilt_position = PWM_WIDTH_MIN_VALUE;
            }
        }

        pan_servo_request_value = (pan_position * 2) / 10;
        if (pan_servo_request_value < PWM_WIDTH_MIN_VALUE) {
            pan_servo_request_value = PWM_WIDTH_MIN_VALUE;
        } else if (pan_servo_request_value > PWM_WIDTH_MAX_VALUE) {
            pan_servo_request_value = PWM_WIDTH_MAX_VALUE;
        }

        tilt_servo_request_value = (tilt_position * 2) / 10;
        if (tilt_servo_request_value < PWM_WIDTH_MIN_VALUE) {
            tilt_servo_request_value = PWM_WIDTH_MIN_VALUE;
        } else if (tilt_servo_request_value > PWM_WIDTH_MAX_VALUE) {
            tilt_servo_request_value = PWM_WIDTH_MAX_VALUE;
        }

        pan_servo_request_result = gpiod_line_request_set(pan_servo_fd, pan_servo_request, pan_servo_request_value);
        if (pan_servo_request_result < 0) {
            perror("gpiod_line_request_set");
            gpiod_close(chip);
            exit(EXIT_FAILURE);
        }

        tilt_servo_request_result = gpiod_line_request_set(tilt_servo_fd, tilt_servo_request, tilt_servo_request_value);
        if (tilt_servo_request_result < 0) {
            perror("gpiod_line_request_set");
            gpiod_close(chip);
            exit(EXIT_FAILURE);
        }

        usleep(50000); // 50 ms

        pan_button_value = gpiod_get_value(pan_button_fd);
        tilt_button_value = gpiod_get_value(tilt_button_fd);
    }

    gpiod_close(chip);
    return 0;
}

