void cleanup(CameraCapture *cap) {
    if (cap->fd != -1) {
        close(cap->fd);
    }
    if (cap->handle) {
        gpiod_handle_unref(cap->handle);
    }
    if (cap->line) {
        gpiod_line_unref(cap->line);
    }
    if (cap->event) {
        gpiod_event_unref(cap->event);
    }
    free(cap->buffer);
    free(cap->event);
    free(cap->line);
    free(cap->handle);
}

void init_camera(CameraCapture *cap) {
    cap->fd = open("/dev/video0", O_RDWR | O_NONBLOCK);
    if (cap->fd == -1) {
        perror("open");
        cleanup(cap);
        exit(1);
    }

    struct gpiod_handle *handle = gpiod_open("/dev/video0", G_PIOD_OPEN_READ);
    if (!handle) {
        perror("gpiod_open");
        cleanup(cap);
        exit(1);
    }
    cap->handle = handle;

    struct gpiod_line *line = gpiod_get_line(handle, 0);
    if (!line) {
        perror("gpiod_get_line");
        cleanup(cap);
        exit(1);
    }
    cap->line = line;

    struct gpiod_event *event = gpiod_get_event(line, 0);
    if (!event) {
        perror("gpiod_get_event");
        cleanup(cap);
        exit(1);
    }
    cap->event = event;

    struct gpiod_request *request = gpiod_request_new();
    if (!request) {
        perror("gpiod_request_new");
        cleanup(cap);
        exit(1);
    }
    cap->request = request;

    struct gpiod_request_args args;
    args.flags = G_PIOD_REQ_FLAG_MMAP;
    args.size = FRAME_WIDTH * FRAME_HEIGHT * 2; // YUYV format
    gpiod_request_set_args(request, &args);
    gpiod_request_add_event(request, event, G_PIOD_REQ_FLAG_READ);
    gpiod_request_submit(handle, request);

    cap->buffer = mmap(0, args.size, PROT_READ, MAP_SHARED, cap->fd, 0);
