        perror("mmap");
        cleanup(cap);
        exit(1);
    }
}

void capture(CameraCapture *cap) {
    struct gpiod_event *event = cap->event;
    struct gpiod_request *request = cap->request;
    struct gpiod_event *event2 = gpiod_get_event(event->line, 0);
    if (!event2) {
        perror("gpiod_get_event");
        cleanup(cap);
        exit(1);
    }

    fd_set readfds;
    FD_ZERO(&readfds);
    FD_SET(event2->fd, &readfds);

    struct timeval timeout;
    timeout.tv_sec = 2;
    timeout.tv_usec = 0;

    int ready = select(event2->fd + 1, &readfds, NULL, NULL, &timeout);
    if (ready == 0) {
        fprintf(stderr, "Timeout\n");
        cleanup(cap);
        exit(1);
    }

    if (read(event2->fd, cap->buffer, args.size) != args.size) {
        perror("read");
        cleanup(cap);
        exit(1);
    }
}

void convert_to_rgb24(CameraCapture *cap) {
    unsigned char *rgb24 = malloc(FRAME_WIDTH * FRAME_HEIGHT * 3);
    if (!rgb24) {
        perror("malloc");
        cleanup(cap);
        exit(1);
    }

    for (int y = 0; y < FRAME_HEIGHT; y++) {
        for (int x = 0; x < FRAME_WIDTH; x++) {
            int yuv_index = (y * FRAME_WIDTH * 2) + (x * 2);
            int rgb_index = (y * FRAME_WIDTH * 3) + (x * 3);
            int y = cap->buffer[yuv_index];
            int u = cap->buffer[yuv_index + 1];
            int v = cap->buffer[yuv_index + 2];
            rgb24[rgb_index] = (unsigned char)(y + 1.5 * (v - u));
            rgb24[rgb_index + 1] = (unsigned char)(2 * y - v + u);
            rgb24[rgb_index + 2] = (unsigned char)(2 * y + v - u);
        }
    }
    cap->rgb24 = rgb24;
}

