typedef struct {
    char filename[256];
    char timestamp[256];
    char motion[1];
    int gpio;
} MotionData;

static void handleMotion(MotionData *data) {
    char filename[256];
    snprintf(filename, sizeof(filename), "motion_captures/%s.jpg", data->filename);
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Failed to open file %s\n", filename);
        return;
    }
    curl_global_cleanup();
    curl_global_init(CURL_GLOBAL_DEFAULT);
    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Failed to initialize curl\n");
        fclose(fp);
        return;
    }
    struct curl_httppost *post = NULL;
    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, JSON_HEADER);
    headers = curl_slist_append(headers, "Content-Type: application/json");
    post = curl_httppost_new();
    curl_httppost_formdata(post, "filename", data->filename);
    curl_httppost_formdata(post, "timestamp", data->timestamp);
    curl_httppost_formdata(post, "motion", data->motion);
    curl_httppost_formdata(post, "gpio", data->gpio);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_HTTPPOST, post);
    curl_easy_setopt(curl, CURLOPT_URL, CAMERA_MODULE_URL, data->gpio);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, NULL);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, fp);
    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        fclose(fp);
        curl_easy_cleanup(curl);
        return;
    }
    curl_easy_cleanup(curl);
    fclose(fp);
    curl_global_cleanup();
    return;
}

