#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/ioctl.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x4C
#define I2C_REG_ADDR 0x0D
#define I2C_READ 0
#define I2C_WRITE 1
#define I2C_READ_BYTES 2
#define I2C_WRITE_BYTES 2
#define I2C_TIMEOUT 100
#define I2C_READ_TIMEOUT 100
#define I2C_WRITE_TIMEOUT 100
#define I2C_READ_RETRY 3
#define I2C_WRITE_RETRY 3
#define CSV_HEADER "timestamp,distance\n"

int i2c_fd;
int gpio_fd;
int log_fd;
char log_buffer[256];
char log_filename[256];
char timestamp_buffer[256];

void handle_sigint(int signum) {
    if (log_fd != -1) {
        close(log_fd);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (gpio_fd != -1) {
        close(gpio_fd);
    }
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (gpio_init() < 0) {
        perror("pigpio init failed");
        return 1;
    }

    snprintf(log_filename, sizeof(log_filename), "depth_log.csv");
    log_fd = open(log_filename, O_CREAT | O_WRONLY | O_TRUNC, 0644);
    if (log_fd == -1) {
        perror("failed to open log file");
        return 1;
    }

    if (i2c_open(I2C_BUS, I2C_ADDR, I2C_READ | I2C_WRITE) < 0) {
        perror("failed to open I2C bus");
        return 1;
    }

    if (i2c_read(i2c_fd, I2C_REG_ADDR, I2C_READ_BYTES, I2C_TIMEOUT, I2C_READ_RETRY) < 0) {
        perror("failed to read I2C register");
        return 1;
    }

    if (write(log_fd, CSV_HEADER, strlen(CSV_HEADER)) < 0) {
        perror("failed to write CSV header");
        return 1;
    }

    while (1) {
        if (i2c_read(i2c_fd, I2C_REG_ADDR, I2C_READ_BYTES, I2C_READ_TIMEOUT, I2C_READ_RETRY) < 0) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            if (write(log_fd, "error,-1\n", 9) < 0) {
                perror("failed to write error row");
            }
            continue;
        }

        int distance = 0;
        if (read(log_fd, log_buffer, sizeof(log_buffer)) < 0) {
            perror("failed to read log buffer");
            continue;
        }

        sscanf(log_buffer, "%s,%d\n", timestamp_buffer, &distance);

        if (strcmp(timestamp_buffer, "timestamp") == 0) {
            continue;
        }

        if (write(log_fd, timestamp_buffer, strlen(timestamp_buffer)) < 0) {
            perror("failed to write timestamp");
        }

        if (write(log_fd, ",", 1) < 0) {
            perror("failed to write comma");
        }

        if (write(log_fd, &distance, sizeof(distance)) < 0) {
            perror("failed to write distance");
        }

        if (write(log_fd, "\n", 1) < 0) {
            perror("failed to write newline");
        }

        if (write(log_fd, "\r\n", 2) < 0) {
            perror("failed to write newline");
        }

        usleep(100000); // 100ms delay
    }

    return 0;
}

