void handle_sigint(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (gpio_fd != -1) {
        gpioTerminate();
    }
    if (fopen("biometric_log.txt", "a") == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    fclose(fopen("biometric_log.txt", "a"));
    exit(EXIT_SUCCESS);
}

