} SensorData;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        gpiod_device_destroy(&trigger_device);
        gpiod_device_destroy(&echo_device);
        gpiod_device_unref(&echo_fd);
        gpiod_device_unref(&trigger_fd);
        fclose(log_file);
        exit(EXIT_SUCCESS);
    }
}

