#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/sigaction.h>
#include <sys/time.h>
#include <stdint.h>
#include <string.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_SLAVE 0x5A
#define PART_ID 0x00
#define MEAS_RATE0 0x08
#define COMMAND 0x47
#define PS_DATA0 0x24
#define PS_DATA1 0x25
#define BPM_OFFSET 100
#define SAMPLE_INTERVAL 100000  // 100ms

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_SLAVE) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    uint8_t part_id;
    if (i2c_smbus_read_byte_data(i2c_fd, PART_ID, &part_id) < 0) {
        perror("Failed to read PART_ID register");
        close(i2c_fd);
        return 1;
    }

    if (part_id != 0x1A) {
        fprintf(stderr, "Invalid part ID: 0x%02X\n", part_id);
        close(i2c_fd);
        return 1;
    }

    uint8_t meas_rate0;
    if (i2c_smbus_write_byte_data(i2c_fd, MEAS_RATE0, 0x01) < 0) {
        perror("Failed to write MEAS_RATE0 register");
        close(i2c_fd);
        return 1;
    }

    uint8_t command;
    if (i2c_smbus_write_byte_data(i2c_fd, COMMAND, 0x01) < 0) {
        perror("Failed to write COMMAND register");
        close(i2c_fd);
        return 1;
    }

    FILE *csv_fd = fopen("heartrate.csv", "w");
    if (!csv_fd) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return 1;
    }

    while (running) {
        struct timeval tv;
        gettimeofday(&tv, NULL);
        char timestamp[32];
        snprintf(timestamp, sizeof(timestamp), "%ld.%06ld", tv.tv_sec, tv.tv_usec);

        uint16_t ps_data0, ps_data1;
        if (i2c_smbus_read_word_data(i2c_fd, PS_DATA0, &ps_data0) < 0) {
            fprintf(stderr, "Error reading PS_DATA0: %d\n", i2c_smbus_get_errno(i2c_fd));
            continue;
        }
        if (i2c_smbus_read_word_data(i2c_fd, PS_DATA1, &ps_data1) < 0) {
            fprintf(stderr, "Error reading PS_DATA1: %d\n", i2c_smbus_get_errno(i2c_fd));
            continue;
        }

        uint16_t proximity = (ps_data0 << 8) | ps_data1;
        uint32_t bpm = proximity / SAMPLE_INTERVAL + BPM_OFFSET;

        if (fprintf(csv_fd, "%s,%u\n", timestamp, bpm) < 0) {
            perror("Failed to write to CSV file");
            close(i2c_fd);
            fclose(csv_fd);
            return 1;
        }
        fflush(csv_fd);

        usleep(SAMPLE_INTERVAL);
    }

    close(i2c_fd);
    fclose(csv_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define GPIO_PIN 17
#define I2C_TIMEOUT 100
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY 100

#define I2C_DEV "/dev/i2c-" I2C_BUS
#define I2C_RDWR ioctl(fd, I2C_SLAVE, I2C_ADDR)
#define I2C_WRITE fd, I2C_RDWR, I2C_WRITE
#define I2C_READ fd, I2C_RDWR, I2C_READ

#define SYSRANGE_START 0x01
#define RESULT_INTERRUPT_STATUS 0x13
#define RESULT_RANGE_STATUS 0x14
#define SYSTEM_INTERRUPT_CLEAR 0x01

#define DISTANCE_MM_BYTES 10
#define DISTANCE_MM_BYTES_OFFSET 10
#define DISTANCE_MM_BYTES_COUNT 2

#define LOG_FILE "distance_log.txt"
#define LOG_HEADER "timestamp,distance_mm\n"

int i2c_fd;
int gpio_fd;
int sensor_present = 0;
int range_start_written = 0;
int range_interrupt_detected = 0;
int range_status_read = 0;
int distance_mm = 0;
int distance_mm_offset = 0;
int distance_mm_count = 0;
int log_file_fd;
char log_buffer[256];
struct i2c_msg i2c_msg[2];
struct i2c_rdma_params i2c_rdma_params;

void handle_i2c_error(int err) {
    fprintf(stderr, "I2C error: %d\n", err);
    exit(EXIT_FAILURE);
}

void handle_gpio_error(int err) {
    fprintf(stderr, "GPIO error: %d\n", err);
    exit(EXIT_FAILURE);
}

void handle_sensor_absent() {
    fprintf(stderr, "Sensor not present at address 0x29\n");
    exit(EXIT_FAILURE);
}

void handle_timeout() {
    fprintf(stderr, "Timeout while waiting for range interrupt\n");
    exit(EXIT_FAILURE);
}

void handle_sigint(int sig) {
    fprintf(stderr, "SIGINT received, shutting down\n");
    close(i2c_fd);
    close(gpio_fd);
    close(log_file_fd);
    piLock();
    piUnexport(GPIO_PIN);
    piRelease();
    exit(EXIT_SUCCESS);
}

void log_distance(double distance_mm) {
    char timestamp[256];
    struct tm *timeinfo;
    time_t now = time(NULL);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(log_buffer, sizeof(log_buffer), "%s,%f\n", timestamp, distance_mm);
    write(log_file_fd, log_buffer, strlen(log_buffer));
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    piLock();
    piUnexport(GPIO_PIN);
    piRelease();

    gpio_fd = piGPIO(GPIO_PIN);
    if (gpio_fd < 0) {
        handle_gpio_error(gpio_fd);
    }

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        handle_i2c_error(errno);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        handle_i2c_error(errno);
    }

    sensor_present = 1;
    if (!sensor_present) {
        handle_sensor_absent();
    }

    piLock();
    piExport(GPIO_PIN);
    piSetPullUp(gpio_fd, GPIO_PIN, 1);
    piSetMode(gpio_fd, GPIO_MODE_EDGE);
    piSetCallback(gpio_fd, GPIO_EDGE_FALL, handle_gpio_edge_fall);
    piRelease();

    while (1) {
        if (!range_start_written) {
            range_start_written = 1;
            if (I2C_WRITE(i2c_fd, SYSRANGE_START, 0) < 0) {
                handle_i2c_error(errno);
            }
        }

        if (!range_interrupt_detected) {
            range_interrupt_detected = 1;
            if (I2C_READ(i2c_fd, RESULT_INTERRUPT_STATUS, 0) < 0) {
                handle_i2c_error(errno);
            }
            if (i2c_msg[0].addr == I2C_ADDR && i2c_msg[0].len == 1) {
                if (i2c_msg[0].data[0] & 0x01) {
                    range_interrupt_detected = 0;
                    if (I2C_READ(i2c_fd, RESULT_RANGE_STATUS, 0) < 0) {
                        handle_i2c_error(errno);
                    }
                    if (i2c_msg[0].addr == I2C_ADDR && i2c_msg[0].len == 16) {
                        if (range_status_read = 1) {
                            if (I2C_READ(i2c_fd, RESULT_RANGE_STATUS, 0) < 0) {
                                handle_i2c_error(errno);
                            }
                            if (i2c_msg[0].addr == I2C_ADDR && i2c_msg[0].len == 16) {
                                memcpy(&distance_mm, i2c_msg[0].data + DISTANCE_MM_BYTES_OFFSET, DISTANCE_MM_BYTES_COUNT);
                                distance_mm = (distance_mm & 0xFFFF) * 1000;
                                log_distance(distance_mm / 1000.0);
                            }
                        }
                    }
                }
            }
        }

        usleep(I2C_TIMEOUT * 1000);
    }

    return 0;
}

void handle_gpio_edge_fall(int gpio, int level, int tick) {
    if (level == 0) {
        piLock();
        piSetMode(gpio_fd, GPIO_MODE_INPUT);
        piRelease();
    } else {
        piLock();
        piSetMode(gpio_fd, GPIO_MODE_OUTPUT);
        piSetPullUp(gpio_fd, GPIO_PIN, 0);
        piRelease();
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x45
#define DISTANCE_RESULT_SIZE 16
#define TIMESTAMP_SIZE 20
#define TIMESTAMP_BUF_SIZE (DISTANCE_RESULT_SIZE + TIMESTAMP_SIZE + 1)

volatile int running = 1;

void handle_sigint(int signum) {
    if (running) {
        printf("Stopping...\n");
        pi_close();
        close(i2c_fd);
        close(log_file_fd);
        running = 0;
    }
}

int main() {
    struct timespec ts;
    char timestamp[TIMESTAMP_BUF_SIZE];
    char distance_result[DISTANCE_RESULT_SIZE];
    int i2c_fd;
    int log_file_fd;
    int pi_fd;
    int distance_result_read;
    int i2c_error;
    int log_file_error;
    int pi_error;

    // Initialize pigpio
    if (pi_init(NULL) < 0) {
        perror("pigpio init");
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Open I2C bus 1
    i2c_fd = i2c_open(I2C_BUS, I2C_ADDR);
    if (i2c_fd < 0) {
        perror("i2c_open");
        return 1;
    }

    // Open log file
    log_file_fd = open("distance_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_file_fd < 0) {
        perror("open log file");
        return 1;
    }

    // Main loop
    while (running) {
        // Get current time
        clock_gettime(CLOCK_MONOTONIC, &ts);
        strftime(timestamp, TIMESTAMP_BUF_SIZE, "%Y-%m-%d %H:%M:%S", localtime(&ts));

        // Trigger measurement
        pi_write(pi_fd, 0x00, 0x01);

        // Wait 50 ms
        nanosleep((const struct timespec[]){{0, 50000000L}}, NULL);

        // Read distance result
        distance_result_read = pi_read(pi_fd, 0x00, DISTANCE_RESULT_SIZE);
        if (distance_result_read < 0) {
            i2c_error = pi_error;
            fprintf(stderr, "Error reading distance result: %s\n", strerror(pi_error));
            continue;
        }

        // Read 16-bit distance result
        int distance_mm = (distance_result[0] << 8) | distance_result[1];
        if (distance_mm < 0 || distance_mm > 65535) {
            fprintf(stderr, "Invalid distance result: %d\n", distance_mm);
            continue;
        }

        // Log and print
        snprintf(distance_result, DISTANCE_RESULT_SIZE, "%d", distance_mm);
        snprintf(timestamp, TIMESTAMP_BUF_SIZE, "%s, %s", timestamp, distance_result);
        fprintf(log_file_fd, "%s\n", timestamp);
        printf("%s\n", timestamp);

        // Wait 200 ms
        nanosleep((const struct timespec[]){{0, 20000000L}}, NULL);
    }

    // Cleanup
    pi_close();
    close(i2c_fd);
    close(log_file_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <poll.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define LOG_FILE "obstacle_log.txt"
#define LOG_FORMAT "%Y-%m-%d %H:%M:%S,%d,%d\n"

void handle_sigint(int sig) {
    printf("Received SIGINT, shutting down...\n");
    pi_close();
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (pi_init() < 0) {
        perror("pigpio init failed");
        return 1;
    }

    if (pi_set_mode(SENSOR_1_GPIO, PI_INPUT) < 0) {
        perror("Setting GPIO 17 to input failed");
        return 1;
    }

    if (pi_set_mode(SENSOR_2_GPIO, PI_INPUT) < 0) {
        perror("Setting GPIO 18 to input failed");
        return 1;
    }

    int fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        perror("Opening log file failed");
        return 1;
    }

    while (1) {
        struct pollfd sensors[2];
        sensors[0].fd = pi_gpio_fd(SENSOR_1_GPIO);
        sensors[1].fd = pi_gpio_fd(SENSOR_2_GPIO);
        sensors[0].events = POLLIN;
        sensors[1].events = POLLIN;

        int result = poll(sensors, 2, 100);
        if (result < 0) {
            perror("poll failed");
            continue;
        }

        if (result == 0) {
            printf("No data available\n");
            continue;
        }

        int sensor1 = pi_read(SENSOR_1_GPIO);
        int sensor2 = pi_read(SENSOR_2_GPIO);

        if (sensor1 < 0 || sensor2 < 0) {
            fprintf(stderr, "Error reading sensor 1 or 2\n");
            continue;
        }

        struct timeval now;
        gettimeofday(&now, NULL);
        fprintf(fd, LOG_FORMAT, now.tv_sec, now.tv_usec / 1000000.0, sensor1, sensor2);
        fflush(fd);

        if (sensor1 == 0) {
            printf("Sensor 1 detected object at %ld.%06ld\n", now.tv_sec, now.tv_usec / 1000000.0);
        } else {
            printf("Sensor 1 no object detected at %ld.%06ld\n", now.tv_sec, now.tv_usec / 1000000.0);
        }

        if (sensor2 == 0) {
            printf("Sensor 2 detected object at %ld.%06ld\n", now.tv_sec, now.tv_usec / 1000000.0);
        } else {
            printf("Sensor 2 no object detected at %ld.%06ld\n", now.tv_sec, now.tv_usec / 1000000.0);
        }
    }

    pi_close();
    close(fd);
    return 0;
}

