#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x6A
#define LED_GPIO 17
#define THRESHOLD 100
#define LOG_FILE "tof_log.txt"
#define LOG_FMT "%ld %f\n"

int i2c_fd;
int gpio_fd;
int sensor_present = 0;
int sensor_init = 0;
int sensor_error = 0;
int sensor_init_error = 0;
int sensor_absent = 0;
int sensor_bus_error = 0;

void sigint_handler(int sig) {
    if (sensor_init) {
        gpioTerminate();
        close(gpio_fd);
    }
    if (i2c_fd > 0) {
        close(i2c_fd);
    }
    exit(EXIT_SUCCESS);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        exit(EXIT_FAILURE);
    }
    THRESHOLD = atoi(argv[1]);

    signal(SIGINT, sigint_handler);

    if (pigpio Haram) {
        fprintf(stderr, "pigpio init failed\n");
        exit(EXIT_FAILURE);
    }

    gpio_fd = gpioOpen(LED_GPIO);
    if (gpio_fd < 0) {
        fprintf(stderr, "gpioOpen failed\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(gpio_fd, PI_OUTPUT)) {
        fprintf(stderr, "gpioSetMode failed\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetPullUpDnControl(gpio_fd, PI_DISABLE)) {
        fprintf(stderr, "gpioSetPullUpDnControl failed\n");
        exit(EXIT_FAILURE);
    }

    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open failed\n");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl failed\n");
        exit(EXIT_FAILURE);
    }

    if (sensorInit()) {
        fprintf(stderr, "sensorInit failed\n");
        exit(EXIT_FAILURE);
    }

    while (1) {
        if (sensorRead()) {
            if (distance < THRESHOLD) {
                gpioWrite(gpio_fd, 1);
            } else {
                gpioWrite(gpio_fd, 0);
            }
        }

        usleep(500000); // 50 ms delay
    }

    return 0;
}

int sensorInit() {
    if (sensorInitError) {
        return 1;
    }

    if (ioctl(i2c_fd, I2C_RDWR, 0) < 0) {
        sensor_bus_error = 1;
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        sensor_bus_error = 1;
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SMBUS_READ, 0x00, 0x00, 0x00, 0x00, 0x00) < 0) {
        sensor_bus_error = 1;
        return 1;
    }

    if (sensor_bus_error) {
        sensor_absent = 1;
        return 1;
    }

    if (sensor_absent) {
        return 1;
    }

    if (sensorInitError) {
        return 1;
    }

    return 0;
}

int sensorRead() {
    if (!sensor_init) {
