#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x50
#define CMD_START 0x0A
#define CMD_LENGTH 0x01
#define CMD_TYPE 0x01
#define CMD_END 0x00
#define CMD_SIZE 4
#define CMD_START_BYTE 0x50
#define CMD_RESPONSE_SIZE 15
#define CMD_RESPONSE_OFFSET 11
#define CMD_RESPONSE_SIZE_BYTES 2
#define MAX_SAMPLES 10
#define LOG_FILE "/intrusion_log.txt"
#define LOG_FORMAT "%Y-%m-%d %H:%M:%S,%d"

void handle_i2c_error(int fd, int err) {
    if (err < 0) {
        perror("i2c ioctl error");
        close(fd);
        exit(EXIT_FAILURE);
    }
}

void handle_read_error(int fd, int err) {
    if (err < 0) {
        perror("i2c read error");
        close(fd);
        exit(EXIT_FAILURE);
    }
}

void handle_write_error(int fd, int err) {
    if (err < 0) {
        perror("i2c write error");
        close(fd);
        exit(EXIT_FAILURE);
    }
}

void handle_sigint(int sig) {
    if (close(i2c_fd) < 0) {
        perror("close i2c fd error");
        exit(EXIT_FAILURE);
    }
    if (close(log_fd) < 0) {
        perror("close log fd error");
        exit(EXIT_FAILURE);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct i2c_msg i2c_msg;
    struct i2c_rdma_request i2c_rdma_request;
    struct i2c_msg i2c_msg_reply;
    int i2c_fd;
    int samples = 0;
    int total_distance = 0;
    int log_fd;
    char log_buffer[256];
    time_t timestamp;
    struct tm *timeinfo;
    char log_entry[256];

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("open i2c dev error");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl i2c slave error");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, handle_sigint);

    log_fd = open(LOG_FILE, O_CREAT | O_WRONLY | O_APPEND);
    if (log_fd < 0) {
        perror("open log file error");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        samples = 0;
        total_distance = 0;

        for (int i = 0; i < MAX_SAMPLES; i++) {
            i2c_msg.addr = I2C_ADDR;
            i2c_msg.flags = I2C_MSG_READ | I2C_MSG_REPEATED_START;
            i2c_msg.len = CMD_RESPONSE_SIZE;
            i2c_msg.buf = malloc(CMD_RESPONSE_SIZE);

            i2c_rdma_request.request = I2C_RDMA_READ;
            i2c_rdma_request.offset = 0;
            i2c_rdma_request.len = CMD_RESPONSE_SIZE;
            i2c_rdma_request.addr = i2c_msg.addr;

            if (ioctl(i2c_fd, I2C_RDWR, &i2c_rdma_request, &i2c_msg) < 0) {
                handle_read_error(i2c_fd, errno);
            }

            if (i2c_msg.flags & I2C_MSG_REPEATED_START) {
                i2c_msg.flags = I2C_MSG_READ;
                i2c_rdma_request.request = I2C_RDMA_READ;
                i2c_rdma_request.offset = 0;
                i2c_rdma_request.len = CMD_RESPONSE_SIZE;
                i2c_rdma_request.addr = i2c_msg.addr;

                if (ioctl(i2c_fd, I2C_RDWR, &i2c_rdma_request, &i2c_msg) < 0) {
                    handle_read_error(i2c_fd, errno);
                }

                free(i2c_msg.buf);
                continue;
            }

            if (i2c_msg.buf == NULL) {
                perror("malloc i2c msg buffer error");
                close(i2c_fd);
                close(log_fd);
                exit(EXIT_FAILURE);
            }

            if (i2c_msg.buf[0] != CMD_START_BYTE) {
                fprintf(stderr, "Invalid response from sensor\n");
                free(i2c_msg.buf);
                continue;
            }

            total_distance += ((i2c_msg.buf[CMD_RESPONSE_OFFSET] << 8) | i2c_msg.buf[CMD_RESPONSE_OFFSET + 1]);
            samples++;

            free(i2c_msg.buf);
        }

        if (samples > 0) {
            timestamp = time(NULL);
            timeinfo = localtime(&timestamp);
            strftime(log_buffer, sizeof(log_buffer), LOG_FORMAT, timeinfo);
            snprintf(log_entry, sizeof(log_entry), "%s,%d", log_buffer, total_distance / samples);
            if (write(log_fd, log_entry, strlen(log_entry)) < 0) {
                perror("write log file error");
                close(i2c_fd);
                close(log_fd);
                exit(EXIT_FAILURE);
            }
            printf("Average distance: %d mm\n", total_distance / samples);
        }

        usleep(100000); // 100 ms delay
    }

    close(i2c_fd);
    close(log_fd);
    return 0;
}

