#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x44
#define I2C_CHANNEL 0
#define I2C_SENSOR 0

#define LOG_FILE "sensor_data.log"

#define ERROR_SENSOR_NOT_PRESENT "Sensor not present on I2C bus."
#define ERROR_I2C_BUS_ERROR "I2C bus error occurred."
#define ERROR_I2C_CONNECTION_FAILED "Failed to connect to I2C sensor."

void handle_sigint(int signum) {
    printf("Graceful shutdown initiated.\n");
    pi_close();
    exit(0);
}

int main() {
    struct i2c_client_data client_data;
    int i2c_fd;
    int sensor_present = 0;
    int error = 0;
    int channel = 0;
    int ambient_light = 0;
    int distance = 0;
    int error_flags = 0;

    signal(SIGINT, handle_sigint);

    if ((i2c_fd = i2c_open(I2C_BUS, I2C_ADDR)) < 0) {
        perror("i2c_open");
        return 1;
    }

    if (i2c_client_data.i2c_msg.addr == 0) {
        i2c_client_data.i2c_msg.addr = I2C_ADDR;
    }

    if (i2c_client_data.i2c_msg.flags == 0) {
        i2c_client_data.i2c_msg.flags = I2C_CLIENT_READ | I2C_CLIENT_STOP;
    }

    if (i2c_client_data.i2c_msg.len == 0) {
        i2c_client_data.i2c_msg.len = 1;
    }

    if (i2c_client_data.i2c_msg.buf == NULL) {
        i2c_client_data.i2c_msg.buf = (char *)malloc(i2c_client_data.i2c_msg.len);
    }

    while (1) {
        if (i2c_read(i2c_fd, &i2c_client_data) < 0) {
            if (error) {
                printf("Error: %s\n", ERROR_I2C_CONNECTION_FAILED);
                error = 0;
            } else {
                printf("Error: %s\n", ERROR_I2C_BUS_ERROR);
                error = 1;
            }
            continue;
        }

        if (i2c_client_data.i2c_msg.flags & I2C_CLIENT_STOP) {
            break;
        }

        if (i2c_client_data.i2c_msg.flags & I2C_CLIENT_READ) {
            if (i2c_client_data.i2c_msg.len == 1) {
                if (i2c_client_data.i2c_msg.buf[0] == 0x00) {
                    sensor_present = 1;
                } else {
                    sensor_present = 0;
                }
            } else if (i2c_client_data.i2c_msg.len == 2) {
                if (i2c_client_data.i2c_msg.buf[0] == 0x00) {
                    ambient_light = i2c_client_data.i2c_msg.buf[1];
                } else {
                    ambient_light = 0;
                }
            } else if (i2c_client_data.i2c_msg.len == 3) {
                if (i2c_client_data.i2c_msg.buf[0] == 0x00) {
                    distance = i2c_client_data.i2c_msg.buf[1];
                    error_flags = i2c_client_data.i2c_msg.buf[2];
                } else {
                    distance = 0;
                    error_flags = 0;
                }
            }
        }

        if (sensor_present) {
            printf("Distance: %d, Ambient Light: %d, Error Flags: %d\n", distance, ambient_light, error_flags);
            if (fopen(LOG_FILE, "a") == NULL) {
                perror("fopen");
                continue;
            }
            fprintf(stderr, "Writing to %s...\n", LOG_FILE);
            if (fprintf(stderr, "Distance: %d, Ambient Light: %d, Error Flags: %d\n", distance, ambient_light, error_flags) < 0) {
                perror("fprintf");
            }
            if (fclose(stderr) < 0) {
                perror("fclose");
            }
        }

        usleep(500000); // 500 ms delay
    }

    if (i2c_client_data.i2c_msg.buf) {
        free(i2c_client_data.i2c_msg.buf);
    }

    i2c_close(i2c_fd);
    pi_close();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>

#define PULSE_US 10000  // 10 microseconds
#define MAX_RANGE 38000  // 38 cm in microseconds
#define MAX_TIMEOUT 200000 // 200 ms in microseconds

int main() {
    if (gpioInitialise() < 0) {
        perror("pigpio init failed");
        return 1;
    }

    // Set up GPIO 17 (trigger) and 18 (echo)
    if (gpioSetMode(17, PI_OUTPUT) < 0) {
        perror("Failed to set GPIO 17 to output");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(18, PI_INPUT) < 0) {
        perror("Failed to set GPIO 18 to input");
        gpioTerminate();
        return 1;
    }

    // Set up echo rising and falling edge timeout
    if (gpioSetTimer(18, gpioRisingEdge, 0, MAX_TIMEOUT) < 0) {
        perror("Failed to set echo rising edge timeout");
        gpioTerminate();
        return 1;
    }
    if (gpioSetTimer(18, gpioFallingEdge, 0, MAX_TIMEOUT) < 0) {
        perror("Failed to set echo falling edge timeout");
        gpioTerminate();
        return 1;

    // Set up 1 kOhm resistor on echo line
    gpioSetPullUpDown(18, PI_OFF);

    // Set up 10 microsecond trigger pulse
    if (gpioWrite(17, 1) < 0) {
        perror("Failed to set GPIO 17 to high");
        gpioTerminate();
        return 1;
    }
    usleep(PULSE_US);
    if (gpioWrite(17, 0) < 0) {
        perror("Failed to set GPIO 17 to low");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Wait for echo rising edge
        if (gpioWaitForEdge(18, PI_RISING) < 0) {
            perror("Echo rising edge timeout");
            gpioTerminate();
            return 1;
        }

        // Wait for echo falling edge
        if (gpioWaitForEdge(18, PI_FALLING) < 0) {
            perror("Echo falling edge timeout");
            gpioTerminate();
            return 1;
        }

        // Get pulse width in microseconds
        int pulse_us = gpioTick() - gpioTickAtLastEvent();

        // Check for invalid pulse duration
        if (pulse_us <= 0 || pulse_us > MAX_RANGE) {
            printf("Invalid pulse duration: %d\n", pulse_us);
            continue;
        }

        // Compute distance in cm
        double distance = (pulse_us * 0.0343) / 2.0;

        // Log reading with timestamp
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        printf("%d-%02d-%02d %02d:%02d:%02d %f cm\n", tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec, distance);

        // Wait for 1 second
        usleep(1000000);
    }

    // Shutdown gracefully on SIGINT/SIGTERM
    signal(SIGINT, [](int) { gpioTerminate(); });
    signal(SIGTERM, [](int) { gpioTerminate(); });

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO17 17
#define GPIO18 18
#define POLL_INTERVAL 100000  // 100 ms

int main() {
    int chip_fd, line_fd, err;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    struct timespec ts;
    char buffer[256];
    FILE *log_file;

    // Open the GPIO chip
    chip_fd = gpiod_chip_open("/dev/gpiod");
    if (chip_fd < 0) {
        perror("gpiod_chip_open");
        return 1;
    }
    chip = gpiod_chip_get_chip(chip_fd);
    if (!chip) {
        perror("gpiod_chip_get_chip");
        gpiod_chip_close(chip_fd);
        return 1;
    }

    // Open the GPIO line
    line_fd = gpiod_chip_request_line(chip, GPIO17);
    if (line_fd < 0) {
        perror("gpiod_chip_request_line");
        gpiod_chip_close(chip_fd);
        return 1;
    }
    line = gpiod_chip_get_line(chip_fd, line_fd);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip_fd);
        return 1;
    }

    // Set the line to input mode
    err = gpiod_line_request_mode(line, GPIOD_MODE_INPUT);
    if (err < 0) {
        perror("gpiod_line_request_mode");
        gpiod_chip_close(chip_fd);
        return 1;
    }

    // Set the line to active-low
    err = gpiod_line_request_edge(line, GPIOD_EDGE_FALLING);
    if (err < 0) {
        perror("gpiod_line_request_edge");
        gpiod_chip_close(chip_fd);
        return 1;
    }

    // Open the buzzer line
    line_fd = gpiod_chip_request_line(chip, GPIO18);
    if (line_fd < 0) {
        perror("gpiod_chip_request_line");
        gpiod_chip_close(chip_fd);
        return 1;
    }
    line = gpiod_chip_get_line(chip_fd, line_fd);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip_fd);
        return 1;
    }

    // Set the buzzer line to output mode
    err = gpiod_line_request_mode(line, GPIOD_MODE_OUTPUT);
    if (err < 0) {
        perror("gpiod_line_request_mode");
        gpiod_chip_close(chip_fd);
        return 1;
    }

    // Open the log file
    log_file = fopen("obstacle_log.txt", "a");
    if (!log_file) {
        perror("fopen");
        gpiod_chip_close(chip_fd);
        return 1;
    }

    // Initialize the buzzer to off
    err = gpiod_line_set_value(line, 0);
    if (err < 0) {
        perror("gpiod_line_set_value");
        gpiod_chip_close(chip_fd);
        fclose(log_file);
        return 1;
    }

    // Set up the timer for polling
    clock_gettime(CLOCK_MONOTONIC, &ts);
    ts.tv_sec += 0;
    ts.tv_nsec = 0;
    ts.tv_nsec += POLL_INTERVAL * 1000000; // 100 ms

    // Main loop
    while (1) {
        // Read the sensor line
        err = gpiod_line_request_value(line, &buffer[0]);
        if (err < 0) {
            perror("gpiod_line_request_value");
            gpiod_chip_close(chip_fd);
            fclose(log_file);
            return 1;
        }

        // Check if the sensor line changed state
        if (buffer[0] == 0 && buffer[0] == 1) {
            // Log the state transition
            char timestamp[256];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%f", &ts);
            fprintf(log_file, "%s: Obstacle detected\n", timestamp);
        }

        // Set the buzzer line based on the sensor line state
        if (buffer[0] == 0) {
            err = gpiod_line_set_value(line, 0);
        } else {
            err = gpiod_line_set_value(line, 1);
        }
        if (err < 0) {
            perror("gpiod_line_set_value");
            gpiod_chip_close(chip_fd);
            fclose(log_file);
            return 1;
        }

        // Update the timer
        clock_gettime(CLOCK_MONOTONIC, &ts);
        ts.tv_sec += 0;
        ts.tv_nsec = 0;
        ts.tv_nsec += POLL_INTERVAL * 1000000; // 100 ms

        // Check for SIGINT or SIGTERM
        if (signal(SIGINT, [](int sig) {
            gpiod_chip_close(chip_fd);
            fclose(log_file);
            return 0;
        }) == SIG_ERR) {
            perror("signal");
            return 1;
        }
        if (signal(SIGTERM, [](int sig) {
            gpiod_chip_close(chip_fd);
            fclose(log_file);
            return 0;
        }) == SIG_ERR) {
            perror("signal");
            return 1;
        }
    }

    // Graceful shutdown
    gpiod_chip_close(chip_fd);
    fclose(log_file);
    return 0;
}

