#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <linux/i2c.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x45
#define LED_PIN 18
#define LED_PIN_ON 1
#define LED_PIN_OFF 0
#define MAX_DISTANCE 500
#define MIN_DISTANCE 50
#define MAX_BLINK 10
#define MIN_BLINK 1

int i2c_fd;
int i2c_handle;
int i2c_attempts = 0;
int i2c_retry_delay = 10;

void handle_i2c_error(int err) {
    if (err < 0) {
        printf("I2C error: %d\n", err);
        if (i2c_attempts < 3) {
            printf("Retrying I2C read/write...\n");
            usleep(i2c_retry_delay);
            i2c_attempts++;
            ioctl(i2c_fd, I2C_RDWR, &i2c_handle);
        } else {
            printf("Failed to connect to I2C bus after 3 attempts. Exiting...\n");
            exit(EXIT_FAILURE);
        }
    }
}

void handle_sensor_absent() {
    printf("Sensor not found. Exiting...\n");
    exit(EXIT_FAILURE);
}

void handle_bus_error() {
    printf("Bus error occurred. Exiting...\n");
    exit(EXIT_FAILURE);
}

void handle_sigint(int signum) {
    printf("SIGINT received. Shutting down...\n");
    gpioTerminate();
    gpioWrite(LED_PIN, LED_PIN_OFF);
    close(i2c_fd);
    exit(EXIT_SUCCESS);
}

int main() {
    struct i2c_client_data i2c_data;
    i2c_data.addr = I2C_ADDR;
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, i2c_data.addr) < 0) {
        handle_i2c_error(errno);
