#define I2C_SLAVE 0x3 << 3
#define I2C_RESTART 0x1 << 3
#define I2C_WRITE 0x0 << 3
#define I2C_READ 0x1 << 3
#define I2C_STOP 0x2 << 3
#define I2C_ACK 0x0
#define I2C_NACK 0x1
#define I2C_MEAS_TRIGGER 0x01
#define I2C_MEAS_STATUS 0x06
#define I2C_DIST_HIGH 0x08
#define I2C_DIST_LOW 0x09

#define I2C_BUS 1
#define I2C_TIMEOUT 500000  // 50 ms in microseconds

typedef struct {
    char timestamp[26];
    int distance_mm;
} DistanceData;

void i2c_read_register(int fd, unsigned char reg, unsigned char *data, int len) {
    unsigned char buf[1];
    buf[0] = reg;
    if (ioctl(fd, I2C_SLAVE, 0x49, I2C_WRITE | I2C_ACK) < 0) {
        perror("ioctl I2C_SLAVE");
        return;
    }
    if (write(fd, buf, 1) != 1) {
        perror("write");
        return;
    }
    if (ioctl(fd, I2C_READ, reg, len) < 0) {
        perror("ioctl I2C_READ");
        return;
    }
    if (read(fd, data, len) != len) {
        perror("read");
        return;
    }
}

void i2c_read_distance(int fd, unsigned char *distance_mm) {
    unsigned char dist_high, dist_low;
    i2c_read_register(fd, I2C_DIST_HIGH, &dist_high, 1);
    i2c_read_register(fd, I2C_DIST_LOW, &dist_low, 1);
    *distance_mm = (dist_high << 8) | dist_low;
}

int main() {
    int fd;
    struct timeval tv;
    DistanceData data;
    char timestamp[26];
    char csv_line[100];
    char csv_file[50] = "distance_log.csv";

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, 0x49, I2C_WRITE | I2C_ACK) < 0) {
        perror("ioctl I2C_SLAVE");
        goto close;
    }

    while (1) {
        gettimeofday(&tv, NULL);
        strftime(timestamp, 26, "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));
        snprintf(csv_line, sizeof(csv_line), "%s,%d", timestamp, 0);

        if (write(fd, &I2C_MEAS_TRIGGER, 1) != 1) {
            perror("write");
            continue;
        }

        tv.tv_sec = 0;
        tv.tv_usec = I2C_TIMEOUT;
        if (select(0, NULL, NULL, NULL, &tv) == 0) {
            fprintf(stderr, "Timeout waiting for data-ready\n");
            continue;
        }

        if (read(fd, &data.distance_mm, sizeof(data.distance_mm)) != 1) {
            perror("read");
            continue;
        }

        snprintf(csv_line + strlen(timestamp), sizeof(csv_line) - strlen(timestamp), ",%d", data.distance_mm);
        if (write(fd, &I2C_MEAS_STATUS, 1) != 1) {
            perror("write");
            continue;
        }

        if (read(fd, &data.distance_mm, sizeof(data.distance_mm)) != 1) {
            perror("read");
            continue;
        }

        snprintf(csv_line + strlen(timestamp), sizeof(csv_line) - strlen(timestamp), ",%d", data.distance_mm);
        if (write(csv_file, csv_line, strlen(csv_line)) != strlen(csv_line)) {
            perror("write");
            continue;
        }

        if (close(fd) < 0) {
            perror("close");
            continue;
        }

        fd = open("/dev/i2c-1", O_RDWR);
        if (fd < 0) {
            perror("open");
            continue;
        }

        if (ioctl(fd, I2C_SLAVE, 0x49, I2C_WRITE | I2C_ACK) < 0) {
            perror("ioctl I2C_SLAVE");
            goto close;
        }
    }

close:
    if (close(fd) < 0) {
        perror("close");
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <string.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x29
#define I2C_REG_ZONE_START 0x00
#define I2C_REG_ZONE_END 0x0F
#define I2C_REG_CONTROL 0x00
#define I2C_REG_CONTROL_ZONE_GRID 0x0F
#define I2C_REG_CONTROL_ZONE_GRID_8X8 0x08

#define I2C_ZONE_COUNT 64

int main() {
    int fd;
    struct iocb iocb;
    struct iocmt iocmt;
    char buffer[2];
    int zone_distance[I2C_ZONE_COUNT];
    int zone_index;

    if ((fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("open");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return 1;
    }

    memset(&iocb, 0, sizeof(iocb));
    iocb.ioctlen = 2;
    iocb.ioctmp = buffer;

    memset(&iocmt, 0, sizeof(iocmt));
    iocmt.ioctmp = buffer;

    iocmt.ioctmp[0] = I2C_REG_ZONE_START;
    iocmt.ioctmp[1] = 0;
    if (ioctl(fd, I2C_SMBHCTL1, &iocmt) < 0) {
        perror("ioctl I2C_SMBHCTL1");
        close(fd);
        return 1;
    }

    iocmt.ioctmp[0] = I2C_REG_ZONE_END;
    iocmt.ioctmp[1] = 0;
    if (ioctl(fd, I2C_SMBHCTL1, &iocmt) < 0) {
        perror("ioctl I2C_SMBHCTL1");
        close(fd);
        return 1;
    }

    iocmt.ioctmp[0] = I2C_REG_CONTROL;
    iocmt.ioctmp[1] = I2C_REG_CONTROL_ZONE_GRID_8X8;
    if (ioctl(fd, I2C_SMBHCTL1, &iocmt) < 0) {
        perror("ioctl I2C_SMBHCTL1");
        close(fd);
        return 1;
    }

    while (1) {
        for (zone_index = 0; zone_index < I2C_ZONE_COUNT; zone_index++) {
            iocmt.ioctmp[0] = I2C_REG_ZONE_START + zone_index;
            iocmt.ioctmp[1] = 0;
            if (ioctl(fd, I2C_SMBHCTL1, &iocmt) < 0) {
                perror("ioctl I2C_SMBHCTL1");
                close(fd);
                return 1;
            }
            zone_distance[zone_index] = (int)(buffer[0] << 8 | buffer[1]);
        }

        for (zone_index = 0; zone_index < I2C_ZONE_COUNT; zone_index++) {
            printf("Zone %d: %d mm\n", zone_index, zone_distance[zone_index]);
        }

        sleep(500);
    }

    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x4C
#define I2C_TIMEOUT 100
#define I2C_RETRIES 3
#define I2C_DELAY 10

#define TOF_SENSOR 0x00
#define TOF_MEASUREMENT 0x00
#define TOF_RESULT 0x01
#define TOF_RESULT_MSB 0x02
#define TOF_RESULT_LSB 0x03
#define TOF_RESULT_MSB_MSB 0x04
#define TOF_RESULT_LSB_LSB 0x05
#define TOF_RESULT_MSB_LSB 0x06
#define TOF_RESULT_LSB_MSB 0x07
#define TOF_RESULT_MSB_MSB_LSB 0x08
#define TOF_RESULT_LSB_LSB_MSB 0x09
#define TOF_RESULT_MSB_LSB_LSB_MSB 0x0A
#define TOF_RESULT_LSB_LSB_MSB_LSB 0x0B
#define TOF_RESULT_MSB_LSB_LSB_MSB_LSB 0x0C
#define TOF_RESULT_LSB_LSB_MSB_LSB_MSB 0x0D
#define TOF_RESULT_MSB_LSB_LSB_MSB_LSB_MSB 0x0E
#define TOF_RESULT_LSB_LSB_MSB_LSB_MSB_LSB 0x0F

int i2c_fd;
int i2c_result;
int i2c_retry = 0;

void handle_sensor_absent() {
    printf("Sensor not found. Exiting...\n");
    exit(EXIT_FAILURE);
}

void handle_bus_error() {
    printf("Bus error. Exiting...\n");
    exit(EXIT_FAILURE);
}

void handle_i2c_error() {
    if (i2c_retry < I2C_RETRIES) {
        printf("I2C read/write failed. Retrying in %d ms...\n", I2C_DELAY);
        usleep(I2C_DELAY * 1000);
        i2c_retry++;
    } else {
        printf("I2C read/write failed after %d retries. Exiting...\n", I2C_RETRIES);
        exit(EXIT_FAILURE);
    }
}

void handle_sigint() {
    printf("Received SIGINT. Exiting...\n");
    exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (gpio_init() < 0) {
        perror("pigpio init failed");
        exit(EXIT_FAILURE);
    }

    if ((i2c_fd = i2c_open(I2C_BUS, I2C_ADDR)) < 0) {
        handle_bus_error();
    }

    while (1) {
        if ((i2c_result = i2c_read(i2c_fd, TOF_SENSOR, I2C_TIMEOUT)) < 0) {
            handle_i2c_error();
        } else if (i2c_result == 0) {
            handle_sensor_absent();
        } else {
            unsigned int result = 0;
            if (i2c_read(i2c_fd, TOF_RESULT_MSB, I2C_TIMEOUT) < 0) {
                handle_i2c_error();
            } else if (i2c_result == 0) {
                handle_sensor_absent();
            } else {
                result |= (i2c_read(i2c_fd, TOF_RESULT_MSB_MSB, I2C_TIMEOUT) << 8) & 0xFF00;
                if (i2c_read(i2c_fd, TOF_RESULT_LSB_MSB, I2C_TIMEOUT) < 0) {
                    handle_i2c_error();
                } else if (i2c_result == 0) {
                    handle_sensor_absent();
                } else {
                    result |= (i2c_read(i2c_fd, TOF_RESULT_LSB_MSB_LSB, I2C_TIMEOUT) << 16) & 0xFFFF00;
                    if (i2c_read(i2c_fd, TOF_RESULT_LSB_MSB_LSB_MSB, I2C_TIMEOUT) < 0) {
                        handle_i2c_error();
                    } else if (i2c_result == 0) {
                        handle_sensor_absent();
                    } else {
                        result |= (i2c_read(i2c_fd, TOF_RESULT_LSB_MSB_LSB_MSB_LSB, I2C_TIMEOUT) << 24) & 0xFFFFFF00;
                        if (i2c_read(i2c_fd, TOF_RESULT_LSB_MSB_LSB_MSB_LSB_MSB, I2C_TIMEOUT) < 0) {
                            handle_i2c_error();
                        } else if (i2c_result == 0) {
                            handle_sensor_absent();
                        } else {
                            result |= (i2c_read(i2c_fd, TOF_RESULT_LSB_MSB_LSB_MSB_LSB_MSB, I2C_TIMEOUT) << 32) & 0xFFFFFFFF;
                            if (i2c_result == 0) {
                                handle_sensor_absent();
                            } else {
                                printf("Distance: %d mm\n", result);
                            }
                        }
                    }
                }
            }
        }
        usleep(100 * 1000);
    }

    i2c_close(i2c_fd);
    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
