#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>

#define TRIG_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22
#define SPEED_OF_SOUND 34300
#define DISTANCE_THRESHOLD 30
#define MEASUREMENT_INTERVAL 100000  // 100 ms

int main() {
    if (gpioInitialise() < 0) {
        perror("pigpio init failed");
        return 1;
    }

    // Set up GPIO pins
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        perror("TRIG_PIN mode failed");
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        perror("ECHO_PIN mode failed");
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        perror("BUZZER_PIN mode failed");
        return 1;
    }

    // Set up buzzer
    if (gpioSetPullUpDown(BUZZER_PIN, PI_OFF) < 0) {
        perror("BUZZER_PIN pull-up/down failed");
        return 1;
    }
    if (gpioSetBit(BUZZER_PIN, PI_ON) < 0) {
        perror("BUZZER_PIN on failed");
        return 1;
    }

    // Set up interrupt handler
    gpioSetAlertFuncEx(ECHO_PIN, 0, (void (*)(void))measure_distance);

    // Main loop
    while (1) {
        usleep(MEASUREMENT_INTERVAL);
    }

    gpioTerminate();
    return 0;
}

void measure_distance(void *arg) {
    int tick_count = 0;
    int start_time = 0;
    int end_time = 0;
    int distance = 0;

    // Trigger the sensor
    gpioWrite(TRIG_PIN, 1);
    usleep(10000000);  // 10 microsecond trigger pulse
    gpioWrite(TRIG_PIN, 0);

    // Wait for echo pulse
    while (gpioRead(ECHO_PIN) == 0) {
        // Wait for echo pulse to start
        while (tick_count < 0) {
            tick_count = gpioGetTicks();
        }
        start_time = tick_count;

        // Wait for echo pulse to stop
        while (tick_count >= 0) {
            tick_count = gpioGetTicks();
        }
        end_time = tick_count;

        // Calculate distance
        distance = (SPEED_OF_SOUND / 2) * (end_time - start_time) / 1000000.0;

        // Check for valid reading
        if (distance >= 2 && distance <= 400) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            printf("Invalid reading: %d cm\n", (int)distance);
        }

        // Check for sensor-absent condition
        if (distance == 0) {
            printf("Sensor absent\n");
        }

        // Check for buzzer condition
        if (distance < DISTANCE_THRESHOLD) {
            // Keep buzzer on
        } else {
            // Turn off buzzer
            gpioWrite(BUZZER_PIN, 0);
        }
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define TRIG_GPIO 23
#define ECHO_GPIO 24
#define LOG_FILE "distance_log.txt"
#define MIN_PULSE_WIDTH 100
#define MAX_PULSE_WIDTH 30000
#define MEASUREMENT_INTERVAL 200
#define MEASUREMENT_FREQUENCY 5
#define TIMEOUT 60

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed: %s\n", gpioGetErrorString(gpioInitialise()));
        exit(1);
    }

    if (gpioSetMode(TRIG_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Set TRIG_GPIO to output failed: %s\n", gpioGetErrorString(gpioSetMode(TRIG_GPIO, PI_OUTPUT)));
        gpioTerminate();
        exit(1);
    }

    if (gpioSetMode(ECHO_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Set ECHO_GPIO to input failed: %s\n", gpioGetErrorString(gpioSetMode(ECHO_GPIO, PI_INPUT)));
        gpioTerminate();
        exit(1);
    }

    if (gpioSetPullDownMode(ECHO_GPIO, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Set ECHO_GPIO pull-down failed: %s\n", gpioGetErrorString(gpioSetPullDownMode(ECHO_GPIO, PI_PUD_DOWN)));
        gpioTerminate();
        exit(1);
    }

    if (gpioSetAlertFunc(ECHO_GPIO, pulse_callback) < 0) {
        fprintf(stderr, "Set ECHO_GPIO alert callback failed: %s\n", gpioGetErrorString(gpioSetAlertFunc(ECHO_GPIO, pulse_callback)));
        gpioTerminate();
        exit(1);
    }

    struct timespec ts;
    char buffer[128];
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        exit(1);
    }

    while (1) {
        gpioWrite(TRIG_GPIO, 1);
        nanosleep(&ts, NULL);
        ts.tv_sec = 0;
        ts.tv_nsec = 200000000; // 200 ms

        struct gpio_event *event;
        while ((event = gpioGetNextEvent(ECHO_GPIO, PI_RISING | PI_FALLING)) != NULL) {
            long rising_edge = event->tv_sec * 1000000 + event->tv_nsec / 1000;
            long falling_edge = event->tv_sec * 1000000 + event->tv_nsec / 1000;
            long pulse_width = falling_edge - rising_edge;

            if (pulse_width >= MIN_PULSE_WIDTH && pulse_width <= MAX_PULSE_WIDTH) {
                long distance = pulse_width * 0.0343 / 2;
                struct tm *now = localtime(&event->tv_sec);
                strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", now);
                fprintf(log_file, "%s,%ld\n", buffer, distance);
                fprintf(stdout, "%s,%ld\n", buffer, distance);
            } else {
                fprintf(stderr, "Warning: Invalid pulse width %ld (min %ld, max %ld) detected\n", pulse_width, MIN_PULSE_WIDTH, MAX_PULSE_WIDTH);
            }
        }

        if (gpioGetNextEvent(ECHO_GPIO, PI_RISING | PI_FALLING) == NULL) {
            fprintf(stderr, "Timeout: No valid echo detected within %d ms\n", TIMEOUT);
        }
    }

    gpioTerminate();
    fclose(log_file);
    return 0;
}

void pulse_callback(struct gpio_event *event) {
    gpioTerminate();
    exit(1);
}

