#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_TRIGGER 23
#define GPIO_ECHO 24
#define GPIO_PWM 18
#define PWM_FREQ_MIN 200
#define PWM_FREQ_MAX 2000
#define PWM_DUTY_CYCLE 50
#define PWM_FREQ_STEP 100
#define PWM_DUTY_CYCLE_STEP 5
#define DISTANCE_MIN 2
#define DISTANCE_MAX 200
#define DISTANCE_STEP 10

int main() {
    if (gpioInitialise() < 0) {
        perror("pigpio init failed");
        return 1;
    }

    // Set up GPIOs
    if (gpioSetMode(GPIO_TRIGGER, PI_INPUT) < 0) {
        perror("Setting GPIO_TRIGGER to input failed");
        return 1;
    }
    if (gpioSetMode(GPIO_ECHO, PI_INPUT) < 0) {
        perror("Setting GPIO_ECHO to input failed");
        return 1;
    }
    if (gpioSetMode(GPIO_PWM, PI_OUTPUT) < 0) {
        perror("Setting GPIO_PWM to output failed");
        return 1;
    }

    // Set up PWM
    int pwm_freq = PWM_FREQ_MIN;
    int pwm_duty = PWM_DUTY_CYCLE;
    int pwm_step = PWM_FREQ_STEP;
    int pwm_duty_step = PWM_DUTY_CYCLE_STEP;

    // Set up HC-SR04
    int distance = 0;
    int echo_timeout = 2000000; // 200 ms timeout in microseconds
    int trigger_pulse = 10000; // 10 us trigger pulse

    // Set up signal handlers
    signal(SIGINT, [](int) {
        gpioWrite(GPIO_PWM, 0);
        gpioTerminate();
        exit(0);
    });
    signal(SIGTERM, [](int) {
        gpioWrite(GPIO_PWM, 0);
        gpioTerminate();
        exit(0);
    });

    while (1) {
        // Trigger HC-SR04
        gpioWrite(GPIO_TRIGGER, 1);
        usleep(trigger_pulse);
        gpioWrite(GPIO_TRIGGER, 0);

        // Wait for echo
        int start_time = micros();
        int echo_start = 0;
        int echo_end = 0;
        int distance = 0;
        int timeout = 0;

        while (timeout < echo_timeout) {
            if (gpioRead(GPIO_ECHO)) {
                echo_start = micros();
            } else {
                if (echo_start > 0) {
                    echo_end = micros();
                    distance = (echo_end - echo_start) / 58.8;
                    if (distance >= DISTANCE_MIN && distance <= DISTANCE_MAX) {
                        break;
                    }
                }
            }
            usleep(10);
            timeout++;
        }

        if (echo_start > 0 && echo_end > 0) {
            int duration = echo_end - echo_start;
            int distance = duration / 58.8;
            if (distance >= DISTANCE_MIN && distance <= DISTANCE_MAX) {
                // Map distance to frequency
                double log_distance = log(distance / DISTANCE_MIN);
                double exp_distance = exp(log_distance / log(DISTANCE_MAX / DISTANCE_MIN));
                double freq = PWM_FREQ_MIN * exp_distance;
                if (freq > PWM_FREQ_MAX) {
                    freq = PWM_FREQ_MAX;
                }

                // Set PWM frequency and duty cycle
                int pwm_freq_step = (freq - pwm_freq) / pwm_freq_step;
                int pwm_duty_step = (pwm_duty * (PWM_DUTY_CYCLE - pwm_duty) / (PWM_DUTY_CYCLE * 2)) / pwm_duty_step;

                pwm_freq += pwm_freq_step * pwm_freq_step;
                pwm_duty += pwm_duty_step * pwm_duty_step;

                if (pwm_freq > PWM_FREQ_MAX) {
                    pwm_freq = PWM_FREQ_MAX;
                }
                if (pwm_duty > PWM_DUTY_CYCLE) {
                    pwm_duty = PWM_DUTY_CYCLE;
                }
                if (pwm_freq < PWM_FREQ_MIN) {
                    pwm_freq = PWM_FREQ_MIN;
                }
                if (pwm_duty < 0) {
                    pwm_duty = 0;
                }

                // Set PWM frequency and duty cycle
                gpioSetPWMfreq(GPIO_PWM, pwm_freq);
                gpioSetPWMduty(GPIO_PWM, pwm_duty);
            }
        } else {
            // Keep previous frequency
        }
    }

    gpioTerminate();
    return 0;
}

