#define MIN_FREQ 200
#define MAX_FREQ 2000
#define MIN_DIST 5
#define MAX_DIST 50
#define MIN_TRIGGER_TIME 10
#define MAX_TRIGGER_TIME 100

int echoPin = 24;
int triggerPin = 23;
int pwmPin = 18;

int lastDistance = 0;
int lastFrequency = 0;

void handleSignal(int sig) {
    printf("Terminating...\n");
    gpioTerminate();
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handleSignal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        perror("pigpio initialisation failed");
        return 1;
    }

    if (gpioSetMode(echoPin, PI_INPUT) < 0) {
        perror("Setting echo pin to input failed");
        return 1;
    }

    if (gpioSetMode(triggerPin, PI_OUTPUT) < 0) {
        perror("Setting trigger pin to output failed");
        return 1;
    }

    if (gpioSetMode(pwmPin, PI_OUTPUT) < 0) {
        perror("Setting pwm pin to output failed");
        return 1;
    }

    if (gpioSetPullUpDnControl(echoPin, PI_DISABLE) < 0) {
        perror("Disabling pull-up/down on echo pin failed");
        return 1;
    }

    printf("Sensor trigger on GPIO23, echo on GPIO24, PWM on GPIO18\n");

    while (1) {
        printf("Distance: %d cm, Frequency: %d Hz\n", lastDistance, lastFrequency);
        usleep(10);

        gpioWrite(triggerPin, 0);
        usleep(10);

        gpioWrite(triggerPin, 1);
        usleep(MIN_TRIGGER_TIME);

        long duration = gpioDelay(echoPin, 0);
        if (duration > MAX_TRIGGER_TIME) {
            printf("Timeout: distance not detected\n");
            lastDistance = lastDistance;
        } else {
            lastDistance = (int) (duration * 1000 / 58.0);
            if (lastDistance < MIN_DIST || lastDistance > MAX_DIST) {
                lastDistance = lastDistance < MIN_DIST ? MIN_DIST : MAX_DIST;
            }

            lastFrequency = MIN_FREQ + (MAX_FREQ - MIN_FREQ) * (MAX_DIST - lastDistance) / (MAX_DIST - MIN_DIST);
            lastFrequency = clamp(lastFrequency, MIN_FREQ, MAX_FREQ);
        }

        gpioHardwarePWM(pwmPin, lastFrequency);
    }

    return 0;
}

int clamp(int x, int min, int max) {
    return x < min ? min : (x > max ? max : x);
}

