#define TRIG_PIN 17
#define ECHO_PIN 18
#define TIMEOUT 50000  // 50 ms in microseconds
#define MIN_DISTANCE 2
#define MAX_DISTANCE 400
#define SPEED_OF_SOUND 29.1

volatile sig_atomic_t exit_flag = 0;

void handle_sigint(int signum) {
    exit_flag = 1;
}

int main() {
    signal(SIGINT, handle_sigint);

    if (gpio_initialise() < 0) {
        perror("pigpio init failed");
        return 1;
    }

    if (gpio_set_mode(TRIG_PIN, PI_OUTPUT) < 0) {
        perror("setting TRIG_PIN to output failed");
        gpio_uninit();
        return 1;
    }

    if (gpio_set_mode(ECHO_PIN, PI_INPUT) < 0) {
        perror("setting ECHO_PIN to input failed");
        gpio_uninit();
        return 1;
    }

    gpio_write(TRIG_PIN, 0);

    while (!exit_flag) {
        gpio_write(TRIG_PIN, 1);
        usleep(10000);  // 10 us trigger pulse

        gpio_write(TRIG_PIN, 0);
        struct timeval start, end;
        gettimeofday(&start, NULL);
        int timeout = 0;
        while (timeout < TIMEOUT) {
            if (gpio_read(ECHO_PIN)) {
                gettimeofday(&end, NULL);
                timeout = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_usec - start.tv_usec);
                if (timeout > TIMEOUT) {
                    timeout = -1;
                    break;
                }
                break;
            }
            usleep(1000);  // 1 ms check
        }

        if (timeout == -1) {
            printf("Invalid reading\n");
        } else if (timeout < MIN_DISTANCE) {
            printf("Invalid reading\n");
        } else if (timeout > MAX_DISTANCE) {
            printf("Invalid reading\n");
        } else {
            double distance = (double)timeout / (2 * SPEED_OF_SOUND);
            printf("Distance: %.2f cm\n", distance);
            if (distance < 10) {
                printf("Too close!\n");
            }
        }
    }

    gpio_uninit();
    return 0;
}

