        if (mode == SPI_WRITE) {
            pi_i2c_write(spi_handle, SPI_CS, SPI_REG_0, 1, *ptr);
            pi_i2c_write(spi_handle, SPI_CS, SPI_REG_1, 1, 0x00);
            pi_i2c_write(spi_handle, SPI_CS, SPI_REG_2, 1, 0x00);
            pi_i2c_write(spi_handle, SPI_CS, SPI_REG_3, 1, 0x01);
            pi_i2c_write(spi_handle, SPI_CS, SPI_REG_4, 1, 0x0C);
            pi_i2c_write(spi_handle, SPI_CS, SPI_REG_5, 1, 0x0D);
        } else {
            unsigned char data[3];
            pi_i2c_read(spi_handle, SPI_CS, SPI_REG_0, 1, data);
            pi_i2c_read(spi_handle, SPI_CS, SPI_REG_1, 1, data + 1);
            pi_i2c_read(spi_handle, SPI_CS, SPI_REG_2, 1, data + 2);
            pi_i2c_read(spi_handle, SPI_CS, SPI_REG_3, 1, data + 3);
            pi_i2c_read(spi_handle, SPI_CS, SPI_REG_4, 1, data + 4);
            pi_i2c_read(spi_handle, SPI_CS, SPI_REG_5, 1, data + 5);
            *ptr = data[0];
            *(ptr + 1) = data[1];
            *(ptr + 2) = data[2];
            *(ptr + 3) = data[3];
            *(ptr + 4) = data[4];
            *(ptr + 5) = data[5];
        }
        *ptr++;
    }

    return error;
}

