#define ALS_LOW 0x22
#define ALS_HIGH 0x23
#define PS1_LOW 0x18
#define PS1_HIGH 0x19
#define I2C_BUS 1
#define I2C_ADDR 0x60
#define PART_ID 0x00
#define RESET 0x01
#define I2C_TIMEOUT 1000

int i2c_fd;
int i2c_attempts = 0;

void handle_signal(int sig) {
    if (sig == SIGINT) {
        printf("SIGINT received, exiting...\n");
        pi_write(0, 0); // Reset the sensor
        close(i2c_fd);
        close(pi_file);
        fclose(log_file);
        exit(0);
    }
}

int main() {
    struct timespec ts;
    char log_file[256] = "si1120_log.txt";
    char log_buffer[256];
    int i2c_result;
    int pi_result;
    int i2c_attempts = 0;
    int log_file_fd;
    int pi_file;
    int i2c_handle;
    int i2c_retry = 0;
    int part_id;
    int alsonum;
    int proxnum;
    time_t rawtime;
    struct tm *timeinfo;

    signal(SIGINT, handle_signal);

    if ((log_file_fd = fopen(log_file, "a")) == -1) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    if (pi_init(0) < 0) {
        perror("pigpio init failed");
        exit(EXIT_FAILURE);
    }

    if ((pi_file = pi_file_open("/dev/spi0.3")) < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if ((i2c_fd = i2c_open(I2C_BUS, I2C_ADDR)) < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    while (1) {
        ts.tv_sec = time(NULL) / 1000;
        ts.tv_nsec = (time(NULL) % 1000) * 1000000;
        clock_gettime(CLOCK_MONOTONIC, &ts);

        if (i2c_attempts < 3) {
            i2c_result = i2c_retry(i2c_fd, I2C_ADDR, 0x01, I2C_TIMEOUT);
            if (i2c_result == 0) {
                i2c_attempts = 0;
                i2c_retry = 0;
            } else {
                i2c_attempts++;
                usleep(10);
            }
        } else {
            printf("Failed to reset sensor after 3 attempts\n");
            exit(EXIT_FAILURE);
        }

        if (i2c_attempts == 0) {
            i2c_result = i2c_read(i2c_fd, I2C_ADDR, 0x00, 1, &part_id);
            if (i2c_result == 0) {
                if (part_id == 0x41) {
                    printf("Part ID verified: 0x41\n");
                } else {
                    printf("Part ID verification failed: 0x%02x\n", part_id);
                    exit(EXIT_FAILURE);
                }
            } else {
                printf("Failed to read part ID\n");
                exit(EXIT_FAILURE);
            }
        }

        if (i2c_attempts == 0) {
            i2c_result = i2c_read(i2c_fd, I2C_ADDR, ALS_LOW, 2, &alsonum);
            if (i2c_result == 0) {
                printf("ALS data read: 0x%02x 0x%02x\n", alsonum & 0xFF, (alsonum >> 8) & 0xFF);
            } else {
                printf("Failed to read ALS data\n");
                exit(EXIT_FAILURE);
            }
        }

        if (i2c_attempts == 0) {
            i2c_result = i2c_read(i2c_fd, I2C_ADDR, PS1_LOW, 2, &proxnum);
            if (i2c_result == 0) {
                printf("Proximity data read: 0x%02x 0x%02x\n", proxnum & 0xFF, (proxnum >> 8) & 0xFF);
            } else {
                printf("Failed to read proximity data\n");
                exit(EXIT_FAILURE);
            }
        }

        if (i2c_attempts == 0) {
            i2c_result = i2c_read(i2c_fd, I2C_ADDR, ALS_HIGH, 2, &alsonum);
            if (i2c_result == 0) {
                printf("ALS data read: 0x%02x 0x%02x\n", alsonum & 0xFF, (alsonum >> 8) & 0xFF);
            } else {
                printf("Failed to read ALS data\n");
                exit(EXIT_FAILURE);
            }
        }

        if (i2c_attempts == 0) {
            i2c_result = i2c_read(i2c_fd, I2C_ADDR, PS1_HIGH, 2, &proxnum);
            if (i2c_result == 0) {
                printf("Proximity data read: 0x%02x 0x%02x\n", proxnum & 0xFF, (proxnum >> 8) & 0xFF);
            } else {
                printf("Failed to read proximity data\n");
                exit(EXIT_FAILURE);
            }
        }

        snprintf(log_buffer, sizeof(log_buffer), "%s %d %d %d\n", ctime(&rawtime), alsonum & 0xFF, (alsonum >> 8) & 0xFF, proxnum & 0xFF, (proxnum >> 8) & 0xFF);
        if (fwrite(log_buffer, 1, strlen(log_buffer), log_file_fd) != strlen(log_buffer)) {
            perror("Failed to write to log file");
            exit(EXIT_FAILURE);
        }

        i2c_retry = 0;
        i2c_attempts = 0;
        sleep(500);
    }

    pi_close(pi_file);
    pi_close(pi_file);
    fclose(log_file);
    exit(EXIT_SUCCESS);
}

