    err = ioctl(i2c_fd, I2C_SMBUS_READ, &iocb);
    handle_i2c_error(err);

    // Convert ambient light to lux
    reading.lux = (lux * 0.1);

    // Log reading
    reading.timestamp = time(NULL);
    strftime(log_buffer, sizeof(log_buffer), "%Y-%m-%d %H:%M:%S.%03d", localtime(&reading.timestamp));
    snprintf(log_line, sizeof(log_line), "%s,%d,%d\n", log_buffer, reading.lux, proximity);
    write(log_fd, log_header, strlen(log_header));
    write(log_fd, log_line, strlen(log_line));
    printf("%s,%d,%d\n", log_buffer, reading.lux, proximity);

    // Main loop
    while (1) {
        // Perform I2C read for ambient light and proximity
        err = ioctl(i2c_fd, I2C_SMBUS_READ, &iocb);
        handle_i2c_error(err);

        // Check for I2C bus errors
        if (err < 0) {
            handle_i2c_bus_error(err);
        }

