        write(log_fd, log_header, strlen(log_header));
        write(log_fd, log_line, strlen(log_line));
        printf("%s,%d,%d\n", log_buffer, reading.lux, proximity);

        // Sleep for 100 ms
        usleep(100000);
    }

    return 0;
}

