int main() {
    struct timespec ts;
    char buffer[128];
    int retries = 0;
    int i2c_fd;
    int result;
    int proximity_low;
    int proximity_high;
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpioInitialise() < 0) {
        handle_error("pigpioInitialise failed");
    }

    if ((i2c_fd = i2cOpen(I2C_ADDR)) < 0) {
        handle_error("i2cOpen failed");
    }

    while (1) {
        ts.tv_sec = time(NULL) / 1;
        ts.tv_nsec = 0;
        nanosleep(&ts, NULL);

        if (retries >= MAX_RETRIES) {
            handle_error("I2C communication failed after 3 retries");
        }

        result = i2cWriteByteData(i2c_fd, 0x03, 0x07);
        if (result < 0) {
            handle_error("i2cWriteByteData failed");
        }

        result = i2cWriteByteData(i2c_fd, 0x02, 0x06);
        if (result < 0) {
            handle_error("i2cWriteByteData failed");
        }

        result = i2cWriteByteData(i2c_fd, 0x00, 0x1A);
        if (result < 0) {
            handle_error("i2cWriteByteData failed");
        }

        result = i2cWriteByteData(i2c_fd, 0x0B, 0x00);
        if (result < 0) {
            handle_error("i2cWriteByteData failed");
        }

        result = i2cWriteByteData(i2c_fd, 0x00, 0x24);
        if (result < 0) {
            handle_error("i2cWriteByteData failed");
        }

        result = i2cWriteByteData(i2c_fd, 0x49, 0x22);
        if (result < 0) {
            handle_error("i2cWriteByteData failed");
        }

        result = i2cWriteByteData(i2c_fd, 0x03, 0x0C);
        if (result < 0) {
            handle_error("i2cWriteByteData failed");
        }

        result = i2cWriteByteData(i2c_fd, 0x0F, 0x0F);
        if (result < 0) {
            handle_error("i2cWriteByteData failed");
        }

        result = i2cWriteByteData(i2c_fd, 0x03, 0x11);
        if (result < 0) {
            handle_error("i2cWriteByteData failed");
        }

        result = i2cWriteByteData(i2c_fd, 0x07, 0x0D);
        if (result < 0) {
            handle_error("i2cWriteByteData failed");
        }

        result = i2cWriteByteData(i2c_fd, 0x03, 0x80);
        if (result < 0) {
            handle_error("i2cWriteByteData failed");
        }

        if (result < 0) {
            retries++;
            nanosleep(&ts, NULL);
            continue;
        }

        result = i2cReadByteData(i2c_fd, 0x16, &proximity_low);
        if (result < 0) {
            handle_error("i2cReadByteData failed");
        }

        result = i2cReadByteData(i2c_fd, 0x17, &proximity_high);
        if (result < 0) {
            handle_error("i2cReadByteData failed");
        }

        if (result < 0) {
            handle_error("I2C communication failed");
        }

        now = time(NULL);
        timeinfo = localtime(&now);
        strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);

        f = fopen(PROXIMITY_LOG_FILE, "a");
        if (f == NULL) {
            handle_error("Failed to open log file");
        }

        fprintf(f, "%s %u %u\n", timestamp, proximity_low, proximity_high);
        fclose(f);

        retries = 0;
    }

    gpioTerminate();
    return 0;
}

