void handle_echo(int gpio, int level, uint64_t tick) {
    static uint64_t prev_rising = 0;
    static uint64_t prev_falling = 0;
    static uint64_t prev_time = 0;

    if (level == 1) {
        if (prev_rising == 0) {
            prev_rising = tick;
        }
    } else {
        if (prev_falling == 0) {
            prev_falling = tick;
        }
        if (prev_rising != 0 && prev_falling != 0) {
            uint64_t duration = prev_falling - prev_rising;
            double distance = (duration * SPEED_OF_SOUND) / 2.0;
            printf("%.2f cm\n", distance);
            if (distance < 20.0) {
                gpioWrite(GPIO27, 1);
            } else {
                gpioWrite(GPIO27, 0);
            }
            prev_rising = 0;
            prev_falling = 0;
        }
    }
}

