#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDR 0x44
#define SHT40_CMD_HIGH_REPEATABILTY 0xFD
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

#define SHT40_TEMP_MSB 0x02
#define SHT40_TEMP_LSB 0x03
#define SHT40_HUMID_MSB 0x04
#define SHT40_HUMID_LSB 0x05

#define SHT40_TEMP_OFFSET -45
#define SHT40_HUMID_OFFSET 0

#define SHT40_LOG_FILE "sht40_log.txt"
#define SHT40_LOG_FORMAT "%Y-%m-%d %H:%M:%S %f %d.%02d°C %d.%02d%%\n"

void crc8(uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x01) {
                crc = (crc >> 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc >>= 1;
            }
        }
    }
    data[len] = crc;
}

void log_sensor_data(int fd, int temp, int humidity) {
    char buffer[256];
    struct tm *timeinfo;
    time_t rawtime;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), SHT40_LOG_FORMAT, timeinfo);
    fprintf(stderr, "%s", buffer);
    fprintf(stderr, "%d.%02d°C %d.%02d%%\n", (int)(temp + 0.5), (int)(humidity / 100.0 + 0.5), temp, humidity);
    fflush(stderr);
}

void handle_i2c_error(int fd, int err) {
    fprintf(stderr, "I2C error: %d\n", err);
    if (close(fd) < 0) {
        perror("close");
    }
}

void handle_log_error(int fd, int err) {
    fprintf(stderr, "Log error: %d\n", err);
    if (close(fd) < 0) {
        perror("close");
    }
}

void handle_signal(int signum) {
    if (close(i2c_fd) < 0) {
        perror("close");
    }
    if (close(log_fd) < 0) {
        perror("close");
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct iocb iocb;
    struct iovec iovec;
    int i2c_fd;
    int temp, humidity;
    int retries = 0;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    iocb.iov_base = &iovec;
    iocb.iov_len = sizeof(iovec);
    iocb.ioctlen = I2C_RDWR;
    iocb.mioctls[0] = I2C_SMBUS_READ;
    iocb.mioctls[1] = SHT40_CMD_HIGH_REPEATABILTY;
    iocb.mioctls[2] = 0;
    iocb.mioctls[3] = 0;
    iocb.mioctls[4] = 0;
    iocb.mioctls[5] = 0;
    iocb.mioctls[6] = 0;
    iocb.mioctls[7] = 0;

    iovec.iov_base = &buffer;
    iovec.iov_len = sizeof(buffer);

    while (1) {
        retries = 0;
        while (retries < 3) {
            if (ioctl(i2c_fd, I2C_SMBUS_READ, &iocb) < 0) {
                handle_i2c_error(i2c_fd, errno);
                retries++;
                continue;
            }

            if (read(i2c_fd, buffer, sizeof(buffer)) < 0) {
                handle_i2c_error(i2c_fd, errno);
                retries++;
                continue;
            }

            crc8(buffer, 6);
            if (buffer[6] != crc) {
                fprintf(stderr, "CRC error\n");
                retries++;
                continue;
            }

            temp = (int)(buffer[SHT40_TEMP_MSB] << 8 | buffer[SHT40_TEMP_LSB]) * 0.01 + SHT40_TEMP_OFFSET;
            humidity = (int)(buffer[SHT40_HUMID_MSB] << 8 | buffer[SHT40_HUMID_LSB]) * 0.01 + SHT40_HUMID_OFFSET;

            log_sensor_data(i2c_fd, temp, humidity);

            if (close(i2c_fd) < 0) {
                perror("close");
            }
            if (close(log_fd) < 0) {
                perror("close");
            }

            i2c_fd = open(I2C_DEVICE, O_RDWR);
            if (i2c_fd < 0) {
                perror("open");
                return EXIT_FAILURE;
            }
            log_fd = open(SHT40_LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
            if (log_fd < 0) {
                perror("open");
                return EXIT_FAILURE;
            }
            break;
        }

        if (retries == 3) {
            fprintf(stderr, "Sensor not found or read failed\n");
            exit(EXIT_FAILURE);
        }
    }

    return EXIT_SUCCESS;
}

