#define SI7015_TEMP_CMD 0xF3
#define SI7015_HUMID_CMD 0xF5
#define SI7015_MEAS_READY 0x00
#define SI7015_MEAS_TIMEOUT 20  // ms

int i2c_fd;
int temp_raw;
int hum_raw;
char *temp_str;
char *hum_str;
char *timestamp_str;

void handle_sensor_absent(int sig) {
    printf("Sensor absent or bus error detected. Exiting...\n");
    close(i2c_fd);
    pigpio_close();
    if (temp_str) {
        free(temp_str);
    }
    if (hum_str) {
        free(hum_str);
    }
    if (timestamp_str) {
        free(timestamp_str);
    }
    exit(EXIT_FAILURE);
}

void handle_sigint(int sig) {
    printf("SIGINT received. Closing I2C handle, pigpio, and file...\n");
    close(i2c_fd);
    pigpio_close();
    if (temp_str) {
        free(temp_str);
    }
    if (hum_str) {
        free(hum_str);
    }
    if (timestamp_str) {
        free(timestamp_str);
    }
    exit(EXIT_SUCCESS);
}

