#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <crc/crc.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define CMD_MEASURE 0x362F
#define CMD_STOP 0x3620
#define CMD_RESET 0x3621
#define CMD_READ 0x3622
#define CMD_STOP_MEASURE 0x362F
#define CMD_RESET_MEASURE 0x362F
#define CMD_READ_MEASUREMENTS 0x3622
#define CMD_STOP_READ 0x362F
#define CMD_READ_SCALE 0x3623
#define CMD_READ_TEMP 0x3624
#define CMD_READ_PRES 0x3625
#define CMD_READ_CRC 0x3626
#define CMD_READ_SCALE_CRC 0x3627
#define CMD_READ_TEMP_CRC 0x3628
#define CMD_READ_PRES_CRC 0x3629
#define CMD_STOP_READ_SCALE 0x362F
#define CMD_STOP_READ_TEMP 0x362F
#define CMD_STOP_READ_PRES 0x362F
#define CMD_STOP_READ_CRC 0x362F
#define CMD_STOP_READ_SCALE_CRC 0x362F
#define CMD_STOP_READ_TEMP_CRC 0x362F
#define CMD_STOP_READ_PRES_CRC 0x362F

#define CRC8_POLY 0x07
#define CRC8_INIT 0x00
#define CRC8_CHECKSUM 0x00

#define PRESSURE_SCALE 1000
#define TEMPERATURE_OFFSET -45
#define TEMPERATURE_SCALE 200

#define LOG_FILE "airflow_data.txt"
#define LOG_HEADER "timestamp,pressure(Pa),temperature(°C)\n"

#define LOG_INTERVAL 100
#define LOG_INTERVAL_MS 100

#define I2C_READ_TIMEOUT 10

int i2c_fd = -1;
int log_fd = -1;

void i2c_open() {
    if ((i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }
}

void i2c_close() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

void i2c_read_measurement() {
    uint8_t buffer[9];
    uint8_t crc8;
    uint32_t pressure, temperature, scale;

    if (ioctl(i2c_fd, I2C_RDWR, buffer, I2C_READ, I2C_ADDR, CMD_READ_MEASUREMENTS) < 0) {
        perror("Failed to read measurement");
        exit(EXIT_FAILURE);
    }

    crc8 = crc8_update(CRC8_INIT, buffer, 8);
    if (crc8 != buffer[8]) {
        fprintf(stderr, "CRC8 error: expected %02x, got %02x\n", crc8, buffer[8]);
        exit(EXIT_FAILURE);
    }

    pressure = (buffer[0] << 5) | (buffer[1] >> 3);
    crc8 = crc8_update(CRC8_INIT, buffer, 9);
    if (crc8 != buffer[9]) {
        fprintf(stderr, "CRC8 error: expected %02x, got %02x\n", crc8, buffer[9]);
        exit(EXIT_FAILURE);
    }
    pressure /= PRESSURE_SCALE;

    temperature = (buffer[2] << 5) | (buffer[3] >> 3);
    crc8 = crc8_update(CRC8_INIT, buffer, 12);
    if (crc8 != buffer[12]) {
        fprintf(stderr, "CRC8 error: expected %02x, got %02x\n", crc8, buffer[12]);
        exit(EXIT_FAILURE);
    }
    temperature = (temperature - 0x80) / 0x80 + TEMPERATURE_OFFSET;

    scale = (buffer[4] << 5) | (buffer[5] >> 3);
    crc8 = crc8_update(CRC8_INIT, buffer, 15);
    if (crc8 != buffer[15]) {
        fprintf(stderr, "CRC8 error: expected %02x, got %02x\n", crc8, buffer[15]);
        exit(EXIT_FAILURE);
    }

    printf("%ld,%ld,%ld\n", current_time(), pressure, temperature);
    fflush(stdout);

    if (log_fd == -1) {
        log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
        if (log_fd < 0) {
            perror("Failed to open log file");
            exit(EXIT_FAILURE);
        }
        write(log_fd, LOG_HEADER, strlen(LOG_HEADER));
    }
    write(log_fd, "%ld,%ld,%ld\n", current_time(), pressure, temperature);
    fflush(log_fd);
}

