#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <time.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x4A
#define MEASUREMENT_COMMAND 0x2C06
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define CRC_SIZE 1
#define TEMPERATURE_OFFSET -45
#define TEMPERATURE_SCALE 175
#define SAMPLE_INTERVAL 5000  // 5 seconds
#define MAX_RETRIES 3

typedef struct {
    int fd;
    int i2c_fd;
    int temp_fd;
    int crc_fd;
    int sigint_received;
} PiZeroConfig;

void handle_sigint(int signum) {
    if (PiZeroConfig.temp_fd > 0) {
        close(PiZeroConfig.temp_fd);
    }
    if (PiZeroConfig.i2c_fd > 0) {
        close(PiZeroConfig.i2c_fd);
    }
    if (PiZeroConfig.crc_fd > 0) {
        close(PiZeroConfig.crc_fd);
    }
    printf("Graceful shutdown initiated.\n");
    exit(0);
}

void init_i2c(PiZeroConfig *config) {
    config->i2c_fd = i2c_open(I2C_BUS, I2C_ADDR);
    if (config->i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        config->sigint_received = 1;
    }
}

void init_temp_log(PiZeroConfig *config) {
    config->temp_fd = open("enclosure_temp_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (config->temp_fd < 0) {
        fprintf(stderr, "Error opening temp log file: %s\n", strerror(errno));
        config->sigint_received = 1;
    }
}

void init_crc(PiZeroConfig *config) {
    config->crc_fd = open("error_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (config->crc_fd < 0) {
        fprintf(stderr, "Error opening error log file: %s\n", strerror(errno));
        config->sigint_received = 1;
    }
}

void write_i2c(PiZeroConfig *config, uint8_t *buf, int len) {
    if (config->i2c_fd < 0) {
        return;
    }
    if (i2c_write(config->i2c_fd, buf, len) < 0) {
        fprintf(stderr, "Error writing to I2C bus: %s\n", strerror(errno));
        config->sigint_received = 1;
    }
}

void read_i2c(PiZeroConfig *config, uint8_t *buf, int len) {
    if (config->i2c_fd < 0) {
        return;
    }
    if (i2c_read(config->i2c_fd, buf, len) < 0) {
        fprintf(stderr, "Error reading from I2C bus: %s\n", strerror(errno));
        config->sigint_received = 1;
    }
}

void validate_crc(PiZeroConfig *config, uint8_t *buf) {
    if (config->crc_fd < 0) {
        return;
    }
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < CRC_SIZE; i++) {
        crc = crc ^ buf[i];
    }
    crc = crc ^ CRC_POLYNOMIAL;
    if (crc != buf[CRC_SIZE]) {
        fprintf(config->crc_fd, "CRC mismatch: %s\n", ctime(&time(NULL)));
    }
}

void process_measurement(PiZeroConfig *config) {
    uint8_t buf[3];
    buf[0] = MEASUREMENT_COMMAND;
    write_i2c(config, buf, 1);
    usleep(15); // Wait at least 15 ms for conversion

    if (read_i2c(config, buf, 3) < 0) {
        return;
    }

    validate_crc(config, buf);

    int raw = (buf[1] << 8) | buf[2];
    double temp = TEMPERATURE_OFFSET + (TEMPERATURE_SCALE * (raw / 65535.0));
    char timestamp[24];
    struct tm *now = localtime(&time(NULL));
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now);
    fprintf(config->temp_fd, "%s %f\n", timestamp, temp);
}

int main() {
    PiZeroConfig config;
    config.sigint_received = 0;
    config.temp_fd = 0;
    config.i2c_fd = 0;
    config.crc_fd = 0;

    signal(SIGINT, handle_sigint);

    init_i2c(&config);
    if (!config.sigint_received) {
        init_temp_log(&config);
        init_crc(&config);
    }

    while (!config.sigint_received) {
        process_measurement(&config);
        usleep(SAMPLE_INTERVAL * 1000);
    }

    return 0;
}

#include <stdio.h>
