#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x44
#define CMD_HIGH_REP 0xFD
#define CRC_POLY 0x31
#define CRC_INIT 0xFF

void handle_sigint(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_fd != -1) {
        close(log_fd);
    }
    printf("Exiting...\n");
    exit(0);
}

int main() {
    struct i2c_msg i2c_msg[1];
    struct i2c_rdma_request i2c_rdma_req;
    struct i2c_client_data i2c_client_data;
    int i2c_fd = -1;
    int log_fd = -1;
    char log_buffer[256];
    time_t rawtime;
    struct tm *timeinfo;
    char log_filename[128];
    char log_buffer2[256];
    uint8_t cmd[1] = {CMD_HIGH_REP};
    uint8_t data[6];
    uint8_t crc[2];
    uint32_t temp_raw;
    uint32_t rh_raw;
    double temp;
    double rh;
    int rc;

    signal(SIGINT, handle_sigint);

    // Open I2C device
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd == -1) {
        perror("open i2c device");
        exit(EXIT_FAILURE);
    }

    // Set I2C client data
    i2c_client_data.iomode = I2C_IOMODE_MASTER;
    i2c_client_data.flags = I2C_CLIENT_DATA;
    rc = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (rc < 0) {
        perror("ioctl i2c slave");
        exit(EXIT_FAILURE);
    }

    // Prepare I2C message
    i2c_msg[0].addr = I2C_ADDR;
    i2c_msg[0].flags = I2C_MSG_RD;
    i2c_msg[0].data[0] = CMD_HIGH_REP;

    // Set up I2C RDMA request
    i2c_rdma_req.request = i2c_msg[0];
    i2c_rdma_req.flags = I2C_RDMA_RD;
    i2c_rdma_req.rdma = I2C_RDMA_RDMA0;

    // Log file setup
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(log_filename, sizeof(log_filename), "%Y-%m-%d %H:%M:%S", timeinfo);
    strcat(log_filename, ".log");
    log_fd = open(log_filename, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        perror("open log file");
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Send command
        rc = ioctl(i2c_fd, I2C_RDWR, &i2c_rdma_req);
        if (rc < 0) {
            perror("ioctl i2c command");
            continue;
        }

        // Read response
        rc = read(i2c_fd, data, 6);
        if (rc < 0) {
            perror("read i2c response");
            continue;
        }

        // Calculate CRC
        crc[0] = CRC_INIT;
        crc[1] = CRC_INIT;
        for (int i = 0; i < 5; i++) {
            crc[0] = crc[0] ^ data[i];
            crc[1] = crc[1] ^ data[i + 1];
        }
        crc[0] = crc[0] ^ CRC_POLY;
        crc[1] = crc[1] ^ CRC_POLY;

        // Validate CRC
        if (crc[0] != data[5] || crc[1] != data[6]) {
            printf("CRC error\n");
            continue;
        }

        // Convert to temperature and humidity
        temp_raw = (data[0] << 8) | data[1];
        temp = -45 + 175.0 * (double)temp_raw / 65535.0;

        rh_raw = (data[2] << 8) | data[3];
        rh = 100.0 * (double)rh_raw / 65535.0;

        // Log data
        snprintf(log_buffer2, sizeof(log_buffer2), "%.2f,%.2f\n", temp, rh);
        write(log_fd, log_buffer2, strlen(log_buffer2));
        printf("%.2f,%.2f\n", temp, rh);

        // Wait 5 seconds
        sleep(5);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <stdint.h>
