#include <time.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x25
#define CMD_MEAS 0x362F
#define CRC_POLY 0x31
#define CRC_INIT 0xFF
#define SCALE_P 240
#define SCALE_T 200
#define OFFSET_T -45

typedef struct {
    uint8_t pressure_msb;
    uint8_t pressure_lsb;
    uint8_t temp_msb;
    uint8_t temp_lsb;
    uint8_t crc1;
    uint8_t crc2;
} SensorData;

static void cleanup() {
    if (fd != -1) {
        close(fd);
    }
    if (fp != -1) {
        fclose(fp);
    }
}

static void handle_error(const char *msg) {
    fprintf(stderr, "%s: %s\n", msg, strerror(errno));
    cleanup();
    exit(EXIT_FAILURE);
}

static void sigint_handler(int sig) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    int fd = open(I2C_DEV, O_RDWR);
    if (fd == -1) {
        handle_error("Failed to open I2C device");
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        handle_error("Failed to set slave address");
    }

    SensorData data;
    char buffer[6];
    char timestamp[20];
    char line[100];

    while (1) {
        uint32_t start = clock();
        if (ioctl(fd, I2C_SMBUS_WRITE, &CMD_MEAS) < 0) {
            handle_error("Failed to send measurement command");
        }

        if (ioctl(fd, I2C_SMBUS_READ, 0, buffer, 6, 0) < 0) {
            handle_error("Failed to read response");
        }

        data.pressure_msb = buffer[0];
        data.pressure_lsb = buffer[1];
        data.temp_msb = buffer[2];
        data.temp_lsb = buffer[3];
        data.crc1 = buffer[4];
        data.crc2 = buffer[5];

        if (crc8(data.pressure_msb, data.pressure_lsb, CRC_POLY, CRC_INIT) != data.crc1) {
            handle_error("CRC mismatch for pressure");
        }

        if (crc8(data.temp_msb, data.temp_lsb, CRC_POLY, CRC_INIT) != data.crc2) {
            handle_error("CRC mismatch for temperature");
        }

        uint32_t pressure = (data.pressure_msb << 8) | data.pressure_lsb;
        uint32_t temp = (data.temp_msb << 8) | data.temp_lsb;

        double pressure_pa = (pressure * SCALE_P) / 0x1000000.0;
        double temp_c = (temp * SCALE_T + OFFSET_T) / 0x1000000.0;

        snprintf(timestamp, sizeof(timestamp), "%ld", (long)clock());

        snprintf(line, sizeof(line), "%s,%f,%f\n", timestamp, pressure_pa, temp_c);

        fp = fopen("airflow_data.txt", "a");
        if (fp == -1) {
            handle_error("Failed to open log file");
        }

        fputs(line, fp);
        fflush(fp);

        uint32_t elapsed = clock() - start;
        if (elapsed < 1000) {
            usleep(1000 - elapsed);
        }
    }

    return 0;
}

static uint8_t crc8(uint8_t data[], uint8_t len, uint8_t poly, uint8_t init) {
    uint8_t crc = init;
    for (uint8_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ poly;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

