#define I2C_ADDR 0x44
#define MEASUREMENT_COMMAND 0x2400
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF
#define TEMPERATURE_OFFSET -45
#define TEMPERATURE_SCALE 175
#define HUMIDITY_SCALE 100
#define MEASUREMENT_INTERVAL 5000  // 5 seconds
#define MEASUREMENT_TIMEOUT 15      // 15 ms

int i2c_fd;
int gpio_fd;
int temperature_raw;
int humidity_raw;
int temperature;
int humidity;
char timestamp[26];
char filename[] = "environment.csv";

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (i2c_fd > 0) {
            close(i2c_fd);
        }
        if (gpio_fd > 0) {
            close(gpio_fd);
        }
        gpioTerminate();
        exit(0);
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        perror("pigpioInitialise");
        return 1;
    }

    if (gpioSetClockDivider(1, 400) < 0) {
        perror("gpioSetClockDivider");
        return 1;
    }

    if ((i2c_fd = i2cOpen(1, I2C_ADDR, 100000)) < 0) {
        perror("i2cOpen");
        return 1;
    }

    if (i2cSetClock(i2c_fd, 400000) < 0) {
        perror("i2cSetClock");
        return 1;
    }

    if (i2cWrite(i2c_fd, 1, 1, MEASUREMENT_COMMAND) < 0) {
        perror("i2cWrite");
        return 1;
    }

    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        strftime(timestamp, 26, "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        if (i2cRead(i2c_fd, 1, 6, 0) < 0) {
            perror("i2cRead");
            continue;
        }

        temperature_raw = (int)(*((unsigned char *)(i2cData + 0)));
        temperature_raw |= ((int)(*((unsigned char *)(i2cData + 1))) << 8);
        if (crc8(temperature_raw, CRC8_POLYNOMIAL, CRC8_INIT) != 0xFF) {
            fprintf(stderr, "CRC8 temperature failed\n");
            continue;
        }

        humidity_raw = (int)(*((unsigned char *)(i2cData + 2)));
        humidity_raw |= ((int)(*((unsigned char *)(i2cData + 3))) << 8);
        if (crc8(humidity_raw, CRC8_POLYNOMIAL, CRC8_INIT) != 0xFF) {
            fprintf(stderr, "CRC8 humidity failed\n");
            continue;
        }

        temperature = (int)temperature_raw;
        temperature = temperature * TEMPERATURE_SCALE / 65535 + TEMPERATURE_OFFSET;
        humidity = (int)humidity_raw;
        humidity = humidity * HUMIDITY_SCALE / 65535;

        if (fopen(filename, "r") == NULL) {
            if (fopen(filename, "w") == NULL) {
                perror("fopen");
                continue;
            }
        }

        if (fputs(timestamp, stdout) < 0) {
            perror("fputs");
            continue;
        }
        if (fputs(",", stdout) < 0) {
            perror("fputs");
            continue;
        }
        if (fprintf(stdout, "%f", temperature) < 0) {
            perror("fprintf");
            continue;
        }
        if (fputs(",", stdout) < 0) {
            perror("fputs");
            continue;
        }
        if (fprintf(stdout, "%f", humidity) < 0) {
            perror("fprintf");
            continue;
        }
        if (fputs("\n", stdout) < 0) {
            perror("fputs");
            continue;
        }

        if (fclose(stdout) < 0) {
            perror("fclose");
            continue;
        }

        if (fputs(timestamp, filename) < 0) {
            perror("fputs");
            continue;
        }
        if (fputs(",", filename) < 0) {
            perror("fputs");
            continue;
        }
        if (fprintf(filename, "%f", temperature) < 0) {
            perror("fprintf");
            continue;
        }
        if (fputs(",", filename) < 0) {
            perror("fputs");
            continue;
        }
        if (fprintf(filename, "%f", humidity) < 0) {
            perror("fprintf");
            continue;
        }
        if (fputs("\n", filename) < 0) {
            perror("fputs");
            continue;
        }

        if (fclose(filename) < 0) {
            perror("fclose");
            continue;
        }
    }

    return 0;
}

int crc8(unsigned int data, unsigned int poly, unsigned char init) {
    unsigned char crc = init;
    while (data) {
        unsigned char bit = data & 1;
        data >>= 1;
        crc = (crc << 1) | (bit ? 0xFF : 0x00);
        if (crc & 0x80) {
            crc ^= poly;
        }
    }
    return crc;
}

