#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define TEMPERATURE_REG 0x00
#define BUFFER_SIZE 10
#define LED_PIN 17
#define AVG_THRESHOLD 28.0

int i2c_fd;
int buffer[BUFFER_SIZE];
int buffer_index = 0;
double running_avg = 0.0;
int buffer_full = 0;
int buffer_empty = 1;

void handle_sigint(int signum) {
    gpioTerminate();
    printf("Exiting...\n");
    exit(0);
}

void handle_sigterm(int signum) {
    gpioTerminate();
    printf("Exiting...\n");
    exit(0);
}

void init_i2c() {
    if (gpioInitialise() < 0) {
        perror("pigpioInitialise");
        exit(1);
    }
    i2c_fd = gpioI2COpen(I2C_BUS, I2C_ADDR);
    if (i2c_fd < 0) {
        perror("gpioI2COpen");
        exit(1);
    }
}

void read_temperature() {
    if (buffer_empty) {
        buffer_empty = 0;
        buffer_full = 0;
    }
    if (buffer_full) {
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    }
    int data[2];
    if (gpioI2CReadWordData(i2c_fd, data) < 0) {
        printf("I2C read failed\n");
        return;
    }
    int temp = (data[1] << 8) | data[0];
    temp = (temp >> 7) & 0x7F;
    temp = temp / 2;
    buffer[buffer_index] = temp;
    running_avg = (running_avg * (BUFFER_SIZE - 1) + buffer[buffer_index]) / BUFFER_SIZE;
}

void update_led() {
    if (running_avg > AVG_THRESHOLD) {
        gpioWrite(LED_PIN, 1);
    } else {
        gpioWrite(LED_PIN, 0);
    }
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);
    init_i2c();
    while (1) {
        read_temperature();
        update_led();
        sleep(1);
    }
    return 0;
}

