#define SHTC3_ADDR 0x70
#define SHTC3_CMD_NORMAL_POWER 0x7866
#define SHTC3_CMD_NORMAL_MEASUREMENT 0x7866
#define SHTC3_MEASUREMENT_TIMEOUT 124
#define SHTC3_MEASUREMENT_INTERVAL 5000

#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT_VALUE 0xFF

typedef struct {
    int fd;
    int i2c_fd;
    int gpio_fd;
    int temperature;
    int humidity;
    int temperature_valid;
    int humidity_valid;
    int temperature_error;
    int humidity_error;
    int log_fd;
} SHTC3Environment;

void handle_shtc3_error(int error_code, const char *message) {
    fprintf(stderr, "SHTC3 error: %d - %s\n", error_code, message);
    exit(EXIT_FAILURE);
}

void handle_i2c_error(int error_code) {
    fprintf(stderr, "I2C error: %d\n", error_code);
    exit(EXIT_FAILURE);
}

void handle_gpio_error(int error_code) {
    fprintf(stderr, "GPIO error: %d\n", error_code);
    exit(EXIT_FAILURE);
}

void handle_file_error(int error_code) {
    fprintf(stderr, "File error: %d\n", error_code);
    exit(EXIT_FAILURE);
}

void handle_sigint(int signum) {
    if (SHTC3Environment.gpio_fd > 0) {
        gpioTerminate();
    }
    close(SHTC3Environment.i2c_fd);
    close(SHTC3Environment.log_fd);
    exit(EXIT_SUCCESS);
}

int main() {
    SHTC3Environment shtc3_env;

    shtc3_env.temperature = 0;
    shtc3_env.humidity = 0;
    shtc3_env.temperature_valid = 0;
    shtc3_env.humidity_valid = 0;
    shtc3_env.temperature_error = 0;
    shtc3_env.humidity_error = 0;
    shtc3_env.log_fd = -1;

    shtc3_env.gpio_fd = gpioInitialise();
    if (shtc3_env.gpio_fd < 0) {
        handle_gpio_error(shtc3_env.gpio_fd);
    }

    shtc3_env.i2c_fd = i2cOpen(1);
    if (shtc3_env.i2c_fd < 0) {
        handle_i2c_error(shtc3_env.i2c_fd);
    }

    shtc3_env.log_fd = open("shtc3_environment.log", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (shtc3_env.log_fd < 0) {
        handle_file_error(shtc3_env.log_fd);
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        int i2c_error = i2cWrite(shtc3_env.i2c_fd, SHTC3_ADDR, SHTC3_CMD_NORMAL_MEASUREMENT);
        if (i2c_error < 0) {
            handle_i2c_error(i2c_error);
        }

        struct i2c_msg msg[1];
        struct i2c_rdma_msg rdma_msg[1];
        msg[0].addr = SHTC3_ADDR;
        msg[0].flags = I2C_M_RD;
        msg[0].len = 6;
        msg[0].data = (char *) calloc(6, sizeof(char));

        int i2c_error = i2cRead(shtc3_env.i2c_fd, msg, 1);
        if (i2c_error < 0) {
            handle_i2c_error(i2c_error);
        }

        int crc8_valid = 1;
        for (int i = 0; i < 6; i++) {
            if (i == 2 || i == 5) {
                int crc8 = 0;
                for (int j = 0; j < 4; j++) {
                    crc8 = crc8 ^ msg[0].data[j];
                    crc8 = crc8 << 8;
                    crc8 |= (msg[0].data[j + 4] & 0xFF);
                }
                if (crc8 != (msg[0].data[i] & 0xFF)) {
                    crc8_valid = 0;
                    break;
                }
            }
        }

        if (crc8_valid) {
            shtc3_env.temperature = (msg[0].data[0] << 8) | msg[0].data[1];
            shtc3_env.humidity = (msg[0].data[2] << 8) | msg[0].data[3];
            shtc3_env.temperature_valid = 1;
            shtc3_env.humidity_valid = 1;
        } else {
            shtc3_env.temperature_valid = 0;
            shtc3_env.humidity_valid = 0;
            shtc3_env.temperature_error = 1;
            shtc3_env.humidity_error = 1;
        }

        if (shtc3_env.temperature_valid && shtc3_env.humidity_valid) {
            double temperature = (175.0 * shtc3_env.temperature) / 65535.0 - 45.0;
            double humidity = (100.0 * shtc3_env.humidity) / 65535.0;
            if (temperature >= -40.0 && temperature <= 125.0 && humidity >= 0.0 && humidity <= 100.0) {
                char buffer[128];
                struct tm *now = gmtime(&time(NULL));
                strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", now);
                fprintf(shtc3_env.log_fd, "%s,%f,%f\n", buffer, temperature, humidity);
                printf("%.2f,%f\n", temperature, humidity);
            } else {
                shtc3_env.temperature_error = 1;
                shtc3_env.humidity_error = 1;
            }
        }

        usleep(SHTC3_MEASUREMENT_TIMEOUT * 1000);
        usleep(SHTC3_MEASUREMENT_INTERVAL * 1000);
    }

    close(shtc3_env.i2c_fd);
    close(shtc3_env.log_fd);
    gpioTerminate();
    return 0;
}

