#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define TEMPERATURE_REGISTER 0x00
#define FAN_GPIO 18
#define FAN_ON_THRESHOLD 28.0
#define FAN_OFF_THRESHOLD 26.0
#define BUFFER_SIZE 60
#define BUFFER_OFFSET 0
#define BUFFER_SIZE_BYTES (BUFFER_SIZE * 2)

typedef struct {
    int8_t buffer[BUFFER_SIZE];
    float running_average;
} TemperatureData;

static TemperatureData temperature_data;

static int i2c_fd;
static int gpio_fd;

static void handle_sigint(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signum);
        pi_set_mode(gpio_fd, PI_OFF);
        pi_close(gpio_fd);
        pi_close(i2c_fd);
        exit(0);
    }
}

static void init_temperature_sensor() {
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
    if (pi_i2c_open(i2c_fd, I2C_BUS, I2C_ADDR) < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }
}

static void init_gpio() {
    if (gpio_fd < 0) {
        perror("Failed to open GPIO");
        exit(EXIT_FAILURE);
    }
    if (pi_set_mode(gpio_fd, PI_OUTPUT)) {
        perror("Failed to set GPIO mode");
        exit(EXIT_FAILURE);
    }
}

static void read_temperature() {
    if (pi_i2c_read_i2c_multi(i2c_fd, 1, &temperature_data.buffer[BUFFER_OFFSET], 1) < 0) {
        perror("Failed to read temperature");
        exit(EXIT_FAILURE);
    }
    temperature_data.running_average = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        temperature_data.running_average += temperature_data.buffer[i];
    }
    temperature_data.running_average /= BUFFER_SIZE;
}

static void update_running_average() {
    temperature_data.running_average = 0.0;
    for (int i = 1; i < BUFFER_SIZE; i++) {
        temperature_data.running_average += temperature_data.buffer[i];
    }
    temperature_data.running_average += temperature_data.buffer[0];
    temperature_data.running_average /= BUFFER_SIZE;
}

static void control_fan() {
    if (temperature_data.running_average > FAN_ON_THRESHOLD) {
        if (pi_set_mode(gpio_fd, PI_ON)) {
            perror("Failed to set GPIO mode");
            exit(EXIT_FAILURE);
        }
    } else if (temperature_data.running_average < FAN_OFF_THRESHOLD) {
        if (pi_set_mode(gpio_fd, PI_OFF)) {
            perror("Failed to set GPIO mode");
            exit(EXIT_FAILURE);
        }
    }
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    pi_init();
    init_temperature_sensor();
    init_gpio();

    temperature_data.running_average = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        temperature_data.buffer[i] = 0;
    }

    while (1) {
        read_temperature();
        update_running_average();
        control_fan();

        for (int i = 0; i < BUFFER_SIZE; i++) {
            printf("%.1f\n", temperature_data.buffer[i]);
        }
        printf("Running average: %.1f\n", temperature_data.running_average);
        printf("Fan state: %s\n", pi_get_mode(gpio_fd) ? "ON" : "OFF");

        usleep(1000000); // 1 second delay
    }

    pi_close(i2c_fd);
    pi_close(gpio_fd);
    pi_exit();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define CMD_MEAS 0x362F
#define CRC8_POLY 0x31
#define CRC8_INIT 0xFF
#define SCALE_PRESSURE 60
#define SCALE_TEMPERATURE 200
#define LOG_FILE "airflow.log"
#define PRESSURE_WARNING 5.0

typedef struct {
    uint64_t timestamp;
    double pressure;
    double temperature;
} AirflowData;

void crc8_validate(uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    if (crc != data[len]) {
        fprintf(stderr, "CRC mismatch\n");
        exit(EXIT_FAILURE);
    }
}

int main() {
    pid_t pid = getpid();
    char log_buffer[256];
    AirflowData data;
    int i2c_fd;
    int status;
    uint8_t buffer[10];
    struct timespec ts;

    if (signal(SIGINT, [](int) {
        close(i2c_fd);
        close(log_fd);
        gpioTerminate();
        exit(EXIT_SUCCESS);
    }) == SIG_ERR) {
        perror("SIGINT handler");
        exit(EXIT_FAILURE);
    }

    if (signal(SIGTERM, [](int) {
        close(i2c_fd);
        close(log_fd);
        gpioTerminate();
        exit(EXIT_SUCCESS);
    }) == SIG_ERR) {
        perror("SIGTERM handler");
        exit(EXIT_FAILURE);
    }

    if ((i2c_fd = i2c_open(I2C_BUS, I2C_ADDR)) < 0) {
        perror("i2c_open");
        exit(EXIT_FAILURE);
    }

    if (i2c_ioctl(i2c_fd, I2C_RDWR, &CMD_MEAS, buffer, sizeof(buffer)) < 0) {
        perror("i2c_ioctl");
        exit(EXIT_FAILURE);
    }

    if (i2c_read(i2c_fd, buffer, 10) < 0) {
        perror("i2c_read");
        exit(EXIT_FAILURE);
    }

    crc8_validate(buffer, 9);

    data.timestamp = (uint64_t)time(NULL);
    data.pressure = (double)((buffer[2] << 8) | buffer[3]) / SCALE_PRESSURE;
    data.temperature = (double)((buffer[4] << 8) | buffer[5]) / SCALE_TEMPERATURE;

    snprintf(log_buffer, sizeof(log_buffer), "%ld,%f,%f\n", data.timestamp, data.pressure, data.temperature);
    if (write(log_fd, log_buffer, strlen(log_buffer)) < 0) {
        perror("write");
        exit(EXIT_FAILURE);
    }

    if (data.pressure > PRESSURE_WARNING) {
        fprintf(stderr, "Warning: Pressure exceeds %f Pa\n", PRESSURE_WARNING);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <gpiod.h>
#include <errno.h>
#include <stdint.h>

#define I2C_DEV "/dev/i2c-" I2C_BUS
#define I2C_BUS 1
#define I2C_ADDR 0x4A
#define I2C_REG 0x00
#define I2C_SIZE 2
#define GPIO_PIN 17
#define GPIO_CHIP 0
#define GPIO_LINE 0

int i2c_fd;
gpiod_chip_t *chip;
gpiod_line_t *line;

int main() {
    // Open I2C device
    if ((i2c_fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize I2C
    if (ioctl(i2c_fd, I2C_SLAVEX) < 0) {
        perror("Failed to initialize I2C");
        close(i2c_fd);
        return 1;
    }

    // Create a chip object
    if ((chip = gpiod_chip_new()) == NULL) {
        perror("Failed to create chip object");
        close(i2c_fd);
        return 1;
    }

    // Add a line to the chip
    if ((line = gpiod_chip_new_line(chip, GPIO_LINE, GPIO_CHIP, GPIO_EDGE_NONE)) == NULL) {
        perror("Failed to add line to chip");
        gpiod_chip_delete(chip);
        close(i2c_fd);
        return 1;
    }

    // Set the line to output mode
    if (gpiod_line_set_mode(line, GPIOD_MODE_OUTPUT) < 0) {
        perror("Failed to set line mode");
        gpiod_chip_delete(chip);
        gpiod_line_delete(line);
        close(i2c_fd);
        return 1;
    }

    // Set the line to high
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Failed to set line value");
        gpiod_chip_delete(chip);
        gpiod_line_delete(line);
        close(i2c_fd);
        return 1;
    }

    while (1) {
        // Read I2C register
        uint16_t temp = 0;
        if (ioctl(i2c_fd, I2C_SMBUS_READ, I2C_REG, I2C_SIZE, &temp) < 0) {
            perror("Failed to read I2C register");
            gpiod_chip_delete(chip);
            gpiod_line_delete(line);
            close(i2c_fd);
            return 1;
        }

        // Convert to Celsius
        int16_t celsius = (temp >> 4) * 0.0625;
        printf("Temperature: %d.0625°C\n", celsius);

        // Check hysteresis band
        if (celsius > 28) {
            // Set LED to high
            if (gpiod_line_set_value(line, 1) < 0) {
                perror("Failed to set LED value");
                gpiod_chip_delete(chip);
                gpiod_line_delete(line);
                close(i2c_fd);
                return 1;
            }
        } else if (celsius < 27) {
            // Set LED to low
            if (gpiod_line_set_value(line, 0) < 0) {
                perror("Failed to set LED value");
                gpiod_chip_delete(chip);
                gpiod_line_delete(line);
                close(i2c_fd);
                return 1;
            }
        }

        // Sleep for 1 second
        usleep(1000000);

        // Handle SIGINT/SIGTERM
        if (sigsetid(0) == 0) {
            sigset_t sigset;
            sigemptyset(&sigset);
            sigaddset(&sigset, SIGINT);
            sigaddset(&sigset, SIGTERM);
            sigprocmask(SIG_BLOCK, &sigset, NULL);

            if (signal(SIGINT, [](int sig) {
                gpiod_chip_delete(chip);
                gpiod_line_delete(line);
                close(i2c_fd);
                return 0;
            }) == SIG_ERR) {
                perror("Failed to set signal handler");
                return 1;
            }

            if (signal(SIGTERM, [](int sig) {
                gpiod_chip_delete(chip);
                gpiod_line_delete(line);
                close(i2c_fd);
                return 0;
            }) == SIG_ERR) {
                perror("Failed to set signal handler");
                return 1;
            }
        }
    }

    // Cleanup
    gpiod_chip_delete(chip);
    gpiod_line_delete(line);
    close(i2c_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define CMD_MEASUREMENT 0x362F
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

typedef struct {
    uint8_t pressure[2];
    uint8_t temperature[2];
    uint16_t scale_factor;
} SensorData;

typedef struct {
    uint64_t timestamp;
    SensorData data;
} Reading;

void handle_sigint(int sig) {
    printf("SIGINT received, exiting...\n");
    pi_write(pi_i2c_open(I2C_BUS, I2C_ADDR, 0), 0, 0);
    pi_close();
    exit(0);
}

int main() {
    signal(SIGINT, handle_sigint);

    if (pi_init() < 0) {
        perror("pigpio init failed");
        return 1;
    }

    int fd = pi_i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (fd < 0) {
        perror("i2c open failed");
        pi_close();
        return 1;
    }

    while (1) {
        pi_i2c_write(fd, CMD_MEASUREMENT, 0);
        pi_i2c_wait(45); // Wait at least 45 ms

        uint8_t buffer[9];
        ssize_t bytes_read = pi_i2c_read(fd, buffer, 9);
        if (bytes_read != 9) {
            printf("Error reading I2C data: %d bytes read\n", bytes_read);
            pi_i2c_close(fd);
            pi_close();
            return 1;
        }

        uint8_t crc = buffer[8];
        uint16_t crc_calculated = 0;
        for (int i = 0; i < 8; i++) {
            crc_calculated = (crc_calculated << 8) ^ buffer[i];
        }
        if (crc_calculated != crc) {
            printf("CRC error for pressure: %02x != %02x\n", crc, crc_calculated);
            pi_i2c_close(fd);
            pi_close();
            return 1;
        }

        crc = buffer[6];
        crc_calculated = 0;
        for (int i = 0; i < 7; i++) {
            crc_calculated = (crc_calculated << 8) ^ buffer[i];
        }
        if (crc_calculated != crc) {
            printf("CRC error for temperature: %02x != %02x\n", crc, crc_calculated);
            pi_i2c_close(fd);
            pi_close();
            return 1;
        }

        SensorData data;
        data.pressure[0] = buffer[0];
        data.pressure[1] = buffer[1];
        data.temperature[0] = buffer[2];
        data.temperature[1] = buffer[3];
        data.scale_factor = (buffer[4] << 8) | buffer[5];

        Reading reading;
        reading.timestamp = (uint64_t)time(NULL);
        reading.data = data;

        FILE *file = fopen("flow_data.txt", "a");
        if (file == NULL) {
            perror("error opening file");
            pi_i2c_close(fd);
            pi_close();
            return 1;
        }

        fprintf(file, "%llu,%d,%d,%d,%d,%d\n", reading.timestamp, data.pressure[0], data.pressure[1], data.temperature[0], data.temperature[1], data.scale_factor);
        fclose(file);

        pi_i2c_close(fd);
        pi_close();
    }

    return 0;
}

