#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define CMD_MEAS 0x3615
#define CRC_POLY 0x31
#define CRC_INIT 0xFF
#define PRESSURE_BYTES 2
#define TEMPERATURE_BYTES 2
#define SCALE_BYTES 3
#define LOG_FILE "hvac_pressure_log.txt"
#define LOG_FMT "%ld,%ld,%ld\n"

typedef struct {
    int fd;
    int i2c_fd;
    int i2c_err;
    int crc_err;
    int temp_err;
    int scale_err;
} SensorData;

void handle_error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

void handle_sigint(int sig) {
    if (SensorData.i2c_fd > 0) {
        i2c_close(SensorData.i2c_fd);
    }
    if (fopen(LOG_FILE, "a") == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    fclose(fopen(LOG_FILE, "w"));
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    SensorData data;
    data.fd = 0;
    data.i2c_fd = 0;
    data.i2c_err = 0;
    data.crc_err = 0;
    data.temp_err = 0;
    data.scale_err = 0;

    if (gpioInitialise() < 0) {
        handle_error("gpioInitialise failed");
    }

    if (i2cOpen(I2C_BUS, I2C_ADDR, &data.i2c_fd) < 0) {
        handle_error("i2cOpen failed");
    }

    if (fopen(LOG_FILE, "w") == NULL) {
        handle_error("Failed to open log file");
    }

    while (1) {
        struct timeval tv;
        gettimeofday(&tv, NULL);
        long timestamp = tv.tv_sec * 1000 + tv.tv_usec / 1000;

        if (i2cWrite(data.i2c_fd, CMD_MEAS, 1) < 0) {
            data.i2c_err = 1;
        } else {
            data.i2c_err = 0;
        }

        if (data.i2c_err || data.crc_err || data.temp_err || data.scale_err) {
            fprintf(stderr, "Error reading sensor: %d\n", data.i2c_err + data.crc_err * 2 + data.temp_err * 4 + data.scale_err * 8);
            continue;
        }

        if (i2cRead(data.i2c_fd, 9, &data.data) < 0) {
            data.i2c_err = 1;
        } else {
            data.i2c_err = 0;
        }

        if (data.i2c_err) {
            fprintf(stderr, "Error reading sensor: i2cRead failed\n");
            continue;
        }

        uint8_t crc = 0;
        for (int i = 0; i < 8; i++) {
            crc = crc ^ data.data[i];
            crc = crc << 1;
            if (crc & 0x80) {
                crc ^= CRC_POLY;
            }
        }

        if (crc != data.data[8]) {
            data.crc_err = 1;
        } else {
            data.crc_err = 0;
        }

        if (data.crc_err) {
            fprintf(stderr, "Error reading sensor: CRC error\n");
            continue;
        }

        double pressure = 0.0;
        double temperature = 0.0;

        for (int i = 0; i < PRESSURE_BYTES; i++) {
            pressure += data.data[i + 9] * (1 << (8 - i));
        }
        pressure /= 256.0;

        for (int i = 0; i < TEMPERATURE_BYTES; i++) {
            temperature += data.data[i + 9 + PRESSURE_BYTES] * (1 << (8 - i));
        }
        temperature /= 256.0;
        temperature /= 200.0;

        fprintf(fopen(LOG_FILE, "a"), LOG_FMT, timestamp, (int)(pressure * 1000), (int)(temperature * 1000));

        sleep(1000);
    }

    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <syslog.h>
#include <time.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x62
#define START_PERIODIC_MEASUREMENT 0x21B1
#define READ_CO2_TEMP_HUMIDITY 0xE000
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF
#define CO2_MIN 0
#define CO2_MAX 4000
#define TEMP_MIN -45
#define TEMP_MAX 175
#define HUMID_MIN 0
#define HUMID_MAX 100
#define BUFFER_SIZE 100
#define CSV_FILE "/var/log/scd40_data/scd40_data.csv"
#define ERROR_LOG "/var/log/scd40_error.log"

volatile sig_atomic_t running = 1;

typedef struct {
    time_t timestamp;
    double co2;
    double temperature;
    double humidity;
} SensorReading;

typedef struct {
    SensorReading buffer[BUFFER_SIZE];
    int head, tail;
    int count;
    pthread_mutex_t mutex;
} CircularBuffer;

CircularBuffer buffer;

void *logging_thread(void *arg) {
    while (running) {
        pthread_mutex_lock(&buffer.mutex);
        if (buffer.count == BUFFER_SIZE) {
            pthread_mutex_unlock(&buffer.mutex);
            continue;
        }
        pthread_mutex_unlock(&buffer.mutex);
        char *filename = (char *)malloc(strlen(CSV_FILE) + 24);
        snprintf(filename, strlen(CSV_FILE) + 24, "%s-%s.csv", CSV_FILE, ctime(&time(NULL)));
        FILE *file = fopen(filename, "w");
        if (!file) {
            fprintf(stderr, "Failed to open CSV file: %s\n", filename);
            free(filename);
            continue;
        }
        fprintf(file, "timestamp,co2,temperature,humidity\n");
        for (int i = 0; i < buffer.count; i++) {
            SensorReading reading = buffer.buffer[i];
            fprintf(file, "%ld,%f,%f,%f\n", reading.timestamp, reading.co2, reading.temperature, reading.humidity);
        }
        fclose(file);
        free(filename);
        pthread_mutex_lock(&buffer.mutex);
        buffer.count = 0;
        pthread_mutex_unlock(&buffer.mutex);
    }
    free(filename);
    return NULL;
}

void *sensor_loop(void *arg) {
    int i2c_fd = -1;
    if ((i2c_fd = i2c_open(I2C_BUS, I2C_ADDR)) < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_fd);
        return NULL;
    }
    if (pigpio_open(0) < 0) {
        fprintf(stderr, "Failed to open pigpio: %d\n", i2c_fd);
        return NULL;
    }
    if (pigpio_i2c_open(i2c_fd, 0) < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_fd);
        return NULL;
    }
    if (pigpio_set_mode(i2c_fd, pigpioORMAL) < 0) {
        fprintf(stderr, "Failed to set I2C device mode: %d\n", i2c_fd);
        return NULL;
    }
    if (pigpio_i2c_write(i2c_fd, START_PERIODIC_MEASUREMENT) < 0) {
        fprintf(stderr, "Failed to send start periodic measurement command: %d\n", i2c_fd);
        return NULL;
    }
    while (running) {
        if (pigpio_delay(1000) < 0) {
            fprintf(stderr, "Failed to wait 1 second: %d\n", i2c_fd);
            return NULL;
        }
        if (pigpio_i2c_write(i2c_fd, READ_CO2_TEMP_HUMIDITY) < 0) {
            fprintf(stderr, "Failed to send read command: %d\n", i2c_fd);
            continue;
        }
        char buffer[9];
        if (pigpio_i2c_read(i2c_fd, buffer, 9) < 0) {
            fprintf(stderr, "Failed to read response: %d\n", i2c_fd);
            continue;
        }
        if (crc8(buffer, 8, CRC8_POLYNOMIAL, CRC8_INIT) != 0) {
            fprintf(stderr, "CRC8 check failed: %s\n", buffer);
            continue;
        }
        double co2 = (buffer[2] * 256 + buffer[3]) / 65535.0 * (CO2_MAX - CO2_MIN) + CO2_MIN;
        double temperature = TEMP_MIN + 175.0 * (buffer[4] * 256 + buffer[5]) / 65535.0;
        double humidity = HUMID_MIN + 100.0 * (buffer[6] * 256 + buffer[7]) / 65535.0;
        SensorReading reading;
        reading.timestamp = time(NULL);
        reading.co2 = co2;
        reading.temperature = temperature;
        reading.humidity = humidity;
        pthread_mutex_lock(&buffer.mutex);
        if (buffer.count < BUFFER_SIZE) {
            buffer.buffer[buffer.head] = reading;
            buffer.head = (buffer.head + 1) % BUFFER_SIZE;
            buffer.count++;
        } else {
            fprintf(stderr, "Buffer full, skipping reading\n");
        }
        pthread_mutex_unlock(&buffer.mutex);
        if (pigpio_delay(5000) < 0) {
            fprintf(stderr, "Failed to wait 5 seconds: %d\n", i2c_fd);
            return NULL;
        }
    }
    pigpio_i2c_close(i2c_fd);
    pigpio_close(0);
    return NULL;
}

void *crc8(void *arg) {
    char *data = (char *)arg;
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < 8; i++) {
        crc = (crc >> 1) ^ (crc & 1 ? CRC8_POLYNOMIAL : 0);
        crc ^= data[i];
    }
    return (uint8_t)(crc & 0xFF);
}

void *error_logger(void *arg) {
    FILE *file = fopen(ERROR_LOG, "a");
    if (!file) {
        fprintf(stderr, "Failed to open error log file: %s\n", ERROR_LOG);
        return NULL;
    }
    while (running) {
        char *line = (char *)malloc(256);
        snprintf(line, 256, "%s: %s\n", ctime(&time(NULL)), strerror(errno));
        fprintf(file, "%s", line);
        free(line);
    }
    fclose(file);
    return NULL;
}

void *sigint_handler(int signum) {
    running = 0;
    return NULL;
}

int main() {
    pthread_t logging_thread, sensor_thread, error_logger_thread;
    pthread_mutex_init(&buffer.mutex, NULL);
    signal(SIGINT, sigint_handler);
    pthread_create(&logging_thread, NULL, logging_thread, NULL);
    pthread_create(&sensor_thread, NULL, sensor_loop, NULL);
    pthread_create(&error_logger_thread, NULL, error_logger, NULL);
    pthread_join(logging_thread, NULL);
    pthread_join(sensor_thread, NULL);
    pthread_join(error_logger_thread, NULL);
    return 0;
}

