#define HTML_PAGE "<!DOCTYPE html>\r\n<html>\r\n<head>\r\n<title>Temperature and Humidity</title>\r\n</head>\r\n<body>\r\n<h1>Temperature and Humidity</h1>\r\n%s%s%s</body>\r\n</html>"

void handle_sensor_error(int error_code) {
    if (error_code == SENSOR_PRESENT) {
        printf("Sensor present\n");
    } else if (error_code == BUS_ERROR) {
        printf("Bus error\n");
    } else if (error_code == SENSOR_ABSENT) {
        printf("Sensor absent\n");
    }
}

void handle_i2c_error(int error_code) {
    handle_sensor_error(error_code);
}

void handle_measurement_error(int error_code) {
    handle_sensor_error(error_code);
}

void handle_measurement_timeout() {
    printf("Measurement timed out\n");
}

void handle_measurement_failure() {
    handle_measurement_error(BUS_ERROR);
}

void handle_measurement_success(int raw_T, int raw_RH) {
    double T = TEMP_OFFSET + TEMP_SCALE * (raw_T / 65535.0);
    double RH = RH_OFFSET + RH_SCALE * (raw_RH / 65535.0);
    RH = fmax(0.0, fmin(RH, 100.0));
    printf("Temperature: %.1f°C\n", T);
    printf("Humidity: %.1f%%\n", RH);
}

void handle_i2c_connection(int fd) {
    if (ioctl(fd, SIOCSI2C, 0) < 0) {
        perror("ioctl SIOCSI2C");
        exit(EXIT_FAILURE);
    }
}

void handle_i2c_init() {
    int fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open /dev/i2c");
        exit(EXIT_FAILURE);
    }
    if (ioctl(fd, SIOCSI2C, I2C_ADDR) < 0) {
        perror("ioctl SIOCSI2C");
        exit(EXIT_FAILURE);
    }
    handle_i2c_connection(fd);
}

void handle_measurement() {
    int retries = 0;
    int raw_T = 0;
    int raw_RH = 0;
    int error_code = SENSOR_PRESENT;

    while (retries < MAX_RETRIES) {
        if (retries > 0) {
            usleep(RETRY_DELAY_MS * 1000);
        }

        if (gpio_i2c_read32(fd, MEASUREMENT_COMMAND, &raw_T, &raw_RH) < 0) {
            handle_measurement_error(BUS_ERROR);
            retries++;
            continue;
        }

        handle_measurement_success(raw_T, raw_RH);
        error_code = SENSOR_PRESENT;
        break;
    }

    if (error_code == SENSOR_ABSENT) {
        handle_measurement_failure();
    }
}

void handle_http_connection(int sock) {
    char buffer[HTML_PAGE_SIZE];
    struct sockaddr_in server_addr;
    socklen_t server_len = sizeof(server_addr);

    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(HTTP_PORT);
    inet_pton(AF_INET, HTTP_IP, &server_addr.sin_addr);

    if (connect(sock, (struct sockaddr *)&server_addr, server_len) < 0) {
        perror("connect");
        return;
    }

    int bytes_received = 0;
    int bytes_sent = 0;

    while (1) {
        if (bytes_received == 0) {
            if (read(sock, buffer, HTML_PAGE_SIZE) < 0) {
                perror("read");
                return;
            }
            bytes_received = strlen(buffer);
        }

        if (strstr(buffer, "GET /") != NULL) {
            handle_measurement();
            bytes_sent = snprintf(buffer, HTML_PAGE_SIZE, HTML_PAGE, HTML_TEMP_LINE, HTML_TEMP_LABEL, HTML_TEMP_FORMAT, T, HTML_RH_LINE, HTML_RH_LABEL, HTML_RH_FORMAT, RH);
            if (write(sock, buffer, bytes_sent) < 0) {
                perror("write");
                return;
            }
            bytes_sent = 0;
        }

        if (strstr(buffer, "Connection: close") != NULL) {
            break;
        }
    }

    close(sock);
}

void handle_signal(int signum) {
    printf("Received signal %d\n", signum);
    if (signum == SIGINT || signum == SIGTERM) {
        handle_measurement();
        handle_i2c_close();
        exit(EXIT_SUCCESS);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    handle_i2c_init();

    int server_fd, new_socket;
    struct sockaddr_in address;
    int addrlen = sizeof(address);

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(HTTP_PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind");
        exit(EXIT_FAILURE);
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    while (1) {
        new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t *)&addrlen);
        if (new_socket < 0) {
            perror("accept");
            continue;
        }

        handle_http_connection(new_socket);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/i2c.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define TMP102_REG 0x00
#define TMP102_TEMP_SHIFT 4
#define TMP102_TEMP_MULT 0.0625

int i2c_fd;
int temp_read_result;
uint16_t temp_value;
char timestamp[20];

void handle_sigint(int signum) {
    if (i2c_fd > 0) {
        close(i2c_fd);
    }
    pi_stop();
    exit(0);
}

int main() {
    if (signal(SIGINT, handle_sigint) == SIG_ERR) {
        perror("Failed to set SIGINT handler");
        exit(EXIT_FAILURE);
    }

    if (pi_init() < 0) {
        perror("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }

    if ((i2c_fd = i2c_open(I2C_BUS, I2C_ADDR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (i2c_ioctl(i2c_fd, I2C_RDWR, &i2c_ioctl_cmd_t{I2C_RDWR, I2C_I2C_SLAVE, 0}) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }

    while (1) {
        temp_read_result = i2c_read_byte(i2c_fd, TMP102_REG);
        if (temp_read_result < 0) {
            fprintf(stderr, "Failed to read temperature: %s\n", strerror(errno));
            continue;
        }

        temp_value = (uint16_t) temp_read_result;
        temp_value >>= TMP102_TEMP_SHIFT;
        temp_value *= TMP102_TEMP_MULT;

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&time(NULL)));

        printf("%s,%f\n", timestamp, temp_value);

        if (fopen("temperature_log.csv", "a") == NULL) {
            perror("Failed to open temperature log file for append");
            exit(EXIT_FAILURE);
        }

        if (fprintf(fopen("temperature_log.csv", "a"), "%s,%f\n", timestamp, temp_value) < 0) {
            perror("Failed to write to temperature log file");
            exit(EXIT_FAILURE);
        }

        if (fclose(fopen("temperature_log.csv", "a")) < 0) {
            perror("Failed to close temperature log file");
            exit(EXIT_FAILURE);
        }

        usleep(500000); // 5 seconds
    }

    return 0;
}

