#define SPI0_CE0 0
#define SPI0_CE1 1
#define SPI0_CS 0
#define SPI0_MOSI 1
#define SPI0_MISO 2
#define SPI0_SCLK 3
#define SPI0_MOSI_PIN GPIO1_7
#define SPI0_MISO_PIN GPIO1_8
#define SPI0_SCLK_PIN GPIO1_9
#define SPI0_CE0_PIN GPIO1_10
#define SPI0_CE1_PIN GPIO1_11
#define SPI0_CS_PIN GPIO1_12
#define RELAY_PIN 17

#define MAX6675_CS 0
#define MAX6675_MOSI 1
#define MAX6675_MISO 2
#define MAX6675_SCLK 3
#define MAX6675_CE 4

#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_MODE 0

#define PID_KP 0.1
#define PID_KI 0.01
#define PID_KD 0.001
#define PID_SAMPLE_TIME 1

#define LOG_FILE "reflow_log.csv"

typedef struct {
    int pid;
    double target_temp;
    double current_temp;
    double error;
    double derivative;
    double integral;
    double output;
} PIDState;

PIDState pid_state;

int spi_fd;
int spi_cs_fd;
int spi_ce0_fd;
int spi_ce1_fd;
int relay_fd;
int max6675_fd;

void handle_spi_error(int err) {
    fprintf(stderr, "SPI error: %d\n", err);
    exit(EXIT_FAILURE);
}

void handle_gpio_error(int err) {
    fprintf(stderr, "GPIO error: %d\n", err);
    exit(EXIT_FAILURE);
}

void handle_sigint(int sig) {
    fprintf(stderr, "Caught SIGINT, exiting...\n");
    exit(EXIT_SUCCESS);
}

void init_spi() {
    int spi_mode = SPI_MODE;
    int spi_bits = SPI_BITS;
    int spi_speed = SPI_SPEED;

    struct spi_ioc_transfer spi_transfer;
    spi_transfer.msb = 0;
    spi_transfer.msbs = 1;
    spi_transfer.size = 1;
    spi_transfer.delay_usec = 0;
    spi_transfer.speed = spi_speed;
    spi_transfer.mode = spi_mode;
    spi_transfer.bits_per_word = spi_bits;

    spi_fd = open("/dev/spi0.0", O_RDWR);
    if (spi_fd < 0) {
        handle_spi_error(errno);
    }

    spi_cs_fd = open("/dev/spi0.0", O_RDWR);
    if (spi_cs_fd < 0) {
        handle_spi_error(errno);
    }

    spi_ce0_fd = open("/dev/spi0.0", O_RDWR);
    if (spi_ce0_fd < 0) {
        handle_spi_error(errno);
    }

    spi_ce1_fd = open("/dev/spi0.0", O_RDWR);
    if (spi_ce1_fd < 0) {
        handle_spi_error(errno);
    }

    ioctl(spi_fd, SPI_IOC_WR_MODE, &spi_mode);
    ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &spi_bits);
    ioctl(spi_fd, SPI_IOC_WR_SPEED_hz, &spi_speed);

    ioctl(spi_cs_fd, SPI_IOC_WR_MODE, &spi_mode);
    ioctl(spi_cs_fd, SPI_IOC_WR_BITS_PER_WORD, &spi_bits);
    ioctl(spi_cs_fd, SPI_IOC_WR_SPEED_hz, &spi_speed);

    ioctl(spi_ce0_fd, SPI_IOC_WR_MODE, &spi_mode);
    ioctl(spi_ce0_fd, SPI_IOC_WR_BITS_PER_WORD, &spi_bits);
    ioctl(spi_ce0_fd, SPI_IOC_WR_SPEED_hz, &spi_speed);

    ioctl(spi_ce1_fd, SPI_IOC_WR_MODE, &spi_mode);
    ioctl(spi_ce1_fd, SPI_IOC_WR_BITS_PER_WORD, &spi_bits);
    ioctl(spi_ce1_fd, SPI_IOC_WR_SPEED_hz, &spi_speed);

    close(spi_fd);
    spi_fd = spi_cs_fd;
    spi_cs_fd = spi_ce0_fd;
    spi_ce0_fd = spi_ce1_fd;
    spi_ce1_fd = 0;
}

void init_gpio() {
    int gpio_mode = GPIO_MODE_OUTPUT;
    int gpio_value = 1;

    struct gpio_chip gpio_chip;
    struct gpio_line gpio_line;

    gpio_chip = gpiod_get_chip(0);
    if (gpio_chip == NULL) {
        handle_gpio_error(errno);
    }

    gpio_line = gpio_chip->get_line(RELAY_PIN);
    if (gpio_line == NULL) {
        handle_gpio_error(errno);
    }

    relay_fd = gpio_chip->get_fd(gpio_line);
    if (relay_fd < 0) {
        handle_gpio_error(errno);
    }

    gpio_set_value(relay_fd, gpio_value);
    if (gpio_set_value(relay_fd, gpio_value) < 0) {
        handle_gpio_error(errno);
    }

    gpio_chip->free_line(gpio_line);
}

void read_max6675() {
    int buffer[3];
    int i;

    for (i = 0; i < 3; i++) {
        buffer[i] = 0;
    }

    struct spi_ioc_transfer spi_transfer;
    spi_transfer.msb = 0;
    spi_transfer.msbs = 1;
    spi_transfer.size = 1;
    spi_transfer.delay_usec = 0;
    spi_transfer.speed = SPI_SPEED;
    spi_transfer.mode = SPI_MODE;
    spi_transfer.bits_per_word = SPI_BITS;

    int spi_cs_fd = spi_ce0_fd;
    int spi_ce1_fd = spi_ce1_fd;

    if (spi_cs_fd > 0) {
        gpio_set_value(spi_cs_fd, 0);
    }

    if (spi_ce1_fd > 0) {
        gpio_set_value(spi_ce1_fd, 1);
    }

    if (ioctl(spi_ce0_fd, SPI_IOC_RD_MOSI, &buffer[0]) < 0) {
        handle_spi_error(errno);
    }

    if (ioctl(spi_ce0_fd, SPI_IOC_RD_MISO, &buffer[1]) < 0) {
        handle_spi_error(errno);
    }

    if (ioctl(spi_ce0_fd, SPI_IOC_RD_SCLK, &buffer[2]) < 0) {
        handle_spi_error(errno);
    }

    if (spi_cs_fd > 0) {
        gpio_set_value(spi_cs_fd, 1);
    }

    if (spi_ce1_fd > 0) {
        gpio_set_value(spi_ce1_fd, 0);
    }

    int temp = (buffer[1] << 4) | (buffer[0] & 0x0F);
    int open_circuit = (buffer[1] >> 4) & 0x1;

    if (open_circuit) {
        fprintf(stderr, "MAX6675 open-circuit detected\n");
        exit(EXIT_FAILURE);
    }

    pid_state.current_temp = (temp * 0.0625) - 0.5;
}

void update_pid() {
    pid_state.error = pid_state.target_temp - pid_state.current_temp;
    pid_state.derivative = pid_state.error - pid_state.previous_error;
    pid_state.integral += pid_state.error * (double)PID_SAMPLE_TIME;

    pid_state.previous_error = pid_state.error;

    pid_state.output = PID_KP * pid_state.error + PID_KI * pid_state.integral + PID_KD * pid_state.derivative;
}

void set_relay_output() {
    int output = pid_state.output * 255;
    if (output < 0) {
        output = 0;
    } else if (output > 255) {
        output = 255;
    }

    int value = output;
    if (gpio_set_value(relay_fd, value) < 0) {
        handle_gpio_error(errno);
    }
}

void log_data() {
    time_t rawtime;
    struct tm * timeinfo;
    char buffer[128];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    snprintf(buffer, sizeof(buffer), "%d-%m-%Y %H:%M:%S,%f", timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday, timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec, (double)timeinfo->tm_monday.tv_usec / 1000000.0);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        exit(EXIT_FAILURE);
    }

    fprintf(log_file, "%s,%f,%f\n", buffer, pid_state.current_temp, pid_state.output);
    fclose(log_file);
}

void cleanup() {
    if (spi_ce0_fd > 0) {
        close(spi_ce0_fd);
    }

    if (spi_ce1_fd > 0) {
        close(spi_ce1_fd);
    }

    if (spi_cs_fd > 0) {
        close(spi_cs_fd);
    }

    if (relay_fd > 0) {
        gpio_free_fd(relay_fd);
    }

    if (max6675_fd > 0) {
        close(max6675_fd);
    }

    if (spi_fd > 0) {
        close(spi_fd);
    }

    if (pid_state.pid > 0) {
        kill(pid_state.pid, SIGKILL);
    }
}

void run() {
    FILE *profile_file = fopen(LOG_FILE, "r");
    if (profile_file == NULL) {
        fprintf(stderr, "Failed to open profile file\n");
        exit(EXIT_FAILURE);
    }

    char line[128];
    int profile_count = 0;
    double profile_times[100];
    double profile_temps[100];

    while (fgets(line, sizeof(line), profile_file)) {
        if (sscanf(line, "%lf,%lf", &profile_times[profile_count], &profile_temps[profile_count]) == 2) {
            profile_count++;
        }
    }

    fclose(profile_file);

    pid_state.pid = fork();
    if (pid_state.pid < 0) {
        handle_gpio_error(errno);
    }

    if (pid_state.pid == 0) {
        execlp("python", "python", "reflow.py", "profile.txt", (char *)NULL);
        handle_gpio_error(errno);
    }

    pid_state.previous_error = 0;

    while (1) {
        read_max6675();
        update_pid();
        set_relay_output();
        log_data();

        sleep(PID_SAMPLE_TIME);
    }
}

int main() {
    signal(SIGINT, handle_sigint);

    init_spi();
    init_gpio();

    FILE *profile_file = fopen(LOG_FILE, "r");
    if (profile_file == NULL) {
        fprintf(stderr, "Failed to open profile file\n");
        exit(EXIT_FAILURE);
    }

    char line[128];
    int profile_count = 0;
    double profile_times[100];
    double profile_temps[100];

    while (fgets(line, sizeof(line), profile_file)) {
