#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <linux/types.h>
#include <linux/gpio.h>
#include <gpiod.h>

#define GPIO17 17
#define GPIO22 22
#define GPIO23 23
#define GPIO24 24
#define RAIN_PIN 0
#define MOTOR_ENA 1
#define MOTOR_IN1 2
#define MOTOR_IN2 3

#define RAIN_PIN_NAME "/dev/gpiochip0/gpio17"
#define MOTOR_ENA_NAME "/dev/gpiochip0/gpio22"
#define MOTOR_IN1_NAME "/dev/gpiochip0/gpio23"
#define MOTOR_IN2_NAME "/dev/gpiochip0/gpio24"

#define RAIN_PIN_NAME_LEN 8
#define MOTOR_ENA_NAME_LEN 8
#define MOTOR_IN1_NAME_LEN 8
#define MOTOR_IN2_NAME_LEN 8

#define RAIN_PIN_ERROR -1
#define MOTOR_ENA_ERROR -1
#define MOTOR_IN1_ERROR -1
#define MOTOR_IN2_ERROR -1

#define RAIN_PIN_STATE 0
#define RAIN_PIN_NOT_RAIN 1
#define MOTOR_ENA_STATE 0
#define MOTOR_ENA_ON 1
#define MOTOR_IN1_STATE 0
#define MOTOR_IN1_FORWARD 1
#define MOTOR_IN1_BACKWARD 0
#define MOTOR_IN2_STATE 0
#define MOTOR_IN2_FORWARD 1
#define MOTOR_IN2_BACKWARD 0

#define RAIN_PIN_POLL_INTERVAL 2
#define RAIN_POLL_TIMEOUT 500000  // 2 seconds in microseconds

#define LOG_PREFIX "Rain Sensor Monitor: "

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("%sExiting...\n", LOG_PREFIX);
        cleanup_gpio();
        exit(EXIT_SUCCESS);
    }
}

void cleanup_gpio() {
    int err;
    gpio_put(MOTOR_ENA, MOTOR_ENA_STATE);
    err = gpio_close(MOTOR_ENA_NAME);
    if (err < 0) {
        perror("gpio_close failed for GPIO22");
        exit(EXIT_FAILURE);
    }

    err = gpio_close(MOTOR_IN1_NAME);
    if (err < 0) {
        perror("gpio_close failed for GPIO23");
        exit(EXIT_FAILURE);
    }

    err = gpio_close(MOTOR_IN2_NAME);
    if (err < 0) {
        perror("gpio_close failed for GPIO24");
        exit(EXIT_FAILURE);
    }

    err = gpio_close(RAIN_PIN_NAME);
    if (err < 0) {
        perror("gpio_close failed for GPIO17");
        exit(EXIT_FAILURE);
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    int err;
    int rain_detected = 0;
    int motor_running = 0;
    int motor_state = MOTOR_ENA_STATE;
    int motor_direction = MOTOR_IN1_FORWARD;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    err = gpiod_open("/dev/gpiod");
    if (err < 0) {
        perror("gpiod_open failed");
        exit(EXIT_FAILURE);
    }

    chip = gpiod_get_chip(0);
    if (!chip) {
        perror("gpiod_get_chip failed");
        err = gpiod_close();
        if (err < 0) {
            perror("gpiod_close failed");
            exit(EXIT_FAILURE);
        }
        exit(EXIT_FAILURE);
    }

    line = gpiod_get_line(chip, GPIO17);
    if (!line) {
        perror("gpiod_get_line failed for GPIO17");
        err = gpiod_close();
        if (err < 0) {
            perror("gpiod_close failed");
            exit(EXIT_FAILURE);
        }
        exit(EXIT_FAILURE);
    }

    err = gpiod_request_line(chip, line, RAIN_PIN);
    if (err < 0) {
        perror("gpiod_request_line failed for GPIO17");
        err = gpiod_close();
        if (err < 0) {
            perror("gpiod_close failed");
            exit(EXIT_FAILURE);
        }
        exit(EXIT_FAILURE);
    }

    err = gpiod_request_line(chip, line, MOTOR_ENA);
    if (err < 0) {
        perror("gpiod_request_line failed for GPIO22");
        err = gpiod_close();
        if (err < 0) {
            perror("gpiod_close failed");
            exit(EXIT_FAILURE);
        }
        exit(EXIT_FAILURE);
    }

    err = gpiod_request_line(chip, line, MOTOR_IN1);
    if (err < 0) {
        perror("gpiod_request_line failed for GPIO23");
        err = gpiod_close();
        if (err < 0) {
            perror("gpiod_close failed");
            exit(EXIT_FAILURE);
        }
        exit(EXIT_FAILURE);
    }

    err = gpiod_request_line(chip, line, MOTOR_IN2);
    if (err < 0) {
        perror("gpiod_request_line failed for GPIO24");
        err = gpiod_close();
        if (err < 0) {
            perror("gpiod_close failed");
            exit(EXIT_FAILURE);
        }
        exit(EXIT_FAILURE);
    }

    err = gpiod_request_edge(chip, line, RAIN_PIN, RAIN_PIN_STATE, RAIN_PIN_POLL_INTERVAL, RAIN_POLL_TIMEOUT, &edge);
    if (err < 0) {
        perror("gpiod_request_edge failed for GPIO17");
        err = gpiod_close();
        if (err < 0) {
            perror("gpiod_close failed");
            exit(EXIT_FAILURE);
        }
        exit(EXIT_FAILURE);
    }

    err = gpiod_request_edge(chip, line, MOTOR_ENA, MOTOR_ENA_STATE, 0, 0, &edge);
    if (err < 0) {
        perror("gpiod_request_edge failed for GPIO22");
        err = gpiod_close();
        if (err < 0) {
            perror("gpiod_close failed");
            exit(EXIT_FAILURE);
        }
        exit(EXIT_FAILURE);
    }

    err = gpiod_request_edge(chip, line, MOTOR_IN1, MOTOR_IN1_STATE, 0, 0, &edge);
    if (err < 0) {
        perror("gpiod_request_edge failed for GPIO23");
        err = gpiod_close();
        if (err < 0) {
            perror("gpiod_close failed");
            exit(EXIT_FAILURE);
        }
        exit(EXIT_FAILURE);
    }

    err = gpiod_request_edge(chip, line, MOTOR_IN2, MOTOR_IN2_STATE, 0, 0, &edge);
    if (err < 0) {
        perror("gpiod_request_edge failed for GPIO24");
        err = gpiod_close();
        if (err < 0) {
            perror("gpiod_close failed");
            exit(EXIT_FAILURE);
        }
        exit(EXIT_FAILURE);
    }

    while (1) {
        err = gpiod_poll_edge(chip, edge, 0);
        if (err < 0) {
            perror("gpiod_poll_edge failed");
            err = gpiod_close();
            if (err < 0) {
                perror("gpiod_close failed");
                exit(EXIT_FAILURE);
            }
            exit(EXIT_FAILURE);
        }

        if (gpio_get_value(RAIN_PIN) == RAIN_PIN_NOT_RAIN) {
            printf("%sRain detected!\n", LOG_PREFIX);
            motor_running = 1;
            motor_state = MOTOR_ENA_ON;
            motor_direction = MOTOR_IN1_FORWARD;
            err = gpiod_request_edge(chip, line, MOTOR_ENA, motor_state, 0, 0, &edge);
            if (err < 0) {
                perror("gpiod_request_edge failed for GPIO22");
                err = gpiod_close();
                if (err < 0) {
                    perror("gpiod_close failed");
                    exit(EXIT_FAILURE);
                }
                exit(EXIT_FAILURE);
            }

            err = gpiod_request_edge(chip, line, MOTOR_IN1, motor_direction, 0, 0, &edge);
            if (err < 0) {
                perror("gpiod_request_edge failed for GPIO23");
                err = gpiod_close();
                if (err < 0) {
                    perror("gpiod_close failed");
                    exit(EXIT_FAILURE);
                }
                exit(EXIT_FAILURE);
            }

            err = gpiod_request_edge(chip, line, MOTOR_IN2, MOTOR_IN2_BACKWARD, 0, 0, &edge);
            if (err < 0) {
                perror("gpiod_request_edge failed for GPIO24");
                err = gpiod_close();
                if (err < 0) {
                    perror("gpiod_close failed");
                    exit(EXIT_FAILURE);
                }
                exit(EXIT_FAILURE);
            }

            usleep(500000); // 5 seconds

            motor_running = 0;
            motor_state = MOTOR_ENA_STATE;
            motor_direction = MOTOR_IN1_FORWARD;
            err = gpiod_request_edge(chip, line, MOTOR_ENA, motor_state, 0, 0, &edge);
            if (err < 0) {
                perror("gpiod_request_edge failed for GPIO22");
                err = gpiod_close();
                if (err < 0) {
                    perror("gpiod_close failed");
                    exit(EXIT_FAILURE);
                }
                exit(EXIT_FAILURE);
            }

            err = gpiod_request_edge(chip, line, MOTOR_IN1, motor_direction, 0, 0, &edge);
            if (err < 0) {
                perror("gpiod_request_edge failed for GPIO23");
                err = gpiod_close();
                if (err < 0) {
                    perror("gpiod_close failed");
                    exit(EXIT_FAILURE);
                }
                exit(EXIT_FAILURE);
            }

            err = gpiod_request_edge(chip, line, MOTOR_IN2, MOTOR_IN2_FORWARD, 0, 0, &edge);
            if (err < 0) {
                perror("gpiod_request_edge failed for GPIO24");
                err = gpiod_close();
                if (err < 0) {
                    perror("gpiod_close failed");
                    exit(EXIT_FAILURE);
                }
                exit(EXIT_FAILURE);
            }
        }

        usleep(RAIN_POLL_TIMEOUT); // 2 seconds
    }

    err = gpiod_close();
    if (err < 0) {
        perror("gpiod_close failed");
        exit(EXIT_FAILURE);
    }

    return 0;
}

