#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <json/json.h>

#define SPI0_CE0 0
#define SPI0_MOSI 1
#define SPI0_MISO 2
#define SPI0_SCLK 3
#define SPI0_SCK 4
#define SPI0_NSS 5
#define SPI0_CS 6
#define SPI0_MOSI_PIN GPIO18
#define SPI0_MISO_PIN GPIO19
#define SPI0_SCLK_PIN GPIO5
#define SPI0_SCK_PIN GPIO6
#define SPI0_NSS_PIN GPIO13
#define SPI0_CS_PIN GPIO12
#define SPI0_SPI_MODE 1
#define SPI0_SPI_FREQ 500000

#define MAX31865_CONFIG 0x80
#define MAX31865_VBIAS 0x01
#define MAX31865_AUTOCONV 0x02
#define MAX31865_FAULT 0x04
#define MAX31865_FAULT_STATUS 0x07
#define MAX31865_RTD_CODE 0x01
#define MAX31865_RTD_CODE_MSB 0x01
#define MAX31865_RTD_CODE_LSB 0x02
#define MAX31865_FAULT_BIT 0x01
#define MAX31865_FAULT_STATUS_BIT 0x02
#define MAX31865_FAULT_STATUS_MSB 0x03
#define MAX31865_FAULT_STATUS_LSB 0x04
#define MAX31865_FAULT_STATUS_MSB_LSB 0x05
#define MAX31865_FAULT_STATUS_MSB_LSB_MSB 0x06
#define MAX31865_FAULT_STATUS_MSB_LSB_MSB_LSB 0x07

#define PT100_REF_RESISTANCE 430
#define PT100_NOMINAL_RESISTANCE 100
#define PT100_CALIBRATION_COEFFICIENTS {
    { 0.001112, 0.000001, 0.0000000001 },
    { 0.001112, 0.000001, 0.0000000001 }
}

#define MAX31865_RTD_CODE_TO_RESISTANCE(code) \
    ((code) / 32768.0 * (PT100_NOMINAL_RESISTANCE + (PT100_REF_RESISTANCE * (PT100_CALIBRATION_COEFFICIENTS[(code) / 32768] + (code) % 32768 * PT100_CALIBRATION_COEFFICIENTS[(code) / 32768] / 32768)))

#define MAX31865_RESISTANCE_TO_TEMPERATURE(resistance) \
    (MAX31865_RTD_CODE_TO_RESISTANCE((resistance) * 32768 / (PT100_NOMINAL_RESISTANCE + (PT100_REF_RESISTANCE * (PT100_CALIBRATION_COEFFICIENTS[0] + (resistance) * PT100_CALIBRATION_COEFFICIENTS[0] / 32768)))))

#define PID_CONTROL_LOOP() \
    do { \
        int16_t error = target_temperature - MAX31865_RESISTANCE_TO_TEMPERATURE(MAX31865_RTD_CODE_TO_RESISTANCE(pigpio_read_spi(SPI0_CS_PIN, 0x01))); \
        int16_t integral = integral + error; \
        int16_t derivative = error - last_error; \
        last_error = error; \
        pid_value = Kp * error + Ki * integral + Kd * derivative; \
    } while (0)

int main(int argc, char **argv) {
    if (argc < 2) {
        printf("Usage: %s config.json\n", argv[0]);
        return 1;
    }

    FILE *config_file = fopen(argv[1], "r");
    if (!config_file) {
        perror("Failed to open config file");
        return 1;
    }

    json_object *config = json_load_file(config_file, 0);
    if (!config) {
        perror("Failed to parse config file");
        fclose(config_file);
        return 1;
    }

    double target_temperature = json_object_get_number(config, "target_temperature") ? json_object_get_number(config, "target_temperature") : 25.0;
    double Kp = json_object_get_number(config, "Kp") ? json_object_get_number(config, "Kp") : 1.0;
    double Ki = json_object_get_number(config, "Ki") ? json_object_get_number(config, "Ki") : 0.1;
    double Kd = json_object_get_number(config, "Kd") ? json_object_get_number(config, "Kd") : 0.01;

    fclose(config_file);

    if (gpio_initialise() < 0) {
        perror("Failed to initialise pigpio");
        return 1;
    }

    if (gpio setwpi2mode(SPI0_CE0, 1) < 0) {
        perror("Failed to set SPI0 CE0 mode");
        return 1;
    }

    if (gpio setwpi2mode(SPI0_MOSI_PIN, 1) < 0) {
        perror("Failed to set SPI0 MOSI mode");
        return 1;
    }

    if (gpio setwpi2mode(SPI0_MISO_PIN, 1) < 0) {
        perror("Failed to set SPI0 MISO mode");
        return 1;
    }

    if (gpio setwpi2mode(SPI0_SCLK_PIN, 1) < 0) {
        perror("Failed to set SPI0 SCLK mode");
        return 1;
    }

    if (gpio setwpi2mode(SPI0_SCK_PIN, 1) < 0) {
        perror("Failed to set SPI0 SCK mode");
        return 1;
    }

    if (gpio setwpi2mode(SPI0_NSS_PIN, 0) < 0) {
        perror("Failed to set SPI0 NSS mode");
        return 1;
    }

    if (gpio setwpi2mode(SPI0_CS_PIN, 1) < 0) {
        perror("Failed to set SPI0 CS mode");
        return 1;
    }

    if (gpio setwpi2mode(SPI0_SPI_MODE, SPI0_SPI_MODE) < 0) {
        perror("Failed to set SPI0 SPI mode");
        return 1;
    }

    if (gpio setwpi2freq(SPI0_SPI_FREQ) < 0) {
        perror("Failed to set SPI0 SPI frequency");
        return 1;
    }

    int last_error = 0;
    int pid_value = 0;
    int pwm_duty = 0;
    int fault_detected = 0;

    signal(SIGINT, [](int sig) {
        printf("SIGINT received, shutting down...\n");
        gpio setwpi2mode(SPI0_CE0, 0);
        gpio setwpi2mode(SPI0_CS_PIN, 0);
        gpio setwpi2freq(0);
        gpio setwpi2mode(SPI0_SPI_MODE, 0);
        gpio setwpi2mode(SPI0_MOSI_PIN, 0);
        gpio setwpi2mode(SPI0_MISO_PIN, 0);
        gpio setwpi2mode(SPI0_SCLK_PIN, 0);
        gpio setwpi2mode(SPI0_SCK_PIN, 0);
        gpio setwpi2mode(SPI0_NSS_PIN, 0);
