void i2c_read(int addr, uint16_t *red, uint16_t *ir) {
    struct i2c_msg msg[1];
    struct i2c_rdma_request req;
    int err;

    msg[0].addr = addr;
    msg[0].flags = I2C_M_RD;
    msg[0].data[0] = FIFO_DATA_REG;

    req.request = msg[0];
    req.flags = I2C_REQ_RDMA;

    err = ioctl(i2c_fd, I2C_RDWR, &req);
    if (err < 0) {
        perror("I2C read error");
        return;
    }

    if (read(msg[0].data, red, 2) != 2) {
        perror("I2C read error");
        return;
    }

    *ir = red[1];
}

