#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <pigpio.h>
#include <signal.h>

#define PULSE_PIN 18
#define LOG_FILE "rpm_log.txt"

pthread_mutex_t rpm_mutex = PTHREAD_MUTEX_INITIALIZER;

void *rpm_thread(void *arg) {
    int count = 0;
    int start_time = 0;
    int current_time = 0;
    int interval = 1000; // 1 second interval

    while (1) {
        pthread_mutex_lock(&rpm_mutex);
        if (start_time == 0) {
            start_time = get_time();
        }
        current_time = get_time();
        if ((current_time - start_time) >= interval) {
            start_time = 0;
            pthread_mutex_unlock(&rpm_mutex);
            count = 0;
            pthread_mutex_lock(&rpm_mutex);
            if (count > 0) {
                double rpm = (double)count * 60.0 / interval;
                char buffer[100];
                sprintf(buffer, "%.2f RPM %d\n", rpm, current_time);
                FILE *log = fopen(LOG_FILE, "a");
                if (log) {
                    fwrite(buffer, sizeof(char), strlen(buffer), log);
                    fclose(log);
                }
                pthread_mutex_unlock(&rpm_mutex);
            } else {
                char buffer[100];
                sprintf(buffer, "0.00 RPM %d\n", current_time);
                FILE *log = fopen(LOG_FILE, "a");
                if (log) {
                    fwrite(buffer, sizeof(char), strlen(buffer), log);
                    fclose(log);
                }
            }
        } else {
            pthread_mutex_unlock(&rpm_mutex);
            if (gpio_get_named(PULSE_PIN)) {
                gpio_wait_for_edge(PULSE_PIN,_EDGE_RISING);
                count++;
            }
        }
    }
    return NULL;
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        pthread_mutex_lock(&rpm_mutex);
        if (gpio_is_active()) {
            gpioTerminate();
        }
        pthread_mutex_unlock(&rpm_mutex);
        FILE *log = fopen(LOG_FILE, "a");
        if (log) {
            fclose(log);
        }
        pthread_mutex_destroy(&rpm_mutex);
        pthread_exit(NULL);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        perror("pigpioInitialise");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    pthread_t rpm_thread_id;
    if (pthread_create(&rpm_thread_id, NULL, rpm_thread, NULL) != 0) {
        perror("pthread_create");
        return 1;
    }

    pthread_mutex_lock(&rpm_mutex);
    if (gpio_set_pull_down(PULSE_PIN)) {
        perror("gpio_set_pull_down");
        return 1;
    }
    pthread_mutex_unlock(&rpm_mutex);

    printf("RPM thread started\n");
    pthread_join(rpm_thread_id, NULL);

    gpioTerminate();
    pthread_mutex_destroy(&rpm_mutex);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <gpiod.h>
#include <errno.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x39
#define FIFO_DATA_REG 0x00
#define FIFO_DATA_SIZE 2
#define LED_PIN 17
#define THRESHOLD 2000

int i2c_fd;
int gpio_fd;
struct gpiod_chip *chip;
struct gpiod_line *line;
struct gpiod_edge *edge;
struct gpiod_state *state;
char log_buffer[256];
char log_filename[] = "adpd144ri_log.txt";

void cleanup() {
    if (chip) {
        gpiod_chip_free(chip);
    }
    if (line) {
        gpiod_line_free(line);
    }
    if (edge) {
        gpiod_edge_free(edge);
    }
    if (state) {
        gpiod_state_free(state);
    }
    if (gpio_fd > 0) {
        close(gpio_fd);
    }
    if (i2c_fd > 0) {
        close(i2c_fd);
    }
    if (log_fd > 0) {
        close(log_fd);
    }
}

void log_data(double red, double ir) {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(log_buffer, sizeof(log_buffer), "%s,%f,%f\n", timestamp, red, ir);
    log_fd = open(log_filename, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_fd > 0) {
        write(log_fd, log_buffer, strlen(log_buffer));
        close(log_fd);
    }
}

int main() {
    cleanup();

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        return 1;
    }

    // Open GPIO 17
    gpio_fd = open("/dev/gpiod", O_RDWR);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO device");
        return 1;
    }

    // Get the chip
    chip = gpiod_chip_open(gpio_fd);
    if (!chip) {
        perror("Failed to get chip");
        return 1;
    }

    // Get the line
    line = gpiod_chip_get_line(chip, LED_PIN);
    if (!line) {
        perror("Failed to get line");
        return 1;
    }

    // Set the line to output
    if (gpiod_line_set_mode(line, GPIOD_MODE_OUTPUT) < 0) {
        perror("Failed to set line mode");
        return 1;
    }

    // Set the line to low
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Failed to set line value");
        return 1;
    }

    // Get the state
    state = gpiod_chip_get_state(chip);
    if (!state) {
        perror("Failed to get state");
        return 1;
    }

    // Set the state to active
    if (gpiod_state_set_active(state) < 0) {
        perror("Failed to set state");
        return 1;
    }

    // Get the edge
    edge = gpiod_line_get_edge(line);
    if (!edge) {
        perror("Failed to get edge");
        return 1;
    }

    // Set the edge to none
    if (gpiod_edge_set_edge(edge, GPIOD_EDGE_NONE) < 0) {
        perror("Failed to set edge");
        return 1;
    }

    // Set the edge callback
    gpiod_edge_set_callback(edge, GPIOD_EDGE_NONE, (gpiod_edge_callback_t)led_callback, NULL);

    // Read the FIFO data register
    while (1) {
        if (ioctl(i2c_fd, I2C_SMBUS_READ, FIFO_DATA_REG, FIFO_DATA_SIZE, NULL, 0) < 0) {
            perror("Failed to read I2C data");
            continue;
        }

        // Read the FIFO data
        uint16_t red = 0;
        uint16_t ir = 0;
        if (read(i2c_fd, &red, 2) < 0) {
            perror("Failed to read I2C data");
            continue;
        }
        if (read(i2c_fd, &ir, 2) < 0) {
            perror("Failed to read I2C data");
            continue;
        }

        // Check if the sensor is present
        if (red == 0x00) {
            printf("Sensor not present\n");
            continue;
        }

        // Check if the IR reading exceeds the threshold
        if (ir > THRESHOLD) {
            // Trigger the LED
            if (gpiod_line_set_value(line, 1) < 0) {
                perror("Failed to set LED value");
            }
        } else {
            // Turn off the LED
            if (gpiod_line_set_value(line, 0) < 0) {
                perror("Failed to set LED value");
            }
        }

        // Log the data
        log_data((double)red, (double)ir);
    }

    return 0;
}

void led_callback(gpiod_edge_callback_t callback, void *arg) {
    if (callback) {
        callback(arg);
    }
}

int main_loop() {
    // Initialize the log file
    log_fd = open(log_filename, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        return 1;
    }

    // Set the log file to append mode
    if (fchmod(log_fd, 0644) < 0) {
        perror("Failed to set log file mode");
        return 1;
    }

    // Start the main loop
    while (1) {
        // Sleep for 100 ms
        usleep(100000);

        // Read the FIFO data register
        if (ioctl(i2c_fd, I2C_SMBUS_READ, FIFO_DATA_REG, FIFO_DATA_SIZE, NULL, 0) < 0) {
            perror("Failed to read I2C data");
            continue;
        }

        // Read the FIFO data
        uint16_t red = 0;
        uint16_t ir = 0;
        if (read(i2c_fd, &red, 2) < 0) {
            perror("Failed to read I2C data");
            continue;
        }
        if (read(i2c_fd, &ir, 2) < 0) {
            perror("Failed to read I2C data");
            continue;
        }

        // Check if the sensor is present
        if (red == 0x00) {
            printf("Sensor not present\n");
            continue;
        }

        // Check if the IR reading exceeds the threshold
        if (ir > THRESHOLD) {
            // Trigger the LED
            if (gpiod_line_set_value(line, 1) < 0) {
                perror("Failed to set LED value");
            }
        } else {
            // Turn off the LED
            if (gpiod_line_set_value(line, 0) < 0) {
                perror("Failed to set LED value");
            }
        }

        // Log the data
        log_data((double)red, (double)ir);
    }

    return 0;
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Start the main loop
    main_loop();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO17 17
#define GPIO18 18
#define GAIN_PIN 60
#define SAMPLE_INTERVAL_MS 10
#define LOG_FILE "audio_log.txt"

int main() {
    // Initialize GPIO subsystem
    int err = 0;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    struct gpiod_edge *edge = NULL;
    struct gpiod_edge_request *request = NULL;
    struct timespec ts;

    // Set up signal handlers for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open GPIO subsystem
    err = gpiod_chip_open("/dev/gpiod");
    if (err < 0) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }
    chip = gpiod_chip_get_current();

    // Open GPIO line
    err = gpiod_chip_request_line(chip, GPIO17, GPIOD_LINE_INPUT);
    if (err < 0) {
        perror("gpiod_chip_request_line");
        exit(EXIT_FAILURE);
    }
    line = gpiod_chip_get_line(chip, err);

    // Set up edge detection
    err = gpiod_line_request_edge(line, GPIOD_EDGE_RISING);
    if (err < 0) {
        perror("gpiod_line_request_edge");
        exit(EXIT_FAILURE);
    }
    edge = gpiod_line_get_edge(line, err);

    // Create edge request
    request = gpiod_edge_request_new(edge, 0, 0, 0);
    if (request == NULL) {
        perror("gpiod_edge_request_new");
        exit(EXIT_FAILURE);
    }

    // Set up logging
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Sleep for SAMPLE_INTERVAL_MS ms
        nanosleep(&ts, NULL);
        ts.tv_sec = 0;
        ts.tv_nsec = SAMPLE_INTERVAL_MS * 1000000;

        // Check for rising edge
        if (gpiod_edge_request_get_status(request) == GPIOD_EDGE_RISING) {
            // Log the event
            time_t rawtime;
            struct tm *timeinfo;
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            fprintf(log_file, "%s %d\n", asctime(timeinfo), 1);
        }

        // Release resources
        gpiod_edge_request_release(request);
        gpiod_line_request_release(line, request);
        gpiod_chip_request_line_release(chip, line);
        gpiod_chip_close(chip);
        fclose(log_file);
        exit(EXIT_SUCCESS);
    }

    return 0;
}

// Signal handler for SIGINT and SIGTERM
void sigint_handler(int signum) {
    // Release resources
    gpiod_edge_request_release(request);
    gpiod_line_request_release(line, request);
    gpiod_chip_request_line_release(chip, line);
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(EXIT_SUCCESS);
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x70
#define TVOC_OFFSET 1
#define eCO2_OFFSET 5
#define IAQ_INDEX 100
#define TVOC_WEIGHT 10.0
#define eCO2_WEIGHT 50.0

int i2c_fd;
int i2c_handle;

void handle_sensor_absent(int sig) {
    printf("Sensor absent or bus error detected. Exiting...\n");
    close(i2c_fd);
    close(i2c_handle);
    exit(1);
}

void handle_sigint(int sig) {
    printf("SIGINT received. Closing I2C handle, flushing log, and exiting...\n");
    close(i2c_fd);
    close(i2c_handle);
    fclose(f);
    exit(0);
}

int main() {
    struct i2c_msg i2c_msg;
    struct i2c_rdma_msg i2c_rdma_msg;
    struct i2c_rdma_handle i2c_rdma_handle;
    int i2c_rdma_return;

    if (pigpio_init(NULL) < 0) {
        perror("pigpio_init");
        return 1;
    }

    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl");
        return 1;
    }

    i2c_handle = pigpio_i2c_open(i2c_fd, I2C_ADDR);
    if (i2c_handle < 0) {
        perror("pigpio_i2c_open");
        return 1;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGABRT, handle_sensor_absent);

    f = fopen("air_quality_log.csv", "a");
    if (!f) {
        perror("fopen");
        return 1;
    }

    while (1) {
        i2c_msg.addr = I2C_ADDR;
        i2c_msg.flags = I2C_MSG_READ | I2C_MSG_REPEATED_START;
        i2c_msg.len = 7;
        i2c_msg.buf = malloc(i2c_msg.len * sizeof(char));

        if (pigpio_i2c_rdma_read(&i2c_rdma_handle, &i2c_rdma_msg, &i2c_msg) < 0) {
            perror("pigpio_i2c_rdma_read");
            continue;
        }

        if (i2c_rdma_msg.flags & I2C_MSG_ERROR) {
            printf("I2C bus error detected. Exiting...\n");
            close(i2c_fd);
            close(i2c_handle);
            fclose(f);
            exit(1);
        }

        if (i2c_rdma_return = i2c_rdma_msg.flags & I2C_MSG_ERROR) {
            printf("Sensor absent or bus error detected. Exiting...\n");
            close(i2c_fd);
            close(i2c_handle);
            fclose(f);
            exit(1);
        }

        if (i2c_rdma_return == I2C_MSG_SUCCESS) {
            int tvoc = (i2c_msg.buf[TVOC_OFFSET] << 8) | i2c_msg.buf[TVOC_OFFSET + 1];
            int eco2 = (i2c_msg.buf[eCO2_OFFSET] << 8) | i2c_msg.buf[eCO2_OFFSET + 1];

            double iaq = clamp(100 - (tvoc / TVOC_WEIGHT) - ((eco2 - 400) / eCO2_WEIGHT), 0, 100);

            char line[100];
            sprintf(line, "%s,%.2f,%.2f,%.2f\n", ctime(&time(NULL)), iaq, tvoc, eco2);

            if (fwrite(line, strlen(line), 1, f) != 1) {
                perror("fwrite");
                continue;
            }

            free(i2c_msg.buf);
        }

        sleep(5);
    }

    pigpio_close(i2c_handle);
    pigpio_stop(NULL);
    close(i2c_fd);
    fclose(f);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <gpiod.h>
#include <time.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_NAME "ttp223_tamper"
#define POLL_INTERVAL_MS 100
#define INTRUSION_TIMEOUT_MS 5000
#define TOUCH_EVENT_THRESHOLD 1

static int line_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

void handle_intrusion() {
    printf("INTRUSION DETECTED\n");
}

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        if (line_fd != -1) {
            gpiod_line_close(line);
            line_fd = -1;
        }
        if (chip) {
            gpiod_chip_unexport(chip);
            gpiod_chip_free(chip);
            chip = NULL;
        }
        exit(EXIT_SUCCESS);
    }
}

int main() {
    struct timespec ts;
    struct timespec start, end;
    int touch_count = 0;
    int intrusion_detected = 0;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpiod_chip_open_by_name(GPIO_CHIP_NAME, &chip) < 0) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    if (gpiod_chip_request_line(chip, GPIO_LINE_NAME, &line) < 0) {
        perror("gpiod_chip_request_line");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_mode(line, GPIOD_MODE_INPUT) < 0) {
        perror("gpiod_line_request_mode");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_consumer(line, "ttp223_tamper") < 0) {
        perror("gpiod_line_request_consumer");
        return EXIT_FAILURE;
    }

    line_fd = gpiod_line_get_fd(line);

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        end.tv_sec = ts.tv_sec + INTRUSION_TIMEOUT_MS / 1000;
        end.tv_nsec = ts.tv_nsec + (INTRUSION_TIMEOUT_MS % 1000) * 1000;

        if (gpiod_line_poll(line, &ts, CLOCK_MONOTONIC, &ts) < 0) {
            perror("gpiod_line_poll");
            return EXIT_FAILURE;
        }

        if (gpiod_line_get_value(line) == TOUCH_EVENT_THRESHOLD) {
            if (!intrusion_detected) {
                intrusion_detected = 1;
                handle_intrusion();
            }
        } else {
            intrusion_detected = 0;
        }

        if (clock_gettime(CLOCK_MONOTONIC, &ts) < 0) {
            perror("clock_gettime");
            return EXIT_FAILURE;
        }
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
