#define FLAME_LOG_FILE "flame_log.txt"
#define FLAME_DURATION_EXPONENT 0.8
#define FLAME_DURATION_MIN 0.1
#define FLAME_DURATION_MAX 0.9
#define PWM_FREQ 100
#define PWM_DUTY_MIN 0
#define PWM_DUTY_MAX 80
#define PWM_DUTY_SCALE (PWM_DUTY_MAX - PWM_DUTY_MIN) / (FLAME_DURATION_MAX - FLAME_DURATION_MIN)

#define GPIO_FLAME 4
#define GPIO_FAN 18
#define GPIO_TIMEOUT 1000000 // 1 second

int flame_detected = 0;
int flame_duration = 0;
int flame_start_time = 0;
int flame_end_time = 0;
int pwm_running = 0;
int gpio_fd = 0;
int pi = 0;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (pwm_running) {
            pwm_stop(pi);
        }
        gpio_close(gpio_fd);
        pi_close(pi);
        exit(0);
    }
}

void log_event(const char *event) {
    struct tm *timeinfo;
    time_t rawtime;
    char buffer[128];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen(FLAME_LOG_FILE, "a");
    if (fp) {
        fprintf(fp, "%s %s\n", buffer, event);
        fclose(fp);
    } else {
        perror("Failed to open flame log file");
    }
}

void init_gpio() {
    if (gpio_initialise()) {
        perror("Failed to initialize pigpio");
        exit(1);
    }
    pi = pi_open();
    if (pi == -1) {
        perror("Failed to open pigpio");
        exit(1);
    }
    gpio_fd = gpio_open(GPIO_FAN);
    if (gpio_fd == -1) {
        perror("Failed to open GPIO fan");
        exit(1);
    }
    gpio_set_mode(gpio_fd, PI_OUTPUT);
    gpio_pwm_frequency(pi, PWM_FREQ);
    gpio_pwm_dutycycle(pi, PWM_DUTY_MIN);
    pwm_running = 0;
}

void poll_sensor() {
    int value;
    int start_time = 0;
    int end_time = 0;
    int debouncing = 0;
    int debounce_count = 0;

    while (1) {
        value = gpio_read(GPIO_FLAME);
        if (value == 0 && !debouncing) {
            start_time = time(NULL);
            debouncing = 1;
            flame_detected = 1;
            flame_duration = 0;
            flame_start_time = start_time;
        } else if (value == 1 && debouncing) {
            end_time = time(NULL);
            flame_duration = end_time - start_time;
            if (flame_duration > FLAME_DURATION_MIN) {
                pwm_running = 1;
                flame_end_time = end_time;
                int duty_cycle = (int)(PWM_DUTY_MIN + (PWM_DUTY_MAX - PWM_DUTY_MIN) * pow(flame_duration, FLAME_DURATION_EXPONENT));
                gpio_pwm_dutycycle(pi, duty_cycle);
            }
            debouncing = 0;
            flame_detected = 0;
        }
        usleep(50000); // 50 ms
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio();

    log_event("System started");

    poll_sensor();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pigpio.h>
#include <stdint.h>

#define SPI_CHANNEL 0
#define SPI_FREQ 1000000
#define SPI_MODE 0
#define SPI_DATA_SIZE 32768
#define SPI_FRAME_SIZE (SPI_DATA_SIZE * 2)
#define SPI_FRAME_COUNT 64
#define SPI_FRAME_PERIOD 100000
#define MAGIC_NUMBER 0x52444144

typedef struct {
    uint64_t timestamp;
    uint32_t start_freq;
    uint32_t end_freq;
    uint32_t chirps;
    uint32_t samples;
    uint32_t frame_period;
} mmWaveConfig;

typedef struct {
    uint32_t frame_number;
    uint64_t timestamp;
    uint8_t data[SPI_FRAME_SIZE];
} mmWaveFrame;

int main() {
    if (gpio_init() < 0) {
        perror("pigpio init failed");
        return 1;
    }

    if (gpio_set_mode(SPI_CHANNEL, PI_SPI_MODE, SPI_MODE) < 0) {
        perror("SPI mode set failed");
        return 1;
    }

    if (gpio_set_clock(SPI_CHANNEL, SPI_FREQ) < 0) {
        perror("SPI clock set failed");
        return 1;
    }

    if (gpio_set_mode(23, PI_OUTPUT) < 0) {
        perror("GPIO 23 set as output failed");
        return 1;
    }

    if (gpio_set_mode(24, PI_EDGE_FALL) < 0) {
        perror("GPIO 24 set as edge fall failed");
        return 1;
    }

    mmWaveConfig config;
    config.start_freq = 7700000000;
    config.end_freq = 7900000000;
    config.chirps = 64;
    config.samples = 256;
    config.frame_period = SPI_FRAME_PERIOD;

    FILE *fp = fopen("mmWaveData.bin", "wb");
    if (!fp) {
        perror("file open failed");
        return 1;
    }

    uint8_t magic_number[] = {MAGIC_NUMBER >> 24, MAGIC_NUMBER >> 16, MAGIC_NUMBER >> 8, MAGIC_NUMBER};
    fwrite(magic_number, 1, 4, fp);

    uint64_t timestamp = 0;
    uint32_t frame_number = 0;

    while (1) {
        if (gpio_get_value(23) == 1) {
            gpio_set_value(23, 0);
            if (gpio_wait_for_edge(24, PI_EDGE_FALL) < 0) {
                perror("data ready interrupt failed");
                return 1;
            }

            mmWaveFrame frame;
            frame.frame_number = frame_number++;
            frame.timestamp = timestamp;

            if (pigpio_spi_transfern(SPI_CHANNEL, SPI_DATA_SIZE, frame.data) < 0) {
                perror("SPI transfer failed");
                return 1;
            }

            if (fwrite(&frame, sizeof(mmWaveFrame), 1, fp) < 1) {
                perror("file write failed");
                return 1;
            }

            timestamp += config.frame_period;
        }
    }

    gpioTerminate();
    fclose(fp);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <fcntl.h>
#include <unistd.h>

#define GPIO_CHIP 0
#define GPIO_NUM 20
#define LOG_FILE "flame_log.txt"
#define LOG_FORMAT "%Y-%m-%dT%H:%M:%S.%03dZ"

void log_state_change(int detected) {
    char buffer[256];
    struct timespec ts;

    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime");
        return;
    }

    if (snprintf(buffer, sizeof(buffer), LOG_FORMAT, ts.tv_sec, ts.tv_nsec / 1000000, detected) == -1) {
        perror("snprintf");
        return;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        return;
    }

    if (fprintf(log_file, "%s\n", buffer) < 0) {
        perror("fprintf");
        fclose(log_file);
        return;
    }

    if (fclose(log_file) != 0) {
        perror("fclose");
        return;
    }
}

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        gpiod_device_t dev;
        gpiod_line_t line;

        if (gpiod_open(GPIO_CHIP, &dev) < 0) {
            perror("gpiod_open");
            return;
        }

        if (gpiod_get_line(dev, GPIO_NUM, &line) < 0) {
            perror("gpiod_get_line");
            gpiod_close(dev);
            return;
        }

        if (gpiod_request_line(dev, line, GPIOD_LINE_REQUEST_RDONLY) < 0) {
            perror("gpiod_request_line");
            gpiod_close(dev);
            gpiod_free_line(&line);
            return;
        }

        gpiod_release_line(dev, line);
        gpiod_close(dev);
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int detected = 0;
    int fd = -1;

    if (gpiod_open(GPIO_CHIP, &chip) < 0) {
        perror("gpiod_open");
        return 1;
    }

    if (gpiod_get_line(chip, GPIO_NUM, &line) < 0) {
        perror("gpiod_get_line");
        gpiod_close(chip);
        return 1;
    }

    if (gpiod_request_line(chip, line, GPIOD_LINE_REQUEST_RDONLY) < 0) {
        perror("gpiod_request_line");
        gpiod_close(chip);
        gpiod_free_line(&line);
        return 1;
    }

    fd = line->fd;
    if (fd < 0) {
        perror("line->fd");
        gpiod_close(chip);
        gpiod_free_line(&line);
        return 1;
    }

    if (fcntl(fd, F_SETOWN, getpid()) < 0) {
        perror("fcntl");
        gpiod_close(chip);
        gpiod_free_line(&line);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        if (read(fd, &detected, sizeof(detected)) < 0) {
            perror("read");
            gpiod_close(chip);
            gpiod_free_line(&line);
            return 1;
        }

        if (detected) {
            log_state_change(1);
        } else {
            log_state_change(0);
        }

        usleep(100000); // 100 milliseconds
    }

    gpiod_close(chip);
    gpiod_free_line(&line);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x44
#define I2C_DEV "/dev/i2c-" I2C_BUS

#define LIGHT_DATA_FILE "light_data.txt"

#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

typedef struct {
    uint16_t exponent;
    uint16_t mantissa;
} LightData;

void log_light_data(const char *filename, const char *timestamp, const LightData *data) {
    FILE *file = fopen(filename, "a");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    char buffer[128];
    struct tm *timeinfo;
    time_t rawtime;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(file, "%s %d %d\n", buffer, data->exponent, data->mantissa);
    fclose(file);
}

void handle_i2c_error(int error) {
    if (error) {
        printf("I2C transaction failed: %d\n", error);
        printf("Retrying...\n");
        sleep(RETRY_DELAY_MS);
    }
}

void handle_sensor_absent(int error) {
    if (error) {
        printf("Sensor absent or not found\n");
        printf("Retrying...\n");
        sleep(RETRY_DELAY_MS);
    }
}

void handle_sigint(int signum) {
    printf("Received SIGINT signal, shutting down...\n");
    pi_close();
    exit(0);
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    int i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    int i2c_result = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (i2c_result < 0) {
        perror("Failed to set I2C slave address");
        goto cleanup;
    }

    LightData data;
    int retries = 0;

    while (1) {
        pi_set_mode(PI_OUTPUT, 1);
        pi_set_pull_up(PI_OUTPUT, 1);

        int i2c_error = 0;
        int i2c_result = ioctl(i2c_fd, I2C_SMBUS_READ, 0, 0x00, &data, 2, I2C_M_RD);
        handle_i2c_error(i2c_result);

        if (data.exponent == 0 && data.mantissa == 0) {
            handle_sensor_absent(i2c_result);
        }

        log_light_data(LIGHT_DATA_FILE, ctime(&time(NULL)), &data);

        retries = 0;
        while (retries < MAX_RETRIES) {
            pi_set_mode(PI_OUTPUT, 0);
            pi_set_pull_up(PI_OUTPUT, 0);

            i2c_error = ioctl(i2c_fd, I2C_SMBUS_READ, 0, 0x00, &data, 2, I2C_M_RD);
            handle_i2c_error(i2c_error);

            if (data.exponent != 0 || data.mantissa != 0) {
                break;
            }

            retries++;
            sleep(RETRY_DELAY_MS);
        }

        if (retries == MAX_RETRIES) {
            printf("Sensor not responding after retries\n");
            break;
        }
    }

    cleanup:
    pi_close();
    close(i2c_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <gpiod.h>
#include <time.h>

volatile sig_atomic_t exit_flag = 0;

void signal_handler(int sig) {
    exit_flag = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_request *request;
    struct gpiod_line_request *request_value;
    struct gpiod_line_request *request_bias;
    struct gpiod_chip_request *chip_request;
    struct timespec ts;
    char timestamp[20];

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiod", GPIOD_OPEN_NEW);
    if (chip == NULL) {
        perror("gpiod_chip_open");
        return 1;
    }

    // Request the line
    chip_request = gpiod_chip_request_lines(chip, 17);
    if (chip_request == NULL) {
        perror("gpiod_chip_request_lines");
        goto cleanup;
    }

    // Request the line as input with bias pulled up
    request = gpiod_line_request_config(chip_request, GPIOD_LINE_REQUEST_INPUT, 0, 0, 0);
    if (request == NULL) {
        perror("gpiod_line_request_config");
        goto cleanup;
    }

    request_value = gpiod_line_request_get_value(request);
    if (request_value == NULL) {
        perror("gpiod_line_request_get_value");
        goto cleanup;
    }

    request_bias = gpiod_line_request_get_bias(request);
    if (request_bias == NULL) {
        perror("gpiod_line_request_get_bias");
        goto cleanup;
    }

    // Get the line settings
    struct gpiod_line_settings *settings = gpiod_line_settings_get(request);
    if (settings == NULL) {
        perror("gpiod_line_settings_get");
        goto cleanup;
    }

    // Set the settings
    settings->edge = GPIOD_EDGE_FALLING;
    settings->active = GPIOD_LINE_ACTIVE_LOW;
    settings->pull = GPIOD_LINE_PULL_UP;
    if (gpiod_line_settings_set(request, settings) == -1) {
        perror("gpiod_line_settings_set");
        goto cleanup;
    }

    // Get the line configuration
    struct gpiod_line_config *config = gpiod_line_config_get(request);
    if (config == NULL) {
        perror("gpiod_line_config_get");
        goto cleanup;
    }

    // Get the line request
    line = gpiod_chip_request_lines(chip_request, 0);
    if (line == NULL) {
        perror("gpiod_chip_request_lines");
        goto cleanup;
    }

    // Get the line request value
    request_value = gpiod_line_request_get_value(request);
    if (request_value == NULL) {
        perror("gpiod_line_request_get_value");
        goto cleanup;
    }

    // Main loop
    while (!exit_flag) {
        // Get the current time
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", localtime(&ts));

        // Get the line value
        if (gpiod_line_request_get_value(request_value) == -1) {
            perror("gpiod_line_request_get_value");
            goto cleanup;
        }

        // Log the flame detection status
        if (config->value == 0) {
            printf("%s Flame Detected: YES\n", timestamp);
        } else {
            printf("%s Flame Detected: NO\n", timestamp);
        }

        // Sleep for 1 second
        nanosleep(&ts, NULL);
    }

cleanup:
    // Release the line request
    if (request_value != NULL) {
        gpiod_line_request_release(request_value);
    }

    // Close the chip request
    if (chip_request != NULL) {
        gpiod_chip_request_release(chip_request);
    }

    // Close the chip
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    // Free the line request
    if (request != NULL) {
        gpiod_line_request_free(request);
    }

    // Free the chip request
    if (chip_request != NULL) {
        gpiod_chip_request_free(chip_request);
    }

    // Free the line settings
    if (settings != NULL) {
        gpiod_line_settings_free(settings);
    }

    // Free the line configuration
    if (config != NULL) {
        gpiod_line_config_free(config);
    }

    // Free the request value
    if (request_value != NULL) {
        gpiod_line_request_free(request_value);
    }

    // Free the request bias
    if (request_bias != NULL) {
        gpiod_line_request_free(request_bias);
    }

    // Free the line
    if (line != NULL) {
        gpiod_line_release(line);
    }

    // Free the chip request
    if (chip_request != NULL) {
        gpiod_chip_request_free(chip_request);
    }

    // Free the request
    if (request != NULL) {
        gpiod_request_free(request);
    }

    return 0;
}

