#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>

#define CHANNELS 8
#define POLL_INTERVAL_MS 50
#define BUFFER_SIZE 1024

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    struct gpiod_state *state;
    char buffer[BUFFER_SIZE];
    char timestamp[128];
    int channel_states[CHANNELS];
    int i, j;
    int status;

    // Register SIGINT handler
    struct sigaction sa;
    sa.sa_handler = [](int sig) {
        printf("Interrupted by Ctrl+C\n");
        // Release all resources
        for (i = 0; i < CHANNELS; i++) {
            if (line = gpiod_line_get_by_number(i)) {
                gpiod_line_free(line);
            }
        }
        if (chip = gpiod_chip_get_by_number(0)) {
            gpiod_chip_free(chip);
        }
        exit(EXIT_SUCCESS);
    };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open GPIOchip 0
    if ((chip = gpiod_chip_open("/dev/gpiod")) == NULL) {
        perror("Failed to open GPIOchip 0");
        exit(EXIT_FAILURE);
    }

    // Iterate over all channels
    for (i = 0; i < CHANNELS; i++) {
        // Request a line for each channel
        if ((line = gpiod_chip_request_line(chip, i)) == NULL) {
            perror("Failed to request GPIO line");
            gpiod_chip_free(chip);
            exit(EXIT_FAILURE);
        }

        // Set the line to input mode with bias disabled
        if ((status = gpiod_line_request_mode(line, GPIOD_MODE_INPUT)) != 0) {
            perror("Failed to set line mode");
            gpiod_chip_free(chip);
            gpiod_line_free(line);
            exit(EXIT_FAILURE);
        }

        // Set the line to input with bias disabled
        if ((status = gpiod_line_request_bias(line, GPIOD_BIAS_NONE)) != 0) {
            perror("Failed to set line bias");
            gpiod_chip_free(chip);
            gpiod_line_free(line);
            exit(EXIT_FAILURE);
        }

        // Request an edge
        if ((edge = gpiod_line_request_edge(line, GPIOD_EDGE_BOTH)) == NULL) {
            perror("Failed to request edge");
            gpiod_chip_free(chip);
            gpiod_line_free(line);
            exit(EXIT_FAILURE);
        }

        // Request a state
        if ((state = gpiod_edge_request_state(edge, GPIOD_STATE_ACTIVE)) == NULL) {
            perror("Failed to request state");
            gpiod_chip_free(chip);
            gpiod_line_free(line);
            gpiod_edge_free(edge);
            exit(EXIT_FAILURE);
        }
    }

    // Poll all channels every POLL_INTERVAL_MS
    while (1) {
        // Get current time in ISO-8601 format
        time_t t = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&t));

        // Read all channel states
        for (i = 0; i < CHANNELS; i++) {
            if ((status = gpiod_edge_get_state(edge[i], state)) != 0) {
                perror("Failed to get edge state");
                gpiod_chip_free(chip);
                for (j = 0; j < CHANNELS; j++) {
                    if (line = gpiod_line_get_by_number(j)) {
                        gpiod_line_free(line);
                    }
                }
                gpiod_edge_free(edge[i]);
                gpiod_chip_free(chip);
                exit(EXIT_FAILURE);
            }
            channel_states[i] = state->edge->state;
        }

        // Log the states to the console
        for (i = 0; i < CHANNELS; i++) {
            printf("%s,%d\n", timestamp, channel_states[i]);
        }

        // Sleep for POLL_INTERVAL_MS
        usleep(POLL_INTERVAL_MS * 1000);
    }

    return 0;
}

