#include <unistd.h>
#include <sys/time.h>
#include <pigpio.h>

#define BUFFER_SIZE 100
#define POLL_INTERVAL 50000  // 50 ms

typedef struct {
    struct timeval timestamp;
    int reading;
} BufferEntry;

BufferEntry buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_full = 0;

void handle_sigint(int signum) {
    printf("Buffer contents:\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (buffer[i].reading == 0) {
            printf("Timestamp: %ldms, Reading: 0\n", (long)(buffer[i].timestamp.tv_sec * 1000 + buffer[i].timestamp.tv_usec / 1000));
        } else {
            printf("Timestamp: %ldms, Reading: 1\n", (long)(buffer[i].timestamp.tv_sec * 1000 + buffer[i].timestamp.tv_usec / 1000));
        }
    }
    freeall();  // Release all pigpio resources
    exit(0);
}

int main() {
    if (gpio_init() < 0) {
        perror("pigpio init failed");
        return 1;
    }

    if (gpio_set_mode(4, PI_INPUT) < 0) {
        perror("GPIO mode set failed");
        return 1;
    }

    if (gpio_pull_up(4) < 0) {
        perror("GPIO pull-up enabled failed");
        return 1;
    }

    if (gpio_hot_start() < 0) {
        perror("GPIO hot start failed");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    struct timeval last_poll = {0, 0};
    while (1) {
        struct timeval now;
        gettimeofday(&now, NULL);

        if (now.tv_sec * 1000 + now.tv_usec / 1000 < last_poll.tv_sec * 1000 + last_poll.tv_usec / 1000) {
            usleep((last_poll.tv_sec * 1000 + last_poll.tv_usec / 1000) - (now.tv_sec * 1000 + now.tv_usec / 1000) * 1000);
        }

        int reading = gpio_get(4);
        if (reading == 0) {
            buffer[buffer_index].reading = 0;
            gettimeofday(&buffer[buffer_index].timestamp, NULL);
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
            if (buffer_full) {
                buffer_full = 0;
            } else {
                buffer_full = 1;
            }
        }

        last_poll.tv_sec = now.tv_sec;
        last_poll.tv_usec = now.tv_usec;

        if (buffer_full) {
            usleep(POLL_INTERVAL - (now.tv_sec * 1000 + now.tv_usec / 1000) - (last_poll.tv_sec * 1000 + last_poll.tv_usec / 1000));
