#define I2C_DEVICE "/dev/i2c-1"
#define I2C_SLAVE 0x55
#define I2C_MODE_CONTROL 0x1D
#define I2C_MODE_CONTROL_VALUE 0x10
#define I2C_OPERATING_STATUS 0x1B
#define I2C_ACCELERATION_X 0x2A
#define I2C_ACCELERATION_Y 0x2C
#define I2C_ACCELERATION_Z 0x2E
#define I2C_ACCELERATION_X_LSB 0x2A
#define I2C_ACCELERATION_Y_LSB 0x2C
#define I2C_ACCELERATION_Z_LSB 0x2E
#define I2C_ACCELERATION_X_MSB 0x2B
#define I2C_ACCELERATION_Y_MSB 0x2D
#define I2C_ACCELERATION_Z_MSB 0x2F
#define I2C_ACCELERATION_SCALE 0.0009765625

#define I2C_READ 0
#define I2C_WRITE 1
#define I2C_RESTART 0
#define I2C_STOP 0
#define I2C_ACK 1
#define I2C_NACK 0

#define I2C_TIMEOUT 1000
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY 500

#define CSV_HEADER "timestamp,acceleration_x,acceleration_y,acceleration_z\n"

int i2c_fd;
int retry_count = 0;

void handle_i2c_error(int err) {
    fprintf(stderr, "I2C error: %d\n", err);
    if (retry_count < I2C_RETRY_COUNT) {
        fprintf(stderr, "Retrying in %dms...\n", I2C_RETRY_DELAY);
        retry_count++;
        usleep(I2C_RETRY_DELAY * 1000);
    } else {
        fprintf(stderr, "I2C communication failed after %d retries\n", I2C_RETRY_COUNT);
        exit(EXIT_FAILURE);
    }
}

void handle_i2c_write_error(int err) {
    fprintf(stderr, "I2C write error: %d\n", err);
    handle_i2c_error(err);
}

void handle_i2c_read_error(int err) {
    fprintf(stderr, "I2C read error: %d\n", err);
    handle_i2c_error(err);
}

void handle_i2c_ioctl_error(int err) {
    fprintf(stderr, "I2C ioctl error: %d\n", err);
    handle_i2c_error(err);
}

void handle_signal(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (fopen("fan_health.csv", "a") == NULL) {
        fprintf(stderr, "Failed to open CSV file for appending\n");
        exit(EXIT_FAILURE);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct iocb iocb;
    struct i2c_msg msg[3];
    struct i2c_rdma_msg rdma_msg;
    char buffer[32];
    char timestamp[32];
    int i, j;
    int sample_count = 0;
    int start_time;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_SLAVE) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }

    memset(&iocb, 0, sizeof(iocb));
    iocb.mostsignificantbit = I2C_NACK;
    iocb.flags = I2C_RDWR | I2C_RESTART | I2C_STOP;

    msg[0].addr = I2C_SLAVE;
    msg[0].flags = I2C_MSL | I2C_MST | I2C_MTR;
    msg[0].data[0] = I2C_MODE_CONTROL;
    msg[0].len = 1;

    msg[1].addr = I2C_SLAVE;
    msg[1].flags = I2C_MSL | I2C_MST | I2C_MTR;
    msg[1].data[0] = I2C_OPERATING_STATUS;
    msg[1].len = 1;

    msg[2].addr = I2C_SLAVE;
    msg[2].flags = I2C_MSL | I2C_MST | I2C_MTR;
    msg[2].data[0] = I2C_ACCELERATION_X;
    msg[2].data[1] = I2C_ACCELERATION_Y;
    msg[2].data[2] = I2C_ACCELERATION_Z;
    msg[2].len = 3;

    start_time = time(NULL);

    while (1) {
        if (retry_count > 0) {
            retry_count--;
            fprintf(stderr, "Retrying in %dms...\n", I2C_RETRY_DELAY);
            usleep(I2C_RETRY_DELAY * 1000);
        }

        if (ioctl(i2c_fd, I2C_RDWR, msg, 3) < 0) {
            handle_i2c_ioctl_error(ioctl(i2c_fd, I2C_SLAVE, I2C_SLAVE));
        }

        if (msg[0].data[0] == I2C_MODE_CONTROL_VALUE) {
            if (msg[1].data[0] & 0x1) {
                break;
            } else {
                fprintf(stderr, "Sensor not in active mode\n");
                sleep(1000);
            }
        }

        if (sample_count % 5 == 0) {
            snprintf(timestamp, sizeof(timestamp), "%s", ctime(&start_time));
            strncpy(timestamp, timestamp, sizeof(timestamp) - 1);
            timestamp[sizeof(timestamp) - 1] = '\0';
            fprintf(stderr, "Logging sample %d: %s\n", sample_count, timestamp);

            if (write(i2c_fd, &msg[2], 3) < 0) {
                handle_i2c_write_error(errno);
            }

            if (read(i2c_fd, buffer, 3) < 0) {
                handle_i2c_read_error(errno);
            }

            int x = (buffer[0] << 8) | buffer[1];
            int y = (buffer[2] << 8) | buffer[3];
            int z = (buffer[4] << 8) | buffer[5];

            double acceleration_x = x * I2C_ACCELERATION_SCALE;
            double acceleration_y = y * I2C_ACCELERATION_SCALE;
            double acceleration_z = z * I2C_ACCELERATION_SCALE;

            fprintf(stderr, "Acceleration: %f, %f, %f\n", acceleration_x, acceleration_y, acceleration_z);

            if (fopen("fan_health.csv", "a") == NULL) {
                fprintf(stderr, "Failed to open CSV file for appending\n");
                exit(EXIT_FAILURE);
            }

            fprintf(fopen("fan_health.csv", "a"), "%s,%f,%f,%f\n", timestamp, acceleration_x, acceleration_y, acceleration_z);
        }

        sample_count++;
    }

    close(i2c_fd);
    fclose(fopen("fan_health.csv", "a"));
    return 0;
}

