    if ((ret = gpioSetMode(GPIO_PIN2, PI_INPUT)) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }
    if ((ret = gpioSetMode(GPIO_PIN3, PI_OUTPUT)) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }

    // Set up LED pin
    if ((ret = gpioSetMode(GPIO_PIN3, PI_OUTPUT)) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }

    // Set up GPIO pins for sensors
    if ((ret = gpioSetPullUpDown(GPIO_PIN1, PI_DISABLE)) < 0) {
        perror("gpioSetPullUpDowm");
        gpioTerminate();
        return 1;
    }
    if ((ret = gpioSetPullUpDowm(GPIO_PIN2, PI_DISABLE)) < 0) {
        perror("gpioSetPullUpDowm");
        gpioTerminate();
        return 1;
    }

    // Open GPIO device
    if ((fd = gpioOpenDevice(0)) < 0) {
        perror("gpioOpenDevice");
        gpioTerminate();
        return 1;
    }

    // Set up GPIO pins for sensors
    if ((ret = gpioSetPullUpDowm(GPIO_PIN1, PI_DISABLE)) < 0) {
        perror("gpioSetPullUpDowm");
        gpioTerminate();
        return 1;
    }
    if ((ret = gpioSetPullUpDowm(GPIO_PIN2, PI_DISABLE)) < 0) {
        perror("gpioSetPullUpDowm");
        gpioTerminate();
        return 1;
    }

    // Set up LED pin
    if ((ret = gpioSetPullUpDowm(GPIO_PIN3, PI_DISABLE)) < 0) {
        perror("gpioSetPullUpDowm");
        gpioTerminate();
        return 1;
    }

    // Set up callback for sensor 1
    gpioSetCallback(GPIO_PIN1, gpioObstacleDetected, GPIO_PIN1);

    // Set up callback for sensor 2
    gpioSetCallback(GPIO_PIN2, gpioObstacleDetected, GPIO_PIN2);

    // Main loop
    while (1) {
        // Poll both sensors
        if ((ret = gpioRead(GPIO_PIN1)) < 0) {
            perror("gpioRead");
            gpioTerminate();
            return 1;
        }
        if ((ret = gpioRead(GPIO_PIN2)) < 0) {
            perror("gpioRead");
            gpioTerminate();
            return 1;
        }

        // Check if either sensor detects an obstacle
        if ((gpio1 = gpioRead(GPIO_PIN1)) == OBSTACLE_THRESHOLD || (gpio2 = gpioRead(GPIO_PIN2)) == OBSTACLE_THRESHOLD) {
            gpioWrite(GPIO_PIN3, 1); // Turn LED ON
        } else {
            gpioWrite(GPIO_PIN3, 0); // Turn LED OFF
        }

        // Sleep for POLL_INTERVAL ms
        usleep(POLL_INTERVAL * 1000);
    }

    // Clean up
    gpioTerminate();
    return 0;
}

