                fprintf(log_file, "%s%d\n", buffer, pulses);
                fflush(log_file);
                pulses = 0;
                rpm = (pulses * 60) / samples;
                if (rpm == 0) {
                    printf("0\n");
                } else {
                    printf("%d\n", rpm);
                }
                samples = 0;
            }
        })) {
            perror("gpioSetTimerFunc");
            return 1;
        }

