#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <pthread.h>

#define LOG_FILE "rotation_log.txt"
#define BUFFER_SIZE 256

pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t log_cond = PTHREAD_COND_INITIALIZER;
pthread_mutex_t state_mutex = PTHREAD_MUTEX_INITIALIZER;
int state = 0;
int prev_state = 0;
int direction = 0;
int rotation_detected = 0;
int running = 1;
pthread_t log_thread;

void* log_rotation(void* arg) {
    FILE* log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return NULL;
    }

    while (running) {
        pthread_mutex_lock(&log_mutex);
        if (rotation_detected) {
            char timestamp[20];
            time_t now = time(NULL);
            struct tm* local_time = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%03d", local_time);
            fprintf(log_file, "%s, %d\n", timestamp, direction);
            rotation_detected = 0;
        }
        pthread_cond_wait(&log_cond, &log_mutex);
        pthread_mutex_unlock(&log_mutex);
    }
    fclose(log_file);
    return NULL;
}

void handle_rotation(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&state_mutex);
    if (level == 1) {
        prev_state = state;
        state = (prev_state << 1) | (level & 1);
        if (state != prev_state) {
            rotation_detected = 1;
            direction = (state - prev_state) / 2;
        }
    }
    pthread_mutex_unlock(&state_mutex);
}

void* signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        running = 0;
        pthread_cond_broadcast(&log_cond);
        pthread_mutex_lock(&log_mutex);
        fclose(fopen(LOG_FILE, "a"));
        pthread_mutex_unlock(&log_mutex);
        return NULL;
    }
    return NULL;
}

int main() {
    if (gpioInitialise() < 0) {
        perror("Failed to initialise pigpio");
        return 1;
    }

    if (gpioSetPullUpDown(17, PUD_UP) < 0) {
        perror("Failed to set pull-up on GPIO 17");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(27, PUD_UP) < 0) {
        perror("Failed to set pull-up on GPIO 27");
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFunc(17, handle_rotation) < 0) {
        perror("Failed to set alert function for GPIO 17");
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFunc(27, handle_rotation) < 0) {
        perror("Failed to set alert function for GPIO 27");
        gpioTerminate();
        return 1;
    }

    if (pthread_create(&log_thread, NULL, log_rotation, NULL) < 0) {
        perror("Failed to create log thread");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        pthread_cond_wait(&log_cond, &log_mutex);
    }

    gpioTerminate();
    return 0;
}

