#define GPIO_CHIP 0
#define GPIO_LINE 23
#define LED_PIN 18
#define POLL_INTERVAL 50000  // 50 ms

int main() {
    int line_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    struct gpiod_event *event;
    int touch_detected = 0;
    char *log_facility = "dev";

    // Open the GPIO chip
    if ((chip = gpiod_chip_open(GPIO_CHIP)) == NULL) {
        syslog(LOG_ERR, "Failed to open GPIO chip %d: %s", GPIO_CHIP, gpiod_chip_errno(chip));
        return 1;
    }

    // Open the line
    if ((line = gpiod_chip_request_line(chip, GPIO_LINE)) == NULL) {
        syslog(LOG_ERR, "Failed to open line %d on GPIO chip %d: %s", GPIO_LINE, GPIO_CHIP, gpiod_chip_errno(chip));
        gpiod_chip_unlink(chip);
        return 1;
    }

    // Set the line to input mode
    if (gpiod_line_request_mode(line, GPIOD_MODE_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set line %d to input mode: %s", GPIO_LINE, gpiod_line_errno(line));
        gpiod_chip_unlink(chip);
        return 1;
    }

    // Create an edge for the line
    if ((edge = gpiod_line_request_edge(line, GPIOD_EDGE_BOTH)) == NULL) {
        syslog(LOG_ERR, "Failed to create edge for line %d: %s", GPIO_LINE, gpiod_line_errno(line));
        gpiod_chip_unlink(chip);
        return 1;
    }

    // Create an event for the edge
    if ((event = gpiod_edge_request_event(edge, GPIOD_EDGE_BOTH, 0)) == NULL) {
        syslog(LOG_ERR, "Failed to create event for edge %d: %s", edge->line->number, gpiod_edge_errno(edge));
        gpiod_chip_unlink(chip);
        return 1;
    }

    // Set the event to trigger on a rising edge
    if (gpiod_event_set_edge(event, GPIOD_EDGE_RISING) < 0) {
        syslog(LOG_ERR, "Failed to set event %d to rising edge: %s", event->line->number, gpiod_event_errno(event));
        gpiod_chip_unlink(chip);
        return 1;
    }

    // Open the syslog
    if (openlog(log_facility, LOG_PID | LOG_CONS | LOG_NDELAY, LOG_DAEMON) < 0) {
        syslog(LOG_ERR, "Failed to open syslog: %s", syslog_errno(NULL));
        return 1;
    }

    // Start the event loop
    while (1) {
        if (gpiod_event_get(event) == 0) {
            touch_detected = 1;
            syslog(LOG_INFO, "Touch detected on GPIO %d", GPIO_LINE);
            // Turn on the LED
            if (gpiod_line_request_value(line, 1) < 0) {
                syslog(LOG_ERR, "Failed to set line %d to 1: %s", GPIO_LINE, gpiod_line_errno(line));
            }
        } else {
            touch_detected = 0;
            // Turn off the LED
            if (gpiod_line_request_value(line, 0) < 0) {
                syslog(LOG_ERR, "Failed to set line %d to 0: %s", GPIO_LINE, gpiod_line_errno(line));
            }
        }

        // Poll the sensor every 50 ms
        usleep(POLL_INTERVAL);
    }

    // Graceful shutdown
    signal(SIGINT, [](int) {
        syslog(LOG_INFO, "Received SIGINT, shutting down...");
        gpiod_chip_unlink(chip);
        return 0;
    });
    signal(SIGTERM, [](int) {
        syslog(LOG_INFO, "Received SIGTERM, shutting down...");
        gpiod_chip_unlink(chip);
        return 0;
    });

    return 0;
}

