#include <signal.h>
#include <unistd.h>
#include <sys/time.h>
#include <pigpio.h>

#define BUFFER_SIZE 100
#define LOG_BUF_SIZE (BUFFER_SIZE * 3)

typedef struct {
    uint8_t sensor;
    uint64_t timestamp;
    uint8_t newState;
} LogEntry;

LogEntry log_buffer[BUFFER_SIZE];
uint8_t log_index = 0;
uint8_t overflow_count = 0;

void handle_sigint(int sig) {
    gpioTerminate();
    printf("Logging buffer:\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        printf("Sensor %d, Timestamp: %llu, New State: %d\n", log_buffer[i].sensor, log_buffer[i].timestamp, log_buffer[i].newState);
    }
    printf("Overflow count: %d\n", overflow_count);
    exit(0);
}

void handle_sigterm(int sig) {
    handle_sigint(sig);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    if (gpioSetMode(4, INPUT) < 0) {
        perror("gpioSetMode");
        return 1;
    }
    if (gpioSetMode(17, INPUT) < 0) {
        perror("gpioSetMode");
        return 1;
    }
    if (gpioSetMode(27, OUTPUT) < 0) {
        perror("gpioSetMode");
        return 1;
    }
    if (gpioSetMode(22, OUTPUT) < 0) {
        perror("gpioSetMode");
        return 1;
    }

    uint8_t led1 = 0;
    uint8_t led2 = 0;

    while (1) {
        struct timeval tv;
        gettimeofday(&tv, NULL);
        uint64_t timestamp = tv.tv_sec * 1000000 + tv.tv_usec;

        LogEntry entry;
        entry.sensor = 0;
        entry.timestamp = timestamp;
        entry.newState = 0;

        if (gpioRead(4) == 1) {
            entry.sensor = 4;
            entry.newState = 1;
        } else if (gpioRead(4) == 0) {
            entry.sensor = 4;
            entry.newState = 0;
        }

        if (gpioRead(17) == 1) {
            entry.sensor = 17;
            entry.newState = 1;
        } else if (gpioRead(17) == 0) {
            entry.sensor = 17;
            entry.newState = 0;
        }

        if (entry.newState != log_buffer[log_index].newState) {
            log_buffer[log_index] = entry;
            log_index = (log_index + 1) % BUFFER_SIZE;
            if (log_index == log_index) {
                overflow_count++;
            }
        }

        if (entry.newState == 1) {
            if (led1 == 0) {
                gpioWrite(27, 1);
                led1 = 1;
            }
        } else if (entry.newState == 0) {
            if (led1 == 1) {
                gpioWrite(27, 0);
                led1 = 0;
            }
        }

        if (entry.newState == 1) {
            if (led2 == 0) {
                gpioWrite(22, 1);
                led2 = 1;
            }
        } else if (entry.newState == 0) {
            if (led2 == 1) {
                gpioWrite(22, 0);
                led2 = 0;
            }
        }

        usleep(50000);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <pigpio.h>

#define LOG_FILE "/var/log/rain_events.log"
#define POLL_INTERVAL_MS 500
#define LOG_MESSAGE_NO_RAIN "No Rain"
#define LOG_MESSAGE_RAIN_DETECTED "Rain Detected"

int main() {
    int fd;
    char buffer[256];
    struct timespec ts;
    int status;
    int rain_detected = 0;
    pid_t pid = getpid();

    if (gpio_init() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    if (gpio_set_pull_up_down(17, PUD_UP) < 0) {
        fprintf(stderr, "Setting pull-up on GPIO 17 failed\n");
        return 1;
    }

    fd = fopen(LOG_FILE, "a");
    if (fd < 0) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        return 1;
    }

    if (clock_gettime(CLOCK_MONOTONIC, &ts) < 0) {
        fprintf(stderr, "Failed to get current time\n");
        return 1;
    }

    while (1) {
        if ((status = gpio_get_named("17")) < 0) {
            fprintf(stderr, "Failed to read GPIO 17\n");
            return 1;
        }

        if (status == 1) {
            rain_detected = 1;
            if (clock_gettime(CLOCK_MONOTONIC, &ts) < 0) {
                fprintf(stderr, "Failed to get current time\n");
                return 1;
            }
            snprintf(buffer, sizeof(buffer), "%ld %s\n", ts.tv_sec, LOG_MESSAGE_RAIN_DETECTED);
            if (fprintf(fd, buffer) < 0) {
                fprintf(stderr, "Failed to write to log file\n");
                return 1;
            }
        } else {
            rain_detected = 0;
            if (clock_gettime(CLOCK_MONOTONIC, &ts) < 0) {
                fprintf(stderr, "Failed to get current time\n");
                return 1;
            }
            snprintf(buffer, sizeof(buffer), "%ld %s\n", ts.tv_sec, LOG_MESSAGE_NO_RAIN);
            if (fprintf(fd, buffer) < 0) {
                fprintf(stderr, "Failed to write to log file\n");
                return 1;
            }
        }

        if (sleep(POLL_INTERVAL_MS / 1000) < 0) {
            fprintf(stderr, "Failed to sleep for %d ms\n", POLL_INTERVAL_MS);
            return 1;
        }
    }

    gpioTerminate();
    fclose(fd);
    return 0;
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        syslog(LOG_INFO, "Received signal %d, shutting down\n", signum);
        gpioTerminate();
        fclose(fd);
        exit(0);
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <pigpio.h>

#define GPIO17 17
#define GPIO18 18
#define DEBOUNCE_MS 5
#define PULSES_PER_REV 2

int fd_log = -1;
int fd_gpio = -1;

void handle_log_error(int err) {
    if (err < 0) {
        perror("Error writing to log file");
        exit(EXIT_FAILURE);
    }
}

void handle_gpio_error(int err) {
    if (err < 0) {
        perror("Error initializing GPIO");
        exit(EXIT_FAILURE);
    }
}

void handle_signal(int signum) {
    if (fd_gpio != -1) {
        gpioTerminate();
    }
    if (fd_log != -1) {
        close(fd_log);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, handle_signal);

    if (gpioInitialise() < 0) {
        handle_gpio_error(gpioInitialise());
    }

    fd_gpio = gpioOpen();
    if (fd_gpio < 0) {
        handle_gpio_error(fd_gpio);
    }

    if (gpioSetMode(GPIO17, PI_INPUT) < 0) {
        handle_gpio_error(gpioSetMode(GPIO17, PI_INPUT));
    }
    if (gpioSetMode(GPIO18, PI_INPUT) < 0) {
        handle_gpio_error(gpioSetMode(GPIO18, PI_INPUT));
    }

    if (gpioSetPullUp(GPIO17, 1) < 0) {
        handle_gpio_error(gpioSetPullUp(GPIO17, 1));
    }
    if (gpioSetPullUp(GPIO18, 1) < 0) {
        handle_gpio_error(gpioSetPullUp(GPIO18, 1));
    }

    fd_log = fopen("shaft_log.txt", "w");
    if (fd_log < 0) {
        perror("Error opening log file");
        exit(EXIT_FAILURE);
    }

    char log_buffer[256];
    struct timespec ts;
    int sensor1_state, sensor2_state;
    int prev_state1 = 0, prev_state2 = 0;
    int prev_time = 0;
    int pulses = 0;

    while (1) {
        if (gpioRead(GPIO17) == 1) {
            sensor1_state = 1;
        } else {
            sensor1_state = 0;
        }

        if (gpioRead(GPIO18) == 1) {
            sensor2_state = 1;
        } else {
            sensor2_state = 0;
        }

        if ((sensor1_state != prev_state1) || (sensor2_state != prev_state2)) {
            if (prev_time > 0) {
                ts.tv_sec = prev_time.tv_sec;
                ts.tv_nsec = prev_time.tv_nsec;
                fprintf(fd_log, "%ld,%d,%d\n", ts.tv_sec, sensor1_state, sensor2_state);
            }
            prev_time = {0, 0};
        }

        prev_state1 = sensor1_state;
        prev_state2 = sensor2_state;

        usleep(DEBOUNCE_MS * 1000);

        if (gpioRead(GPIO17) == 1) {
            sensor1_state = 1;
        } else {
            sensor1_state = 0;
        }

        if (gpioRead(GPIO18) == 1) {
            sensor2_state = 1;
        } else {
            sensor2_state = 0;
        }

        if ((sensor1_state != prev_state1) || (sensor2_state != prev_state2)) {
            if (prev_time > 0) {
                ts.tv_sec = prev_time.tv_sec;
                ts.tv_nsec = prev_time.tv_nsec;
                fprintf(fd_log, "%ld,%d,%d\n", ts.tv_sec, sensor1_state, sensor2_state);
            }
            prev_time = {0, 0};
        }

        prev_state1 = sensor1_state;
        prev_state2 = sensor2_state;

        if ((sensor1_state == 1) && (sensor2_state == 1)) {
            pulses++;
        }

        if (pulses >= PULSES_PER_REV) {
            double rpm = (double)(pulses * 60) / (double)(DEBOUNCE_MS / 1000);
            printf("RPM: %.2f\n", rpm);
            pulses = 0;
        }
    }

    return 0;
}

