#define I2C_BUS 1
#define I2C_ADDR 0x1D
#define CTRL1 0x1F
#define ACCEL_START 0x28
#define ACCEL_END 0x2D
#define THRESHOLD 500
#define LED_PIN 17
#define LOG_FILE "seismic_events.log"

#define I2C_RETRIES 3
#define I2C_TIMEOUT 100

void log_event(const char *timestamp, double magnitude) {
    char buffer[256];
    struct tm *timeinfo;
    time_t rawtime;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(stderr, "%s, Peak Vibration: %.2f\n", buffer, magnitude);
    fprintf(stderr, "Event logged to %s\n", LOG_FILE);
    FILE *log = fopen(LOG_FILE, "a");
    if (log) {
        fprintf(log, "%s, Peak Vibration: %.2f\n", buffer, magnitude);
        fclose(log);
    }
}

int i2c_read(int bus, int addr, unsigned char *buf, int len, int retries) {
    int fd = i2c_open(bus, addr);
    if (fd < 0) {
        perror("i2c_open");
        return -1;
    }
    int n = 0;
    while (n < len && retries > 0) {
        if (i2c_read(fd, buf + n, len - n) < 0) {
            perror("i2c_read");
            return -1;
        }
        n += i2c_read(fd, buf + n, len - n);
        if (n == len) {
            break;
        }
        retries--;
        usleep(I2C_TIMEOUT * 1000);
    }
    i2c_close(fd);
    return n;
}

int main() {
    if (gpio_init() < 0) {
        perror("gpio_init");
        return 1;
    }
    if (gpio setw OnCollision LED_PIN 1) {
        printf("LED on GPIO %d set\n", LED_PIN);
    } else {
        printf("Failed to set LED on GPIO %d\n", LED_PIN);
        return 1;
    }

    int i2c_fd = i2c_open(I2C_BUS, I2C_ADDR);
    if (i2c_fd < 0) {
        perror("i2c_open");
        return 1;
    }

    unsigned char ctrl1[1] = {0};
    if (i2c_read(i2c_fd, CTRL1, 1) < 1) {
        perror("i2c_read");
        return 1;
    }
    if (ctrl1[0] & 0x20) {
        printf("Power-down bit cleared successfully\n");
    } else {
        printf("Failed to clear power-down bit\n");
        return 1;
    }

    double magnitude;
    while (1) {
        if (i2c_read(i2c_fd, (unsigned char *) &magnitude, sizeof(magnitude)) < sizeof(magnitude)) {
            perror("i2c_read");
            continue;
        }
        if (magnitude > THRESHOLD) {
            gpio toggle LED_PIN 1;
            log_event("Event triggered", magnitude);
            usleep(1000000); // 1 second
            gpio toggle LED_PIN 0;
        }
        usleep(100000); // 100 ms
    }

    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_PIN_4 4
#define GPIO_PIN_17 17
#define GPIO_PIN_27 27
#define GPIO_PIN_22 22
#define GPIO_PIN_18 18

int main() {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    struct gpiod_state *state;
    int i;
    int sensor_values[4];
    int led_state = 0;

    // Register signal handlers
    signal(SIGINT, [](int) { exit(EXIT_SUCCESS); });
    signal(SIGTERM, [](int) { exit(EXIT_SUCCESS); });

    // Open the GPIO chip
    if ((fd = gpiod_open("/dev/gpiod")) < 0) {
        perror("gpiod_open");
        exit(EXIT_FAILURE);
    }

    // Get the first chip
    if ((chip = gpiod_get_chip(fd)) == NULL) {
        perror("gpiod_get_chip");
        gpiod_close(fd);
        exit(EXIT_FAILURE);
    }

    // Create lines for the sensors
    for (i = 0; i < 4; i++) {
        int pin = GPIO_PIN_4 + i;
        if ((line = gpiod_request_line(chip, pin, GPIOD_LINE_INPUT)) == NULL) {
            perror("gpiod_request_line");
            gpiod_close(fd);
            exit(EXIT_FAILURE);
        }
    }

    // Create edges for the lines
    for (i = 0; i < 4; i++) {
        int pin = GPIO_PIN_4 + i;
        if ((edge = gpiod_request_edge(line[i], GPIOD_EDGE_EDGE_RISING)) == NULL) {
            perror("gpiod_request_edge");
            gpiod_close(fd);
            exit(EXIT_FAILURE);
        }
    }

    // Set up the LED
    if ((line = gpiod_request_line(chip, GPIO_PIN_18, GPIOD_LINE_OUTPUT)) == NULL) {
        perror("gpiod_request_line");
        gpiod_close(fd);
        exit(EXIT_FAILURE);
    }

    // Set the LED to off
    if (gpiod_set_value(line, 0) < 0) {
        perror("gpiod_set_value");
        gpiod_close(fd);
        exit(EXIT_FAILURE);
    }

    // Poll the lines every 50 ms
    while (1) {
        for (i = 0; i < 4; i++) {
            int pin = GPIO_PIN_4 + i;
            if (gpiod_get_value(line[i]) == 0) {
                sensor_values[i] = 1;
            } else {
                sensor_values[i] = 0;
            }
        }

        // Check if any sensor detected an object
        if (sensor_values[0] || sensor_values[1] || sensor_values[2] || sensor_values[3]) {
            // Turn on the LED
            if (gpiod_set_value(line[GPIO_PIN_18], 1) < 0) {
                perror("gpiod_set_value");
                gpiod_close(fd);
                exit(EXIT_FAILURE);
            }
        } else {
            // Turn off the LED
            if (gpiod_set_value(line[GPIO_PIN_18], 0) < 0) {
                perror("gpiod_set_value");
                gpiod_close(fd);
                exit(EXIT_FAILURE);
            }
        }

        // Sleep for 50 ms
        usleep(50000);
    }

    // Clean up resources
    for (i = 0; i < 4; i++) {
        if (gpiod_release_edge(edge[i]) < 0) {
            perror("gpiod_release_edge");
            gpiod_close(fd);
            exit(EXIT_FAILURE);
        }
    }

    if (gpiod_release_line(line[GPIO_PIN_18]) < 0) {
        perror("gpiod_release_line");
        gpiod_close(fd);
        exit(EXIT_FAILURE);
    }

    for (i = 0; i < 4; i++) {
        if (gpiod_release_line(line[i]) < 0) {
            perror("gpiod_release_line");
            gpiod_close(fd);
            exit(EXIT_FAILURE);
        }
    }

    if (gpiod_close(fd) < 0) {
        perror("gpiod_close");
        exit(EXIT_FAILURE);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <poll.h>
#include <gpiod.h>

#define MAX_SENSORS 5
#define DEBOUNCE_MS 50
#define LOG_FILE "/var/log/flame_events.log"

volatile sig_atomic_t sigint_received = 0;
volatile sig_atomic_t sigterm_received = 0;

typedef struct {
    int pin;
    int line;
    int sensor_id;
} Sensor;

Sensor sensors[MAX_SENSORS] = {
    {2, 0, 1},
    {3, 1, 2},
    {4, 2, 3},
    {17, 3, 4},
    {27, 4, 5}
};

int chip_fd;
gpiod_chip_t *chip;
gpiod_line_t *lines[MAX_SENSORS];
int line_count = 0;

void handle_sigint() {
    sigint_received = 1;
    for (int i = 0; i < line_count; i++) {
        gpiod_line_close(lines[i]);
    }
    gpiod_chip_close(chip);
    closelog();
    exit(0);
}

void handle_sigterm() {
    sigterm_received = 1;
    for (int i = 0; i < line_count; i++) {
        gpiod_line_close(lines[i]);
    }
    gpiod_chip_close(chip);
    closelog();
    exit(0);
}

void init_gpiod() {
    chip_fd = open("/dev/gpiod", O_RDONLY | O_NONBLOCK);
    if (chip_fd < 0) {
        syslog(LOG_USER, "Failed to open /dev/gpiod: %d", chip_fd);
        exit(1);
    }

    chip = gpiod_chip_open(chip_fd);
    if (chip == NULL) {
        syslog(LOG_USER, "Failed to open gpiod chip: %d", chip_fd);
        close(chip_fd);
        exit(1);
    }

    for (int i = 0; i < MAX_SENSORS; i++) {
        lines[i] = gpiod_chip_request_line(chip, sensors[i].pin);
        if (lines[i] == NULL) {
            syslog(LOG_USER, "Failed to request line for sensor %d: %d", i, sensors[i].pin);
            close(chip_fd);
            exit(1);
        }
    }
    line_count = MAX_SENSORS;
}

void read_line(int line, int *value) {
    gpiod_line_request(line, GPIOD_LINE_REQUEST_READ);
    *value = gpiod_line_read(line);
    gpiod_line_request(line, GPIOD_LINE_REQUEST_RELEASE);
}

void check_flame(int line, int *value) {
    if (*value == 0) {
        syslog(LOG_USER, "Flame detected on sensor %d (GPIO %d)", line_count - 1, sensors[line_count - 1].pin);
        char timestamp[26];
        struct tm *now;
        time_t t;
        t = time(NULL);
        now = localtime(&t);
        strftime(timestamp, 26, "%Y-%m-%dT%H:%M:%S.%06dZ", now);
        FILE *log_file = fopen(LOG_FILE, "a");
        if (log_file != NULL) {
            fprintf(log_file, "%s - Sensor ID: %d (GPIO %d) - Flame Detected\n", timestamp, sensors[line_count - 1].sensor_id, sensors[line_count - 1].pin);
            fflush(log_file);
            fclose(log_file);
        } else {
            syslog(LOG_USER, "Failed to open %s for writing: %d", LOG_FILE, log_file);
        }
    }
}

void poll_sensors() {
    struct pollfd pfd[MAX_SENSORS];
    for (int i = 0; i < MAX_SENSORS; i++) {
        pfd[i].fd = lines[i]->handle;
        pfd[i].events = POLLIN;
    }

    while (!sigint_received && !sigterm_received) {
        int result = poll(pfd, MAX_SENSORS, 1000);
        if (result < 0) {
            syslog(LOG_USER, "Poll failed: %d", result);
            continue;
        }

        for (int i = 0; i < MAX_SENSORS; i++) {
            if (pfd[i].revents & POLLIN) {
                int value;
                read_line(lines[i]->handle, &value);
                check_flame(i, &value);
            }
        }
    }
}

int main() {
    init_gpiod();

    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    poll_sensors();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>

#define GPIO_PIN_TO_NUM(pin) \
    ((pin) == 5 ? 0 : \
     (pin) == 6 ? 1 : \
     (pin) == 13 ? 2 : \
     (pin) == 19 ? 3 : \
     (pin) == 26 ? 4 : \
     (pin) == 12 ? 5 : \
     (pin) == 16 ? 6 : \
     (pin) == 20 ? 7 : \
     -1)

#define BUFFER_SIZE 1024

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <duration>\n", argv[0]);
        return 1;
    }

    long duration = atol(argv[1]);
    if (duration <= 0) {
        fprintf(stderr, "Duration must be a positive integer.\n");
        return 1;
    }

    int fd = gpiod_open("/dev/gpiod");
    if (fd < 0) {
        perror("gpiod_open");
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_new(fd);
    if (!chip) {
        perror("gpiod_chip_new");
        gpiod_close(fd);
        return 1;
    }

    struct gpiod_chip *gpio_chip = gpiod_chip_lookup(chip, "gpio");
    if (!gpio_chip) {
        fprintf(stderr, "gpio chip not found.\n");
        gpiod_close(fd);
        gpiod_chip_unref(chip);
        return 1;
    }

    struct gpiod_line *line;
    int pin_index = 0;
    for (int i = 0; i < 8; i++) {
        int pin = GPIO_PIN_TO_NUM(i + 5);
        if (pin == -1) {
            fprintf(stderr, "Invalid pin number %d.\n", i + 5);
            gpiod_close(fd);
            gpiod_chip_unref(chip);
            return 1;
        }

        line = gpiod_chip_get_line(gpio_chip, pin);
        if (!line) {
            fprintf(stderr, "Line %d not found.\n", pin);
            gpiod_close(fd);
            gpiod_chip_unref(chip);
            return 1;
        }

        if (gpiod_line_set_pull(line, GPIOD_LINE_PUD_UP) < 0) {
            perror("gpiod_line_set_pull");
            gpiod_close(fd);
            gpiod_chip_unref(chip);
            return 1;
        }

        if (gpiod_line_request_line(line, 0) < 0) {
            perror("gpiod_line_request_line");
            gpiod_close(fd);
            gpiod_chip_unref(chip);
            return 1;
        }

        if (gpiod_line_get_line_owner(line) != 0) {
            fprintf(stderr, "Line %d is owned by another process.\n", pin);
            gpiod_close(fd);
            gpiod_chip_unref(chip);
            return 1;
        }

        if (gpiod_line_get_line_type(line) != GPIOD_LINE_TYPE_EDGE) {
            fprintf(stderr, "Line %d is not an edge-triggered line.\n", pin);
            gpiod_close(fd);
            gpiod_chip_unref(chip);
            return 1;
        }

        if (gpiod_line_get_line_mode(line) != GPIOD_LINE_MODE_POLL) {
            fprintf(stderr, "Line %d is not in polling mode.\n", pin);
            gpiod_close(fd);
            gpiod_chip_unref(chip);
            return 1;
        }

        pin_index++;
    }

    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    char timestamp[64];
    snprintf(timestamp, sizeof(timestamp), "%sZ", ctime(&ts));

    for (long i = 0; i < duration; i++) {
        for (int j = 0; j < 8; j++) {
            struct gpiod_line *line = gpiod_chip_get_line(gpio_chip, j + 5);
            if (!line) {
                fprintf(stderr, "Line %d not found.\n", j + 5);
                gpiod_close(fd);
                gpiod_chip_unref(chip);
                return 1;
            }

            int value = gpiod_line_get_value(line);
            if (value == 0) {
                printf("%s T%d %d\n", timestamp, j, j + 5);
            } else {
                printf("%s F%d %d\n", timestamp, j, j + 5);
            }
        }

        clock_gettime(CLOCK_MONOTONIC, &ts);
        snprintf(timestamp, sizeof(timestamp), "%sZ", ctime(&ts));

        for (int j = 0; j < 8; j++) {
            struct gpiod_line *line = gpiod_chip_get_line(gpio_chip, j + 5);
            if (!line) {
                fprintf(stderr, "Line %d not found.\n", j + 5);
                gpiod_close(fd);
                gpiod_chip_unref(chip);
                return 1;
            }

            int value = gpiod_line_get_value(line);
            if (value == 1) {
                printf("%s F%d %d\n", timestamp, j, j + 5);
            } else {
                printf("%s T%d %d\n", timestamp, j, j + 5);
            }
        }
    }

    for (int j = 0; j < 8; j++) {
        struct gpiod_line *line = gpiod_chip_get_line(gpio_chip, j + 5);
        if (!line) {
            fprintf(stderr, "Line %d not found.\n", j + 5);
            gpiod_close(fd);
            gpiod_chip_unref(chip);
            return 1;
        }

        gpiod_line_free(line);
    }

    gpiod_chip_unref(chip);
    gpiod_close(fd);

    return 0;
}

void signal_handler(int signum) {
    if (signum == SIGINT) {
        for (int j = 0; j < 8; j++) {
            struct gpiod_line *line = gpiod_chip_get_line(gpio_chip, j + 5);
            if (!line) {
                fprintf(stderr, "Line %d not found.\n", j + 5);
                gpiod_close(fd);
                gpiod_chip_unref(chip);
                return;
            }

            gpiod_line_free(line);
        }

        gpiod_chip_unref(chip);
        gpiod_close(fd);
    }

    return;
}

int main(int argc, char *argv[]) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    return main_callee(argc, argv);
}

int main_callee(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    return main(argc, argv);
}

