#define I2C_BUS 1
#define I2C_ADDR 0x10
#define VEML7700_CONFIG 0x00
#define VEML7700_ALS_GAIN 0x01
#define VEML7700_ALS_INTTIME 0x02
#define VEML7700_ALS_REG 0x04
#define VEML7700_PWM 0x03
#define VEML7700_PWM_MODE 0x0A
#define VEML7700_PWM_RANGE 0x0B
#define VEML7700_PWM_FREQ 0x0C
#define VEML7700_PWM_DUTY 0x0D

#define ALS_GAIN_1_8 0x00
#define ALS_INTTIME_100MS 0x00
#define PWM_FREQ_1000HZ 1000
#define PWM_RANGE_0_100 0x00
#define PWM_DUTY_MAX 100

#define LOG_FILE "grow_log.txt"

int i2c_fd;
int pwm_fd;
int sensor_present = 0;
int error_code = 0;

void handle_sensor_absent() {
    printf("Sensor absent or bus error\n");
    error_code = 1;
}

void handle_sigint() {
    printf("SIGINT received, shutting down\n");
    pi_set_mode(pwm_fd, PI_OUTPUT);
    pi_set_PWM_dutycycle(pwm_fd, 0);
    pi_close(pwm_fd);
    close(i2c_fd);
    fclose(fopen(LOG_FILE, "a"));
    pi_stop();
    exit(0);
}

void log_sample(char *timestamp, double lux, int brightness, int error) {
    char log_buffer[256];
    struct tm *timeinfo;
    time_t rawtime;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(log_buffer, 256, "%Y-%m-%d %H:%M:%S", timeinfo);
    sprintf(log_buffer + strlen(log_buffer), ", lux=%.2f, brightness=%d, error=%d\n", lux, brightness, error);
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fwrite(log_buffer, strlen(log_buffer), 1, log_file);
        fflush(log_file);
        fclose(log_file);
    } else {
        printf("Failed to open log file\n");
    }
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    pi_init();
    pwm_fd = pi_gpio_open(18, PI_OUTPUT);
    if (pwm_fd < 0) {
        printf("Failed to open PWM channel\n");
        return 1;
    }

    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        printf("Failed to open I2C bus\n");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        printf("Failed to set I2C slave address\n");
        return 1;
    }

    sensor_present = 1;
    error_code = 0;

    // Configure sensor
    uint16_t config = ALS_GAIN_1_8 | ALS_INTTIME_100MS;
    if (write(i2c_fd, &config, 2) != 2) {
        printf("Failed to write sensor configuration\n");
        handle_sensor_absent();
    }

    while (1) {
        // Read ambient light
        uint16_t raw;
        if (read(i2c_fd, &raw, 2) != 2) {
            printf("Failed to read ambient light\n");
            handle_sensor_absent();
        }

        double lux = raw * 0.0576;
        int brightness = 0;
        if (lux < 100) {
            brightness = PWM_DUTY_MAX;
        } else if (lux < 500) {
            brightness = 75;
        } else if (lux < 1000) {
            brightness = 50;
        } else {
            brightness = 25;
        }

        // Set PWM duty cycle
        if (pi_set_PWM_dutycycle(pwm_fd, brightness) < 0) {
            printf("Failed to set PWM duty cycle\n");
            handle_sensor_absent();
        }

        // Log sample
        char timestamp[256];
        time_t rawtime;
        time(&rawtime);
        struct tm *timeinfo = localtime(&rawtime);
        strftime(timestamp, 256, "%Y-%m-%d %H:%M:%S", timeinfo);
        log_sample(timestamp, lux, brightness, error_code);

        // Wait 1 second
        usleep(1000000);
    }

    return 0;
}

