#define TOUCH_LOG_FILE "touch_log.txt"
#define TOUCH_CHANNEL_COUNT 8
#define DEBOUNCE_TIME_MS 500
#define POLL_INTERVAL_MS 50

int touch_channels[TOUCH_CHANNEL_COUNT] = {2, 3, 4, 5, 6, 7, 8, 9};
int touch_led = 17;
int touch_log_file_fd = -1;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, exiting...\n", signum);
        gpioTerminate();
        if (touch_log_file_fd != -1) {
            fclose(touch_log_file_fd);
        }
        exit(EXIT_SUCCESS);
    }
}

int main() {
    if (signal(SIGINT, handle_signal) == SIG_ERR ||
        signal(SIGTERM, handle_signal) == SIG_ERR) {
        perror("Failed to set signal handlers");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        perror("Failed to initialise pigpio");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < TOUCH_CHANNEL_COUNT; i++) {
        if (gpioSetPullDownDontPull(touch_channels[i]) < 0) {
            perror("Failed to set pull-down on touch channels");
            return EXIT_FAILURE;
        }
    }

    if (gpioSetMode(touch_led, PI_OUTPUT) < 0) {
        perror("Failed to set LED mode");
        return EXIT_FAILURE;
    }

    touch_log_file_fd = fopen(TOUCH_LOG_FILE, "a");
    if (touch_log_file_fd == -1) {
        perror("Failed to open touch log file");
        return EXIT_FAILURE;
    }

    printf("Security Keypad Initialized\n");

    while (1) {
        int touched = 0;
        for (int i = 0; i < TOUCH_CHANNEL_COUNT; i++) {
            int state = gpioRead(touch_channels[i]);
            if (state == 1 && !touched) {
                touched = 1;
                printf("Channel %d touched\n", i + 1);
                char timestamp[20];
                time_t now = time(NULL);
                struct tm *ltm = localtime(&now);
                strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", ltm);
                fprintf(touch_log_file_fd, "%s - Channel %d Touched\n", timestamp, i + 1);
            } else if (state == 0 && touched) {
                touched = 0;
                printf("Channel %d released\n", i + 1);
            }
        }

        if (touched) {
            gpioWrite(touch_led, 1);
        } else {
            gpioWrite(touch_led, 0);
        }

        gpioDelay(POLL_INTERVAL_MS);
    }

    return EXIT_SUCCESS;
}

