#include <gpiod.h>
#include <unistd.h>

#define GPIO17 17
#define GPIO27 27
#define GPIO22 22
#define POLL_INTERVAL 50000  // 50 ms
#define LOG_FILE "path_log.csv"

static void handle_sigint(int sig) {
    gpiod_chip_close(chip);
    gpiod_line_close(line);
    gpiod_line_unref(line);
    gpiod_chip_unref(chip);
    fclose(log_file);
    exit(EXIT_SUCCESS);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    struct gpiod_state *state;
    char buffer[128];
    FILE *log_file = fopen(LOG_FILE, "w");

    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    if (gpiod_chip_open("/dev/gpiod") < 0) {
        perror("Failed to open gpiod device");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_get_default();
    if (!chip) {
        perror("Failed to get default chip");
        return EXIT_FAILURE;
    }

    if (gpiod_chip_request_line(chip, GPIO17, GPIOD_EDGE_BOTH, &line) < 0) {
        perror("Failed to request GPIO17 line");
        return EXIT_FAILURE;
    }

    if (gpiod_chip_request_line(chip, GPIO27, GPIOD_EDGE_BOTH, &line) < 0) {
        perror("Failed to request GPIO27 line");
        return EXIT_FAILURE;
    }

    if (gpiod_chip_request_line(chip, GPIO22, GPIOD_EDGE_BOTH, &line) < 0) {
        perror("Failed to request GPIO22 line");
        return EXIT_FAILURE;
    }

    if (gpiod_chip_request_edge(chip, line, GPIOD_EDGE_BOTH, &edge) < 0) {
        perror("Failed to request edge");
        return EXIT_FAILURE;
    }

    state = gpiod_chip_get_state(chip);
    if (state->state != GPIOD_STATE_ACTIVE) {
        perror("Chip is not active");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        snprintf(buffer, sizeof(buffer), "%ld,%d,%d,%d\n", (long)time(NULL), line->value, line->next->value, line->next->next->value);
        fprintf(log_file, buffer);

        usleep(POLL_INTERVAL);

        if (gpiod_line_poll(line, edge, POLL_INTERVAL) < 0) {
            perror("Failed to poll line");
            return EXIT_FAILURE;
        }
    }

    fclose(log_file);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <gpiod.h>
#include <time.h>

#define GPIO4 4
#define FLAME_EVENT_FILE "flame_events.txt"

void handle_signal(int sig) {
    gpiod_close(gpio);
    exit(EXIT_SUCCESS);
}

int main() {
    struct gpiod_chip *gpio;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    struct timespec ts;
    char buffer[256];
    FILE *fp;

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    if ((gpio = gpiod_chip_open("/dev/gpiod")) == NULL) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request the GPIO line
    if ((line = gpiod_chip_request_line(gpio, GPIO4)) == NULL) {
        perror("Failed to request GPIO line");
        gpiod_chip_unrequest_line(gpio, line);
        gpiod_chip_close(gpio);
        exit(EXIT_FAILURE);
    }

    // Set the line to edge detection on falling edge
    if ((edge = gpiod_line_request_edge(line, GPIOD_EDGE_FALLING)) == NULL) {
        perror("Failed to request edge");
        gpiod_line_release_edge(line, edge);
        gpiod_chip_unrequest_line(gpio, line);
        gpiod_chip_close(gpio);
        exit(EXIT_FAILURE);
    }

    // Open the event file
    fp = fopen(FLAME_EVENT_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open event file");
        exit(EXIT_FAILURE);
    }

    // Initialize the clock for timestamp
    clock_gettime(CLOCK_MONOTONIC, &ts);

    while (1) {
        // Read the line value
        if ((line->value = gpiod_line_read(line)) == -1) {
            perror("Failed to read line value");
            gpiod_line_release_edge(line, edge);
            gpiod_chip_unrequest_line(gpio, line);
            gpiod_chip_close(gpio);
            fclose(fp);
            exit(EXIT_FAILURE);
        }

        // Check if the line value has changed from 0 to 1 (flame detected)
        if (line->value == 0) {
            // Write the event to the file
            sprintf(buffer, "%ld,%ld\n", (long)ts.tv_sec, (long)ts.tv_nsec);
            if (fwrite(buffer, 1, strlen(buffer), fp) != strlen(buffer)) {
                perror("Failed to write event to file");
                fclose(fp);
                exit(EXIT_FAILURE);
            }

            // Print the alert
            printf("Flame detected at %ld.%09ld\n", (long)ts.tv_sec, (long)ts.tv_nsec);
        }

        // Sleep for 1 millisecond
        nanosleep(&ts, &ts);
    }

    // Clean up resources
    gpiod_line_release_edge(line, edge);
    gpiod_chip_unrequest_line(gpio, line);
    gpiod_chip_close(gpio);
    fclose(fp);
    exit(EXIT_SUCCESS);
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>

#define GPIO_PIN 23
#define GPIO_CHIP 4
#define LED_PIN 24

int main() {
    int chip_fd, line_fd, err;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_event *event;
    struct timespec ts;
    char log_buffer[256];
    FILE *log_file;

    // Open GPIO chip
    chip_fd = open("/dev/gpiochip4", O_RDWR);
    if (chip_fd < 0) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    chip = gpiod_chip_open(chip_fd);
    if (!chip) {
        perror("Failed to open GPIO chip");
        gpiod_chip_close(chip_fd);
        return 1;
    }

    // Request GPIO line
    line_fd = gpiod_chip_request_line(chip, GPIO_PIN);
    if (line_fd < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        gpiod_chip_close(chip_fd);
        return 1;
    }

    line = gpiod_chip_get_line(chip, line_fd);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        gpiod_chip_close(chip_fd);
        return 1;
    }

    // Set GPIO line to input
    if (gpiod_line_set_direction(line, GPIOD_LINE_DIR_IN) < 0) {
        perror("Failed to set GPIO line direction");
        gpiod_chip_close(chip);
        gpiod_chip_close(chip_fd);
        gpiod_line_close(line_fd);
        return 1;
    }

    // Set GPIO line to active-high
    if (gpiod_line_set_edge(line, GPIOD_EDGE_BOTH) < 0) {
        perror("Failed to set GPIO line edge");
        gpiod_chip_close(chip);
        gpiod_chip_close(chip_fd);
        gpiod_line_close(line_fd);
        return 1;
    }

    // Set GPIO line to line event
    if (gpiod_line_request_event(line, GPIOD_LINE_EVENT_EDGE) < 0) {
        perror("Failed to request GPIO line event");
        gpiod_chip_close(chip);
        gpiod_chip_close(chip_fd);
        gpiod_line_close(line_fd);
        return 1;
    }

    // Set timeout to 1 second
    if (gpiod_line_set_timeout(line, 1) < 0) {
        perror("Failed to set GPIO line timeout");
        gpiod_chip_close(chip);
        gpiod_chip_close(chip_fd);
        gpiod_line_close(line_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_chip_close(chip);
        gpiod_chip_close(chip_fd);
        gpiod_line_close(line_fd);
        return 1;
    }

    // Initialize event
    event = gpiod_line_get_event(line);
    if (!event) {
        perror("Failed to get GPIO line event");
        gpiod_chip_close(chip);
        gpiod_chip_close(chip_fd);
        gpiod_line_close(line_fd);
        fclose(log_file);
        return 1;
    }

    // Set event callback
    gpiod_line_set_callback(line, event, (void (*)(void))handle_event, NULL);

    // Main loop
    while (1) {
        nanosleep(&ts, NULL);
    }

    // Handle SIGINT and SIGTERM
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Cleanup
    gpiod_line_close(line_fd);
    gpiod_chip_close(chip);
    gpiod_chip_close(chip_fd);
    fclose(log_file);

    return 0;

    // Event callback
    void handle_event(void *arg) {
        struct timespec ts;
        char log_buffer[256];
        int new_state;

        // Get current time
        clock_gettime(CLOCK_MONOTONIC, &ts);
        strftime(log_buffer, sizeof(log_buffer), "%Y-%m-%d %H:%M:%S.%3f", &ts);

        // Toggle LED
        new_state = !gpiod_line_get_value(line);
        if (gpiod_line_set_value(line, new_state) < 0) {
            perror("Failed to set GPIO line value");
            return 1;
        }

        // Log event
        fprintf(log_file, "%s LED: %d\n", log_buffer, new_state);
    }

    // Signal handler
    void handle_signal(int sig) {
        // Release all libgpiod resources
        gpiod_line_close(line_fd);
        gpiod_chip_close(chip);
        gpiod_chip_close(chip_fd);
        fclose(log_file);

        // Exit
        exit(EXIT_SUCCESS);
    }
}

#include <errno.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>

#define FLAME_SENSOR_NAME "gpiochip0"
#define FLAME_PIN 17
#define BUZZER_PIN 18
#define ALERT_LOG_FILE "alert_log.txt"
#define BUZZER_ON_TIME 200000  // 2 seconds in milliseconds

int flame_sensor_fd;
int flame_pin_fd;
int buzzer_fd;
FILE *log_file;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (buzzer_fd > 0) {
            gpiod_line_request_output(buzzer_fd, 1);
            gpiod_line_set_value(buzzer_fd, 0);
        }
        if (flame_pin_fd > 0) {
            gpiod_line_request_input(b Flame_PIN);
            gpiod_line_set_value(b flame_pin_fd, 0);
        }
        if (flame_sensor_fd > 0) {
            gpiod_chip_close(flame_sensor_fd);
        }
        if (log_file) {
            fclose(log_file);
        }
        exit(0);
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    struct timespec ts;

    // Initialize signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    if ((chip = gpiod_chip_open_by_name(FLAME_SENSOR_NAME)) == NULL) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Open the flame sensor pin
    if ((line = gpiod_chip_get_line(chip, FLAME_PIN)) == NULL) {
        fprintf(stderr, "Error opening flame sensor pin: %s\n", strerror(errno));
        return 1;
    }

    // Request input mode
    if (gpiod_line_request_input(line) < 0) {
        fprintf(stderr, "Error setting input mode: %s\n", strerror(errno));
        return 1;
    }

    // Open the buzzer pin
    if ((line = gpiod_chip_get_line(chip, BUZZER_PIN)) == NULL) {
        fprintf(stderr, "Error opening buzzer pin: %s\n", strerror(errno));
        return 1;
    }

    // Request output mode
    if (gpiod_line_request_output(line) < 0) {
        fprintf(stderr, "Error setting output mode: %s\n", strerror(errno));
        return 1;
    }

    // Open the log file
    if ((log_file = fopen(ALERT_LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Log startup
    if (fprintf(log_file, "System started\n") < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return 1;
    }

    // Initialize flame sensor pin
    if (gpiod_line_request_edge(line, GPIOD_EDGE_EDGE_ANY) < 0) {
        fprintf(stderr, "Error setting edge mode: %s\n", strerror(errno));
        return 1;
    }

    // Initialize buzzer pin
    if (gpiod_line_request_edge(line, GPIOD_EDGE_EDGE_ANY) < 0) {
        fprintf(stderr, "Error setting edge mode: %s\n", strerror(errno));
        return 1;
    }

    // Start the main loop
    while (1) {
        // Poll the flame sensor
        if (clock_gettime(CLOCK_MONOTONIC, &ts) < 0) {
            fprintf(stderr, "Error getting current time: %s\n", strerror(errno));
            return 1;
        }

        if ((ts.tv_sec % 5) == 0) {
            // Check the flame sensor value
            if (gpiod_line_get_value(line) == 0) {
                // Flame detected
                if (fprintf(log_file, "%s Flame detected\n", ctime(&ts.tv_sec))) < 0) {
                    fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
                    return 1;
                }
                // Activate the buzzer
                if (gpiod_line_request_output(line) < 0) {
                    fprintf(stderr, "Error setting output mode: %s\n", strerror(errno));
                    return 1;
                }
                if (gpiod_line_set_value(line, 1) < 0) {
                    fprintf(stderr, "Error setting buzzer value: %s\n", strerror(errno));
                    return 1;
                }
                // Wait for 100 ms
                usleep(100000);
                // Deactivate the buzzer
                if (gpiod_line_request_output(line) < 0) {
                    fprintf(stderr, "Error setting output mode: %s\n", strerror(errno));
                    return 1;
                }
                if (gpiod_line_set_value(line, 0) < 0) {
                    fprintf(stderr, "Error setting buzzer value: %s\n", strerror(errno));
                    return 1;
                }
            } else {
                // No flame detected
                if (fprintf(log_file, "%s No flame detected\n", ctime(&ts.tv_sec)) < 0) {
                    fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
                    return 1;
                }
            }
        }

        // Check for shutdown signals
        if (signal(SIGINT, handle_signal) == SIG_DFL) {
            signal(SIGINT, handle_signal);
        }
        if (signal(SIGTERM, handle_signal) == SIG_DFL) {
            signal(SIGTERM, handle_signal);
        }

        // Sleep for 500 ms
        if (clock_gettime(CLOCK_MONOTONIC, &ts) < 0) {
            fprintf(stderr, "Error getting current time: %s\n", strerror(errno));
            return 1;
        }
        if (ts.tv_sec % 5 == 0) {
            if (nanosleep(&ts.tv_sec, &ts.tv_nsec) < 0) {
                fprintf(stderr, "Error sleeping: %s\n", strerror(errno));
                return 1;
            }
        } else {
            if (nanosleep(&ts.tv_sec, &ts.tv_nsec) < 0) {
                fprintf(stderr, "Error sleeping: %s\n", strerror(errno));
                return 1;
            }
        }
    }

    // Log shutdown
    if (fprintf(log_file, "System stopped\n") < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return 1;
    }

    // Close the log file
    if (fclose(log_file) < 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return 1;
    }

    // Close the buzzer pin
    if (gpiod_line_request_output(buzzer_fd) < 0) {
        fprintf(stderr, "Error setting output mode: %s\n", strerror(errno));
        return 1;
    }
    if (gpiod_line_set_value(buzzer_fd, 0) < 0) {
        fprintf(stderr, "Error setting buzzer value: %s\n", strerror(errno));
        return 1;
    }

    // Close the flame sensor pin
    if (gpiod_line_request_input(flame_pin_fd) < 0) {
        fprintf(stderr, "Error setting input mode: %s\n", strerror(errno));
        return 1;
    }
    if (gpiod_line_set_value(flame_pin_fd, 0) < 0) {
        fprintf(stderr, "Error setting flame sensor value: %s\n", strerror(errno));
        return 1;
    }

    // Close the GPIO chip
    if (gpiod_chip_close(flame_sensor_fd) < 0) {
        fprintf(stderr, "Error closing GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <sys/time.h>
#include <pigpio.h>

#define GPIO4 4
#define GPIO17 17
#define LOG_FILE "touch_log.txt"
#define DEBOUNCE 200  // ms
#define POLL_INTERVAL 10  // ms

int touch_log_fd = -1;
int touch_log_opened = 0;

void handle_sigint(int signum) {
    if (touch_log_opened) {
        close(touch_log_fd);
        touch_log_opened = 0;
    }
    gpioTerminate();
    exit(0);
}

void handle_sigterm(int signum) {
    if (touch_log_opened) {
        close(touch_log_fd);
        touch_log_opened = 0;
    }
    gpioTerminate();
    exit(0);
}

int main() {
    struct timeval tv;
    int gpio4_state, gpio17_state;
    int debounce_count = 0;
    char timestamp[128];

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    if (gpioInitialise() < 0) {
        perror("pigpioInitialise");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO4, PI_INPUT) < 0) {
        perror("gpioSetMode");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO17, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        exit(EXIT_FAILURE);
    }

    if (gpioSetPullUp(GPIO4, 1) < 0) {
        perror("gpioSetPullUp");
        exit(EXIT_FAILURE);
    }

    gettimeofday(&tv, NULL);
    sprintf(timestamp, "%s", ctime(&tv));

    touch_log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (touch_log_fd < 0) {
        perror("open");
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        exit(EXIT_FAILURE);
    }
    touch_log_opened = 1;

    while (1) {
        gettimeofday(&tv, NULL);
        tv.tv_sec = tv.tv_sec + DEBOUNCE / 1000;
        tv.tv_usec = 0;

        if (gpioWaitForEdge(GPIO4, PI_RISING, &tv) < 0) {
            perror("gpioWaitForEdge");
            continue;
        }

        debounce_count = 0;
        gpio17_state = gpioGetLevel(GPIO17);
        gpioSetLevel(GPIO17, gpio17_state);
        gettimeofday(&tv, NULL);
        sprintf(timestamp, "%s", ctime(&tv));
        if (write(touch_log_fd, timestamp, strlen(timestamp)) < 0) {
            perror("write");
            if (!touch_log_opened) {
                fprintf(stderr, "Failed to write to log file %s\n", LOG_FILE);
                exit(EXIT_FAILURE);
            }
        }

        while (debounce_count < DEBOUNCE / 1000) {
            gettimeofday(&tv, NULL);
            tv.tv_sec = tv.tv_sec + POLL_INTERVAL / 1000;
            tv.tv_usec = 0;

            if (gpioWaitForTimeout(GPIO4, POLL_INTERVAL, &tv) < 0) {
                perror("gpioWaitForTimeout");
                break;
            }

            gpio4_state = gpioGetLevel(GPIO4);
            if (gpio4_state == 1) {
                debounce_count++;
            } else {
                debounce_count = 0;
            }
        }

        gpioSetLevel(GPIO17, 0);
    }

    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_1 4
#define SENSOR_2 17
#define SENSOR_3 27

#define LOG_FILE "magnet_log.txt"
#define POLL_INTERVAL 100
#define INITIAL_STATE_LOG 1

int main() {
    if (gpioInitialise() < 0) {
        perror("pigpioInitialise failed");
        return 1;
    }

    if (gpioSetMode(SENSOR_1, PI_INPUT) < 0) {
        perror("Setting GPIO4 to input failed");
        return 1;
    }
    if (gpioSetPullUpData(SENSOR_1, 1) < 0) {
        perror("Setting GPIO4 pull-up failed");
        return 1;
    }

    if (gpioSetMode(SENSOR_2, PI_INPUT) < 0) {
        perror("Setting GPIO17 to input failed");
        return 1;
    }
    if (gpioSetPullUpData(SENSOR_2, 1) < 0) {
        perror("Setting GPIO17 pull-up failed");
        return 1;
    }

    if (gpioSetMode(SENSOR_3, PI_INPUT) < 0) {
        perror("Setting GPIO27 to input failed");
        return 1;
    }
    if (gpioSetPullUpData(SENSOR_3, 1) < 0) {
        perror("Setting GPIO27 pull-up failed");
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    if (INITIAL_STATE_LOG) {
        char state[3];
        int initial_state = gpioRead(SENSOR_1) | (gpioRead(SENSOR_2) << 1) | (gpioRead(SENSOR_3) << 2);
        fprintf(log_file, "%s %d\n", ctime(&time(NULL)), initial_state);
    }

    while (1) {
        int state = 0;
        int changed = 0;
        for (int i = 0; i < 3; i++) {
            int sensor = SENSOR_1 + (i << 1);
            int pin = SENSOR_1 + i;
            int val = gpioRead(pin);
            if (val != (state >> i)) {
                state |= (1 << i);
                changed = 1;
            }
        }

        if (changed) {
            char state_str[3];
            for (int i = 0; i < 3; i++) {
                state_str[i] = (state >> i) & 1 ? '1' : '0';
            }
            state_str[3] = '\0';
            fprintf(log_file, "%s %s\n", ctime(&time(NULL)), state_str);
        }

        gpioDelay(POLL_INTERVAL);
    }

    gpioTerminate();
    fclose(log_file);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x4A
#define BPM_MIN 30
#define BPM_MAX 220
#define HEART_RATE_FILE "heart_rate.csv"

void handle_sigint(int signum) {
    if (i2c_close(i2c) == -1) {
        perror("i2c_close failed");
        exit(EXIT_FAILURE);
    }
    pi_close();
    if (fclose(f) == EOF) {
        perror("fclose failed");
        exit(EXIT_FAILURE);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (pi_init() == -1) {
        perror("pi_init failed");
        exit(EXIT_FAILURE);
    }

    int i2c = i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (i2c == -1) {
        perror("i2c_open failed");
        exit(EXIT_FAILURE);
    }

    if (i2c_read_byte_data(i2c, 0x00, 0) == -1) {
        perror("i2c_read_byte_data failed");
        i2c_close(i2c);
        pi_close();
        exit(EXIT_FAILURE);
    }
    if (*(uint8_t *)(&data) != 0x02) {
        fprintf(stderr, "PART_ID is not 0x02\n");
        i2c_close(i2c);
        pi_close();
        exit(EXIT_FAILURE);
    }

    if (i2c_read_byte_data(i2c, 0x01, 0) == -1) {
        perror("i2c_read_byte_data failed");
        i2c_close(i2c);
        pi_close();
        exit(EXIT_FAILURE);
    }
    if (*(uint8_t *)(&data) != 0x01) {
        fprintf(stderr, "HW_REV is not 0x01\n");
        i2c_close(i2c);
        pi_close();
        exit(EXIT_FAILURE);
    }

    if (i2c_write_byte_data(i2c, 0x3F, 0) == -1) {
        perror("i2c_write_byte_data failed");
        i2c_close(i2c);
        pi_close();
        exit(EXIT_FAILURE);
    }

    if (i2c_write_byte_data(i2c, 0x04, 0) == -1) {
        perror("i2c_write_byte_data failed");
        i2c_close(i2c);
        pi_close();
        exit(EXIT_FAILURE);
    }

    if (i2c_write_byte_data(i2c, 0x01, 0) == -1) {
        perror("i2c_write_byte_data failed");
        i2c_close(i2c);
        pi_close();
        exit(EXIT_FAILURE);
    }

    FILE *f = fopen(HEART_RATE_FILE, "a");
    if (f == NULL) {
        perror("fopen failed");
        i2c_close(i2c);
        pi_close();
        exit(EXIT_FAILURE);
    }

    while (1) {
        if (i2c_read_word_data(i2c, 0x2A, 0) == -1) {
            fprintf(stderr, "i2c_read_word_data failed\n");
            if (i2c_read_byte_data(i2c, 0x2A, 0) == -1) {
                fprintf(stderr, "i2c_read_byte_data failed\n");
            }
            continue;
        }
        uint16_t raw = data;
        uint32_t bpm = (uint32_t) raw * 0.5;
        uint32_t moving_avg = 0;
        int count = 0;
        for (int i = 0; i < 5; i++) {
            if (i2c_read_word_data(i2c, 0x2A, 0) == -1) {
                fprintf(stderr, "i2c_read_word_data failed\n");
                continue;
            }
            uint16_t temp = data;
            moving_avg += temp;
            count++;
        }
        if (count == 0) {
            fprintf(stderr, "No valid readings\n");
            continue;
        }
        moving_avg /= count;
        if (moving_avg < BPM_MIN || moving_avg > BPM_MAX) {
            fprintf(stderr, "Invalid BPM\n");
            continue;
        }
        char buffer[128];
        snprintf(buffer, sizeof(buffer), "%s,%u\n", ctime(&current_time), (unsigned int) moving_avg);
        if (fwrite(buffer, 1, strlen(buffer), f) != strlen(buffer)) {
            perror("fwrite failed");
        }
        fflush(f);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <fcntl.h>
#include <syslog.h>

#define LOG_FILE "flame_log.txt"
#define LOG_FORMAT "%Y-%m-%d %H:%M:%S %s\n"

int main() {
    int fd, line, chip;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    struct gpiod_state *state;
    char buffer[128];
    char timestamp[128];
    int edge_detected = 0;
    int flame_detected = 0;
    int running = 1;

    // Open the log file in append mode
    fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        perror("Failed to open log file");
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = [](int sig) {
        if (running) {
            flame_detected = 0;
            edge_detected = 0;
            running = 0;
            close(fd);
            gpiod_chip_free(chip);
            return 0;
        }
        return 0;
    };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Get the GPIO chip for GPIO17
    chip = gpiod_chip_open("/dev/gpiod");
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Find the line for GPIO17
    line = gpiod_chip_get_line(chip, 17);
    if (line == NULL) {
        perror("Failed to find GPIO17 line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up the line as input with internal pull-up
    line = gpiod_line_request_input(line, 1);
    if (line == NULL) {
        perror("Failed to set line as input");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up edge detection
    edge = gpiod_line_request_edge(line, GPIOD_EDGE_FALLING);
    if (edge == NULL) {
        perror("Failed to set edge detection");
        gpiod_chip_close(chip);
        return 1;
    }

    // Get the state of the line
    state = gpiod_line_request_state(edge, 0);
    if (state == NULL) {
        perror("Failed to get line state");
        gpiod_chip_close(chip);
        return 1;
    }

    // Start polling
    while (running) {
        // Read the current state
        if (gpiod_state_get(state, &flame_detected) < 0) {
            perror("Failed to get line state");
            gpiod_chip_close(chip);
            return 1;
        }

        // Check for edge detection
        if (edge_detected) {
            // Record the timestamp
            if (strftime(timestamp, sizeof(timestamp), LOG_FORMAT, localtime()) < 0) {
                perror("Failed to format timestamp");
                return 1;
            }
            if (write(fd, timestamp, strlen(timestamp)) < 0) {
                perror("Failed to write to log file");
                return 1;
            }
            if (write(fd, "FLAME DETECTED\n", 13) < 0) {
                perror("Failed to write to log file");
                return 1;
            }

            // Print to console
            printf("FLAME DETECTED\n");

            // Reset edge detection
            edge_detected = 0;
        }

        // Poll every 100 ms
        usleep(100000);
    }

    // Clean up
    if (running) {
        flame_detected = 0;
        edge_detected = 0;
        running = 0;
        close(fd);
        gpiod_chip_close(chip);
    }

    return 0;
}

