#define POLL_INTERVAL 100
#define CSV_FILE "tracking_log.csv"

int main() {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_request *request;
    struct gpiod_event *event;
    char *header = "timestamp,sensor1,sensor2,sensor3,sensor4\n";
    char timestamp[128];
    FILE *csv_file;

    // Register signal handlers
    signal(SIGINT, [](int sig) {
        if (csv_file) {
            fclose(csv_file);
        }
        if (chip) {
            gpiod_chip_free(chip);
        }
        if (line) {
            gpiod_line_free(line);
        }
        if (request) {
            gpiod_line_request_free(request);
        }
        exit(EXIT_SUCCESS);
    });

    signal(SIGTERM, [](int sig) {
        if (csv_file) {
            fclose(csv_file);
        }
        if (chip) {
            gpiod_chip_free(chip);
        }
        if (line) {
            gpiod_line_free(line);
        }
        if (request) {
            gpiod_line_request_free(request);
        }
        exit(EXIT_SUCCESS);
    });

    // Open the GPIO chip
    if ((fd = gpiod_chip_open("/dev/gpiod")) < 0) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }
    if ((chip = gpiod_chip_get_fd(fd)) == NULL) {
        perror("gpiod_chip_get_fd");
        gpiod_chip_close(fd);
        return EXIT_FAILURE;
    }

    // Create a request for each GPIO pin
    request = malloc(4 * sizeof(struct gpiod_line_request));
    if (!request) {
        perror("malloc");
        gpiod_chip_close(fd);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input(request, GPIO_PIN_1, 0) < 0) {
        perror("gpiod_line_request_input");
        free(request);
        gpiod_chip_close(fd);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input(request + 1, GPIO_PIN_2, 0) < 0) {
        perror("gpiod_line_request_input");
        free(request);
        gpiod_chip_close(fd);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input(request + 2, GPIO_PIN_3, 0) < 0) {
        perror("gpiod_line_request_input");
        free(request);
        gpiod_chip_close(fd);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input(request + 3, GPIO_PIN_4, 0) < 0) {
        perror("gpiod_line_request_input");
        free(request);
        gpiod_chip_close(fd);
        return EXIT_FAILURE;
    }

    // Get a line for each request
    for (int i = 0; i < 4; i++) {
        if ((line = gpiod_chip_get_line(chip, request + i)) == NULL) {
            perror("gpiod_chip_get_line");
            free(request);
            gpiod_chip_close(fd);
            return EXIT_FAILURE;
        }
    }

    // Open the CSV file
    csv_file = fopen(CSV_FILE, "a+");
    if (!csv_file) {
        perror("fopen");
        free(request);
        gpiod_chip_close(fd);
        return EXIT_FAILURE;
    }

    // Write the header if the file is newly created
    if (fseek(csv_file, 0, SEEK_SET) == 0) {
        if (fwrite(header, 1, strlen(header), csv_file) != strlen(header)) {
            perror("fwrite");
            fclose(csv_file);
            free(request);
            gpiod_chip_close(fd);
            return EXIT_FAILURE;
        }
    }

    // Main loop
    while (1) {
        // Get the current timestamp
        time_t t = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&t));

        // Read the values from the lines
        for (int i = 0; i < 4; i++) {
            if ((request + i)->value = gpiod_line_get_value(line + i)) < 0) {
                perror("gpiod_line_get_value");
                continue;
            }
        }

        // Write the values to the CSV file
        if (fprintf(csv_file, "%s,%d,%d,%d,%d\n", timestamp, request[0]->value, request[1]->value, request[2]->value, request[3]->value) < 0) {
            perror("fprintf");
            fclose(csv_file);
            free(request);
            gpiod_chip_close(fd);
            return EXIT_FAILURE;
        }

        // Sleep for the poll interval
        usleep(POLL_INTERVAL * 1000);
    }

    // Cleanup
    free(request);
    gpiod_chip_close(fd);
    fclose(csv_file);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <syslog.h>
#include <signal.h>
#include <gpiod.h>

#define SENSOR_1 1
#define SENSOR_2 2
#define DEBOUNCE_WINDOW 50
#define POLL_INTERVAL 100

int main() {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    struct gpiod_event *event;
    struct timespec ts;
    char buffer[256];
    char log_filename[256];
    char log_msg[256];
    int line_fd;
    int line_state;
    int event_detected;
    int event_count = 0;

    // Set up log file
    snprintf(log_filename, sizeof(log_filename), "/var/log/tilt_events.log");
    if ((fd = open(log_filename, O_WRONLY | O_CREAT | O_APPEND, 0644)) < 0) {
        perror("Failed to open log file");
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = [](int sig) {
        if (sig == SIGINT || sig == SIGTERM) {
            // Release all resources
            if (chip) {
                gpiod_chip_close(chip);
                chip = NULL;
            }
            if (line) {
                gpiod_line_unref(line);
                line = NULL;
            }
            if (edge) {
                gpiod_edge_unref(edge);
                edge = NULL;
            }
            if (event) {
                gpiod_event_unref(event);
                event = NULL;
            }
            if (fd) {
                close(fd);
                fd = -1;
            }
            syslog(LOG_INFO, "Tilt sensor monitoring stopped");
            return 0;
        }
        return -1;
    };
    sa.sa_flags = SA_RESTART;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open GPIO chip
    if ((chip = gpiod_chip_open("/dev/gpiod")) == NULL) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Get GPIO lines
    if ((line = gpiod_chip_get_line(chip, SENSOR_1)) == NULL) {
        perror("Failed to get GPIO line 1");
        return 1;
    }
    if ((line = gpiod_chip_get_line(chip, SENSOR_2)) == NULL) {
        perror("Failed to get GPIO line 2");
        return 1;
    }

    // Configure lines
    if (gpiod_line_request(line, GPIOD_LINE_MODE_INPUT, GPIOD_LINE_ACTIVE_LOW, GPIOD_LINE_PULL_UP)) {
        perror("Failed to configure GPIO line");
        return 1;
    }

    // Set up edge detection
    if ((edge = gpiod_line_request_edge(line, GPIOD_EDGE_FALLING, DEBOUNCE_WINDOW)) == NULL) {
        perror("Failed to set up edge detection");
        return 1;
    }

    // Set up event handling
    if ((event = gpiod_line_request_event(line, GPIOD_LINE_EVENT_EDGE, GPIOD_LINE_EVENT_EDGE_FALLING)) == NULL) {
        perror("Failed to set up event handling");
        return 1;
    }

    // Poll lines
    while (1) {
        // Get current time
        clock_gettime(CLOCK_MONOTONIC, &ts);

        // Read line states
        if ((line_fd = gpiod_line_request_read(line)) < 0) {
            perror("Failed to read GPIO line");
            return 1;
        }
        line_state = gpiod_line_read(line);
        gpiod_line_release_read(line_fd);
        line_fd = -1;

        // Check for event
        if (line_state == 0) {
            event_detected = 1;
        } else {
            event_detected = 0;
        }

        // Log event if detected
        if (event_detected && (event_count % 2 == 0)) {
            event_count++;
            snprintf(log_msg, sizeof(log_msg), "%s, Sensor %d tilted\n", ctime(&ts.tv_sec), SENSOR_1);
            if (write(fd, log_msg, strlen(log_msg)) < 0) {
                perror("Failed to write to log file");
                return 1;
            }
        }

        // Sleep for POLL_INTERVAL
        nanosleep(&ts, NULL);

        // Check for SIGINT or SIGTERM
        if (sigwaitignore(&sa.sa_mask, &sig) < 0) {
            perror("Failed to wait for signal");
            return 1;
        }
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>

#define GPIO17 17
#define GPIO27 27
#define GPIO22 22
#define LOG_FILE "obstacle_log.csv"
#define LOG_HEADER "timestamp,sensor1,sensor2,led_state\n"

int main() {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line1, *line2, *line3;
    struct gpiod_edge *edge1, *edge2, *edge3;
    struct gpiod_state *state;
    char buffer[256];
    FILE *log_file;
    struct timespec ts;
    int sensor1, sensor2, led_state;
    int exit_code = 0;

    // Open the log file
    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        exit(EXIT_FAILURE);
    }

    // Set up the log header
    fprintf(log_file, "%s", LOG_HEADER);

    // Get the current time
    clock_gettime(CLOCK_MONOTONIC, &ts);

    // Open the GPIO chip
    if ((chip = gpiod_chip_open("/dev/gpiod")) == NULL) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    // Check if GPIOchip0 is available
    if (gpiod_chip_has_chip(chip, 0) == 0) {
        fprintf(stderr, "GPIOchip0 is not available\n");
        exit(EXIT_FAILURE);
    }

    // Get the GPIO line for sensor1
    if ((line1 = gpiod_chip_get_line(chip, 0, GPIO17)) == NULL) {
        fprintf(stderr, "Failed to get GPIO line for sensor1\n");
        exit(EXIT_FAILURE);
    }

    // Set up the edge for sensor1
    if ((edge1 = gpiod_line_request_edge(line1, GPIOD_EDGE_FALLING)) == NULL) {
        fprintf(stderr, "Failed to set up edge for sensor1\n");
        exit(EXIT_FAILURE);
    }

    // Get the GPIO line for sensor2
    if ((line2 = gpiod_chip_get_line(chip, 0, GPIO27)) == NULL) {
        fprintf(stderr, "Failed to get GPIO line for sensor2\n");
        exit(EXIT_FAILURE);
    }

    // Set up the edge for sensor2
    if ((edge2 = gpiod_line_request_edge(line2, GPIOD_EDGE_FALLING)) == NULL) {
        fprintf(stderr, "Failed to set up edge for sensor2\n");
        exit(EXIT_FAILURE);
    }

    // Get the GPIO line for the LED
    if ((line3 = gpiod_chip_get_line(chip, 0, GPIO22)) == NULL) {
        fprintf(stderr, "Failed to get GPIO line for LED\n");
        exit(EXIT_FAILURE);
    }

    // Set up the edge for the LED
    if ((edge3 = gpiod_line_request_edge(line3, GPIOD_EDGE_FALLING)) == NULL) {
        fprintf(stderr, "Failed to set up edge for LED\n");
        exit(EXIT_FAILURE);
    }

    // Set up the state for the edges
    if ((state = gpiod_edge_get_state(edge1)) == NULL) {
        fprintf(stderr, "Failed to get state for sensor1\n");
        exit(EXIT_FAILURE);
    }

    // Set up the state for the edges
    if ((state = gpiod_edge_get_state(edge2)) == NULL) {
        fprintf(stderr, "Failed to get state for sensor2\n");
        exit(EXIT_FAILURE);
    }

    // Set up the state for the edges
    if ((state = gpiod_edge_get_state(edge3)) == NULL) {
        fprintf(stderr, "Failed to get state for LED\n");
        exit(EXIT_FAILURE);
    }

    // Set the state to 0 for all edges
    if (gpiod_edge_set_state(edge1, 0) == -1) {
        fprintf(stderr, "Failed to set state for sensor1\n");
        exit(EXIT_FAILURE);
    }

    if (gpiod_edge_set_state(edge2, 0) == -1) {
        fprintf(stderr, "Failed to set state for sensor2\n");
        exit(EXIT_FAILURE);
    }

    if (gpiod_edge_set_state(edge3, 0) == -1) {
        fprintf(stderr, "Failed to set state for LED\n");
        exit(EXIT_FAILURE);
    }

    // Start the edges
    if (gpiod_edge_enable(edge1) == -1) {
        fprintf(stderr, "Failed to enable edge for sensor1\n");
        exit(EXIT_FAILURE);
    }

    if (gpiod_edge_enable(edge2) == -1) {
        fprintf(stderr, "Failed to enable edge for sensor2\n");
        exit(EXIT_FAILURE);
    }

    if (gpiod_edge_enable(edge3) == -1) {
        fprintf(stderr, "Failed to enable edge for LED\n");
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Read the current time
        clock_gettime(CLOCK_MONOTONIC, &ts);

        // Read the sensor values
        if (gpiod_line_get_value(line1, &sensor1) == -1) {
            fprintf(stderr, "Failed to read sensor1\n");
            exit(EXIT_FAILURE);
        }

        if (gpiod_line_get_value(line2, &sensor2) == -1) {
            fprintf(stderr, "Failed to read sensor2\n");
            exit(EXIT_FAILURE);
        }

        // Read the LED state
        if (gpiod_line_get_value(line3, &led_state) == -1) {
            fprintf(stderr, "Failed to read LED state\n");
            exit(EXIT_FAILURE);
        }

        // Log the data
        if (fprintf(log_file, "%ld,%d,%d,%d\n", (long)ts.tv_sec + ts.tv_nsec / 1e9, sensor1, sensor2, led_state) < 0) {
            fprintf(stderr, "Failed to write to log file\n");
            exit(EXIT_FAILURE);
        }

        // Flush the log file
        if (fflush(log_file) < 0) {
            fprintf(stderr, "Failed to flush log file\n");
            exit(EXIT_FAILURE);
        }

        // Check if both sensors are 0
        if (sensor1 == 0 && sensor2 == 0) {
            // Turn the LED on
            if (gpiod_line_set_value(line3, 1) == -1) {
                fprintf(stderr, "Failed to turn LED on\n");
                exit(EXIT_FAILURE);
            }
        } else {
            // Turn the LED off
            if (gpiod_line_set_value(line3, 0) == -1) {
                fprintf(stderr, "Failed to turn LED off\n");
                exit(EXIT_FAILURE);
            }
        }

        // Sleep for 100 ms
        usleep(100000);

        // Handle SIGINT
        if (signal(SIGINT, [](int sig) {
            // Turn off the LED
            if (gpiod_line_set_value(line3, 0) == -1) {
                fprintf(stderr, "Failed to turn LED off\n");
                exit(EXIT_FAILURE);
            }

            // Release all line resources
            if (gpiod_edge_disable(edge1) == -1) {
                fprintf(stderr, "Failed to disable edge for sensor1\n");
                exit(EXIT_FAILURE);
            }

            if (gpiod_edge_disable(edge2) == -1) {
                fprintf(stderr, "Failed to disable edge for sensor2\n");
                exit(EXIT_FAILURE);
            }

            if (gpiod_edge_disable(edge3) == -1) {
                fprintf(stderr, "Failed to disable edge for LED\n");
                exit(EXIT_FAILURE);
            }

            // Release the state
            if (gpiod_edge_get_state(edge1) == NULL) {
                fprintf(stderr, "Failed to release state for sensor1\n");
                exit(EXIT_FAILURE);
            }

            if (gpiod_edge_get_state(edge2) == NULL) {
                fprintf(stderr, "Failed to release state for sensor2\n");
                exit(EXIT_FAILURE);
            }

            if (gpiod_edge_get_state(edge3) == NULL) {
                fprintf(stderr, "Failed to release state for LED\n");
                exit(EXIT_FAILURE);
            }

            // Close the chip
            if (gpiod_chip_close(chip) == -1) {
                fprintf(stderr, "Failed to close GPIO chip\n");
                exit(EXIT_FAILURE);
            }

            // Close the log file
            if (fclose(log_file) != 0) {
                fprintf(stderr, "Failed to close log file\n");
                exit(EXIT_FAILURE);
            }

            exit(EXIT_SUCCESS);
        }));
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>

volatile sig_atomic_t stop = 0;

void handle_sigint(int sig) {
    stop = 1;
    printf("SIGINT received, stopping...\n");
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise failed");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    int gpio4 = gpioOpen(4);
    if (gpio4 < 0) {
        perror("gpioOpen failed");
        gpioTerminate();
        return 1;
    }

    int gpio17 = gpioOpen(17);
    if (gpio17 < 0) {
        perror("gpioOpen failed");
        gpioTerminate();
        return 1;
    }

    int ledPin = gpioSetMode(gpio17, PI_OUTPUT);
    if (ledPin < 0) {
        perror("gpioSetMode failed");
        gpioTerminate();
        return 1;
    }

    int ledState = 0;
    while (!stop) {
        int val = gpioRead(gpio4);
        if (val == 1) {
            printf("%ld detected\n", (long)gpioTick() / 1000.0);
            if (ledState == 0) {
                ledState = 1;
                gpioWrite(gpio17, 1);
            } else {
                ledState = 0;
                gpioWrite(gpio17, 0);
            }
        }
        gpioDelay(125); // 125 microseconds
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO17 17
#define GPIO27 27
#define GPIO22 22
#define PULL_UP 1
#define ACTIVE_LOW 0

int main() {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    struct gpiod_event *event;
    int left, center, right;
    char buffer[100];
    int status;

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, [](int signum) {
        printf("Received SIGINT signal. Exiting...\n");
        cleanup();
        exit(EXIT_SUCCESS);
    });
    signal(SIGTERM, [](int signum) {
        printf("Received SIGTERM signal. Exiting...\n");
        cleanup();
        exit(EXIT_SUCCESS);
    });

    // Open the gpiod device
    if ((fd = gpiod_open("/dev/gpiod")) < 0) {
        perror("gpiod_open");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Get the first chip
    if ((chip = gpiod_chip_next(fd)) == NULL) {
        perror("gpiod_chip_next");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Get the first line for each GPIO
    if ((line = gpiod_chip_get_line(chip, GPIO17)) == NULL) {
        perror("gpiod_chip_get_line");
        cleanup();
        exit(EXIT_FAILURE);
    }
    if ((line = gpiod_chip_get_line(chip, GPIO27)) == NULL) {
        perror("gpiod_chip_get_line");
        cleanup();
        exit(EXIT_FAILURE);
    }
    if ((line = gpiod_chip_get_line(chip, GPIO22)) == NULL) {
        perror("gpiod_chip_get_line");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Set the line to active-low with pull-up
    if ((status = gpiod_line_set_pull(line, PULL_UP)) < 0) {
        perror("gpiod_line_set_pull");
        cleanup();
        exit(EXIT_FAILURE);
    }
    if ((status = gpiod_line_set_edge(line, EDGE_FALLING)) < 0) {
        perror("gpiod_line_set_edge");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Create an event for each line
    if ((event = gpiod_line_request_event(line, 0)) == NULL) {
        perror("gpiod_line_request_event");
        cleanup();
        exit(EXIT_FAILURE);
    }
    if ((edge = gpiod_event_get_edge(event)) == NULL) {
        perror("gpiod_event_get_edge");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Start the event
    if ((status = gpiod_event_enable(event)) < 0) {
        perror("gpiod_event_enable");
        cleanup();
        exit(EXIT_FAILURE);
    }

    while (1) {
        // Read the sensor states
        if ((left = gpiod_line_get_value(line)) < 0) {
            perror("gpiod_line_get_value");
            cleanup();
            exit(EXIT_FAILURE);
        }
        if ((center = gpiod_line_get_value(line)) < 0) {
            perror("gpiod_line_get_value");
            cleanup();
            exit(EXIT_FAILURE);
        }
        if ((right = gpiod_line_get_value(line)) < 0) {
            perror("gpiod_line_get_value");
            cleanup();
            exit(EXIT_FAILURE);
        }

        // Log the sensor states
        sprintf(buffer, "Left: %d, Center: %d, Right: %d\n", left, center, right);
        printf("%s", buffer);

        // Wait for 100 ms
        usleep(100000);
    }

    cleanup();

    return 0;
}

void cleanup() {
    if (line) {
        gpiod_line_free(line);
        line = NULL;
    }
    if (edge) {
        gpiod_event_free(edge);
        edge = NULL;
    }
    if (event) {
        gpiod_event_free(event);
        event = NULL;
    }
    if (chip) {
        gpiod_chip_free(chip);
        chip = NULL;
    }
    if (fd) {
        gpiod_close(fd);
        fd = NULL;
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDR 0x49
#define ALS_VISIBLE_DATA_REG_LSB 0x24
#define ALS_VISIBLE_DATA_REG_MSB 0x25

#define I2C_TIMEOUT 100

void i2c_init(int *fd) {
    *fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open i2c device");
        exit(EXIT_FAILURE);
    }
    if (ioctl(*fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set slave address");
        exit(EXIT_FAILURE);
    }
}

void i2c_read(int fd, uint8_t *buf, size_t size) {
    if (read(fd, buf, size) < 0) {
        perror("Failed to read from i2c device");
        exit(EXIT_FAILURE);
    }
}

void i2c_cleanup(int fd) {
    if (close(fd) < 0) {
        perror("Failed to close i2c device");
        exit(EXIT_FAILURE);
    }
}

int main() {
    int i2c_fd;
    uint8_t data[2];

    i2c_init(&i2c_fd);

    while (1) {
        i2c_read(i2c_fd, data, 2);
        uint16_t heart_rate = (data[0] << 8) | data[1];
        printf("Heart Rate: %04x\n", heart_rate);

        // Simulate a 100ms delay
        usleep(100000);

        // Handle Ctrl+C
        if (signal(SIGINT, [](int) {
            i2c_cleanup(i2c_fd);
            exit(EXIT_SUCCESS);
        }) == SIGINT) {
            printf("Ctrl+C received, exiting...\n");
            i2c_cleanup(i2c_fd);
            exit(EXIT_SUCCESS);
        }
    }

    return 0;
}

