    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);

    // Open the GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    // Open the lines
    line_left = gpiod_chip_get_line(chip, GPIO_LINE_LEFT);
    line_middle = gpiod_chip_get_line(chip, GPIO_LINE_MIDDLE);
    line_right = gpiod_chip_get_line(chip, GPIO_LINE_RIGHT);
    if (!line_left || !line_middle || !line_right) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    // Create requests
    request_left = gpiod_line_request_input(line_left, 0);
    request_middle = gpiod_line_request_input(line_middle, 0);
    request_right = gpiod_line_request_input(line_right, 0);
    if (!request_left || !request_middle || !request_right) {
        perror("gpiod_line_request_input");
        goto cleanup;
    }

    // Set up edge detection
    edge = gpiod_request_get_edge(request_left);
    if (!edge) {
        perror("gpiod_request_get_edge");
        goto cleanup;
    }
    gpiod_edge_set_edge(edge, GPIOD_EDGE_BOTH);
    gpiod_request_set_edge(request_left, edge);

    edge = gpiod_request_get_edge(request_middle);
    if (!edge) {
        perror("gpiod_request_get_edge");
        goto cleanup;
    }
    gpiod_edge_set_edge(edge, GPIOD_EDGE_BOTH);
    gpiod_request_set_edge(request_middle, edge);

    edge = gpiod_request_get_edge(request_right);
    if (!edge) {
        perror("gpiod_request_get_edge");
        goto cleanup;
    }
    gpiod_edge_set_edge(edge, GPIOD_EDGE_BOTH);
    gpiod_request_set_edge(request_right, edge);

    // Start reading
    while (1) {
        // Read values
        value_left = gpiod_line_read(line_left);
        value_middle = gpiod_line_read(line_middle);
        value_right = gpiod_line_read(line_right);

        // Log values
        printf("L:%d M:%d R:%d\n", value_left, value_middle, value_right);

        // Sleep for POLL_INTERVAL
        usleep(POLL_INTERVAL);
    }

