    if (line_fd_left >= 0) {
        close(line_fd_left);
    }
    if (line_fd_middle >= 0) {
        close(line_fd_middle);
    }
    if (line_fd_right >= 0) {
        close(line_fd_right);
    }
    if (request_left) {
        gpiod_request_free(request_left);
    }
    if (request_middle) {
        gpiod_request_free(request_middle);
    }
    if (request_right) {
        gpiod_request_free(request_right);
    }
    if (line_left) {
        gpiod_line_free(line_left);
    }
    if (line_middle) {
        gpiod_line_free(line_middle);
    }
    if (line_right) {
        gpiod_line_free(line_right);
    }
    if (chip) {
        gpiod_chip_free(chip);
    }
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>

#define GPIO_CHIP 0
#define NUM_LINES 8
#define POLL_INTERVAL_MS 200
#define BUFFER_SIZE 128

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    struct timespec ts;
    char buffer[BUFFER_SIZE];
    int i, status;

    // Install SIGINT/SIGTERM handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP);
    if (chip == NULL) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }

    // Request all lines as inputs
    for (i = 0; i < NUM_LINES; i++) {
        line = gpiod_chip_request_line(chip, GPIOD_LINE_INPUT, i);
        if (line == NULL) {
            perror("gpiod_chip_request_line");
            gpiod_chip_unexport(chip);
            exit(EXIT_FAILURE);
        }
    }

    // Loop indefinitely
    while (1) {
        // Get current time
        clock_gettime(CLOCK_MONOTONIC, &ts);
        long long timestamp = ts.tv_sec * 1000 + ts.tv_nsec / 1000000;

        // Get line values
        for (i = 0; i < NUM_LINES; i++) {
            line = gpiod_chip_get_line(chip, i);
            if (line == NULL) {
                perror("gpiod_chip_get_line");
                gpiod_chip_unexport(chip);
                exit(EXIT_FAILURE);
            }
            status = gpiod_line_get_value(line, &line->value);
            if (status < 0) {
                perror("gpiod_line_get_value");
                gpiod_chip_unexport(chip);
                exit(EXIT_FAILURE);
            }
            if (line->value == 1) {
                sprintf(buffer + strlen(buffer), "CH%d=1", i + 1);
            } else {
                sprintf(buffer + strlen(buffer), "CH%d=0", i + 1);
            }
        }

        // Print timestamp and channel states
        printf("[%llds] %s\n", timestamp, buffer);
        fflush(stdout);

        // Sleep for POLL_INTERVAL_MS
        nanosleep(&ts, NULL);
    }

    // Graceful shutdown
    handle_signal(EXIT_SUCCESS);

    return 0;
}

// Handle signal
void handle_signal(int signum) {
    // Release all resources
    for (i = 0; i < NUM_LINES; i++) {
        line = gpiod_chip_get_line(chip, i);
        if (line == NULL) {
            continue;
        }
        gpiod_line_free(line);
    }
    gpiod_chip_unexport(chip);
    gpiod_chip_close(chip);
    exit(EXIT_SUCCESS);
}

