#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>

#define I2C_ADDR 0x23
#define I2C_CMD 0x10
#define I2C_TIMEOUT 180
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY 100

#define MAX_LUX 1000
#define MIN_LUX 0

#define LOG_BASE 10
#define LOG_SCALE 1.0 / 1000.0

#define MAX_BRIGHTNESS 255
#define MIN_BRIGHTNESS 0

#define LED_PIN 18

typedef struct {
    uint8_t msb;
    uint8_t lsb;
} I2CResult;

void i2c_read(uint8_t addr, uint8_t cmd, I2CResult *result) {
    int retries = 0;
    while (retries < I2C_RETRY_COUNT) {
        result->msb = 0;
        result->lsb = 0;
        if (retry_i2c(addr, cmd, result)) {
            break;
        }
        retries++;
        if (retries >= I2C_RETRY_COUNT) {
            printf("I2C read failed after %d retries\n", retries);
            exit(EXIT_FAILURE);
        }
        usleep(I2C_RETRY_DELAY);
    }
}

int retry_i2c(uint8_t addr, uint8_t cmd, I2CResult *result) {
    int fd = wiringPiI2CFileOpen(I2C_ADDR, 1);
    if (fd < 0) {
        printf("Failed to open I2C device\n");
        return 0;
    }
    wiringPiI2CWrite(fd, cmd);
    wiringPiI2CRead(fd, result);
    wiringPiI2CFileClose(fd);
    return 1;
}

int main() {
    if (gpioInitialise() < 0) {
        perror("pigpio init failed");
        return EXIT_FAILURE;
    }

    int brightness = 0;
    int light_lux = 0;

    signal(SIGINT, [](int) {
        printf("Received SIGINT signal, exiting...\n");
        gpioTerminate();
        exit(EXIT_SUCCESS);
    });

    signal(SIGTERM, [](int) {
        printf("Received SIGTERM signal, exiting...\n");
        gpioTerminate();
        exit(EXIT_SUCCESS);
    });

    printf("Initializing I2C...\n");
    if (wiringPiI2CFileOpen(I2C_ADDR, 1) < 0) {
        printf("Failed to open I2C device\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    printf("Reading I2C...\n");
    i2c_read(I2C_ADDR, I2C_CMD, &light_lux);

    printf("Ambient light lux: %d\n", light_lux);

    brightness = log_mapping(light_lux);

    printf("Setting LED brightness: %d\n", brightness);

    gpioSetPWMCbFunc(LED_PIN, [](int gpio, int level, void *arg) {
        brightness = log_mapping(light_lux);
        gpioSetPWMLevel(LED_PIN, brightness);
    });

    gpioSetPWM(LED_PIN, MAX_BRIGHTNESS, 0, brightness);

    printf("Running...\n");
    while (1) {
        sleep(1);
    }

    gpioTerminate();
    return 0;
}

int log_mapping(int lux) {
    if (lux < MIN_LUX) {
        return MIN_BRIGHTNESS;
    } else if (lux > MAX_LUX) {
        return MAX_BRIGHTNESS;
    } else {
        return (int)(log10((double)lux) * LOG_SCALE * MAX_BRIGHTNESS + 0.5);
    }
}

