#include <string.h>
#include <signal.h>
#include <gpiod.h>
#include <time.h>

#define LED_PIN 18
#define BUZZER_PIN 17
#define FLAME_PIN 4

#define LED_ON 1
#define LED_OFF 0
#define BUZZER_ON 1
#define BUZZER_OFF 0

#define FLAME_FAULT_THRESHOLD 5
#define FLAME_FAULT_TIMEOUT 500  // ms

typedef struct {
    int pin;
    int value;
    int state;
    int fault;
    time_t fault_start;
} GPIOLineState;

GPIOLineState flame_sensor_state;
GPIOLineState led_state;
GPIOLineState buzzer_state;

void handle_sigint(int signum) {
    gpiod_line_close(gpiod_get_line(flame_sensor_state.pin));
    gpiod_line_close(gpiod_get_line(led_state.pin));
    gpiod_line_close(gpiod_get_line(buzzer_state.pin));
    exit(EXIT_FAILURE);
}

void log_event(const char *event, time_t timestamp) {
    char buffer[256];
    struct tm *timeinfo;
    timeinfo = localtime(&timestamp);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s %s\n", buffer, event);
}

