#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP 0
#define LED_LINE 17
#define BUTTON_LINE 18

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge_event *event;
    int status;

    // Open GPIO chip 0
    chip = gpiod_chip_open(GPIO_CHIP, O_CTRLC);
    if (chip == NULL) {
        perror("gpiod_chip_open");
        return 1;
    }

    // Request LED line as output initially low
    line = gpiod_chip_request_line(chip, LED_LINE, GPIOD_LINE_TYPE_EDGE);
    if (line == NULL) {
        perror("gpiod_chip_request_line");
        gpiod_chip_unexport(chip);
        return 1;
    }
    gpiod_line_set_direction(line, GPIOD_DIR_OUT);
    gpiod_line_set_value(line, 0);
    gpiod_line_request_edge(line, GPIOD_EDGE_FALLING);
    gpiod_line_enable(line, GPIOD_EDGE_DETECT);

    // Request button line as input with internal pull-up
    line = gpiod_chip_request_line(chip, BUTTON_LINE, GPIOD_LINE_TYPE_EDGE);
    if (line == NULL) {
        perror("gpiod_chip_request_line");
        gpiod_chip_unexport(chip);
        return 1;
    }
    gpiod_line_set_direction(line, GPIOD_DIR_IN);
    gpiod_line_set_pullup(line, 1);
    gpiod_line_request_edge(line, GPIOD_EDGE_FALLING);
    gpiod_line_enable(line, GPIOD_EDGE_DETECT);

    event = gpiod_line_event_wait(line, 1);
    if (event == NULL) {
        perror("gpiod_line_event_wait");
        gpiod_chip_unexport(chip);
        return 1;
    }

    printf("LED blinking with button press detection...\n");

    while (1) {
        // Toggle LED
        gpiod_line_set_value(line, 1);
        sleep(1);
        gpiod_line_set_value(line, 0);
        sleep(1);

        // Check for button press
        if (gpiod_line_event_wait(event, 1) == GPIOD_EDGE_FALLING) {
            printf("Button pressed, stopping LED...\n");
            gpiod_line_disable(line, GPIOD_EDGE_DETECT);
            gpiod_line_set_value(line, 0);
            gpiod_chip_unexport(chip);
            return 0;
        }
    }

    return 0;
}

void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Received SIGINT, exiting...\n");
        gpiod_chip_unexport(chip);
        return;
    }
    return;
}

int main() {
    signal(SIGINT, signal_handler);
    return blink_button();
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <sys/time.h>
#include <pigpio.h>

void handle_sigint(int signum) {
    gpioWrite(5, 0);  // Turn off the LED
    printf("SIGINT caught, exiting...\n");
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        perror("pigpioInitialise failed");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(5, PI_OUTPUT) < 0) {
        perror("gpioSetMode failed");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    while (1) {
        gpioWrite(5, 1);  // Turn on the LED
        printf("LED ON\n");
        fflush(stdout);  // Flush stdout
        usleep(750000);  // Wait 750 ms

        gpioWrite(5, 0);  // Turn off the LED
        printf("LED OFF\n");
        fflush(stdout);  // Flush stdout
        usleep(750000);  // Wait 750 ms
    }

    return 0;
}

#include <stdio.h>
