int main() {
    int chip_fd, line_fd, err;
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    // Open the gpiochip0 device
    chip_fd = gpiod_open("/dev/gpiod", O_RDWR);
    if (chip_fd < 0) {
        perror("gpiod_open");
        return 1;
    }

    // Get the gpiochip0 device
    chip = gpiod_get_chip(chip_fd);
    if (!chip) {
        perror("gpiod_get_chip");
        goto cleanup;
    }

    // Open GPIO24 as output
    line_fd = gpiod_get_line(chip, 24, GPIOD_LINE_DIR_OUT);
    if (line_fd < 0) {
        perror("gpiod_get_line");
        goto cleanup;
    }

    // Set GPIO24 to output low
    err = gpiod_set_value(line_fd, 0);
    if (err < 0) {
        perror("gpiod_set_value");
        goto cleanup;
    }

    // Open GPIO22 as input with internal pull-down
    line_fd = gpiod_get_line(chip, 22, GPIOD_LINE_DIR_IN);
    if (line_fd < 0) {
        perror("gpiod_get_line");
        goto cleanup;
    }

    // Set GPIO22 to input with internal pull-down
    err = gpiod_set_pull(line_fd, GPIOD_PULL_DOWN);
    if (err < 0) {
        perror("gpiod_set_pull");
        goto cleanup;
    }

    // Main loop
    while (1) {
        // Read the button state
        err = gpiod_get_value(line_fd);
        if (err < 0) {
            perror("gpiod_get_value");
            goto cleanup;
        }

        if (gpiod_get_value(line_fd) == 1) {
            // Button is pressed, blink the LED
            err = gpiod_set_value(line_fd, 1);
            if (err < 0) {
                perror("gpiod_set_value");
                goto cleanup;
            }
            usleep(500000); // 500 ms
            err = gpiod_set_value(line_fd, 0);
            if (err < 0) {
                perror("gpiod_set_value");
                goto cleanup;
            }
            usleep(500000); // 500 ms
        } else {
            // Button is not pressed, turn the LED off
            err = gpiod_set_value(line_fd, 0);
            if (err < 0) {
                perror("gpiod_set_value");
                goto cleanup;
            }
        }
    }

cleanup:
    // Close the line
    if (line_fd >= 0) {
        gpiod_line_close(line_fd);
    }

    // Close the chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close the chip_fd
    if (chip_fd >= 0) {
        gpiod_close(chip_fd);
    }

    return 0;
}

