#define I2C_BUS 1
#define I2C_ADDR 0x29
#define VL6180X_REG_0x016 0x16
#define VL6180X_REG_0x000 0x00
#define VL6180X_REG_0x0207 0x07
#define VL6180X_REG_0x04D 0x4d

#define MAX_LOG_ENTRIES 1000
#define LOG_FILE "distance_log.txt"

volatile sig_atomic_t running = 1;

void handle_sigint(int sig) {
    running = 0;
    printf("SIGINT received, exiting...\n");
    piLock();
    piUnexport(0);
    piUnload();
    exit(0);
}

void init_vl6180x() {
    int fd;
    struct i2c_msg messages[2];
    struct i2c_rdwr_ioctl_msg ioctl_msg;
    int status;

    fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return;
    }

    ioctl(fd, I2C_SLAVE, I2C_ADDR);

    messages[0].addr = I2C_ADDR;
    messages[0].flags = I2C_M_RD;
    messages[0].len = 1;
    messages[0].buf = (unsigned char *) &VL6180X_REG_0x016;

    messages[1].addr = I2C_ADDR;
    messages[1].flags = I2C_M_RD;
    messages[1].len = 1;
    messages[1].buf = (unsigned char *) &VL6180X_REG_0x000;

    status = ioctl(fd, I2C_RDWR, messages);
    if (status < 0) {
        perror("Failed to initialize VL6180X");
        return;
    }

    messages[0].addr = I2C_ADDR;
    messages[0].flags = I2C_M_WRITE;
    messages[0].len = 1;
    messages[0].buf = (unsigned char *) &VL6180X_REG_0x0207;

    status = ioctl(fd, I2C_RDWR, messages);
    if (status < 0) {
        perror("Failed to write VL6180X register");
        return;
    }

    close(fd);
}

void read_range_status() {
    int fd;
    struct i2c_msg messages[1];
    struct i2c_rdwr_ioctl_msg ioctl_msg;
    int status;

    fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return;
    }

    ioctl(fd, I2C_SLAVE, I2C_ADDR);

    messages[0].addr = I2C_ADDR;
    messages[0].flags = I2C_M_RD;
    messages[0].len = 1;
    messages[0].buf = (unsigned char *) &VL6180X_REG_0x04D;

    status = ioctl(fd, I2C_RDWR, messages);
    if (status < 0) {
        perror("Failed to read VL6180X range status");
        return;
    }

    close(fd);

    if (messages[0].buf[0] & 0x80) {
        printf("Error: VL6180X range status error\n");
    } else {
        printf("Distance: %.2f mm\n", (float) (messages[0].buf[0] & 0x7F) * 100);
    }
}

int main() {
    piLock();
    piUnexport(0);
    piUnload();

    signal(SIGINT, handle_sigint);

    init_vl6180x();

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    while (running) {
        piExport(0);
        piSetMode(0, PI_OUTPUT);
        piSetPullup(0, PI_PUPD_ON);
        piSetClock(0, 4000000);
        piSetServo(0, 0);
        piDelayMicroseconds(1000000); // 100 ms

        read_range_status();

        if (running) {
            if (piWrite(0, 0, 0) == 0) {
                if ((float) (piRead(0, 0) & 0x7F) * 100 < 100) {
                    fprintf(log_file, "%s DOOR_OPEN\n", ctime(&time(NULL)));
                } else {
                    fprintf(log_file, "%s DOOR_CLOSED\n", ctime(&time(NULL)));
                }
            } else {
                printf("Error writing to GPIO\n");
            }
        }

        piSetMode(0, PI_OFF);
        piUnexport(0);
        piLock();
    }

    fclose(log_file);
    piLock();
    piUnexport(0);
    piUnload();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <sys/timerfd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/epoll.h>
#include <sys/termio.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69
#define CONTROL_REG 0x00
#define DATA_REG 0x01
#define SAMPLE_INTERVAL_MS 10
#define SAMPLES_PER_SECOND 1000
#define LOG_FILE "audio_log.dat"

#define LOG_HEADER "sec,nsec,sensor1,sensor2,tdoa\n"

int i2c_fd1, i2c_fd2;
int sensor1_fd, sensor2_fd;
int timer_fd;
int epoll_fd;
int fd;
int log_fd;

void handle_sigint(int signum) {
    if (log_fd != -1) {
        close(log_fd);
    }
    if (epoll_fd != -1) {
        close(epoll_fd);
    }
    if (timer_fd != -1) {
        close(timer_fd);
    }
    if (sensor1_fd != -1) {
        close(sensor1_fd);
    }
    if (sensor2_fd != -1) {
        close(sensor2_fd);
    }
    if (i2c_fd1 != -1) {
        close(i2c_fd1);
    }
    if (i2c_fd2 != -1) {
        close(i2c_fd2);
    }
    if (pigpioTerminate() == 0) {
        printf("pigpio terminated successfully\n");
    } else {
        printf("pigpio termination failed\n");
    }
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (pigpio_init() < 0) {
        perror("pigpio_init failed");
        return 1;
    }

    fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd == -1) {
        perror("failed to open log file");
        return 1;
    }

    if (write(fd, LOG_HEADER, strlen(LOG_HEADER)) < 0) {
        perror("failed to write log header");
        return 1;
    }

    i2c_fd1 = i2c_open(I2C_BUS, SENSOR1_ADDR);
    if (i2c_fd1 == -1) {
        perror("failed to open i2c bus 1 for sensor 1");
        return 1;
    }

    i2c_fd2 = i2c_open(I2C_BUS, SENSOR2_ADDR);
    if (i2c_fd2 == -1) {
        perror("failed to open i2c bus 1 for sensor 2");
        return 1;
    }

    sensor1_fd = pigpio_i2c_open(i2c_fd1, 0, CONTROL_REG);
    if (sensor1_fd == -1) {
        perror("failed to open sensor 1 control register");
        return 1;
    }

    sensor2_fd = pigpio_i2c_open(i2c_fd2, 0, CONTROL_REG);
    if (sensor2_fd == -1) {
        perror("failed to open sensor 2 control register");
        return 1;
    }

    if (pigpio_i2c_write(sensor1_fd, 0x80) < 0) {
        perror("failed to enable sensor 1");
        return 1;
    }

    if (pigpio_i2c_write(sensor2_fd, 0x80) < 0) {
        perror("failed to enable sensor 2");
        return 1;
    }

    timer_fd = timerfd_create(CLOCK_REALTIME, 0);
    if (timer_fd == -1) {
        perror("failed to create timerfd");
        return 1;
    }

    struct itimerspec timer_spec;
    timer_spec.it_value.tv_sec = 1 / SAMPLE_INTERVAL_MS;
    timer_spec.it_value.tv_nsec = 0;
    timer_spec.it_interval.tv_sec = 1 / SAMPLE_INTERVAL_MS;
    timer_spec.it_interval.tv_nsec = 0;
    if (timerfd_settime(timer_fd, 0, &timer_spec, NULL, NULL, NULL) < 0) {
        perror("failed to set timer interval");
        return 1;
    }

    epoll_fd = epoll_create(1);
    if (epoll_fd == -1) {
        perror("failed to create epoll");
        return 1;
    }

    struct epoll_event event;
    event.events = EPOLLIN;
    event.data.fd = fd;
    epoll_ctl(epoll_fd, EPOLL_CTL_ADD, fd, &event);

    event.data.fd = timer_fd;
    event.events = EPOLLIN;
    epoll_ctl(epoll_fd, EPOLL_CTL_ADD, timer_fd, &event);

    while (1) {
        struct epoll_event events[1];
        int num_events = epoll_wait(epoll_fd, events, 1, -1);
        if (num_events == 0) {
            continue;
        }

        if (events[0].data.fd == fd) {
            char buffer[1024];
            ssize_t read_bytes = read(fd, buffer, 1024);
            if (read_bytes < 0) {
                perror("failed to read log file");
                continue;
            }
            if (write(fd, buffer, read_bytes) < 0) {
                perror("failed to write log file");
                continue;
            }
        } else if (events[0].data.fd == timer_fd) {
            struct itimerspec timer_spec;
            timerfd_get_info(timer_fd, &timer_spec);
            if (timer_spec.it_value.tv_sec > 0) {
                struct timespec now;
                clock_gettime(CLOCK_REALTIME, &now);
                if (now.tv_sec > timer_spec.it_value.tv_sec) {
                    timerfd_settime(timer_fd, 0, &timer_spec, NULL, NULL, NULL);
                }
            }
        }
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/ioctl.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_MODE 3
#define SPI_SPEED 1000000
#define SPI_FLAGS 0b11000000000  // CPHA=1, CPOL=1, aux SPI off

#define SPI_WORD_SIZE 16
#define SPI_WORD_FORMAT 0b00000001  // 16-bit words

#define X_GYRO 0x04
#define Y_GYRO 0x06
#define Z_GYRO 0x08
#define X_ACCEL 0x0A
#define Y_ACCEL 0x0C
#define Z_ACCEL 0x0E

#define SAMPLE_RATE 100
#define SAMPLE_DELAY 40
#define LOG_FILE "imu_data.csv"

volatile sig_atomic_t running = 1;

void cleanup() {
    if (spiHandle) {
        spiClose(spiHandle);
    }
    if (fp) {
        fclose(fp);
    }
    piLock();
    piGpioTerminate();
    piUnlock();
}

void handle_signal(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise()) {
        fprintf(stderr, "Error initializing GPIO\n");
        return 1;
    }

    piLock();
    piSetPullup(8, 0);  // Disable pull-up on CE0
    piSetMode(8, PI_OUTPUT);  // Set CE0 as output
    piSetBit(8, 0);  // Set CE0 to 0
    piUnlock();

    int spiHandle = spiOpen(SPI_CHANNEL, SPI_MODE, SPI_SPEED, SPI_FLAGS);
    if (spiHandle < 0) {
        fprintf(stderr, "Error opening SPI handle\n");
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "w");
    if (!fp) {
        fprintf(stderr, "Error opening log file\n");
        return 1;
    }

    fprintf(fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);
    signal(SIGABRT, handle_signal);
    signal(SIGFPE, handle_signal);
    signal(SIGILL, handle_signal);
    signal(SIGSEGV, handle_signal);
    signal(SIGBUS, handle_signal);
    signal(SIGPIPE, handle_signal);
    signal(SIGXCPU, handle_signal);
    signal(SIGXFSZ, handle_signal);
    signal(SIGALRM, handle_signal);
    signal(SIGVTALRM, handle_signal);
    signal(SIGVTIMER, handle_signal);
    signal(SIGPROF, handle_signal);
    signal(SIGUSR1, handle_signal);
    signal(SIGUSR2, handle_signal);
    signal(SIGTERM, handle_signal);
    signal(SIGINT, handle_signal);

    struct timespec delay;
    delay.tv_sec = 0;
    delay.tv_nsec = SAMPLE_DELAY * 1000;

    while (running) {
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);

        if (now.tv_sec * 1000000 + now.tv_nsec < now.tv_sec * 1000000 + delay.tv_sec * 1000000 + delay.tv_nsec) {
            continue;
        }

        uint16_t data[SPI_WORD_SIZE];
        int bytes_read = spiXfer(spiHandle, data, SPI_WORD_SIZE, SPI_WORD_FORMAT);
        if (bytes_read < 0) {
            fprintf(stderr, "SPI error: %d\n", bytes_read);
            continue;
        }

        if (data[0] & 0x80) {
            fprintf(stderr, "Invalid data received\n");
            continue;
        }

        uint16_t gyro_x = (data[X_GYRO] << 8) | data[X_GYRO + 1];
        uint16_t gyro_y = (data[Y_GYRO] << 8) | data[Y_GYRO + 1];
        uint16_t gyro_z = (data[Z_GYRO] << 8) | data[Z_GYRO + 1];
        uint16_t accel_x = (data[X_ACCEL] << 8) | data[X_ACCEL + 1];
        uint16_t accel_y = (data[Y_ACCEL] << 8) | data[Y_ACCEL + 1];
        uint16_t accel_z = (data[Z_ACCEL] << 8) | data[Z_ACCEL + 1];

        double gyro_x_deg_per_sec = gyro_x * 0.005;
        double gyro_y_deg_per_sec = gyro_y * 0.005;
        double gyro_z_deg_per_sec = gyro_z * 0.005;
        double accel_x_g = accel_x * 0.00025;
        double accel_y_g = accel_y * 0.00025;
        double accel_z_g = accel_z * 0.00025;

        char timestamp[20];
        snprintf(timestamp, sizeof(timestamp), "%.3f", now.tv_sec + now.tv_nsec / 1000000000.0);

        fprintf(fp, "%s,%f,%f,%f,%f,%f,%f\n", timestamp, gyro_x_deg_per_sec, gyro_y_deg_per_sec, gyro_z_deg_per_sec, accel_x_g, accel_y_g, accel_z_g);

        nanosleep(&delay, NULL);
    }

    cleanup();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/sigaction.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spi0.0"
#define SPI_CS_PIN 8
#define SPI_MODE 3
#define SPI_SPEED 1000000
#define SPI_BYTES_PER_TRANSFER 2
#define SPI_TRANSFER_SIZE (SPI_BYTES_PER_TRANSFER * SPI_BYTES_PER_TRANSFER)

typedef struct {
    int spi_fd;
    int cs_fd;
} SpiAdaptor;

SpiAdaptor spiAdaptor;

void sigintHandler(int sig) {
    if (spiAdaptor.spi_fd > 0) {
        close(spiAdaptor.spi_fd);
    }
    if (spiAdaptor.cs_fd > 0) {
        close(spiAdaptor.cs_fd);
    }
    exit(EXIT_SUCCESS);
}

int spiInit() {
    int ret;

    // Open SPI device
    spiAdaptor.spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spiAdaptor.spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    // Open CS GPIO line
    spiAdaptor.cs_fd = open("/dev/gpiod/major:138", O_RDWR);
    if (spiAdaptor.cs_fd < 0) {
        perror("Failed to open CS GPIO line");
        close(spiAdaptor.spi_fd);
        return -1;
    }

    // Set CS pin to output
    ret = ioctl(spiAdaptor.cs_fd, SPI_IOC_MODE, SPI_IOC_MODE_WRITE);
    if (ret < 0) {
        perror("Failed to set CS pin to output");
        close(spiAdaptor.cs_fd);
        close(spiAdaptor.spi_fd);
        return -1;
    }

    // Set SPI mode
    ret = ioctl(spiAdaptor.spi_fd, SPI_IOC_SET_MODE, SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(spiAdaptor.cs_fd);
        close(spiAdaptor.spi_fd);
        return -1;
    }

    // Set SPI speed
    ret = ioctl(spiAdaptor.spi_fd, SPI_IOC_SET_SPEED, SPI_SPEED);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        close(spiAdaptor.cs_fd);
        close(spiAdaptor.spi_fd);
        return -1;
    }

    // Set SPI bits per byte
    ret = ioctl(spiAdaptor.spi_fd, SPI_IOC_SET_BITS_PER_BYTE, SPI_BYTES_PER_TRANSFER);
    if (ret < 0) {
        perror("Failed to set SPI bits per byte");
        close(spiAdaptor.cs_fd);
        close(spiAdaptor.spi_fd);
        return -1;
    }

    return 0;
}

int spiTransfer(int cs, uint16_t address, uint16_t *data) {
    int ret;

    // Set CS pin to low
    ret = ioctl(spiAdaptor.cs_fd, SPI_IOC_MODE, SPI_IOC_MODE_WRITE);
    if (ret < 0) {
        perror("Failed to set CS pin to low");
        return -1;
    }
    ret = ioctl(spiAdaptor.cs_fd, SPI_IOC_SET_VALUE, cs);
    if (ret < 0) {
        perror("Failed to set CS pin to low");
        return -1;
    }

    // Send address
    ret = ioctl(spiAdaptor.spi_fd, SPI_IOC_TRANSFER, address);
    if (ret < 0) {
        perror("Failed to send address");
        return -1;
    }

    // Read data
    ret = ioctl(spiAdaptor.spi_fd, SPI_IOC_TRANSFER, data);
    if (ret < 0) {
        perror("Failed to read data");
        return -1;
    }

    return 0;
}

int main() {
    int ret;
    uint16_t data[3];
    uint16_t scale = 0x8000;

    signal(SIGINT, sigintHandler);

    if (spiInit() < 0) {
        return EXIT_FAILURE;
    }

    while (1) {
        // Read gyroscope data
        ret = spiTransfer(spiAdaptor.cs_fd, 0x04, &data[0]);
        if (ret < 0) {
            perror("Failed to read gyroscope data");
            continue;
        }
        printf("Gyroscope X: %.2f dps\n", (float)(data[0] & 0x7F) * 0.02);

        // Read accelerometer data
        ret = spiTransfer(spiAdaptor.cs_fd, 0x0A, &data[1]);
        if (ret < 0) {
            perror("Failed to read accelerometer data");
            continue;
        }
        printf("Accelerometer X: %.2f g\n", (float)(data[1] & 0x7F) * 0.00025);

        // Read gyroscope data
        ret = spiTransfer(spiAdaptor.cs_fd, 0x06, &data[2]);
        if (ret < 0) {
            perror("Failed to read gyroscope data");
            continue;
        }
        printf("Gyroscope Y: %.2f dps\n", (float)(data[2] & 0x7F) * 0.02);

        // Read accelerometer data
        ret = spiTransfer(spiAdaptor.cs_fd, 0x0C, &data[3]);
        if (ret < 0) {
            perror("Failed to read accelerometer data");
            continue;
        }
        printf("Accelerometer Y: %.2f g\n", (float)(data[3] & 0x7F) * 0.00025);

        // Read gyroscope data
        ret = spiTransfer(spiAdaptor.cs_fd, 0x08, &data[4]);
        if (ret < 0) {
            perror("Failed to read gyroscope data");
            continue;
        }
        printf("Gyroscope Z: %.2f dps\n", (float)(data[4] & 0x7F) * 0.02);

        // Read accelerometer data
        ret = spiTransfer(spiAdaptor.cs_fd, 0x0E, &data[5]);
        if (ret < 0) {
            perror("Failed to read accelerometer data");
            continue;
        }
        printf("Accelerometer Z: %.2f g\n", (float)(data[5] & 0x7F) * 0.00025);

        // Log data every 100 ms
        sleep(0.1);

        // Clear the console
        system("clear");
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_FREQ 1000000
#define SPI_MODE 0
#define SPI_CS 8
#define SPI_READ_CMD 0x8000

#define X_GYRO_OUT 0x04
#define Y_GYRO_OUT 0x06
#define Z_GYRO_OUT 0x08
#define X_ACCL_OUT 0x0A
#define Y_ACCL_OUT 0x0C
#define Z_ACCL_OUT 0x0E

#define GYRO_SCALE 0.05
#define ACCEL_SCALE 0.00025

#define SPI_TRANSFER_SIZE 2
#define SPI_TRANSFER_TIMEOUT 1000000

void handle_spi_transfer_error(int error) {
    printf("SPI transfer error: %d\n", error);
    gpioTerminate();
    exit(EXIT_FAILURE);
}

void handle_spi_open_error(int error) {
    printf("SPI open error: %d\n", error);
    gpioTerminate();
    exit(EXIT_FAILURE);
}

void handle_spi_close_error(int error) {
    printf("SPI close error: %d\n", error);
    gpioTerminate();
    exit(EXIT_FAILURE);
}

int main() {
    if (gpioInitialise() < 0) {
        printf("pigpio initialization failed\n");
        return 1;
    }

    int spi_fd = -1;
    int spi_transfer_result = 0;
    int spi_transfer_timeout = 0;

    if ((spi_fd = spiOpen(SPI_CHANNEL, SPI_FREQ, SPI_MODE, SPI_CS)) < 0) {
        handle_spi_open_error(spi_fd);
    }

    while (1) {
        if (spiTransfer(spi_fd, SPI_READ_CMD, SPI_TRANSFER_SIZE, &spi_transfer_result) < 0) {
            handle_spi_transfer_error(spi_transfer_result);
        }

        if (spiTransfer(spi_fd, 0x0000, SPI_TRANSFER_SIZE, &spi_transfer_result) < 0) {
            handle_spi_transfer_error(spi_transfer_result);
        }

        int x_gyro = 0;
        int y_gyro = 0;
        int z_gyro = 0;
        int x_accl = 0;
        int y_accl = 0;
        int z_accl = 0;

        if (spiTransfer(spi_fd, X_GYRO_OUT, SPI_TRANSFER_SIZE, &x_gyro) < 0) {
            handle_spi_transfer_error(spi_transfer_result);
        }

        if (spiTransfer(spi_fd, Y_GYRO_OUT, SPI_TRANSFER_SIZE, &y_gyro) < 0) {
            handle_spi_transfer_error(spi_transfer_result);
        }

        if (spiTransfer(spi_fd, Z_GYRO_OUT, SPI_TRANSFER_SIZE, &z_gyro) < 0) {
            handle_spi_transfer_error(spi_transfer_result);
        }

        if (spiTransfer(spi_fd, X_ACCL_OUT, SPI_TRANSFER_SIZE, &x_accl) < 0) {
            handle_spi_transfer_error(spi_transfer_result);
        }

        if (spiTransfer(spi_fd, Y_ACCL_OUT, SPI_TRANSFER_SIZE, &y_accl) < 0) {
            handle_spi_transfer_error(spi_transfer_result);
        }

        if (spiTransfer(spi_fd, Z_ACCL_OUT, SPI_TRANSFER_SIZE, &z_accl) < 0) {
            handle_spi_transfer_error(spi_transfer_result);
        }

        double gyro_x = (double)x_gyro * GYRO_SCALE;
        double gyro_y = (double)y_gyro * GYRO_SCALE;
        double gyro_z = (double)z_gyro * GYRO_SCALE;

        double accl_x = (double)x_accl * ACCEL_SCALE;
        double accl_y = (double)y_accl * ACCEL_SCALE;
        double accl_z = (double)z_accl * ACCEL_SCALE;

        printf("%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n", gyro_x, gyro_y, gyro_z, accl_x, accl_y, accl_z);

        if (wait(100) < 0) {
            handle_spi_close_error(spi_fd);
        }
    }

    spiClose(spi_fd);
    gpioTerminate();
    return 0;
}

