}

void i2c_read(int reg_start, int reg_count, int *data) {
    int retries = 0;
    int reg_end = reg_start + reg_count * reg_size;
    int i;
    for (i = 0; i < reg_count; i++) {
        data[i] = 0;
        while (retries < MAX_RETRIES) {
            if (read(i2c_fd, &data[i], reg_size) < 0) {
                if (errno == EAGAIN || errno == EIO) {
                    retries++;
                    usleep(I2C_TIMEOUT);
                } else {
                    perror("Failed to read from I2C");
                    exit(EXIT_FAILURE);
                }
            } else {
                break;
            }
        }
        if (retries >= MAX_RETRIES) {
            perror("Failed to read from I2C after retries");
            exit(EXIT_FAILURE);
        }
    }
}

void i2c_write(int reg_start, int reg_count, int *data) {
    int retries = 0;
    int reg_end = reg_start + reg_count * reg_size;
    int i;
    for (i = 0; i < reg_count; i++) {
        while (retries < MAX_RETRIES) {
            if (write(i2c_fd, &data[i], reg_size) < 0) {
                if (errno == EAGAIN || errno == EIO) {
                    retries++;
                    usleep(I2C_TIMEOUT);
                } else {
                    perror("Failed to write to I2C");
                    exit(EXIT_FAILURE);
                }
            } else {
                break;
            }
        }
        if (retries >= MAX_RETRIES) {
            perror("Failed to write to I2C after retries");
            exit(EXIT_FAILURE);
        }
    }
}

int main() {
    i2c_init();
    int accel_data[ACCEL_REG_COUNT];
    int gyro_data[GYRO_REG_COUNT];
    int who_am_i;
    int i;

    // Verify sensor presence
    i2c_read(WHO_AM_I, 1, &who_am_i);
    if (who_am_i != 0x86) {
        printf("Sensor not present\n");
        i2c_close();
        exit(EXIT_FAILURE);
    }

    // Initialize sensor
    i2c_write(ACCEL_CONFIG, ACCEL_REG_COUNT, &ACCEL_CONFIG_VALUE);
    i2c_write(GYRO_CONFIG, GYRO_REG_COUNT, &GYRO_CONFIG_VALUE);

    // Wake up sensor
    i2c_write(ACCEL_CONFIG, 1, &0x01);

    printf("Sensor initialized\n");

    while (1) {
        i2c_read(ACCEL_REG_START, ACCEL_REG_COUNT, accel_data);
        i2c_read(GYRO_REG_START, GYRO_REG_COUNT, gyro_data);

        for (i = 0; i < ACCEL_REG_COUNT; i++) {
            int raw = accel_data[i];
            int sign = (raw & GYRO_REG_SIGN) ? -1 : 1;
            int scale = (raw & GYRO_REG_SCALE) ? 2 : 1;
            int offset = (raw & GYRO_REG_OFFSET_MASK) >> GYRO_REG_OFFSET_MASK_VALUE;
            int offset2 = (raw & GYRO_REG_OFFSET_MASK) >> GYRO_REG_OFFSET_MASK_VALUE_2;
            int offset3 = (raw & GYRO_REG_OFFSET_MASK) >> GYRO_REG_OFFSET_MASK_VALUE_3;
            int offset4 = (raw & GYRO_REG_OFFSET_MASK) >> GYRO_REG_OFFSET_MASK_VALUE_4;
            int offset5 = (raw & GYRO_REG_OFFSET_MASK) >> GYRO_REG_OFFSET_MASK_VALUE_5;
            int offset6 = (raw & GYRO_REG_OFFSET_MASK) >> GYRO_REG_OFFSET_MASK_VALUE_6;
            int offset7 = (raw & GYRO_REG_OFFSET_MASK) >> GYRO_REG_OFFSET_MASK_VALUE_7;
            int offset8 = (raw & GYRO_REG_OFFSET_MASK) >> GYRO_REG_OFFSET_MASK_VALUE_8;
            int raw_scaled = (raw - offset) * scale;
            int scaled = sign * raw_scaled + offset2;
            printf("Accel X: %d\n", scaled);
            printf("Accel Y: %d\n", scaled);
            printf("Accel Z: %d\n", scaled);
        }

        for (i = 0; i < GYRO_REG_COUNT; i++) {
            int raw = gyro_data[i];
            int sign = (raw & GYRO_REG_SIGN) ? -1 : 1;
            int scale = (raw & GYRO_REG_SCALE) ? 2 : 1;
            int offset = (raw & GYRO_REG_OFFSET_MASK) >> GYRO_REG_OFFSET_MASK_VALUE;
            int offset2 = (raw & GYRO_REG_OFFSET_MASK) >> GYRO_REG_OFFSET_MASK_VALUE_2;
            int offset3 = (raw & GYRO_REG_OFFSET_MASK) >> GYRO_REG_OFFSET_MASK_VALUE_3;
            int offset4 = (raw & GYRO_REG_OFFSET_MASK) >> GYRO_REG_OFFSET_MASK_VALUE_4;
            int offset5 = (raw & GYRO_REG_OFFSET_MASK) >> GYRO_REG_OFFSET_MASK_VALUE_5;
            int offset6 = (raw & GYRO_REG_OFFSET_MASK) >> GYRO_REG_OFFSET_MASK_VALUE_6;
            int offset7 = (raw & GYRO_REG_OFFSET_MASK) >> GYRO_REG_OFFSET_MASK_VALUE_7;
            int offset8 = (raw & GYRO_REG_OFFSET_MASK) >> GYRO_REG_OFFSET_MASK_VALUE_8;
            int raw_scaled = (raw - offset) * scale;
            int scaled = sign * raw_scaled + offset2;
            printf("Gyro X: %d\n", scaled);
            printf("Gyro Y: %d\n", scaled);
            printf("Gyro Z: %d\n", scaled);
        }

        usleep(500000); // 50 ms
    }

    i2c_close();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x53
#define ADXL345_ID 0xE5
#define LED_PIN 17
#define POLL_INTERVAL 10
#define IMPACT_THRESHOLD 2.5
#define SCALE_FACTOR 256

int i2c_fd;
int led_fd;
int log_fd;
int sensor_present = 0;
int bus_error = 0;
int sigint_received = 0;

void handle_sigint() {
    if (sigint_received) {
        printf("Caught SIGINT, exiting...\n");
        exit(0);
    }
    sigint_received = 1;
}

void handle_error(int error_code) {
    if (error_code) {
        printf("I2C error: %d\n", error_code);
        bus_error = 1;
    }
}

void handle_sensor_absent() {
    printf("Sensor not found, exiting...\n");
    exit(0);
}

void handle_bus_error() {
    printf("Bus error occurred, exiting...\n");
    exit(0);
}

void read_sensor_data() {
    int data[6];
    int i;
    int reg = 0x00;
    int reg_count = 1;
    int reg_data;

    if (ioctl(i2c_fd, I2C_RDWR, &reg) < 0) {
        handle_error(ioctl(i2c_fd, I2C_RDWR, &reg));
        return;
    }

    if (read(i2c_fd, &reg_data, 1) < 0) {
        handle_error(read(i2c_fd, &reg_data, 1));
        return;
    }

    if (reg_data != ADXL345_ID) {
        handle_sensor_absent();
        return;
    }

    for (i = 0; i < reg_count; i++) {
        if (ioctl(i2c_fd, I2C_RDMSB, reg + i) < 0) {
            handle_error(ioctl(i2c_fd, I2C_RDMSB, reg + i));
            return;
        }

        if (read(i2c_fd, &data[i], 1) < 0) {
            handle_error(read(i2c_fd, &data[i], 1));
            return;
        }
    }

    int x = data[1] * SCALE_FACTOR / 256.0;
    int y = data[2] * SCALE_FACTOR / 256.0;
    int z = data[3] * SCALE_FACTOR / 256.0;

    double magnitude = sqrt(x * x + y * y + z * z);

    if (magnitude > IMPACT_THRESHOLD) {
        printf("Impact detected! Magnitude: %.2f g\n", magnitude);
        gpioWrite(led_fd, 1);
        sleep(500);
        gpioWrite(led_fd, 0);

        char timestamp[100];
        struct tm *now;
        time_t t;
        t = time(NULL);
        now = localtime(&t);
        strftime(timestamp, 100, "%Y-%m-%d %H:%M:%S", now);

        char log_entry[200];
        snprintf(log_entry, 200, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);

        if (write(log_fd, log_entry, strlen(log_entry)) < 0) {
            handle_error(write(log_fd, log_entry, strlen(log_entry)));
        }
    }
}

void init_i2c() {
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(1);
    }

    sensor_present = 1;
}

void init_gpio() {
    if ((led_fd = gpioOpen(LED_PIN)) < 0) {
        perror("Failed to open GPIO");
        exit(1);
    }

    if (gpioSetMode(led_fd, PI_OUTPUT) < 0) {
        perror("Failed to set GPIO mode");
        exit(1);
    }

    if (gpioSetPullUp(led_fd, 0) < 0) {
        perror("Failed to set GPIO pull-up");
        exit(1);
    }

    if (gpioSetPullDown(led_fd, 0) < 0) {
        perror("Failed to set GPIO pull-down");
        exit(1);
    }
}

void init_pigpio() {
    if (pigpio Haram()) {
        perror("Failed to initialize pigpio");
        exit(1);
    }
}

void cleanup() {
    if (sensor_present) {
        close(i2c_fd);
    }

    if (led_fd >= 0) {
        gpioClose(led_fd);
    }

    if (log_fd >= 0) {
        close(log_fd);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    if (pigpio Haram()) {
        pigpio Haram();
    }
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    init_pigpio();
    init_i2c();
    init_gpio();

    while (!sigint_received) {
        read_sensor_data();
        usleep(POLL_INTERVAL * 1000000);
    }

    cleanup();

    return 0;
}

