#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1D
#define WHO_AM_I 0x0D
#define LED_PIN 17
#define THRESHOLD 2.0
#define LED_ON_TIME 500000  // 500 ms in microseconds

int i2c_fd;
int led_fd;

void i2c_read(int fd, uint8_t *buf, size_t size) {
    if (ioctl(fd, I2C_RDWR, buf, size) < 0) {
        perror("I2C read failed");
        return;
    }
}

void i2c_write(int fd, uint8_t *buf, size_t size) {
    if (ioctl(fd, I2C_RDWR, buf, size) < 0) {
        perror("I2C write failed");
        return;
    }
}

void i2c_init() {
    if ((i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return;
    }

    uint8_t who_am_i = 0;
    i2c_read(i2c_fd, &who_am_i, 1);
    if (who_am_i != 0x1A) {
        fprintf(stderr, "Sensor identity mismatch\n");
        return;
    }
}

void i2c_poll() {
    uint8_t buf[1];
    while (1) {
        i2c_read(i2c_fd, buf, 1);
        int x = (buf[0] & 0x07) * 256;
        int y = (buf[0] >> 3) * 256;
        int z = (buf[0] >> 6) * 256;

        if (x > THRESHOLD || y > THRESHOLD || z > THRESHOLD) {
            led_fd = open("/sys/class/leds/led0/brightness", O_WRONLY);
            if (led_fd < 0) {
                perror("Failed to open LED");
                continue;
            }
            write(led_fd, "1", 1);
            close(led_fd);

            FILE *log = fopen("impact_log.txt", "a");
            if (!log) {
                perror("Failed to open log file");
                continue;
            }
            fprintf(log, "%ld\n", (long int) time(NULL));
            fclose(log);
        }

        usleep(100000); // 100 ms
    }
}

void i2c_cleanup() {
    close(i2c_fd);
    close(led_fd);
}

int main() {
    i2c_init();
    i2c_poll();

    signal(SIGINT, i2c_cleanup);
    signal(SIGTERM, i2c_cleanup);

    return 0;
}

#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>

#define I2C_DEV "/dev/i2c-" I2C_BUS
#define I2C_BUS 1
#define I2C_ADDR 0x35
#define I2C_REG_X 0x10
#define I2C_REG_Y 0x11
#define I2C_REG_Z 0x12
#define I2C_REG_STATUS 0x13
#define I2C_REG_CONTROL 0x14

#define I2C_READ 0x3
#define I2C_WRITE 0x4

#define I2C_REG_SIZE 2
#define I2C_DATA_SIZE 4

#define CSV_HEADER "timestamp,X,Y,Z"
#define CSV_FILE "magnetic_field_log.csv"

void i2c_read(int fd, int reg, void *buf, size_t size) {
    ssize_t bytes_read;
    if ((bytes_read = ioctl(fd, I2C_READ, reg)) < 0) {
        perror("ioctl");
        return;
    }
    if (bytes_read < size) {
        fprintf(stderr, "I2C read failed: %d bytes read, expected %d\n", bytes_read, size);
        return;
    }
    memcpy(buf, buf + size - bytes_read, bytes_read);
}

void i2c_write(int fd, int reg, void *buf, size_t size) {
    ssize_t bytes_written;
    if ((bytes_written = ioctl(fd, I2C_WRITE, reg)) < 0) {
        perror("ioctl");
        return;
    }
    if (bytes_written < size) {
        fprintf(stderr, "I2C write failed: %d bytes written, expected %d\n", bytes_written, size);
        return;
    }
    memcpy(buf, buf + size - bytes_written, bytes_written);
}

int main() {
    int i2c_fd;
    struct stat st;
    char buffer[I2C_DATA_SIZE];
    char timestamp[20];
    FILE *csv_file;

    if ((i2c_fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("open");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl");
        close(i2c_fd);
        return 1;
    }

    if (fstat(i2c_fd, &st) < 0) {
        perror("fstat");
        close(i2c_fd);
        return 1;
    }

    if (fopen_csv(csv_file, CSV_FILE) < 0) {
        perror("fopen");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(NULL)) < 0) {
            perror("strftime");
            continue;
        }

        if (i2c_read(i2c_fd, I2C_REG_X, buffer, I2C_REG_SIZE) < 0) {
            continue;
        }
        if (i2c_read(i2c_fd, I2C_REG_Y, buffer + I2C_REG_SIZE, I2C_REG_SIZE) < 0) {
            continue;
        }
        if (i2c_read(i2c_fd, I2C_REG_Z, buffer + 2 * I2C_REG_SIZE, I2C_REG_SIZE) < 0) {
            continue;
        }

        fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, *(int *)buffer, *(int *)(buffer + I2C_REG_SIZE), *(int *)(buffer + 2 * I2C_REG_SIZE));

        if (i2c_read(i2c_fd, I2C_REG_STATUS, buffer, I2C_REG_SIZE) < 0) {
            fprintf(stderr, "I2C status read failed\n");
            continue;
        }
        if (*(int *)buffer & 0x01) {
            fprintf(stderr, "I2C error: %d\n", *(int *)buffer);
            continue;
        }

        if (sleep(1) < 0) {
            perror("sleep");
            continue;
        }
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        pause();
    }

    return 0;

    void handle_signal(int signum) {
        if (signum == SIGINT || signum == SIGTERM) {
            if (i2c_fd != -1) {
                close(i2c_fd);
            }
            if (csv_file != NULL) {
                fclose(csv_file);
            }
            fprintf(stderr, "Caught signal %d, exiting...\n", signum);
            exit(0);
        }
    }

    int fopen_csv(FILE *file, const char *filename) {
        if (access(filename, F_OK) == -1) {
            if (mkdir(filename, 0777) == -1) {
                perror("mkdir");
                return -1;
            }
            if (fopen(filename, "w") < 0) {
                perror("fopen");
                return -1;
            }
        } else {
            if (fopen(filename, "a") < 0) {
                perror("fopen");
                return -1;
            }
        }
        file = fopen(filename, "a");
        return file;
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <gpiod.h>
#include <errno.h>
#include <time.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x53
#define GPIO_INT_PIN 17
#define INT_MAP 0x00
#define INT_ENABLE 0x2E
#define THRESH_FF 0x0A
#define TIME_FF 0x20
#define POWER_CTL 0x2D
#define DATAX0 0x32
#define INT_SOURCE 0x30

#define LOG_FILE "freefall_log.csv"
#define LOG_HEADER "timestamp,X,Y,Z\n"

int i2c_fd;
int gpio_fd;
gpiod_chip_t *chip;
gpiod_line_mfd_t *line;
gpiod_line_t *int_line;
gpiod_event_t *event;
struct timespec ts;
char buffer[6];

void init_i2c() {
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }
}

void init_gpio() {
    chip = gpiod_chip_open("/dev/gpiod");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }
    line = gpiod_chip_new(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to create GPIO line");
        exit(EXIT_FAILURE);
    }
    int_line = gpiod_chip_get_line(chip, line, GPIO_LINE_INT);
    if (!int_line) {
        perror("Failed to get GPIO line");
        exit(EXIT_FAILURE);
    }
    gpio_fd = gpiod_line_request_fd(int_line);
    if (gpio_fd < 0) {
        perror("Failed to request GPIO line");
        exit(EXIT_FAILURE);
    }
    event = gpiod_line_request_event(int_line, GPIO_LINE_INT);
    if (!event) {
        perror("Failed to request GPIO event");
        exit(EXIT_FAILURE);
    }
    gpiod_line_enable(int_line, GPIO_LINE_INT);
    gpiod_event_enable(event, GPIO_LINE_INT);
}

void read_i2c(int reg) {
    ssize_t bytes_read;
    if ((bytes_read = i2c_read(i2c_fd, reg, 1, buffer)) < 0) {
        perror("Failed to read I2C register");
        exit(EXIT_FAILURE);
    }
    return;
}

void write_i2c(int reg, uint8_t *data, int len) {
    ssize_t bytes_written;
    if ((bytes_written = i2c_write(i2c_fd, reg, data, len)) < 0) {
        perror("Failed to write I2C register");
        exit(EXIT_FAILURE);
    }
    return;
}

void log_data(const char *format, ...) {
    va_list args;
    va_start(args, format);
    vfprintf(stderr, format, args);
    va_end(args);
}

void handle_event(int fd, gpiod_event_t *event) {
    if (gpiod_event_poll(event, 0) < 0) {
        perror("Failed to poll event");
        exit(EXIT_FAILURE);
    }
    read_i2c(INT_SOURCE);
    if (buffer[0] & 0x04) {
        read_i2c(DATAX0);
        if (buffer[0] == 0xE5) {
            write_i2c(THRESH_FF, &0x1F, 1);
            write_i2c(TIME_FF, &0x3F, 1);
            write_i2c(POWER_CTL, &0x08, 1);
            write_i2c(INT_ENABLE, &0x04, 1);
            write_i2c(INT_MAP, &0x00, 1);
            write_i2c(0x00, &0xE5, 1);
            char timestamp[20];
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S.", tm);
            sprintf(buffer, "%s%.3f", timestamp, (double)clock() / CLOCKS_PER_SEC);
            FILE *log = fopen(LOG_FILE, "a");
            if (!log) {
                perror("Failed to open log file");
                exit(EXIT_FAILURE);
            }
            fprintf(log, "%s,%d,%d,%d\n", buffer, buffer[1], buffer[2], buffer[3]);
            fflush(log);
        } else {
            log_data("Sensor ID mismatch, exiting\n");
            exit(EXIT_FAILURE);
        }
    } else {
        log_data("Non-freefall interrupt, ignoring\n");
    }
}

void cleanup() {
    if (gpio_fd >= 0) {
        gpiod_line_release(int_line, GPIO_LINE_INT);
        gpiod_chip_release(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (gpio_fd >= 0) {
        close(gpio_fd);
    }
    if (event) {
        gpiod_event_release(event);
    }
    if (line) {
        gpiod_line_release(line, GPIO_LINE);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (fopen(LOG_FILE, "r") != NULL) {
        fclose(fopen(LOG_FILE, "w"));
    }
}

int main() {
    init_i2c();
    read_i2c(0x00);
    if (buffer[0] != 0xE5) {
        log_data("Sensor ID mismatch, exiting\n");
        exit(EXIT_FAILURE);
    }
    init_gpio();
    while (1) {
        handle_event(gpio_fd, event);
    }
    cleanup();
    return 0;
}

