#define I2C_WRITE_ACCEL_CONFIG 0x01

#define I2C_ACCEL_DATA_SIZE 6
#define I2C_ACCEL_DATA_SIZE_BYTES (I2C_ACCEL_DATA_SIZE * 2)

#define TIMESTAMP_FORMAT "%Y-%m-%d %H:%M:%S.%06d"

void i2c_open(int *fd) {
    *fd = open(I2C_BUS, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
}

void i2c_close(int fd) {
    close(fd);
}

void i2c_read(int fd, uint8_t *buf, size_t size) {
    if (read(fd, buf, size) < 0) {
        perror("Failed to read from I2C device");
        exit(EXIT_FAILURE);
    }
}

void i2c_write(int fd, uint8_t *buf, size_t size) {
    if (write(fd, buf, size) < 0) {
        perror("Failed to write to I2C device");
        exit(EXIT_FAILURE);
    }
}

void i2c_read_accel(int fd, uint8_t *buf) {
    i2c_write(fd, &I2C_WRITE_ACCEL_REG, 1);
    i2c_read(fd, buf, I2C_ACCEL_DATA_SIZE_BYTES);
}

