#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <time.h>

#define GPIO17 17
#define GPIO27 27
#define LOG_FILE "conveyor_log.txt"
#define LOG_FORMAT "%ld,%ld,%ld\n"

typedef struct {
    int gpio;
    int direction;
    int bias;
    int pull;
    int edge;
    int edge_dir;
} gpio_request_t;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        gpiod_close_all();
        exit(EXIT_SUCCESS);
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    struct timespec ts;
    char buffer[256];
    FILE *log_file;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if ((chip = gpiod_chip_open("/dev/gpiod")) == NULL) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }

    if ((line = gpiod_chip_request_line(chip, GPIO17, GPIOD_LINE_DIR_IN, GPIOD_LINE_BIAS_PULL_UP)) == NULL) {
        perror("gpiod_chip_request_line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if ((edge = gpiod_line_request_edge(line, GPIOD_EDGE_EDGE_RISING)) == NULL) {
        perror("gpiod_line_request_edge");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if ((line = gpiod_chip_request_line(chip, GPIO27, GPIOD_LINE_DIR_IN, GPIOD_LINE_BIAS_PULL_UP)) == NULL) {
        perror("gpiod_chip_request_line");
        gpiod_line_free(line);
        gpiod_line_free(edge);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if ((edge = gpiod_line_request_edge(line, GPIOD_EDGE_EDGE_RISING)) == NULL) {
        perror("gpiod_line_request_edge");
        gpiod_line_free(line);
        gpiod_line_free(edge);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        gpiod_line_free(edge);
        gpiod_line_free(edge);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        long long timestamp = ts.tv_sec * 1000 + ts.tv_nsec / 1000000;

        if (gpiod_line_get_value(line) == 1) {
            if (gpiod_edge_get_edge(edge) == 1) {
                printf("Both sensors triggered. Halting conveyor.\n");
            }
        }

        if (fprintf(log_file, LOG_FORMAT, timestamp, gpiod_line_get_value(line), gpiod_edge_get_edge(edge)) < 0) {
            perror("fprintf");
            gpiod_line_free(edge);
            gpiod_line_free(edge);
            gpiod_chip_close(chip);
            fclose(log_file);
            exit(EXIT_FAILURE);
        }

        if (ferror(log_file)) {
            perror("ferror");
            gpiod_line_free(edge);
            gpiod_line_free(edge);
            gpiod_chip_close(chip);
            fclose(log_file);
            exit(EXIT_FAILURE);
        }

        if (fprintf(log_file, "\n") < 0) {
            perror("fprintf");
            gpiod_line_free(edge);
            gpiod_line_free(edge);
            gpiod_chip_close(chip);
            fclose(log_file);
            exit(EXIT_FAILURE);
        }

        if (ferror(log_file)) {
            perror("ferror");
            gpiod_line_free(edge);
            gpiod_line_free(edge);
            gpiod_chip_close(chip);
            fclose(log_file);
            exit(EXIT_FAILURE);
        }

        if (sleep(50) == -1) {
            perror("sleep");
            gpiod_line_free(edge);
            gpiod_line_free(edge);
            gpiod_chip_close(chip);
            fclose(log_file);
            exit(EXIT_FAILURE);
        }

        if (gpiod_line_get_value(line) == 1) {
            if (gpiod_edge_get_edge(edge) == 1) {
                printf("Both sensors triggered. Halting conveyor.\n");
            }
        }
    }

    gpiod_line_free(edge);
    gpiod_line_free(edge);
    gpiod_chip_close(chip);
    fclose(log_file);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x1D
#define WHO_AM_I 0x0D
#define CTRL_REG1 0x2A
#define DATA_REG 0x01

int main() {
    int fd;
    struct i2c_msg msg[1];
    struct i2c_rdwr_ioctl_msg ioctl_msg;
    char buf[6];
    int x, y, z;
    double angle;
    char *log_file = "fall_log.txt";
    FILE *log = NULL;
    int exit_code = 0;

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open");
        exit_code = 1;
        goto cleanup;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl");
        exit_code = 1;
        goto cleanup;
    }

    msg[0].addr = I2C_ADDR;
    msg[0].flags = I2C_M_RD;
    msg[0].data[0] = WHO_AM_I;
    if (read(fd, buf, 1, &msg[0].len) < 0) {
        perror("read");
        exit_code = 1;
        goto cleanup;
    }
    if (buf[0] != 0x2A) {
        fprintf(stderr, "Error: WHO_AM_I register does not match 0x2A\n");
        exit_code = 1;
        goto cleanup;
    }

    msg[0].addr = I2C_ADDR;
    msg[0].flags = I2C_M_RD;
    msg[0].data[0] = CTRL_REG1;
    if (ioctl(fd, I2C_RDWR, msg, &ioctl_msg) < 0) {
        perror("ioctl");
        exit_code = 1;
        goto cleanup;
    }
    if ((msg[0].data[0] & 0x01) == 0) {
        fprintf(stderr, "Error: CTRL_REG1 not in active mode\n");
        exit_code = 1;
        goto cleanup;
    }

    msg[0].addr = I2C_ADDR;
    msg[0].flags = I2C_M_RD;
    msg[0].data[0] = DATA_REG;
    if (read(fd, buf, 6, &msg[0].len) < 0) {
        perror("read");
        exit_code = 1;
        goto cleanup;
    }
    x = (buf[0] << 4) | buf[1];
    y = (buf[2] << 4) | buf[3];
    z = (buf[4] << 4) | buf[5];
    angle = atan2(x, sqrt(y * y + z * z));

    log = fopen(log_file, "a");
    if (!log) {
        perror("fopen");
        exit_code = 1;
        goto cleanup;
    }
    fprintf(log, "%f %d %d %d\n", angle, x, y, z);
    fflush(log);

    while (1) {
        msg[0].addr = I2C_ADDR;
        msg[0].flags = I2C_M_RD;
        msg[0].data[0] = DATA_REG;
        if (read(fd, buf, 6, &msg[0].len) < 0) {
            perror("read");
            exit_code = 1;
            goto cleanup;
        }
        x = (buf[0] << 4) | buf[1];
        y = (buf[2] << 4) | buf[3];
        z = (buf[4] << 4) | buf[5];
        angle = atan2(x, sqrt(y * y + z * z));

        if (fabs(angle) > M_PI / 4) {
            fprintf(log, "%f %d %d %d\n", angle, x, y, z);
            fflush(log);
        }

        usleep(1000000 / 100); // 10 ms delay
    }

cleanup:
    if (log) {
        fclose(log);
    }
    if (fd >= 0) {
        close(fd);
    }
    return exit_code;
}

#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x1E
#define WHO_AM_I 0x0F
#define XOUT 0x28
#define YOUT 0x29
#define ZOUT 0x2A
#define CTRL_REG1 0x70
#define CTRL_REG4 0x0C
#define CTRL_REG3 0x00
#define CAL_X 0.000146
#define CAL_Y 0.000146
#define CAL_Z 0.000146
#define THRESHOLD 800.0

int i2c_fd;

void handle_error(int err, const char *msg) {
    if (err) {
        perror(msg);
        exit(EXIT_FAILURE);
    }
}

void init_i2c() {
    if ((i2c_fd = open(I2C_DEV, O_RDWR)) < 0) {
        handle_error(errno, "open i2c device");
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        handle_error(errno, "set slave address");
    }
}

void init_sensor() {
    int retries = 0;
    while (retries < 3) {
        if (ioctl(i2c_fd, I2C_RDWR, 0) < 0) {
            handle_error(errno, "ioctl i2c");
        }
        if (ioctl(i2c_fd, I2C_SMBUS_WRITE, 0, &CTRL_REG1, 1, 0) < 0) {
            handle_error(errno, "write CTRL_REG1");
        }
        if (ioctl(i2c_fd, I2C_SMBUS_WRITE, 0, &CTRL_REG4, 1, 0) < 0) {
            handle_error(errno, "write CTRL_REG4");
        }
        if (ioctl(i2c_fd, I2C_SMBUS_WRITE, 0, &CTRL_REG3, 1, 0) < 0) {
            handle_error(errno, "write CTRL_REG3");
        }
        if (ioctl(i2c_fd, I2C_SMBUS_READ, 0, &WHO_AM_I, 1, 0) < 0) {
            handle_error(errno, "read WHO_AM_I");
        }
        if (memcmp(&WHO_AM_I, &0x3D, 1) == 0) {
            break;
        }
        retries++;
    }
    if (retries == 3) {
        fprintf(stderr, "Sensor not found after 3 retries\n");
        exit(EXIT_FAILURE);
    }
}

void read_sensor() {
    int x, y, z;
    while (1) {
        if (ioctl(i2c_fd, I2C_SMBUS_READ, 0, &XOUT, 1, 0) < 0) {
            handle_error(errno, "read XOUT");
        }
        if (ioctl(i2c_fd, I2C_SMBUS_READ, 0, &YOUT, 1, 0) < 0) {
            handle_error(errno, "read YOUT");
        }
        if (ioctl(i2c_fd, I2C_SMBUS_READ, 0, &ZOUT, 1, 0) < 0) {
            handle_error(errno, "read ZOUT");
        }
        x = (int)((*((unsigned char *) &XOUT) << 8) | *((unsigned char *) &XOUT));
        y = (int)((*((unsigned char *) &YOUT) << 8) | *((unsigned char *) &YOUT));
        z = (int)((*((unsigned char *) &ZOUT) << 8) | *((unsigned char *) &ZOUT));
        x *= CAL_X;
        y *= CAL_Y;
        z *= CAL_Z;
        double total = x + y + z;
        if (total > THRESHOLD) {
            fprintf(stderr, "Metal detected: %f mG\n", total);
        }
        char buf[100];
        sprintf(buf, "%f,%f,%f\n", x / CAL_X, y / CAL_Y, z / CAL_Z);
        write(STDERR, buf, strlen(buf));
        write(STDOUT, buf, strlen(buf));
        fflush(STDOUT);
    }
}

void cleanup() {
    if (i2c_fd > 0) {
        close(i2c_fd);
    }
}

void signal_handler(int sig) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    init_i2c();
    init_sensor();
    read_sensor();
    return 0;
}

