#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip4"
#define GPIO_LINE_NAME "gpio17"

int main() {
    int chip_fd, line_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    struct gpiod_event *event;
    struct timespec ts;
    char line_name[128];

    if (signal(SIGINT, [](int) {
        if (line) {
            gpiod_line_close(line);
        }
        if (chip) {
            gpiod_chip_close(chip);
        }
        printf("Exiting...\n");
        exit(0);
    })) == SIG_ERR {
        perror("signal");
        exit(EXIT_FAILURE);
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    line = gpiod_line_open(chip, GPIO_LINE_NAME);
    if (!line) {
        perror("gpiod_line_open");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(line)) {
        printf("Line %s requested as input\n", GPIO_LINE_NAME);
    } else {
        perror("gpiod_line_request_input");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_get_value(line)) {
        perror("gpiod_line_get_value");
        exit(EXIT_FAILURE);
    }

    while (1) {
        ts.tv_sec = 1;
        ts.tv_nsec = 0;
        nanosleep(&ts, NULL);

        if (gpiod_line_get_value(line)) {
            printf("Path clear\n");
        } else {
            printf("Obstacle detected\n");
            printf("Self-parking sequence started\n");
            sleep(2); // Simulated self-parking time
            printf("Self-parking completed\n");
        }
    }

    gpiod_chip_close(chip);
    gpiod_line_close(line);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <gpiod.h>
#include <unistd.h>

#define GPIO_CHIP 0
#define GPIO_LINE_1 17
#define GPIO_LINE_2 27
#define POLL_INTERVAL 100000  // 100 ms
#define LOG_FORMAT "%Y-%m-%d %H:%M:%S"

int main() {
    int line_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line1, *line2;
    struct gpiod_request *request1, *request2;
    struct gpiod_value *value1, *value2;
    struct timespec ts;
    char buffer[128];

    // Initialize the GPIO chip
    if ((chip = gpiod_chip_open(GPIO_CHIP)) == NULL) {
        perror("gpiod_chip_open");
        return 1;
    }

    // Request both lines
    if ((line1 = gpiod_chip_request_get(line1, GPIO_LINE_1, GPIOD_LINE_REQUEST_INPUT)) == NULL ||
        (line2 = gpiod_chip_request_get(line2, GPIO_LINE_2, GPIOD_LINE_REQUEST_INPUT)) == NULL) {
        gpiod_chip_close(chip);
        perror("gpiod_chip_request_get");
        return 1;
    }

    // Request values
    if ((request1 = gpiod_line_request_get_values(line1, GPIOD_LINE_REQUEST_VALUES)) == NULL ||
        (request2 = gpiod_line_request_get_values(line2, GPIOD_LINE_REQUEST_VALUES)) == NULL) {
        gpiod_chip_close(chip);
        gpiod_line_request_close(line1);
        gpiod_line_request_close(line2);
        perror("gpiod_line_request_get_values");
        return 1;
    }

    // Set polling interval
    if (gpiod_line_request_set_poll_interval(request1, POLL_INTERVAL) < 0 ||
        gpiod_line_request_set_poll_interval(request2, POLL_INTERVAL) < 0) {
        gpiod_chip_close(chip);
        gpiod_line_request_close(line1);
        gpiod_line_request_close(line2);
        perror("gpiod_line_request_set_poll_interval");
        return 1;
    }

    // Initialize timestamp
    clock_gettime(CLOCK_MONOTONIC, &ts);

    while (1) {
        // Read values
        if (gpiod_line_request_get_values(request1, value1) < 0 ||
            gpiod_line_request_get_values(request2, value2) < 0) {
            gpiod_chip_close(chip);
            gpiod_line_request_close(line1);
            gpiod_line_request_close(line2);
            perror("gpiod_line_request_get_values");
            return 1;
        }

        // Log status
        sprintf(buffer, "%s %d %d", ctime(&ts), value1->value, value2->value);

        // Check for obstacle
        if (value1->value == 0 || value2->value == 0) {
            printf("%s\n", buffer);
        }

        // Update timestamp
        clock_gettime(CLOCK_MONOTONIC, &ts);

        // Sleep for polling interval
        nanosleep(&ts, NULL);
    }

    // Cleanup
    gpiod_chip_close(chip);
    gpiod_line_request_close(line1);
    gpiod_line_request_close(line2);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <gpiod.h>
#include <sys/signal.h>

#define SPI0_CE0 8
#define SPI_MODE_3 3
#define MSB_FIRST 1
#define SPI_CLOCK_SPEED 1000000
#define X_REG 0x04
#define Y_REG 0x06
#define Z_REG 0x08
#define MSC_CTRL 0x24
#define SCALE_FACTOR 0.02

int spi_fd;
int spi_cs_fd;
struct gpiod_chip *chip;
struct gpiod_line *line;

void spi_init() {
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    line = gpiod_line_request(spi_cs_fd, SPI0_CE0, GPIOD_LINE_DIR_OUT);
    if (line == NULL) {
        perror("Failed to request SPI CS line");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_chip_open(line->dev) < 0) {
        perror("Failed to open SPI chip");
        close(spi_fd);
        gpiod_line_free(line);
        exit(EXIT_FAILURE);
    }

    struct gpiod_edge *edge;
    if ((edge = gpiod_edge_request(line->dev, GPIOD_EDGE_EDGE_NONE)) == NULL) {
        perror("Failed to request SPI chip edge");
        close(spi_fd);
        gpiod_chip_close(chip);
        gpiod_line_free(line);
        exit(EXIT_FAILURE);
    }

    if (gpiod_chip_request_edge(chip, edge) < 0) {
        perror("Failed to request SPI chip edge");
        close(spi_fd);
        gpiod_edge_free(edge);
        gpiod_chip_close(chip);
        gpiod_line_free(line);
        exit(EXIT_FAILURE);
    }

    if (gpiod_chip_enable(chip) < 0) {
        perror("Failed to enable SPI chip");
        close(spi_fd);
        gpiod_chip_close(chip);
        gpiod_edge_free(edge);
        gpiod_line_free(line);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MSC, MSC_CTRL) < 0) {
        perror("Failed to write MSC_CTRL register");
        close(spi_fd);
        gpiod_chip_close(chip);
        gpiod_edge_free(edge);
        gpiod_line_free(line);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_RD_DATA_READY, 0) < 0) {
        perror("Failed to read MSC_CTRL register");
        close(spi_fd);
        gpiod_chip_close(chip);
        gpiod_edge_free(edge);
        gpiod_line_free(line);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, SPI_MODE_3) < 0) {
        perror("Failed to write SPI mode");
        close(spi_fd);
        gpiod_chip_close(chip);
        gpiod_edge_free(edge);
        gpiod_line_free(line);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BIT_ORDER, MSB_FIRST) < 0) {
        perror("Failed to write bit order");
        close(spi_fd);
        gpiod_chip_close(chip);
        gpiod_edge_free(edge);
        gpiod_line_free(line);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_SPD, SPI_CLOCK_SPEED) < 0) {
        perror("Failed to write SPI clock speed");
        close(spi_fd);
        gpiod_chip_close(chip);
        gpiod_edge_free(edge);
        gpiod_line_free(line);
        exit(EXIT_FAILURE);
    }
}

void spi_read_gyroscope() {
    uint8_t buffer[3];
    ssize_t bytes_read;

    // Send the address with MSB set
    if (ioctl(spi_fd, SPI_IOC_WR_DATA, 0x80) < 0) {
        perror("Failed to write address");
        return;
    }

    // Read 2 bytes
    if ((bytes_read = ioctl(spi_fd, SPI_IOC_RD_DATA, buffer)) < 0) {
        perror("Failed to read data");
        return;
    }

    // Convert raw values to angular rates
    int x = (int16_t) buffer[0] * SCALE_FACTOR;
    int y = (int16_t) buffer[1] * SCALE_FACTOR;
    int z = (int16_t) buffer[2] * SCALE_FACTOR;

    // Log the results
    printf("X: %d, Y: %d, Z: %d\n", x, y, z);
}

void spi_loop() {
    while (1) {
        spi_read_gyroscope();
        usleep(100000); // 100 ms delay
    }
}

void cleanup() {
    gpiod_chip_free(chip);
    gpiod_line_free(line);
    close(spi_fd);
}

void signal_handler(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, signal_handler);

    spi_init();

    spi_loop();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x6B
#define WHO_AM_I 0x3D
#define OUTX_L_G 0x22

#define GYRO_SENSITIVITY 0.00875
#define ACCEL_SENSITIVITY 0.000061

int main() {
    int fd;
    int err;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed: %d\n", err);
        return 1;
    }

    // Open I2C bus
    if ((fd = i2cOpen(I2C_BUS, I2C_ADDR, 0)) < 0) {
        fprintf(stderr, "I2C open failed: %d\n", err);
        gpioTerminate();
        return 1;
    }

    // Read WHO_AM_I register
    uint8_t who_am_i;
    if ((err = i2cReadByte(fd, WHO_AM_I, 0)) < 0) {
        fprintf(stderr, "WHO_AM_I read failed: %d\n", err);
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }
    if (who_am_i != 0x6B) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x6B, got 0x%02x\n", who_am_i);
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }

    // Configure accelerometer
    if ((err = i2cWriteByte(fd, 0x3A, 0x42)) < 0) {
        fprintf(stderr, "Accelerometer CTRL1 write failed: %d\n", err);
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }

    // Configure gyroscope
    if ((err = i2cWriteByte(fd, 0x3B, 0x42)) < 0) {
        fprintf(stderr, "Gyroscope CTRL2 write failed: %d\n", err);
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Burst read
        uint8_t data[12];
        if ((err = i2cBurstRead(fd, OUTX_L_G, 12, data)) < 0) {
            fprintf(stderr, "Burst read failed: %d\n", err);
            i2cClose(fd);
            gpioTerminate();
            return 1;
        }

        // Convert data
        double gyro_x = (data[0] << 8 | data[1]) * GYRO_SENSITIVITY;
        double gyro_y = (data[2] << 8 | data[3]) * GYRO_SENSITIVITY;
        double gyro_z = (data[4] << 8 | data[5]) * GYRO_SENSITIVITY;

        double accel_x = (data[6] << 8 | data[7]) * ACCEL_SENSITIVITY;
        double accel_y = (data[8] << 8 | data[9]) * ACCEL_SENSITIVITY;
        double accel_z = (data[10] << 8 | data[11]) * ACCEL_SENSITIVITY;

        // Print data
        printf("%.6f %.6f %.6f %.6f %.6f %.6f\n", gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);

        // Sleep for 100 ms
        if ((err = gpioDelay(100)) < 0) {
            fprintf(stderr, "Delay failed: %d\n", err);
            i2cClose(fd);
            gpioTerminate();
            return 1;
        }
    }

    // Clean shutdown on Ctrl+C
    signal(SIGINT, [](int) {
        i2cClose(fd);
        gpioTerminate();
        exit(0);
    });

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <pigpio.h>

#define I2C_ADDR 0x1D
#define I2C_BUS 1
#define I2C_SDA 2
#define I2C_SCL 3
#define WHO_AM_I 0x0D
#define HYBRID_MODE 0x01
#define OUT_X_MSB 0x01
#define OUT_X_LSB 0x02
#define OUT_Y_MSB 0x03
#define OUT_Y_LSB 0x04
#define OUT_Z_MSB 0x05
#define OUT_Z_LSB 0x06
#define CTRL_REG1 0x2A
#define CTRL_REG2 0x2B
#define M_CTRL_REG1 0x5B
#define M_CTRL_REG2 0x5C

#define BUFFER_SIZE 12
#define LOG_BUFFER_SIZE 1024

int i2c_fd;
int i2c_handle;
int sensor_present = 0;
int log_fd;
char log_buffer[LOG_BUFFER_SIZE];
char log_line[LOG_BUFFER_SIZE * 2 + 1];

void handle_sigint(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (i2c_handle != -1) {
        close(i2c_handle);
    }
    if (log_fd != -1) {
        close(log_fd);
    }
    printf("Exiting...\n");
    exit(0);
}

void init_i2c() {
    i2c_fd = open("/dev/i2c-n", I2C_BUS);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }
    i2c_handle = i2c_open(i2c_fd, I2C_ADDR);
    if (i2c_handle == -1) {
        perror("Failed to open I2C handle");
        exit(EXIT_FAILURE);
    }
}

void init_sensor() {
    if (!sensor_present) {
        printf("Sensor not present, exiting...\n");
        exit(EXIT_FAILURE);
    }
    // Set hybrid mode
    if (i2c_write(i2c_handle, CTRL_REG1, HYBRID_MODE) < 0) {
        perror("Failed to set hybrid mode");
        exit(EXIT_FAILURE);
    }
    if (i2c_write(i2c_handle, CTRL_REG2, HYBRID_MODE) < 0) {
        perror("Failed to set hybrid mode");
        exit(EXIT_FAILURE);
    }
    if (i2c_write(i2c_handle, M_CTRL_REG1, HYBRID_MODE) < 0) {
        perror("Failed to set hybrid mode");
        exit(EXIT_FAILURE);
    }
    if (i2c_write(i2c_handle, M_CTRL_REG2, HYBRID_MODE) < 0) {
        perror("Failed to set hybrid mode");
        exit(EXIT_FAILURE);
    }
}

void read_sensor_data() {
    int i;
    char buffer[BUFFER_SIZE];
    int success = 0;

    for (i = 0; i < 3; i++) {
        if (i2c_read(i2c_handle, OUT_X_MSB + i, buffer + i * 2) < 0) {
            perror("Failed to read sensor data");
            continue;
        }
        if (i2c_read(i2c_handle, OUT_X_LSB + i, buffer + i * 2 + 1) < 0) {
            perror("Failed to read sensor data");
            continue;
        }
        if (i2c_read(i2c_handle, OUT_Y_MSB + i, buffer + (i + 3) * 2) < 0) {
            perror("Failed to read sensor data");
            continue;
        }
        if (i2c_read(i2c_handle, OUT_Y_LSB + i, buffer + (i + 3) * 2 + 1) < 0) {
            perror("Failed to read sensor data");
            continue;
        }
        if (i2c_read(i2c_handle, OUT_Z_MSB + i, buffer + (i + 5) * 2) < 0) {
            perror("Failed to read sensor data");
            continue;
        }
        if (i2c_read(i2c_handle, OUT_Z_LSB + i, buffer + (i + 5) * 2 + 1) < 0) {
            perror("Failed to read sensor data");
            continue;
        }
        success = 1;
        break;
    }

    if (!success) {
        printf("Failed to read sensor data\n");
        return;
    }

    // Log data
    snprintf(log_line, sizeof(log_line), "X: %d, Y: %d, Z: %d\n",
            (int)(buffer[0] << 14 | buffer[1]),
            (int)(buffer[3] << 14 | buffer[4]),
            (int)(buffer[5] << 14 | buffer[6]));
    strncat(log_line, "Magnetometer: ", sizeof(log_line) - strlen(log_line));
    for (i = 7; i < BUFFER_SIZE; i += 2) {
        log_line[0] = '\0';
        snprintf(log_line, sizeof(log_line), "X: %d, Y: %d, Z: %d\n",
                (int)(buffer[i] << 14 | buffer[i + 1]),
                (int)(buffer[i + 3] << 14 | buffer[i + 4]),
                (int)(buffer[i + 5] << 14 | buffer[i + 6]));
        strncat(log_line, "Magnetometer: ", sizeof(log_line) - strlen(log_line));
    }
    strncat(log_line, "Timestamp: ", sizeof(log_line) - strlen(log_line));
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    snprintf(log_line + strlen(log_line), sizeof(log_line) - strlen(log_line), "%d-%m-%Y %H:%M:%S", timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday, timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec);
    strncat(log_line, "\n", sizeof(log_line) - strlen(log_line));
    if (log_fd == -1) {
        log_fd = open("/dev/log", O_WRONLY | O_CREAT | O_APPEND, 0644);
        if (log_fd == -1) {
            perror("Failed to open log file");
            exit(EXIT_FAILURE);
        }
    }
    write(log_fd, log_line, strlen(log_line));
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    init_i2c();
    init_sensor();

    while (1) {
        read_sensor_data();
        usleep(100000); // 100 ms delay
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <math.h>

#define I2C_BUS 1
#define I2C_ADDR 0x53
#define ACCEL_X 0x32
#define ACCEL_Y 0x33
#define ACCEL_Z 0x34
#define TILT_THRESHOLD 30.0

typedef struct {
    int fd;
    int accel_fd;
    int log_fd;
    int last_time;
    double last_tilt;
} TiltSensor;

void init_sensor(TiltSensor *sensor) {
    if ((sensor->fd = open("/dev/i2c-" I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open i2c bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(sensor->fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set slave address");
        exit(EXIT_FAILURE);
    }

    if ((sensor->accel_fd = open("/dev/i2c-" I2C_BUS", O_RDWR")) < 0) {
        perror("Failed to open i2c device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(sensor->accel_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set slave address");
        exit(EXIT_FAILURE);
    }

    if (ioctl(sensor->accel_fd, I2C_RDWR, 0) < 0) {
        perror("Failed to enable I2C device");
        exit(EXIT_FAILURE);
    }

    sensor->last_time = 0;
    sensor->last_tilt = 0;
}

void read_acceleration(TiltSensor *sensor, double *x, double *y, double *z) {
    if (read(sensor->accel_fd, sensor->buffer, 6) < 0) {
        perror("Failed to read acceleration data");
        exit(EXIT_FAILURE);
    }

    *x = (sensor->buffer[ACCEL_X] << 8) | sensor->buffer[ACCEL_X + 1];
    *y = (sensor->buffer[ACCEL_Y] << 8) | sensor->buffer[ACCEL_Y + 1];
    *z = (sensor->buffer[ACCEL_Z] << 8) | sensor->buffer[ACCEL_Z + 1];
}

void calculate_tilt(double x, double y, double *tilt) {
    *tilt = atan2(y, x);
}

void log_event(double tilt, double timestamp) {
    char buffer[256];
    struct timeval tv;

    gettimeofday(&tv, NULL);
    sprintf(buffer, "%ld.%06ld %f\n", (long)tv.tv_sec, (long)tv.tv_usec, tilt);
    write(sensor->log_fd, buffer, strlen(buffer));
}

void cleanup(TiltSensor *sensor) {
    if (sensor->log_fd > 0) {
        close(sensor->log_fd);
    }
    if (sensor->accel_fd > 0) {
        close(sensor->accel_fd);
    }
    if (sensor->fd > 0) {
        close(sensor->fd);
    }
}

void handle_signal(int signum) {
    cleanup(&sensor);
    exit(EXIT_SUCCESS);
}

int main() {
    TiltSensor sensor;
    double x, y, z, tilt;

    init_sensor(&sensor);

    signal(SIGINT, handle_signal);

    while (1) {
        if (gettimeofday(&tv, NULL) < 0) {
            perror("Failed to get current time");
            cleanup(&sensor);
            exit(EXIT_FAILURE);
        }

        if ((tv.tv_sec - sensor->last_time) >= 0.1) {
            read_acceleration(&sensor, &x, &y, &z);
            calculate_tilt(x, y, &tilt);

            if (fabs(tilt - sensor->last_tilt) > 0.01) {
                if (fabs(tilt) > TILT_THRESHOLD) {
                    log_event(tilt, tv.tv_sec);
                }
                sensor->last_tilt = tilt;
            }

            sensor->last_time = tv.tv_sec;
        }
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/ioctl.h>
#include <linux/i2c.h>
#include <pigpio.h>

#define GPIO17 17
#define I2C_ADDR 0x38
#define I2C_BUS 1

int i2c_fd;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, exiting...\n", signum);
        piStop();
        close(i2c_fd);
        exit(0);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    int threshold;
    if (sscanf(argv[1], "%d", &threshold) != 1) {
        fprintf(stderr, "Invalid threshold value\n");
        return 1;
    }

    if (threshold <= 0) {
        fprintf(stderr, "Threshold must be a positive integer\n");
        return 1;
    }

    if (piInitialise() < 0) {
        perror("pigpioInitialise");
        return 1;
    }

    if (gpioSetMode(GPIO17, PI_INPUT) < 0) {
        perror("gpioSetMode");
        piTerminate();
        return 1;
    }

    if (ioctl(I2C_BUS, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl");
        piTerminate();
        return 1;
    }

    if (i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR) < 0) {
        perror("open");
        piTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl");
        close(i2c_fd);
        piTerminate();
        return 1;
    }

    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        piTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO17, PI_INPUT) < 0) {
        perror("gpioSetMode");
        piTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        struct timeval start, end;
        gettimeofday(&start, NULL);

        int high_count = 0;
        for (int i = 0; i < 5000; i++) {
            if (gpioRead(GPIO17) == 1) {
                high_count++;
            }
            usleep(1);
        }

        gettimeofday(&end, NULL);
        double elapsed = (end.tv_sec - start.tv_sec) * 1000 + (end.tv_usec - start.tv_usec) / 1000.0;
        if (elapsed < 5.0) {
            continue;
        }

        if (high_count > threshold) {
            printf("ALERT: %f seconds of high readings\n", elapsed);
        } else {
            printf("Normal: %f seconds of high readings\n", elapsed);
        }

        usleep(1000);
    }

    return 0;
}

#include <stdio.h>
