#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <gpiod.h>
#include <errno.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1E
#define CTRL_REG1_M 0x20
#define OUT_X_L_M 0x08
#define OUT_X_H_M 0x0A
#define OUT_Y_L_M 0x0C
#define OUT_Y_H_M 0x0E
#define OUT_Z_L_M 0x10
#define OUT_Z_H_M 0x12
#define I2C_BLOCK_READ 0x40

#define LED_PIN 17
#define PWM_FREQ 1000000
#define PWM_RESOLUTION 16

int i2c_fd;
struct gpiod_handle *gpio_handle;
struct gpiod_line *gpio_line;
struct gpiod_state *gpio_state;
int pwm_fd;
int led_value = 0;

void i2c_error_handler(int err) {
    fprintf(stderr, "I2C error: %d\n", err);
    close(i2c_fd);
    exit(EXIT_FAILURE);
}

void gpio_error_handler(int err) {
    fprintf(stderr, "GPIO error: %d\n", err);
    gpiod_line_close(gpio_line);
    gpiod_handle_close(gpio_handle);
    close(pwm_fd);
    exit(EXIT_FAILURE);
}

void init_i2c() {
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        i2c_error_handler(errno);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        i2c_error_handler(errno);
    }
}

void init_gpio() {
    gpio_handle = gpiod_open("/dev/gpiod");
    if (!gpio_handle) {
        gpio_error_handler(errno);
    }
    gpio_state = gpiod_get_state(gpio_handle);
    if (!gpio_state) {
        gpio_error_handler(errno);
    }
    gpio_line = gpiod_get_line(gpio_handle, LED_PIN);
    if (!gpio_line) {
        gpio_error_handler(errno);
    }
    gpio_state = gpiod_get_state(gpio_handle);
    if (!gpio_state) {
        gpio_error_handler(errno);
    }
    gpio_line->direction = GPIODIRECTION_OUT;
    if (gpio_state->set(gpio_line, GPIODIRECTION_OUT) < 0) {
        gpio_error_handler(errno);
    }
    pwm_fd = gpiod_pwm_open(gpio_handle, LED_PIN);
    if (!pwm_fd) {
        gpio_error_handler(errno);
    }
    if (gpiod_pwm_set_frequency(pwm_fd, PWM_FREQ) < 0) {
        gpio_error_handler(errno);
    }
    if (gpiod_pwm_set_resolution(pwm_fd, PWM_RESOLUTION) < 0) {
        gpio_error_handler(errno);
    }
    led_value = 0;
    if (gpiod_pwm_write(pwm_fd, led_value) < 0) {
        gpio_error_handler(errno);
    }
}

void read_magnetometer() {
    int data[6];
    ssize_t bytes_read;
    if ((bytes_read = i2c_smbus_read_i2c_block_data(i2c_fd, OUT_X_L_M, 6, data)) < 0) {
        i2c_error_handler(errno);
    }
    float x = (data[0] | (data[1] << 8)) / 16384.0;
    float y = (data[2] | (data[3] << 8)) / 16384.0;
    float z = (data[4] | (data[5] << 8)) / 16384.0;
    float z_magnitude = sqrt(x*x + y*y + z*z);
    led_value = (int)(255.0 * z_magnitude / 1.0);
    if (gpiod_pwm_write(pwm_fd, led_value) < 0) {
        gpio_error_handler(errno);
    }
}

int main() {
    init_i2c();
    init_gpio();
    while (1) {
        read_magnetometer();
        usleep(100000);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1E
#define CONFIG_REG_A 0x70
#define CONFIG_REG_B 0x21
#define MODE_REG 0x00
#define SAMPLE_AVG 8
#define OUTPUT_RATE 15
#define GAIN 1.3

#define HARD_IRON_WINDOW 100
#define HARD_IRON_SAMPLE_INTERVAL 500

int i2c_fd;
int i2c_handle;
int i2c_error = 0;
int i2c_read_error = 0;
int i2c_write_error = 0;

int *hardiron_offsets = NULL;
int hardiron_offset_count = 0;
int hardiron_offset_index = 0;
int hardiron_offset_size = HARD_IRON_WINDOW;

void handle_i2c_error(int signum) {
    if (signum == SIGI2C) {
        if (i2c_error) {
            fprintf(stderr, "I2C read error: %d\n", i2c_read_error);
        } else if (i2c_write_error) {
            fprintf(stderr, "I2C write error: %d\n", i2c_write_error);
        }
        i2c_error = 0;
        i2c_read_error = 0;
        i2c_write_error = 0;
    }
}

void handle_sigint(int signum) {
    if (hardiron_offsets) {
        free(hardiron_offsets);
    }
    pi_close();
    if (i2c_fd > 0) {
        close(i2c_fd);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);
    signal(SIGI2C, handle_i2c_error);

    if (pi_init()) {
        fprintf(stderr, "pigpio init failed\n");
        return EXIT_FAILURE;
    }

    if ((i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR)) < 0) {
        perror("open i2c device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl i2c slave");
        return EXIT_FAILURE;
    }

    i2c_handle = pi_i2c_open(i2c_fd, I2C_ADDR);

    if (i2c_handle < 0) {
        perror("pi_i2c_open");
        return EXIT_FAILURE;
    }

    // Configure the magnetometer
    int config_reg_a = 0x70;
    int config_reg_b = 0x20;
    int mode_reg = 0x00;

    if (pi_i2c_write(i2c_handle, config_reg_a, 1) < 0) {
        i2c_write_error = 1;
        fprintf(stderr, "Failed to write config_reg_a: %d\n", config_reg_a);
    }

    if (pi_i2c_write(i2c_handle, config_reg_b, 1) < 0) {
        i2c_write_error = 1;
        fprintf(stderr, "Failed to write config_reg_b: %d\n", config_reg_b);
    }

    if (pi_i2c_write(i2c_handle, mode_reg, 1) < 0) {
        i2c_write_error = 1;
        fprintf(stderr, "Failed to write mode_reg: %d\n", mode_reg);
    }

    // Initialize hardiron offsets
    hardiron_offsets = malloc(sizeof(int) * HARD_IRON_WINDOW);
    if (!hardiron_offsets) {
        fprintf(stderr, "Failed to allocate hardiron_offsets\n");
        return EXIT_FAILURE;
    }
    hardiron_offset_count = HARD_IRON_WINDOW;
    hardiron_offset_index = 0;

    // Main loop
    while (1) {
        // Read raw data
        int raw_data[3];
        if (pi_i2c_read(i2c_handle, raw_data, 3) < 0) {
            i2c_read_error = 1;
            fprintf(stderr, "Failed to read raw data\n");
        } else {
            // Apply hardiron offsets
            int x = raw_data[0] - hardiron_offsets[hardiron_offset_index];
            int y = raw_data[1] - hardiron_offsets[hardiron_offset_index];
            int z = raw_data[2] - hardiron_offsets[hardiron_offset_index];

            // Update hardiron offsets
            if (hardiron_offset_index < HARD_IRON_WINDOW - 1) {
                hardiron_offsets[hardiron_offset_index] = (x + y + z) / 3;
                hardiron_offset_index++;
            } else {
                int sum = 0;
                for (int i = 0; i < HARD_IRON_WINDOW; i++) {
                    sum += hardiron_offsets[i];
                }
                int avg = sum / HARD_IRON_WINDOW;
                for (int i = 0; i < HARD_IRON_WINDOW; i++) {
                    hardiron_offsets[i] = (hardiron_offsets[i] + avg) / 2;
                }
                hardiron_offset_index = 0;
            }

            // Print offset-corrected values
            printf("%d %d %d\n", x, y, z);
        }

        // Sleep for HARD_IRON_SAMPLE_INTERVAL ms
        usleep(HARD_IRON_SAMPLE_INTERVAL * 1000);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
