#include <gpiod/attributes.h>
#include <gpiod/line.h>
#include <gpiod/device.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define LSM303D_ADDRESS 0x1D
#define WHO_AM_I 0x0F
#define INT1_CFG 0x2A
#define OUT_X_L_A 0x28
#define CTRL_REG1 0x27
#define CTRL_REG4 0x28
#define INT1_PIN 23

#define BUFFER_SIZE 64
#define SAMPLE_RATE 50
#define SAMPLE_INTERVAL (1000 / SAMPLE_RATE)
#define SAMPLES_TO_DUMP 10

typedef struct {
    int fd;
    int i2c_fd;
    int buffer_idx;
    int buffer_full;
    int buffer_size;
    int samples_to_dump;
} LSM303DConfig;

void init_i2c(LSM303DConfig *config) {
    config->fd = open(I2C_DEVICE, O_RDWR);
    if (config->fd < 0) {
        perror("Failed to open I2C device");
        exit(1);
    }
    if (ioctl(config->fd, I2C_SLAVE, LSM303D_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        exit(1);
    }
    config->i2c_fd = config->fd;
}

void init_gpio(LSM303DConfig *config) {
    int line_fd;
    struct gpiod_line *line;
    struct gpiod_device *device;
    struct gpiod_attribute *attr;
    struct gpiod_signalfd *signalfd;
    struct sigaction sa;

    line_fd = gpiod_open("/dev/gpiod");
    if (line_fd < 0) {
        perror("Failed to open gpiod device");
        exit(1);
    }

    device = gpiod_get_new_device(line_fd);
    if (!device) {
        perror("Failed to get new device");
        exit(1);
    }

    line = gpiod_get_new_line(device, INT1_PIN);
    if (!line) {
        perror("Failed to get new line");
        exit(1);
    }

    attr = gpiod_get_new_attribute(line, GPIOD_ATTR_EDGE);
    if (!attr) {
        perror("Failed to get new attribute");
        exit(1);
    }

    signalfd = gpiod_get_new_signalfd(line, GPIOD_SIGNALLINE_EDGE);
    if (!signalfd) {
        perror("Failed to get new signalfd");
        exit(1);
    }

    config->gpio_fd = line_fd;
    config->signalfd = signalfd;

    gpiod_set_signalfd(signalfd, GPIOD_SIGNALLINE_EDGE, &sa, 0);
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sa.sa_handler = SIG_DFL;
    sigaction(SIGINT, &sa, NULL);

    gpiod_enable_signalfd(signalfd, GPIOD_SIGNALLINE_EDGE);
    gpiod_enable_line(line, GPIOD_LINE_EDGE);
    gpiod_enable_device(device, GPIOD_DEVICE_EDGE);
}

void read_lsm303d(LSM303DConfig *config) {
    int status;
    uint8_t data[6];
    uint16_t x, y, z;

    status = i2c_smbus_read_i2c_block_data(config->i2c_fd, OUT_X_L_A, 6, data);
    if (status < 0) {
        fprintf(stderr, "I2C read failed: %d\n", status);
        return;
    }

    x = (data[0] << 8) | data[1];
    y = (data[2] << 8) | data[3];
    z = (data[4] << 8) | data[5];

    config->buffer[idx].x = x;
    config->buffer[idx].y = y;
    config->buffer[idx].z = z;

    config->buffer_idx = (config->buffer_idx + 1) % config->buffer_size;
    if (config->buffer_idx == 0 && config->buffer_full) {
        config->buffer_full = 0;
    }
}

void configure_lsm303d(LSM303DConfig *config) {
    uint8_t data[1];

    data[0] = CTRL_REG1;
    data[0] = 0x57; // 50 Hz ODR, all axes enabled

    i2c_smbus_write_byte_data(config->i2c_fd, CTRL_REG1, data[0]);

    data[0] = CTRL_REG4;
    data[0] = 0x00; // Full-scale +-2g

    i2c_smbus_write_byte_data(config->i2c_fd, CTRL_REG4, data[0]);

    data[0] = INT1_CFG;
    data[0] = 0x2A; // Threshold 2000 mg, duration 0

    i2c_smbus_write_byte_data(config->i2c_fd, INT1_CFG, data[0]);
}

void handle_interrupt(LSM303DConfig *config) {
    struct timespec ts;
    int i;

    clock_gettime(CLOCK_MONOTONIC, &ts);
    fprintf(stderr, "Interrupt at %ld.%09ld\n", ts.tv_sec, ts.tv_nsec / 1000000.0);

    for (i = 0; i < config->samples_to_dump; i++) {
        fprintf(stderr, "Sample %d: %d %d %d\n", i, config->buffer[(config->buffer_idx - i) % config->buffer_size].x, config->buffer[(config->buffer_idx - i) % config->buffer_size].y, config->buffer[(config->buffer_idx - i) % config->buffer_size].z);
    }
}

int main() {
    LSM303DConfig config;
    int i;

    config.buffer_idx = 0;
    config.buffer_full = 0;
    config.buffer_size = BUFFER_SIZE;
    config.samples_to_dump = SAMPLES_TO_DUMP;

    init_i2c(&config);
    if (config.fd < 0) {
        return 1;
    }

    init_gpio(&config);
    if (config.gpio_fd < 0) {
        return 1;
    }

    read_lsm303d(&config);
    if (config.buffer_idx < config.buffer_size) {
        config.buffer_full = 0;
    }

    configure_lsm303d(&config);

    while (1) {
        struct gpiod_signalfd_event event;
        int signalfd = config.signalfd;
        int line_fd = config.gpio_fd;

        if (gpiod_wait_signalfd(signalfd, &event, 0) < 0) {
            perror("Failed to wait for signalfd");
            continue;
        }

        if (event.type == GPIOD_LINE_EDGE) {
            handle_interrupt(&config);
        }

        if (config.buffer_idx < config.buffer_size) {
            read_lsm303d(&config);
        } else {
            fprintf(stderr, "Buffer full, skipping read\n");
        }

        usleep(SAMPLE_INTERVAL * 1000);
    }

    return 0;
}

#include <stdio.h>
