#define GPIO17 17
#define GPIO27 27
#define FLYBACK_DIODE 0x01
#define LOW 0
#define HIGH 1

int main() {
    int err;
    struct gpiod_chip *chip;
    struct gpiod_line *line1, *line2;
    struct gpiod_edge *edge1, *edge2;
    struct gpiod_state *state1, *state2;

    // Initialize libgpiod
    err = gpiod_init(&chip);
    if (err) {
        perror("gpiod_init");
        return 1;
    }

    // Select GPIOchip 0
    err = gpiod_chip_request_chip(chip, 0);
    if (err) {
        perror("gpiod_chip_request_chip");
        gpiod_chip_free(chip);
        return 1;
    }

    // Request GPIO17 and GPIO27
    err = gpiod_chip_request_line(chip, GPIO17, FLYBACK_DIODE);
    if (err) {
        perror("gpiod_chip_request_line");
        gpiod_chip_free(chip);
        return 1;
    }
    line1 = gpiod_chip_get_line(chip, GPIO17);
    err = gpiod_chip_request_line(chip, GPIO27, FLYBACK_DIODE);
    if (err) {
        perror("gpiod_chip_request_line");
        gpiod_chip_free(chip);
        return 1;
    }
    line2 = gpiod_chip_get_line(chip, GPIO27);

    // Set initial state to LOW
    err = gpiod_line_request_state(line1, LOW);
    if (err) {
        perror("gpiod_line_request_state");
        gpiod_chip_free(chip);
        return 1;
    }
    err = gpiod_line_request_state(line2, LOW);
    if (err) {
        perror("gpiod_line_request_state");
        gpiod_chip_free(chip);
        return 1;
    }

    // Set up edge detection
    err = gpiod_line_request_edge(line1, GPIOD_EDGE_BOTH);
    if (err) {
        perror("gpiod_line_request_edge");
        gpiod_chip_free(chip);
        return 1;
    }
    edge1 = gpiod_line_get_edge(line1);
    err = gpiod_line_request_edge(line2, GPIOD_EDGE_BOTH);
    if (err) {
        perror("gpiod_line_request_edge");
        gpiod_chip_free(chip);
        return 1;
    }
    edge2 = gpiod_line_get_edge(line2);

    // Set up state handlers
    state1 = gpiod_line_request_state(line1, GPIOD_STATE_EDGE);
    state2 = gpiod_line_request_state(line2, GPIOD_STATE_EDGE);

    // Install SIGINT/SIGTERM handler
    signal(SIGINT, [](int sig) {
        gpiod_line_request_state(line1, LOW);
        gpiod_line_request_state(line2, LOW);
        gpiod_chip_free(chip);
        return 0;
    });
    signal(SIGTERM, [](int sig) {
        gpiod_line_request_state(line1, LOW);
        gpiod_line_request_state(line2, LOW);
        gpiod_chip_free(chip);
        return 0;
    });

    // Main loop
    while (1) {
        // Energize solenoid 1 for 500 ms
        gpiod_line_request_state(line1, HIGH);
        nanosleep((const struct timespec[]){{500000000, 0}}, NULL);
        gpiod_line_request_state(line1, LOW);

        // Energize solenoid 2 for 500 ms
        gpiod_line_request_state(line2, HIGH);
        nanosleep((const struct timespec[]){{500000000, 0}}, NULL);
        gpiod_line_request_state(line2, LOW);

        // Wait for 1 second before next cycle
        nanosleep((const struct timespec[]){{1000000000, 0}}, NULL);
    }

    gpiod_chip_free(chip);
    return 0;
}

