        syslog(LOG_ERR, "Failed to open GPIO chip: %s\n", gpiod_chip_errno(chip));
        return 1;
    }

    // Request the PIR pin
    if ((line = gpiod_chip_request_line(chip, GPIO4, GPIOD_LINE_REQUEST_INPUT)) == NULL) {
        syslog(LOG_ERR, "Failed to request PIR pin: %s\n", gpiod_line_request_errno(line));
        gpiod_chip_unrequest_line(chip, line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the relay pin
    if ((line = gpiod_chip_request_line(chip, GPIO17, GPIOD_LINE_REQUEST_OUTPUT)) == NULL) {
        syslog(LOG_ERR, "Failed to request relay pin: %s\n", gpiod_line_request_errno(line));
        gpiod_chip_unrequest_line(chip, line);
        gpiod_chip_unrequest_line(chip, line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the relay pin to LOW
    if (gpiod_line_request_set_value(line, 0) < 0) {
        syslog(LOG_ERR, "Failed to set relay pin to LOW: %s\n", gpiod_line_request_errno(line));
        gpiod_chip_unrequest_line(chip, line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Create an event request for the PIR pin
    if ((event_request = gpiod_line_request_event(line, GPIOD_EVENT_EDGE_ANY)) == NULL) {
        syslog(LOG_ERR, "Failed to request event for PIR pin: %s\n", gpiod_line_request_event_errno(event_request));
        gpiod_chip_unrequest_line(chip, line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Create a loop to poll the PIR pin
    if ((loop = gpiod_loop_new()) == NULL) {
        syslog(LOG_ERR, "Failed to create loop: %s\n", gpiod_loop_new_errno(loop));
        gpiod_chip_unrequest_line(chip, line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Create an event request for the loop
    if ((event_request = gpiod_loop_request_event(loop, GPIOD_EVENT_EDGE_ANY)) == NULL) {
        syslog(LOG_ERR, "Failed to request event for loop: %s\n", gpiod_loop_request_event_errno(event_request));
        gpiod_loop_close(loop);
        gpiod_chip_unrequest_line(chip, line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Start the loop
    if (gpiod_loop_start(loop) < 0) {
        syslog(LOG_ERR, "Failed to start loop: %s\n", gpiod_loop_start_errno(loop));
        gpiod_loop_close(loop);
        gpiod_chip_unrequest_line(chip, line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Read the PIR pin
        if (gpiod_line_get_value(line, &motion_detected) < 0) {
            syslog(LOG_ERR, "Failed to read PIR pin: %s\n", gpiod_line_get_value_errno(line));
            gpiod_chip_unrequest_line(chip, line);
            gpiod_chip_close(chip);
            return 1;
        }

        // Check if motion is detected
        if (motion_detected) {
            // Energize the relay
            if (gpiod_line_request_set_value(line, 1) < 0) {
                syslog(LOG_ERR, "Failed to energize relay: %s\n", gpiod_line_request_set_value_errno(line));
                gpiod_chip_unrequest_line(chip, line);
                gpiod_chip_close(chip);
                return 1;
            }
            relay_state = 1;
            syslog(LOG_INFO, "Motion detected, energizing relay\n");
        } else {
            // De-energize the relay
            if (gpiod_line_request_set_value(line, 0) < 0) {
                syslog(LOG_ERR, "Failed to de-energize relay: %s\n", gpiod_line_request_set_value_errno(line));
                gpiod_chip_unrequest_line(chip, line);
                gpiod_chip_close(chip);
                return 1;
            }
            relay_state = 0;
            syslog(LOG_INFO, "No motion detected, de-energizing relay\n");
        }

        // Check for timeout
        if (timeout >= PIR_TIMEOUT) {
            // De-energize the relay and log a warning
            if (gpiod_line_request_set_value(line, 0) < 0) {
                syslog(LOG_ERR, "Failed to de-energize relay: %s\n", gpiod_line_request_set_value_errno(line));
                gpiod_chip_unrequest_line(chip, line);
                gpiod_chip_close(chip);
                return 1;
            }
            relay_state = 0;
            syslog(LOG_WARNING, "PIR sensor remains HIGH for %d seconds, de-energizing relay\n", timeout);
        }

        // Poll the PIR pin every 50 ms
        usleep(POLL_INTERVAL * 1000);

        // Increment the timeout
        timeout++;
    }

    // Clean shutdown on SIGINT/SIGTERM
    if (signal(SIGINT, [](int signum) {
        // Release all GPIO lines
        gpiod_line_request_release(line, event_request);
        gpiod_line_request_release(line, request);
        gpiod_chip_release(line);
        gpiod_chip_close(chip);
        // Close the log
        close(logfd);
        // Exit
        exit(0);
    }) == SIG_ERR) {
        syslog(LOG_ERR, "Failed to set SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (signal(SIGTERM, [](int signum) {
        // Release all GPIO lines
        gpiod_line_request_release(line, event_request);
        gpiod_line_request_release(line, request);
        gpiod_chip_release(line);
        gpiod_chip_close(chip);
        // Close the log
        close(logfd);
        // Exit
        exit(0);
    }) == SIG_ERR) {
        syslog(LOG_ERR, "Failed to set SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <time.h>

volatile sig_atomic_t running = 1;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        syslog(LOG_INFO, "Irrigation system shutting down...");
        running = 0;
        gpioTerminate();
        close_syslog();
        exit(0);
    }
}

void init_syslog() {
    openlog("irrigation_system", LOG_PID | LOG_CONS | LOG_NDELAY, LOG_LOCAL0);
}

void close_syslog() {
    closelog();
}

void log_state_change(int gpio, int state, time_t timestamp) {
    char buffer[256];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&timestamp));
    syslog(LOG_INFO, "Relay %d: %s -> %s (%s)", gpio, (state ? "ON" : "OFF"), (state ? "OFF" : "ON"), buffer);
}

int main() {
    init_syslog();

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpioInitialise failed: %d", gpioInitialise());
        close_syslog();
        exit(1);
    }

    if (gpioSetMode(4, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(4, PI_OUTPUT) failed: %d", gpioSetMode(4, PI_OUTPUT));
        close_syslog();
        exit(1);
    }

    if (gpioSetMode(17, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(17, PI_OUTPUT) failed: %d", gpioSetMode(17, PI_OUTPUT));
        close_syslog();
        exit(1);
    }

    if (gpioSetMode(27, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(27, PI_OUTPUT) failed: %d", gpioSetMode(27, PI_OUTPUT));
        close_syslog();
        exit(1);
    }

    if (gpioSetMode(22, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(22, PI_OUTPUT) failed: %d", gpioSetMode(22, PI_OUTPUT));
        close_syslog();
        exit(1);
    }

    int relays[4] = {4, 17, 27, 22};
    int states[4] = {1, 1, 1, 1}; // 1 = HIGH (OFF), 0 = LOW (ON)
    int current = 0;
    time_t last_time = 0;
    time_t current_time = 0;
    time_t timer_start = 0;
    int timer_state = 0;

    gpioSetTimerFuncEx(0, 60, 0, (void (*)(void))timer_callback, NULL);

    while (running) {
        current_time = time(NULL);
        if (current_time - last_time >= 60) {
            last_time = current_time;
            timer_state = 1;
        }

        if (timer_state == 1) {
            if (current_time - timer_start >= 300) {
                states[current] = 0;
                log_state_change(relays[current], states[current], current_time);
                timer_start = current_time;
                timer_state = 0;
                current = (current + 1) % 4;
            } else {
                states[current] = 1;
                log_state_change(relays[current], states[current], current_time);
                timer_start = current_time;
                timer_state = 0;
            }
        }

        if (running) {
            sleep(1);
        }
    }

    handle_signal(SIGINT);
    handle_signal(SIGTERM);

    close_syslog();
    exit(0);
}

void timer_callback(void *arg) {
    // This function is not used in the current implementation
}

void close_syslog() {
    closelog();
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/time.h>
#include <gpiod.h>
#include <unistd.h>

#define GPIO_PIN_18 18
#define GPIO_PIN_23 23
#define GPIO_PIN_24 24
#define GPIO_PIN_25 25

#define RELAY_1 0
#define RELAY_2 1
#define RELAY_3 2
#define RELAY_4 3

#define PRIME_INTERVALS [2, 3, 5, 7]

int main() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    struct timespec interval;
    int relay_state[4] = {0};
    int i;

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiod");
    if (chip == NULL) {
        perror("gpiod_chip_open");
        return 1;
    }

    // Get the first GPIO chip
    ret = gpiod_chip_get_fd(chip, 0);
    if (ret < 0) {
        perror("gpiod_chip_get_fd");
        goto cleanup;
    }

    // Create a new line for each GPIO pin
    for (i = 0; i < 4; i++) {
        line = gpiod_chip_request_line(chip, GPIO_PIN_18 + i, GPIOD_LINE_INPUT);
        if (line == NULL) {
            perror("gpiod_chip_request_line");
            goto cleanup;
        }
    }

    // Set the direction of each line to output
    for (i = 0; i < 4; i++) {
        ret = gpiod_line_set_direction(line[i], GPIOD_DIR_OUTPUT);
        if (ret < 0) {
            perror("gpiod_line_set_direction");
            goto cleanup;
        }
    }

    // Initialize the relays to off
    for (i = 0; i < 4; i++) {
        relay_state[i] = 0;
    }

    // Set the initial interval
    interval.tv_sec = 0;
    interval.tv_nsec = 0;

    // Set up the timer
    clock_gettime(CLOCK_MONOTONIC, &interval);
    interval.tv_sec = PRIME_INTERVALS[0];
    interval.tv_nsec = 0;

    // Set up the timer callback
    for (i = 0; i < 4; i++) {
        edge = gpiod_line_request_edge(line[i], GPIOD_EDGE_BOTH);
        if (edge == NULL) {
            perror("gpiod_line_request_edge");
            goto cleanup;
        }
        gpiod_edge_enable(edge, 1);
    }

    // Main loop
    while (1) {
        // Check for SIGINT or SIGTERM
        if (signal(SIGINT, [](int) { exit(EXIT_SUCCESS; }) == SIG_ERR) {
            perror("SIGINT");
        }
        if (signal(SIGTERM, [](int) { exit(EXIT_SUCCESS; }) == SIG_ERR) {
            perror("SIGTERM");
        }

        // Sleep for the interval
        clock_nanosleep(CLOCK_MONOTONIC, 0, &interval, NULL);

        // Toggle the relays
        for (i = 0; i < 4; i++) {
            relay_state[i] = !relay_state[i];
            gpiod_line_set_value(line[i], relay_state[i] ? 1 : 0);
        }
    }

cleanup:
    // Release all resources
    for (i = 0; i < 4; i++) {
        gpiod_line_release_edge(edge[i]);
        gpiod_line_release(line[i]);
    }
    gpiod_chip_release(chip);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>

#define ALARM_LOG_FILE "alarm_log.txt"
#define ALARM_THRESHOLD 1000 // 1000 microseconds (1ms)
#define ALARM_DURATION 3000 // 3 seconds
#define DEBOUNCE_TIME 100 // 100ms

int alarm_active = 0;
int alarm_last_time = 0;
int alarm_last_state = 0;

void alarm_handler(int sig) {
    if (alarm_active) {
        printf("Shutting down alarm...\n");
        gpio_write(27, 0);
        alarm_active = 0;
        alarm_last_time = 0;
        alarm_last_state = 0;
    }
    printf("Received signal %d, shutting down...\n", sig);
    exit(0);
}

int main() {
    signal(SIGINT, alarm_handler);
    signal(SIGTERM, alarm_handler);

    if (gpio_initialise() < 0) {
        perror("pigpio init failed");
        return 1;
    }

    if (gpio_set_mode(17, PI_INPUT) < 0) {
        perror("Setting GPIO17 to input failed");
        gpio_deinit();
        return 1;
    }

    if (gpio_set_pull_up(17, 1) < 0) {
        perror("Setting GPIO17 to pull-up failed");
        gpio_deinit();
        return 1;
    }

    if (gpio_set_mode(27, PI_OUTPUT) < 0) {
        perror("Setting GPIO27 to output failed");
        gpio_deinit();
        return 1;
    }

    FILE *log_file = fopen(ALARM_LOG_FILE, "a");
    if (!log_file) {
        perror("Opening log file failed");
        gpio_deinit();
        return 1;
    }

    while (1) {
        int state = gpio_read(17);
        if (state && !alarm_active && alarm_last_state != state) {
            alarm_active = 1;
            alarm_last_time = gpio_get_time();
            alarm_last_state = state;
            printf("Alarm triggered at %ld\n", alarm_last_time);
            gpio_write(27, 1);
            fprintf(log_file, "%ld\n", alarm_last_time);
        } else if (!state && alarm_active) {
            alarm_active = 0;
            alarm_last_time = 0;
            alarm_last_state = 0;
            gpio_write(27, 0);
            printf("Alarm deactivated at %ld\n", gpio_get_time());
        }

        if (alarm_active) {
            if (gpio_get_time() - alarm_last_time > ALARM_DURATION) {
                alarm_active = 0;
                alarm_last_time = 0;
                alarm_last_state = 0;
                gpio_write(27, 0);
                printf("Alarm duration expired at %ld\n", gpio_get_time());
            }
        }

        if (alarm_active) {
            if (gpio_get_time() - alarm_last_time > DEBOUNCE_TIME) {
                alarm_last_time = gpio_get_time();
            }
        }

        if (alarm_active) {
            fprintf(log_file, "%ld\n", gpio_get_time());
        }

        if (gpio_get_time() - alarm_last_time > 100) {
            alarm_last_time = gpio_get_time();
        }

        sleep(0.1);
    }

    gpio_write(27, 0);
    gpio_set_mode(27, PI_INPUT);
    gpio_deinit();
    fclose(log_file);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_SLAVE_ADDR 0x68
#define MPU6050_WHO_AM_I 0x75
#define MPU6050_GYRO_XOUT_H 0x43
#define MPU6050_GYRO_XOUT_L 0x44
#define MPU6050_GYRO_YOUT_H 0x45
#define MPU6050_GYRO_YOUT_L 0x46
#define MPU6050_GYRO_ZOUT_H 0x47
#define MPU6050_GYRO_ZOUT_L 0x48
#define MPU6050_ACCEL_XOUT_H 0x58
#define MPU6050_ACCEL_XOUT_L 0x59
#define MPU6050_ACCEL_YOUT_H 0x5A
#define MPU6050_ACCEL_YOUT_L 0x5B
#define MPU6050_ACCEL_ZOUT_H 0x5C
#define MPU6050_ACCEL_ZOUT_L 0x5D
#define MPU6050_TEMP_OUT_H 0x6A
#define MPU6050_TEMP_OUT_L 0x6B
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_SLEEP 0x80
#define MPU6050_WAKE 0x00
#define MPU6050_GYRO_SENSITIVITY 131.0
#define THRESHOLD 50.0

typedef struct {
    int fd;
    int samples;
    double buffer[100][3];
    double buffer_sum[3];
    double buffer_avg[3];
    double buffer_max[3];
    double buffer_min[3];
    double buffer_abs;
    double buffer_abs_avg;
    double buffer_abs_max;
    double buffer_abs_min;
    double threshold;
} MPU6050Data;

void initMPU6050(MPU6050Data *mpu) {
    mpu->samples = 0;
    mpu->buffer_sum[0] = 0;
    mpu->buffer_sum[1] = 0;
    mpu->buffer_sum[2] = 0;
    mpu->buffer_avg[0] = 0;
    mpu->buffer_avg[1] = 0;
    mpu->buffer_avg[2] = 0;
    mpu->buffer_max[0] = 0;
    mpu->buffer_max[1] = 0;
    mpu->buffer_max[2] = 0;
    mpu->buffer_min[0] = 0;
    mpu->buffer_min[1] = 0;
    mpu->buffer_min[2] = 0;
    mpu->buffer_abs = 0;
    mpu->buffer_abs_avg = 0;
    mpu->buffer_abs_max = 0;
    mpu->buffer_abs_min = 0;
    mpu->threshold = THRESHOLD;
    mpu->fd = open(I2C_BUS, O_RDWR);
    if (mpu->fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }
    if (ioctl(mpu->fd, I2C_SLAVE, I2C_SLAVE_ADDR) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }
    if (write(mpu->fd, &MPU6050_WAKE, sizeof(MPU6050_WAKE)) < 0) {
        perror("write");
        exit(EXIT_FAILURE);
    }
    if (read(mpu->fd, &mpu->buffer[0][0], 6) < 0) {
        perror("read");
        exit(EXIT_FAILURE);
    }
    if (mpu->buffer[0][0] != 0x68) {
        fprintf(stderr, "MPU6050 not found\n");
        exit(EXIT_FAILURE);
    }
    if (read(mpu->fd, &mpu->buffer[0][0], 6) < 0) {
        perror("read");
        exit(EXIT_FAILURE);
    }
    if (mpu->buffer[0][0] != 0x68) {
        fprintf(stderr, "MPU6050 not found\n");
        exit(EXIT_FAILURE);
    }
}

void readMPU6050Data(MPU6050Data *mpu) {
    if (read(mpu->fd, &mpu->buffer[mpu->samples][0], 6) < 0) {
        perror("read");
        exit(EXIT_FAILURE);
    }
    mpu->samples++;
    if (mpu->samples == 100) {
        mpu->samples = 0;
        mpu->buffer_sum[0] += mpu->buffer[mpu->samples][0];
        mpu->buffer_sum[1] += mpu->buffer[mpu->samples][1];
        mpu->buffer_sum[2] += mpu->buffer[mpu->samples][2];
        mpu->buffer_avg[0] = mpu->buffer_sum[0] / 100.0;
        mpu->buffer_avg[1] = mpu->buffer_sum[1] / 100.0;
        mpu->buffer_avg[2] = mpu->buffer_sum[2] / 100.0;
        mpu->buffer_max[0] = fmax(mpu->buffer_max[0], mpu->buffer[mpu->samples][0]);
        mpu->buffer_max[1] = fmax(mpu->buffer_max[1], mpu->buffer[mpu->samples][1]);
        mpu->buffer_max[2] = fmax(mpu->buffer_max[2], mpu->buffer[mpu->samples][2]);
        mpu->buffer_min[0] = fmin(mpu->buffer_min[0], mpu->buffer[mpu->samples][0]);
        mpu->buffer_min[1] = fmin(mpu->buffer_min[1], mpu->buffer[mpu->samples][1]);
        mpu->buffer_min[2] = fmin(mpu->buffer_min[2], mpu->buffer[mpu->samples][2]);
        mpu->buffer_abs = sqrt(pow(mpu->buffer_avg[0], 2) + pow(mpu->buffer_avg[1], 2) + pow(mpu->buffer_avg[2], 2));
        mpu->buffer_abs_avg = mpu->buffer_abs;
        mpu->buffer_abs_max = fmax(mpu->buffer_abs_max, mpu->buffer_abs);
        mpu->buffer_abs_min = fmin(mpu->buffer_abs_min, mpu->buffer_abs);
        if (mpu->buffer_abs > mpu->threshold) {
            triggerCallback(mpu);
        }
    }
}

void triggerCallback(MPU6050Data *mpu) {
    printf("Angular velocity threshold exceeded: %.2f deg/s\n", mpu->buffer_abs);
}

void cleanup(MPU6050Data *mpu) {
    close(mpu->fd);
}

int main() {
    MPU6050Data mpu;
    initMPU6050(&mpu);
    while (1) {
        readMPU6050Data(&mpu);
    }
    cleanup(&mpu);
    return 0;
}

