#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/time.h>
#include <signal.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDR 0x23
#define BH1750_MODE 0x10
#define BH1750_CONVERSION_TIME 0x01
#define BH1750_LUX_MULT 0x1C
#define BH1750_LUX_DIV 0x13

#define RED_RELAY 17
#define GREEN_RELAY 27
#define BLUE_RELAY 22

#define LOG_FILE "lighting_log.txt"

typedef struct {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int value;
} GPIOLine;

GPIOLine gpioline[3] = {{0}, {0}, {0}};

void sigint_handler(int signum) {
    for (int i = 0; i < 3; i++) {
        if (gpioline[i].line) {
            gpiod_line_put(gpioline[i].chip, gpioline[i].line, 0);
        }
    }
    close(gpioline[0].fd);
    close(gpioline[1].fd);
    close(gpioline[2].fd);
    unlink(LOG_FILE);
    exit(0);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    int fd;
    int lux;
    char timestamp[128];
    struct i2c_msg msg[1];
    struct i2c_rdma_msg msg2[1];
    struct i2c_err err;
    struct timespec ts;
    int seconds = 0;
    int minutes = 0;
    int hours = 0;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    msg[0].addr = I2C_ADDR;
    msg[0].flags = I2C_M_RD;
    msg[0].data[0] = BH1750_MODE;

    if (ioctl(fd, I2C_RDWR, msg) < 0) {
        perror("Failed to write to BH1750");
        exit(1);
    }

    msg[0].data[0] = BH1750_CONVERSION_TIME;
    if (ioctl(fd, I2C_RDWR, msg) < 0) {
        perror("Failed to wait for conversion");
        exit(1);
    }

    msg[0].data[0] = BH1750_LUX_MULT;
    if (ioctl(fd, I2C_RDWR, msg) < 0) {
        perror("Failed to read lux value");
        exit(1);
    }

    lux = msg[0].data[0] / 1.2;

    msg[0].data[0] = BH1750_LUX_DIV;
    if (ioctl(fd, I2C_RDWR, msg) < 0) {
        perror("Failed to read lux value");
        exit(1);
    }

    lux = msg[0].data[0] / 1.2;

    for (int i = 0; i < 3; i++) {
        fd = open("/dev/gpiod", O_RDONLY);
        if (fd < 0) {
            perror("Failed to open gpiod");
            exit(1);
        }
        chip = gpiod_chip_open(fd);
        if (!chip) {
            perror("Failed to open gpiod chip");
            exit(1);
        }
        for (int j = 0; j < 3; j++) {
            line = gpiod_chip_get_line(chip, RED_RELAY + j);
            if (!line) {
                perror("Failed to get GPIO line");
                exit(1);
            }
            gpioline[j].fd = fd;
            gpioline[j].chip = chip;
            gpioline[j].line = line;
            gpiod_line_request_edge(line, GPIOD_EDGE_BOTH);
            gpioline[j].value = 0;
        }
        gpiod_chip_release(chip);
    }

    while (1) {
        seconds = time(NULL) / 60;
