#define VIBRATION_LOG_FILE "vibration_events.log"
#define VIBRATION_WINDOW_SIZE 5
#define VIBRATION_THRESHOLD 3
#define POLL_TIMEOUT_DEFAULT 1000

volatile sig_atomic_t exit_flag = 0;

void handle_signal(int signum) {
    exit_flag = 1;
    syslog(LOG_INFO, "Received signal %d, exiting gracefully.", signum);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        syslog(LOG_INFO, "Using default poll timeout of 1000 ms.");
        poll_timeout = POLL_TIMEOUT_DEFAULT;
    } else {
        poll_timeout = atoi(argv[1]);
        if (poll_timeout <= 0) {
            syslog(LOG_ERR, "Invalid poll timeout value. Using default 1000 ms.");
            poll_timeout = POLL_TIMEOUT_DEFAULT;
        }
    }

    struct gpiod_line *line;
    struct gpiod_line_request *request;
    struct pollfd pollfd;
    struct timespec ts;
    char buffer[128];
    int fd;
    int events;
    int high_count = 0;
    int window[5];
    int window_index = 0;
    time_t timestamp;
    struct tm *timeinfo;
    char timestamp_str[128];

    // Open vibration log file
    if ((fd = open(VIBRATION_LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644)) < 0) {
        perror("Failed to open vibration log file");
        exit(EXIT_FAILURE);
    }

    // Set up signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Get GPIO17 line
    if ((line = gpiod_get_line_by_number(17)) == NULL) {
        perror("Failed to get GPIO17 line");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Create request for input
    if ((request = gpiod_line_request_input(line)) == NULL) {
        perror("Failed to create input request");
        close(fd);
        gpiod_line_unref(line);
        exit(EXIT_FAILURE);
    }

    // Set up pollfd
    pollfd.fd = request->line->file->fd;
    pollfd.events = POLLIN | POLLERR | POLLHUP | POLLNVAL;
    pollfd.revents = 0;

    // Main loop
    while (!exit_flag) {
        ts.tv_sec = 0;
        ts.tv_nsec = 0;
        clock_gettime(CLOCK_MONOTONIC, &ts);

        if (poll(&pollfd, 1, poll_timeout) < 0) {
            perror("Failed to poll");
            close(fd);
            gpiod_line_unref(line);
            exit(EXIT_FAILURE);
        }

        if (request->line->file->events & POLLIN) {
            int value;
            if (gpiod_line_request_read(request, &value) < 0) {
                perror("Failed to read line value");
                close(fd);
                gpiod_line_unref(line);
                exit(EXIT_FAILURE);
            }

            if (value == 1) {
                high_count++;
                window[window_index] = 1;
                window_index = (window_index + 1) % VIBRATION_WINDOW_SIZE;
                if (high_count >= VIBRATION_THRESHOLD) {
                    time_t now = time(NULL);
                    struct tm *nowinfo = localtime(&now);
                    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", nowinfo);
                    syslog(LOG_INFO, "EARTHQUAKE ALERT: Vibration sensor detected high value at %s", timestamp_str);
                }
            } else {
                high_count = 0;
                window[window_index] = 0;
            }

            // Log event
            if (fprintf(fd, "%ld %d\n", (long)ts.tv_sec, value) < 0) {
                perror("Failed to log event");
                close(fd);
                gpiod_line_unref(line);
                exit(EXIT_FAILURE);
            }
            if (fsync(fd) < 0) {
                perror("Failed to flush log file");
                close(fd);
                gpiod_line_unref(line);
                exit(EXIT_FAILURE);
            }
        }
    }

    // Close log file
    if (close(fd) < 0) {
        perror("Failed to close log file");
        exit(EXIT_FAILURE);
    }

    // Unref line
    gpiod_line_unref(line);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <math.h>
#include <time.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x1E
#define SDA_PIN 2
#define SCL_PIN 3
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

#define X_REG 0x03
#define Y_REG 0x04
#define Z_REG 0x05
#define X_MSB_REG 0x02
#define CRA_REG 0x00

#define CALIBRATE 0x00
#define RATE_15HZ 0x14

#define COMPASS_NORTH 0
#define COMPASS_NE 1
#define COMPASS_E 2
#define COMPASS_SE 3
#define COMPASS_S 4
#define COMPASS_SW 5
#define COMPASS_W 6
#define COMPASS_NW 7

#define MAX_SAMPLES 1000

typedef struct {
    char timestamp[20];
    float calibrated_x;
    float calibrated_y;
    float calibrated_z;
    float heading;
    char direction[3];
} MagData;

int main() {
    int fd;
    struct iocb iocb;
    struct iocm iocm;
    struct i2c_msg msg;
    char buffer[9];
    MagData data[MAX_SAMPLES];
    int i;
    float x, y, z;
    float heading;
    char direction[3];
    char *filename = "mag_log.csv";
    FILE *fp;
    time_t t;
    struct tm *local_time;
    int status;

    if ((fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("open");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl");
        return 1;
    }

    memset(&iocb, 0, sizeof(iocb));
    iocb.ioc_buf = buffer;
    iocb.ioc_nbytes = 9;
    iocb.ioc_flags = I2C_SMBUS_READ;

    memset(&iocm, 0, sizeof(iocm));
    iocm.ioc_cmdtype = I2C_CMD_READ;
    iocm.ioc_offset = 0;
    iocm.ioc_nbytes = 9;

    if (ioctl(fd, I2C_SET_I2C_M, &iocm) < 0) {
        perror("ioctl");
        return 1;
    }

    if (ioctl(fd, I2C_SET_I2C_B, &iocb) < 0) {
        perror("ioctl");
        return 1;
    }

    fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("fopen");
        return 1;
    }

    if (fputs("Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading,Direction\n", fp) == EOF) {
        perror("fputs");
        return 1;
    }

    for (i = 0; i < MAX_SAMPLES; i++) {
        t = time(NULL);
        local_time = localtime(&t);
        strftime(data[i].timestamp, 20, "%Y-%m-%d %H:%M:%S", local_time);

        if (ioctl(fd, I2C_SMBUS_READ, &msg, &iocb, &iocm) < 0) {
            fprintf(stderr, "I2C read failed: %d\n", errno);
            continue;
        }

        memcpy(&buffer, msg.ioctl.ioctl_buf, msg.ioctl.ioc_nbytes);

        x = (buffer[0] << 8) | buffer[1];
        y = (buffer[2] << 8) | buffer[3];
        z = (buffer[4] << 8) | buffer[5];

        x -= X_OFFSET;
        y -= Y_OFFSET;
        z -= Z_OFFSET;

        heading = atan2f(y, x) * 180.0 / M_PI;
        heading = heading < 0 ? heading + 360.0 : heading;

        switch ((int)(heading / 45.0)) {
            case COMPASS_NORTH:
                strcpy(direction, "N");
                break;
            case COMPASS_NE:
                strcpy(direction, "NE");
                break;
            case COMPASS_E:
                strcpy(direction, "E");
                break;
            case COMPASS_SE:
                strcpy(direction, "SE");
                break;
            case COMPASS_S:
                strcpy(direction, "S");
                break;
            case COMPASS_SW:
                strcpy(direction, "SW");
                break;
            case COMPASS_W:
                strcpy(direction, "W");
                break;
            case COMPASS_NW:
                strcpy(direction, "NW");
                break;
        }

        data[i].calibrated_x = x;
        data[i].calibrated_y = y;
        data[i].calibrated_z = z;
        data[i].heading = heading;
        strcpy(data[i].direction, direction);

        if (fprintf(fp, "%s,%f,%f,%f,%f,%s\n", data[i].timestamp, data[i].calibrated_x, data[i].calibrated_y, data[i].calibrated_z, data[i].heading, data[i].direction) < 0) {
            perror("fprintf");
            return 1;
        }

        if (fclose(fp) < 0) {
            perror("fclose");
            return 1;
        }

        fp = fopen(filename, "a");
        if (fp == NULL) {
            perror("fopen");
            return 1;
        }
    }

    if (fclose(fp) < 0) {
        perror("fclose");
        return 1;
    }

    for (i = 0; i < MAX_SAMPLES; i++) {
        free(data[i].timestamp);
        free(data[i].direction);
    }

    close(fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>

#define RELAY_COUNT 4
#define RELAY_GPIO[RELAY_COUNT] {17, 23, 24, 25}
#define RELAY_PIN_COUNT 4
#define RELAY_PIN[RELAY_PIN_COUNT] {1, 1, 1, 1}
#define RELAY_TIMEOUT 5000
#define RELAY_GAP 1000
#define LOG_FILE "irrigation_log.txt"

void log_irrigation(int relay_num, int moisture_level) {
    char buffer[256];
    struct tm *timeinfo;
    time_t rawtime;
    FILE *log_file;

    rawtime = time(NULL);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    fprintf(log_file, "%s %d %d\n", buffer, relay_num, moisture_level);
    fflush(log_file);
    fclose(log_file);
}

void activate_relay(int relay_num) {
    int gpio_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;

    gpio_fd = gpiod_open("/dev/gpiod");
    if (gpio_fd < 0) {
        perror("Failed to open gpiod");
        exit(EXIT_FAILURE);
    }

    chip = gpiod_get_chip(gpio_fd);
    if (chip == NULL) {
        perror("Failed to get chip");
        gpiod_close(gpio_fd);
        exit(EXIT_FAILURE);
    }

    line = gpiod_get_line(chip, RELAY_GPIO[relay_num]);
    if (line == NULL) {
        perror("Failed to get line");
        gpiod_close(gpio_fd);
        gpiod_chip_free(chip);
        exit(EXIT_FAILURE);
    }

    edge = gpiod_get_edge(line, GPIOD_EDGE_BOTH);
    if (edge == NULL) {
        perror("Failed to get edge");
        gpiod_close(gpio_fd);
        gpiod_chip_free(chip);
        gpiod_line_free(line);
        exit(EXIT_FAILURE);
    }

    gpiod_edge_request_edge(edge, GPIOD_EDGE_REQUEST_EDGE);
    gpiod_edge_enable(edge, GPIOD_EDGE_BOTH);

    gpiod_line_request_output(line, RELAY_PIN[relay_num]);
    gpiod_line_request_drive(line, 0);

    gpiod_line_request_value(line, 0);
    gpiod_line_request_edge(line, GPIOD_EDGE_BOTH);

    gpiod_chip_request_close(chip);
    gpiod_chip_free(chip);
    gpiod_line_request_close(line);
    gpiod_line_free(line);
    gpiod_edge_request_close(edge);
    gpiod_edge_free(edge);
    gpiod_close(gpio_fd);
}

void deactivate_relay(int relay_num) {
    int gpio_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;

    gpio_fd = gpiod_open("/dev/gpiod");
    if (gpio_fd < 0) {
        perror("Failed to open gpiod");
        exit(EXIT_FAILURE);
    }

    chip = gpiod_get_chip(gpio_fd);
    if (chip == NULL) {
        perror("Failed to get chip");
        gpiod_close(gpio_fd);
        exit(EXIT_FAILURE);
    }

    line = gpiod_get_line(chip, RELAY_GPIO[relay_num]);
    if (line == NULL) {
        perror("Failed to get line");
        gpiod_close(gpio_fd);
        gpiod_chip_free(chip);
        exit(EXIT_FAILURE);
    }

    edge = gpiod_get_edge(line, GPIOD_EDGE_BOTH);
    if (edge == NULL) {
        perror("Failed to get edge");
        gpiod_close(gpio_fd);
        gpiod_chip_free(chip);
        gpiod_line_free(line);
        exit(EXIT_FAILURE);
    }

    gpiod_edge_request_edge(edge, GPIOD_EDGE_REQUEST_EDGE);
    gpiod_edge_enable(edge, GPIOD_EDGE_BOTH);

    gpiod_line_request_output(line, RELAY_PIN[relay_num]);
    gpiod_line_request_drive(line, 1);

    gpiod_line_request_value(line, 1);
    gpiod_line_request_edge(line, GPIOD_EDGE_BOTH);

    gpiod_chip_request_close(chip);
    gpiod_chip_free(chip);
    gpiod_line_request_close(line);
    gpiod_line_free(line);
    gpiod_edge_request_close(edge);
    gpiod_edge_free(edge);
    gpiod_close(gpio_fd);
}

void handle_signal(int signum) {
    int i;
    for (i = 0; i < RELAY_COUNT; i++) {
        activate_relay(i);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    int moisture_level;
    srand(time(NULL));
    struct sigaction sa;

    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);

    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        moisture_level = rand() % 101;
        log_irrigation(moisture_level / 10, moisture_level);

        if (moisture_level < 30) {
            for (int i = 0; i < RELAY_COUNT; i++) {
                activate_relay(i);
                usleep(RELAY_TIMEOUT * 1000);
                deactivate_relay(i);
                usleep(RELAY_GAP * 1000);
            }
        }

        usleep(10 * 1000);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <sys/time.h>
#include <pigpio.h>

volatile sig_atomic_t stop = 0;
volatile sig_atomic_t watering = 0;
volatile sig_atomic_t wateringDone = 0;

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    int moistureValues[] = {20, 40, 60, 80, 100};
    int moistureIndex = 0;

    while (!stop) {
        if (stop) {
            break;
        }

        if (watering) {
            if (stop) {
                break;
            }

            int moisture = moistureValues[moistureIndex];
            if (moisture >= 50) {
                wateringDone = 1;
                break;
            }

            int servoValveClosed = 500;
            int servoValveOpen = 1500;
            int servoNozzleAngles[] = {500, 1750, 1500, 1250, 1000};

            for (int i = 0; i < 5; i++) {
                int servoAngle = servoNozzleAngles[i];
                if (gpioServo(17, servoAngle) < 0) {
                    int attempts = 0;
                    while (attempts < 3) {
                        usleep(100000);
                        attempts++;
                        if (gpioServo(17, servoAngle) < 0) {
                            fprintf(stderr, "Valve servo failed to open at %d degrees\n", servoAngle);
                            if (i == 4) {
                                fprintf(stderr, "Critical warning: Valve servo failed to open\n");
                            }
                            break;
                        }
                    }
                    if (attempts == 3) {
                        fprintf(stderr, "Valve servo failed to open after 3 attempts\n");
                        gpioTerminate();
                        return 1;
                    }
                }

                if (gpioServo(18, servoAngle) < 0) {
                    int attempts = 0;
                    while (attempts < 3) {
                        usleep(100000);
                        attempts++;
                        if (gpioServo(18, servoAngle) < 0) {
                            fprintf(stderr, "Nozzle servo failed to move to %d degrees\n", servoAngle);
                            break;
                        }
                    }
                    if (attempts == 3) {
                        fprintf(stderr, "Nozzle servo failed to move after 3 attempts\n");
                        gpioTerminate();
                        return 1;
                    }
                }

                usleep(2000000); // 2 seconds per step
            }

            usleep(500000); // 5 seconds hold
            if (gpioServo(17, servoValveClosed) < 0) {
                int attempts = 0;
                while (attempts < 3) {
                    usleep(100000);
                    attempts++;
                    if (gpioServo(17, servoValveClosed) < 0) {
                        fprintf(stderr, "Valve servo failed to close after %d attempts\n", attempts);
                        break;
                    }
                }
                if (attempts == 3) {
                    fprintf(stderr, "Valve servo failed to close after 3 attempts\n");
                    gpioTerminate();
                    return 1;
                }
            }

            usleep(500000); // 5 seconds hold
            moistureIndex = (moistureIndex + 1) % 5;
        }

        usleep(500000); // 5 seconds between cycles
    }

    if (wateringDone) {
        fprintf(stderr, "Watering cycle completed\n");
    } else {
        fprintf(stderr, "No watering cycle completed\n");
    }

    gpioTerminate();
    return 0;
}

void signalHandler(int signum) {
    stop = 1;
    if (watering) {
        gpioServo(17, 0);
        gpioServo(18, 0);
    }
    exit(0);
}

int main() {
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);
    return main();
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>

#define MPU6050_ADDR 0x68
#define GYRO_XOUT_H 0x43
#define PWR_MGMT_1 0x6B
#define I2C_BUS 1

void init_i2c() {
    int fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        exit(EXIT_FAILURE);
    }
}

void read_gyroscope_data(int fd, uint8_t* buffer) {
    uint8_t reg = 0x43;
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write to GYRO_XOUT_H register");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (read(fd, buffer, 6) != 6) {
        perror("Failed to read GYRO_XOUT_H register");
        close(fd);
        exit(EXIT_FAILURE);
    }
}

void convert_and_log(int fd, uint8_t* buffer, double* x, double* y, double* z) {
    *x = (buffer[0] << 8) | buffer[1];
    *y = (buffer[2] << 8) | buffer[3];
    *z = (buffer[4] << 8) | buffer[5];

    *x *= 131.0 / 1000.0; // Convert to deg/sec
    *y *= 131.0 / 1000.0;
    *z *= 131.0 / 1000.0;

    fprintf(stderr, "Timestamp: %ld, X: %f, Y: %f, Z: %f\n", (long)time(NULL), *x, *y, *z);
}

void handle_sensor_absent(int fd) {
    fprintf(stderr, "Sensor absent or I2C bus error\n");
    close(fd);
    exit(EXIT_FAILURE);
}

void handle_sigint(int signum) {
    fprintf(stderr, "Caught SIGINT signal, exiting...\n");
    close(fd);
    exit(EXIT_SUCCESS);
}

int main() {
    double x, y, z;
    int fd = 0;
    uint8_t buffer[6];

    init_i2c();
    fd = open("/dev/log", O_WRONLY | O_CREAT, 0644);
    if (fd < 0) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    while (1) {
        read_gyroscope_data(fd, buffer);
        convert_and_log(fd, buffer, &x, &y, &z);
        sleep(0.1); // Sample at 10 Hz
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN_1 4
#define GPIO_PIN_2 17
#define GPIO_PIN_3 27
#define GPIO_PIN_4 22
#define GPIO_PIN_LOCK 24
#define GPIO_PIN_UNLOCK 23

#define STEP_DELAY 3000  // 3 ms
#define DEBOUNCE_DELAY 100  // 100 ms

int main() {
    int ret;
    int lock_state = 0;
    int unlock_state = 0;
    int steps = 0;
    int direction = 1;  // 1 for clockwise, -1 for counter-clockwise

    if ((ret = gpioInitialise()) < 0) {
        fprintf(stderr, "gpioInitialise() failed: %d\n", ret);
        return 1;
    }

    gpioSetMode(GPIO_PIN_1, PI_OUTPUT);
    gpioSetMode(GPIO_PIN_2, PI_OUTPUT);
    gpioSetMode(GPIO_PIN_3, PI_OUTPUT);
    gpioSetMode(GPIO_PIN_4, PI_OUTPUT);
    gpioSetMode(GPIO_PIN_LOCK, PI_INPUT);
    gpioSetMode(GPIO_PIN_UNLOCK, PI_INPUT);
    gpioSetPullDownMode(GPIO_PIN_LOCK, PI_PUD_UP);
    gpioSetPullDownMode(GPIO_PIN_UNLOCK, PI_PUD_UP);

    signal(SIGINT, handleInterrupt);

    while (1) {
        int current_lock_state = gpioRead(GPIO_PIN_LOCK);
        int current_unlock_state = gpioRead(GPIO_PIN_UNLOCK);

        if (current_lock_state && !lock_state) {
            lock_state = 1;
            printf("LOCK pressed\n");
            steps = 0;
            direction = 1;
        } else if (!current_lock_state && lock_state) {
            lock_state = 0;
            printf("LOCK released\n");
        }

        if (current_unlock_state && !unlock_state) {
            unlock_state = 1;
            printf("UNLOCK pressed\n");
            steps = 0;
            direction = -1;
        } else if (!current_unlock_state && unlock_state) {
            unlock_state = 0;
            printf("UNLOCK released\n");
        }

        if (lock_state || unlock_state) {
            int step = 0;
            for (int i = 0; i < 4; i++) {
                if (lock_state && i % 2 == 0) {
                    gpioWrite(GPIO_PIN_1, 1);
                    gpioWrite(GPIO_PIN_2, 0);
                    gpioWrite(GPIO_PIN_3, 0);
                    gpioWrite(GPIO_PIN_4, 0);
                } else if (unlock_state && i % 2 == 0) {
                    gpioWrite(GPIO_PIN_1, 0);
                    gpioWrite(GPIO_PIN_2, 1);
                    gpioWrite(GPIO_PIN_3, 0);
                    gpioWrite(GPIO_PIN_4, 0);
                } else if (lock_state && i % 2 == 1) {
                    gpioWrite(GPIO_PIN_1, 0);
                    gpioWrite(GPIO_PIN_2, 0);
                    gpioWrite(GPIO_PIN_3, 1);
                    gpioWrite(GPIO_PIN_4, 0);
                } else if (unlock_state && i % 2 == 1) {
                    gpioWrite(GPIO_PIN_1, 0);
                    gpioWrite(GPIO_PIN_2, 0);
                    gpioWrite(GPIO_PIN_3, 0);
                    gpioWrite(GPIO_PIN_4, 1);
                }
                gpioSetMode(GPIO_PIN_1, PI_OFF);
                gpioSetMode(GPIO_PIN_2, PI_OFF);
                gpioSetMode(GPIO_PIN_3, PI_OFF);
                gpioSetMode(GPIO_PIN_4, PI_OFF);
                gpioDelay(DEBOUNCE_DELAY);
                if (lock_state && direction == 1) {
                    step = 1;
                } else if (unlock_state && direction == -1) {
                    step = -1;
                }
                if (step) {
                    gpioWrite(GPIO_PIN_1, 1);
                    gpioWrite(GPIO_PIN_2, 0);
                    gpioWrite(GPIO_PIN_3, 0);
                    gpioWrite(GPIO_PIN_4, 0);
                    gpioDelay(STEP_DELAY);
                    gpioWrite(GPIO_PIN_1, 0);
                    gpioWrite(GPIO_PIN_2, 1);
                    gpioWrite(GPIO_PIN_3, 0);
                    gpioWrite(GPIO_PIN_4, 0);
                    gpioDelay(STEP_DELAY);
                    gpioWrite(GPIO_PIN_1, 0);
                    gpioWrite(GPIO_PIN_2, 0);
                    gpioWrite(GPIO_PIN_3, 1);
                    gpioWrite(GPIO_PIN_4, 0);
                    gpioDelay(STEP_DELAY);
                    gpioWrite(GPIO_PIN_1, 0);
                    gpioWrite(GPIO_PIN_2, 0);
                    gpioWrite(GPIO_PIN_3, 0);
                    gpioWrite(GPIO_PIN_4, 1);
                    gpioDelay(STEP_DELAY);
                }
            }
            steps += direction;
            if (steps >= 512) {
                direction = -1;
                steps -= 512;
            } else if (steps <= -512) {
                direction = 1;
                steps += 512;
            }
        }

        if (lock_state || unlock_state) {
            gpioSetMode(GPIO_PIN_1, PI_OUTPUT);
            gpioSetMode(GPIO_PIN_2, PI_OUTPUT);
            gpioSetMode(GPIO_PIN_3, PI_OUTPUT);
            gpioSetMode(GPIO_PIN_4, PI_OUTPUT);
        } else {
            gpioSetMode(GPIO_PIN_1, PI_OFF);
            gpioSetMode(GPIO_PIN_2, PI_OFF);
            gpioSetMode(GPIO_PIN_3, PI_OFF);
            gpioSetMode(GPIO_PIN_4, PI_OFF);
        }
    }

    return 0;
}

void handleInterrupt(int signum) {
    printf("Interrupt received, de-energizing coils...\n");
    gpioTerminate();
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>

#define GPIO17 17
#define GPIO18 18
#define TRIGGER 0
#define ECHO 1
#define SPEED_OF_SOUND 343000  // m/s
#define DISTANCE_CM 0.01715  // cm/us
#define TIMEOUT_US 50000  // 50 ms
#define MIN_GUARD_TIME 60000  // 60 ms

int gpiod_fd;
struct gpiod_chip *chip;
struct gpiod_line *line;

void handle_gpio_error(int err) {
    fprintf(stderr, "GPIO error: %d\n", err);
    if (gpiod_fd != -1) {
        gpiod_close(gpiod_fd);
        gpiod_fd = -1;
    }
    if (chip) {
        gpiod_chip_free(chip);
        chip = NULL;
    }
    if (line) {
        gpiod_line_free(line);
        line = NULL;
    }
    exit(EXIT_FAILURE);
}

void handle_timeout() {
    fprintf(stderr, "Timeout error\n");
    if (gpiod_fd != -1) {
        gpiod_close(gpiod_fd);
        gpiod_fd = -1;
    }
    if (chip) {
        gpiod_chip_free(chip);
        chip = NULL;
    }
    if (line) {
        gpiod_line_free(line);
        line = NULL;
    }
    exit(EXIT_FAILURE);
}

void handle_signal(int signum) {
    if (gpiod_fd != -1) {
        gpiod_close(gpiod_fd);
        gpiod_fd = -1;
    }
    if (chip) {
        gpiod_chip_free(chip);
        chip = NULL;
    }
    if (line) {
        gpiod_line_free(line);
        line = NULL;
    }
    if (fopen(distance_log.txt, "a") == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        exit(EXIT_FAILURE);
    }
    fclose(distance_log);
    exit(EXIT_SUCCESS);
}

int main() {
    struct gpiod_line *line;
    int trigger, echo;
    int distance_cm;
    char log_buffer[256];
    FILE *distance_log;

    if (signal(SIGINT, handle_signal) == SIG_ERR) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        exit(EXIT_FAILURE);
    }
    if (signal(SIGTERM, handle_signal) == SIG_ERR) {
        fprintf(stderr, "Failed to set SIGTERM handler\n");
        exit(EXIT_FAILURE);
    }

    gpiod_fd = gpiod_open("/dev/gpiod", O_RDWR);
    if (gpiod_fd == -1) {
        handle_gpio_error(gpiod_errno(gpiod_fd));
    }

    chip = gpiod_chip_open(gpiod_fd);
    if (chip == NULL) {
        handle_gpio_error(gpiod_errno(gpiod_fd));
    }

    line = gpiod_chip_get_line(chip, GPIO17, TRIGGER);
    if (line == NULL) {
        handle_gpio_error(gpiod_errno(gpiod_fd));
    }

    line = gpiod_chip_get_line(chip, GPIO18, ECHO);
    if (line == NULL) {
        handle_gpio_error(gpiod_errno(gpiod_fd));
    }

    if (gpiod_line_request_output(line, 1) == -1) {
        handle_gpio_error(gpiod_errno(gpiod_fd));
    }

    if (gpiod_line_request_input(line, 1) == -1) {
        handle_gpio_error(gpiod_errno(gpiod_fd));
    }

    distance_log = fopen("distance_log.txt", "a");
    if (distance_log == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        exit(EXIT_FAILURE);
    }

    while (1) {
        usleep(MIN_GUARD_TIME);

        gpiod_line_request_trigger(line, 1);
        usleep(10);
        gpiod_line_request_output(line, 0);
        usleep(10);

        gpiod_line_request_input(line, 1);
        int start_us = 0;
        int end_us = 0;
        int duration_us = 0;
        int timeout = 0;

        while (timeout < TIMEOUT_US) {
            usleep(1);
            if (gpiod_line_get_value(line, 1) == 1) {
                start_us = micros();
            } else if (start_us != 0) {
                end_us = micros();
                duration_us = end_us - start_us;
                distance_cm = (int)(duration_us * DISTANCE_CM);
                snprintf(log_buffer, sizeof(log_buffer), "%d\n", distance_cm);
                if (fwrite(log_buffer, 1, strlen(log_buffer), distance_log) != strlen(log_buffer)) {
                    fprintf(stderr, "Failed to write to log file\n");
                    fclose(distance_log);
                    exit(EXIT_FAILURE);
                }
                break;
            }
            timeout++;
        }

        if (timeout == TIMEOUT_US) {
            fprintf(stderr, "Timeout\n");
            snprintf(log_buffer, sizeof(log_buffer), "-1\n");
            if (fwrite(log_buffer, 1, strlen(log_buffer), distance_log) != strlen(log_buffer)) {
                fprintf(stderr, "Failed to write to log file\n");
                fclose(distance_log);
                exit(EXIT_FAILURE);
            }
        }

        gpiod_line_request_output(line, 1);
        gpiod_line_request_trigger(line, 0);
        usleep(10);

        gpiod_line_request_input(line, 0);
        gpiod_line_request_trigger(line, 1);
        usleep(10);

        gpiod_line_request_output(line, 0);
        gpiod_line_request_trigger(line, 0);
    }

    fclose(distance_log);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <pigpio/i2c.h>

#define VL53L1X_ADDR 0x29
#define VL53L1X_RESET 0x0000
#define VL53L1X_MODE 0x0080
#define VL53L1X_START 0x01
#define VL53L1X_STATUS 0x0044
#define VL53L1X_RESULT_MSB 0x0096
#define VL53L1X_RESULT_LSB 0x0097
#define VL53L1X_RESULT 0x0096 | 0x0001

#define DISTANCE_THRESHOLD 50
#define POLL_INTERVAL 100000  // 100 ms

volatile int sigint_received = 0;

void handle_sigint(int signum) {
    if (sigint_received) {
        printf("Received SIGINT, shutting down...\n");
        gpioTerminate();
        gpioTerminateI2C();
        gpioWrite(18, 0);  // Set relay to LOW
        exit(0);
    }
    sigint_received = 1;
}

int main() {
    struct i2c_msg messages[1];
    struct i2c_rdwr_ioctl_data data;
    int i2c_fd;
    int status;
    int distance;
    int mode;
    int status_register;
    int interrupt_status;
    int result;

    signal(SIGINT, handle_sigint);

    if (gpioInitialise() < 0) {
        perror("pigpioInitialise");
        return 1;
    }

    if (gpioSetMode(18, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        return 1;
    }

    if (gpioSetPullUpDown(18, PI_PUD_OFF) < 0) {
        perror("gpioSetPullUpDow");
        return 1;
    }

    if ((i2c_fd = i2cOpen(1)) < 0) {
        perror("i2cOpen");
        return 1;
    }

    // Software reset
    if (i2cWrite(i2c_fd, 1, VL53L1X_ADDR, VL53L1X_RESET, 1) < 0) {
        perror("i2cWrite");
        return 1;
    }

    // Set mode to continuous ranging
    if (i2cWrite(i2c_fd, 1, VL53L1X_ADDR, VL53L1X_MODE, VL53L1X_START) < 0) {
        perror("i2cWrite");
        return 1;
    }

    // Set up polling loop
    while (!sigint_received) {
        data.msgs[0].addr = VL53L1X_ADDR;
        data.msgs[0].flags = I2C_MSG_WRITE;
        data.msgs[0].len = 1;
        data.msgs[0].buf[0] = VL53L1X_STATUS;

        if (i2cIoctl(i2c_fd, I2C_RDWR, &data, messages, 1) < 0) {
            perror("i2cIoctl");
            return 1;
        }

        if (messages[0].flags & I2C_MSG_ERROR) {
            status = messages[0].buf[0];
            if (status == I2C_ERROR) {
                printf("I2C error: %d\n", status);
            } else {
                printf("I2C error: %d\n", status);
            }
            continue;
        }

        interrupt_status = messages[0].buf[0];
        if (interrupt_status & 0x01) {
            // Data ready
            if (i2cRead(i2c_fd, 1, VL53L1X_ADDR, VL53L1X_RESULT, messages, 1) < 0) {
                perror("i2cRead");
                return 1;
            }

            if (messages[0].flags & I2C_MSG_ERROR) {
                status = messages[0].buf[0];
                if (status == I2C_ERROR) {
                    printf("I2C error: %d\n", status);
                } else {
                    printf("I2C error: %d\n", status);
                }
                continue;
            }

            result = messages[0].buf[0];
            distance = (result & 0xFF00) >> 8;
            distance |= (result & 0x00FF);

            if (distance <= DISTANCE_THRESHOLD) {
                printf("Distance: %d cm, Door opened\n", distance);
                gpioWrite(18, 1);  // Set relay to HIGH
            } else {
                printf("Distance: %d cm, Door closed\n", distance);
                gpioWrite(18, 0);  // Set relay to LOW
            }
        } else {
            printf("No data ready\n");
        }

        // Poll every 100 ms
        usleep(POLL_INTERVAL);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x68
#define MPU6050_REG_PWR_MGMT_1 0x6B
#define MPU6050_REG_GYRO_CONFIG 0x1B
#define MPU6050_REG_GYRO_XOUT_H 0x43

#define MPU6050_GYRO_SENSITIVITY 131.0

int i2c_fd;

void i2c_init() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open i2c bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set slave address");
        exit(EXIT_FAILURE);
    }
}

void i2c_deinit() {
    close(i2c_fd);
}

void i2c_read_register(int reg) {
    char buffer[2];
    ssize_t bytes_read;

    if ((bytes_read = write(i2c_fd, &reg, 1)) != 1) {
        perror("Failed to write to I2C register");
        exit(EXIT_FAILURE);
    }

    if ((bytes_read = read(i2c_fd, buffer, 2)) != 2) {
        perror("Failed to read from I2C register");
        exit(EXIT_FAILURE);
    }

    printf("Register 0x%02x: %d %d\n", reg, buffer[0], buffer[1]);
}

void i2c_write_register(int reg, int value) {
    char buffer[2];
    buffer[0] = reg;
    buffer[1] = value;

    if (write(i2c_fd, buffer, 2) != 2) {
        perror("Failed to write to I2C register");
        exit(EXIT_FAILURE);
    }
}

void i2c_read_gyro_data() {
    char buffer[6];
    ssize_t bytes_read;

    if ((bytes_read = read(i2c_fd, buffer, 6)) != 6) {
        perror("Failed to read from I2C register");
        exit(EXIT_FAILURE);
    }

    int x = (buffer[0] << 8) | buffer[1];
    int y = (buffer[2] << 8) | buffer[3];
    int z = (buffer[4] << 8) | buffer[5];

    double x_deg_per_sec = (double)x * MPU6050_GYRO_SENSITIVITY / 32768.0;
    double y_deg_per_sec = (double)y * MPU6050_GYRO_SENSITIVITY / 32768.0;
    double z_deg_per_sec = (double)z * MPU6050_GYRO_SENSITIVITY / 32768.0;

    printf("Gyroscope: %.2f, %.2f, %.2f dps\n", x_deg_per_sec, y_deg_per_sec, z_deg_per_sec);
}

void i2c_handle_error(int error) {
    if (error == -EIO) {
        printf("I2C bus error\n");
    } else if (error == -EBUSY) {
        printf("I2C bus busy\n");
    } else {
        perror("I2C error");
    }
}

void i2c_signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        i2c_deinit();
        exit(EXIT_SUCCESS);
    }
}

int main() {
    struct sigaction sa;

    sa.sa_handler = i2c_signal_handler;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        exit(EXIT_FAILURE);
    }

    i2c_init();

    i2c_write_register(MPU6050_REG_PWR_MGMT_1, 0x00); // Wake up the sensor
    i2c_write_register(MPU6050_REG_GYRO_CONFIG, 0x01); // Set full-scale range to ±250 dps

    while (1) {
        i2c_read_gyro_data();
        sleep(0.1); // Read every 100ms
    }

    return 0;
}

