        perror("Failed to get GPIO chip");
        close(fd);
        return 1;
    }

    if (gpiod_request_chip(chip, GPIO_CHIP, &line) < 0) {
        perror("Failed to request GPIO line");
        gpiod_free_chip(chip);
        close(fd);
        return 1;
    }

    for (i = 0; i < 4; i++) {
