            gpiod_free_chip(chip);
            gpiod_free_line(line);
            gpiod_free_edge(edge);
            for (int j = 0; j < 4; j++) {
                gpiod_free_line(line);
                gpiod_free_chip(chip);
                close(fd);
                return 1;
            }
        }
    }

    if (clock_gettime(CLOCK_MONOTONIC, &ts) < 0) {
        perror("Failed to get current time");
        return 1;
    }

    if (fprintf(stderr, "Watering system started at %s\n", ctime(&ts.tv_sec))) {
        return 1;
    }

    while (1) {
        if (clock_gettime(CLOCK_MONOTONIC, &ts) < 0) {
            perror("Failed to get current time");
            return 1;
        }

        if (difftime(ts.tv_sec, now) >= 86400) {
            now = time(NULL);
            if (fprintf(stderr, "Watering cycle started at %s\n", ctime(&now))) {
                return 1;
            }

            for (i = 0; i < 4; i++) {
                if (gpiod_set_value(state, 0) < 0) {
                    perror("Failed to set GPIO value");
                    gpiod_free_chip(chip);
                    gpiod_free_line(line);
                    gpiod_free_edge(edge);
                    for (int j = 0; j < 4; j++) {
                        gpiod_free_line(line);
                        gpiod_free_chip(chip);
                        close(fd);
                        return 1;
                    }
                }

                if (gpiod_request_edge(line, GPIOD_EDGE_BOTH, &edge) < 0) {
                    perror("Failed to request GPIO edge");
                    gpiod_free_chip(chip);
                    gpiod_free_line(line);
                    gpiod_free_edge(edge);
                    for (int j = 0; j < 4; j++) {
                        gpiod_free_line(line);
                        gpiod_free_chip(chip);
                        close(fd);
                        return 1;
                    }
                }

                if (gpiod_request_state(line, GPIOD_STATE_OUTPUT, &state) < 0) {
                    perror("Failed to request GPIO state");
                    gpiod_free_chip(chip);
                    gpiod_free_line(line);
                    gpiod_free_edge(edge);
                    for (int j = 0; j < 4; j++) {
                        gpiod_free_line(line);
                        gpiod_free_chip(chip);
                        close(fd);
                        return 1;
                    }
                }

                if (gpiod_set_value(state, 1) < 0) {
                    perror("Failed to set GPIO value");
                    gpiod_free_chip(chip);
                    gpiod_free_line(line);
                    gpiod_free_edge(edge);
                    for (int j = 0; j < 4; j++) {
                        gpiod_free_line(line);
                        gpiod_free_chip(chip);
                        close(fd);
                        return 1;
                    }
                }

                if (sleep(5) < 0) {
                    perror("Failed to sleep");
                    return 1;
                }

                if (gpiod_set_value(state, 0) < 0) {
                    perror("Failed to set GPIO value");
                    gpiod_free_chip(chip);
                    gpiod_free_line(line);
                    gpiod_free_edge(edge);
                    for (int j = 0; j < 4; j++) {
                        gpiod_free_line(line);
                        gpiod_free_chip(chip);
                        close(fd);
                        return 1;
                    }
                }
            }

            if (fprintf(stderr, "Watering cycle ended at %s\n", ctime(&now))) {
                return 1;
            }
        }

        if (clock_gettime(CLOCK_MONOTONIC, &ts) < 0) {
            perror("Failed to get current time");
            return 1;
        }

        if (difftime(ts.tv_sec, now) >= 60) {
            now = time(NULL);
            if (fprintf(stderr, "Watering system polling at %s\n", ctime(&now))) {
                return 1;
            }
        }
    }

    gpiod_free_chip(chip);
    gpiod_free_line(line);
    gpiod_free_edge(edge);
    for (int j = 0; j < 4; j++) {
        gpiod_free_line(line);
        gpiod_free_chip(chip);
        close(fd);
    }

    return 0;
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        gpiod_free_chip(chip);
        gpiod_free_line(line);
        gpiod_free_edge(edge);
        for (int j = 0; j < 4; j++) {
            gpiod_free_line(line);
            gpiod_free_chip(chip);
            close(fd);
        }
        exit(EXIT_SUCCESS);
    }
}

int main() {
    struct sigaction sa;

    sa.sa_handler = signal_handler;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set SIGINT handler");
        return 1;
    }

    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set SIGTERM handler");
        return 1;
    }

    return main();
}

