void log_error(const char *message, int level) {
    time_t rawtime;
    struct tm * timeinfo;
    char buffer[128];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, 128, "%Y-%m-%d %H:%M:%S", timeinfo);

    switch (level) {
        case 0:
            syslog(LOG_ERR, "%s: %s", buffer, message);
            break;
        case 1:
            syslog(LOG_WARNING, "%s: %s", buffer, message);
            break;
        case 2:
            syslog(LOG_NOTICE, "%s: %s", buffer, message);
            break;
        case 3:
            syslog(LOG_INFO, "%s: %s", buffer, message);
            break;
        case 4:
            syslog(LOG_DEBUG, "%s: %s", buffer, message);
            break;
    }

    fprintf(stderr, "%s: %s\n", buffer, message);
}

void log_status(const char *message) {
    time_t rawtime;
    struct tm * timeinfo;
    char buffer[128];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, 128, "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(stderr, "%s: %s\n", buffer, message);
}

