#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <syslog.h>
#include <gpiod.h>

#define GPIO17 17
#define GPIO18 18
#define GPIO23 23
#define LOG_FILE "flame_log.txt"
#define DEBOUNCE_INTERVAL 500000  // 50ms in microseconds
#define DEBOUNCE_COUNT 3

int fd_buzzer, fd_led;
int fd_log;
int fd_gpio;

gpiod_chip_t *chip;
gpiod_line_mfd_t *line_mfd;
gpiod_line_cnf_t *line_cnf;
gpiod_line_state_t *line_state;

void handle_gpio_error(int err) {
    if (err < 0) {
        perror("GPIO operation failed");
        gpiod_line_free(line_mfd);
        gpiod_line_free(line_cnf);
        gpiod_line_free(line_state);
        gpiod_chip_free(chip);
        if (fd_log > 0) {
            close(fd_log);
        }
        if (fd_buzzer > 0) {
            close(fd_buzzer);
        }
        if (fd_led > 0) {
            close(fd_led);
        }
        exit(EXIT_FAILURE);
    }
}

void handle_sigint(int signum) {
    if (fd_log > 0) {
        close(fd_log);
    }
    if (fd_buzzer > 0) {
        close(fd_buzzer);
    }
    if (fd_led > 0) {
        close(fd_led);
    }
    if (fd_gpio > 0) {
        close(fd_gpio);
    }
    if (fd_log > 0) {
        close(fd_log);
    }
    if (fd_buzzer > 0) {
        close(fd_buzzer);
    }
    if (fd_led > 0) {
        close(fd_led);
    }
    if (fd_gpio > 0) {
        close(fd_gpio);
    }
    gpiod_line_free(line_mfd);
    gpiod_line_free(line_cnf);
    gpiod_line_free(line_state);
    gpiod_chip_free(chip);
    exit(EXIT_SUCCESS);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_mfd *line_mfd;
    struct gpiod_line_cnf *line_cnf;
    struct gpiod_line_state *line_state;
    int fd_buzzer, fd_led, fd_log;
    int count = 0;
    int flame_detected = 0;
    char log_buffer[256];
    struct timespec ts;

    if (signal(SIGINT, handle_sigint) == SIG_ERR) {
        perror("SIGINT handler setup failed");
        return EXIT_FAILURE;
    }

    if ((fd_gpio = open("/dev/gpiod", O_RDONLY)) < 0) {
        perror("Failed to open /dev/gpiod");
        return EXIT_FAILURE;
    }

    if ((chip = gpiod_chip_open(fd_gpio)) == NULL) {
        handle_gpio_error(-1);
    }

    if ((line = gpiod_chip_get_line(chip, GPIO17)) == NULL) {
        handle_gpio_error(-1);
    }

    if ((line_mfd = gpiod_line_mfd_alloc()) == NULL) {
        handle_gpio_error(-1);
    }

    if ((line_cnf = gpiod_line_cnf_alloc()) == NULL) {
        handle_gpio_error(-1);
    }

    if ((line_state = gpiod_line_state_alloc()) == NULL) {
        handle_gpio_error(-1);
    }

    gpiod_line_mfd_set(line_mfd, line, GPIOD_LINE_MFD_ACTIVE_LOW);
    gpiod_line_cnf_set(line_cnf, line, GPIOD_LINE_CNF_DIR_INPUT);
    gpiod_line_cnf_set(line_cnf, line, GPIOD_LINE_CNF_EDGE_FALLING);
    gpiod_line_state_set(line_state, line, GPIOD_LINE_STATE_LOW);

    if ((fd_buzzer = open("/dev/gpiopwm0", O_RDWR)) < 0) {
        perror("Failed to open /dev/gpiopwm0");
        handle_gpio_error(-1);
    }

    if ((fd_led = open("/dev/gpiopwm2", O_RDWR)) < 0) {
        perror("Failed to open /dev/gpiopwm2");
        handle_gpio_error(-1);
    }

    if ((fd_log = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644)) < 0) {
        perror("Failed to open log file");
        handle_gpio_error(-1);
    }

    if (clock_gettime(CLOCK_MONOTONIC, &ts) < 0) {
        perror("Failed to get current time");
        handle_gpio_error(-1);
    }

    while (1) {
        if (gpiod_line_state_get(line_state, line) == GPIOD_LINE_STATE_HIGH) {
            flame_detected = 1;
        } else {
            flame_detected = 0;
        }

        if (flame_detected) {
            if (count < DEBOUNCE_COUNT) {
                count++;
                if (count == DEBOUNCE_COUNT) {
                    count = 0;
                    flame_detected = 0;
                    break;
                }
            } else {
                count = 0;
                flame_detected = 0;
            }

            if (fd_buzzer > 0) {
                gpiod_pwm_write(fd_buzzer, 1, 1);
            }

            if (fd_led > 0) {
                gpiod_pwm_write(fd_led, 1, 1);
            }

            if (clock_gettime(CLOCK_MONOTONIC, &ts) < 0) {
                handle_gpio_error(-1);
            }

            if (strftime(log_buffer, sizeof(log_buffer), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec)) < 0) {
                handle_gpio_error(-1);
            }

            if (fprintf(fd_log, "%s Flame Detected\n", log_buffer) < 0) {
                handle_gpio_error(-1);
            }

            if (fflush(fd_log) < 0) {
                handle_gpio_error(-1);
            }

            if (fsync(fd_log) < 0) {
                handle_gpio_error(-1);
            }
        } else {
            if (fd_buzzer > 0) {
                gpiod_pwm_write(fd_buzzer, 0, 1);
            }

            if (fd_led > 0) {
                gpiod_pwm_write(fd_led, 0, 1);
            }
        }

        usleep(DEBOUNCE_INTERVAL);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/time.h>
#include <pigpio.h>

#define GPIO17 17
#define GPIO27 27
#define LOG_FILE "dispense_log.txt"
#define LOG_FORMAT "%Y-%m-%d %H:%M:%S,%d,%d,%d\n"

int init_pigpio() {
    if (gpioInitialise() < 0) {
        perror("pigpioInitialise");
        return 1;
    }
    return 0;
}

int set_gpio_output(int pin, int value) {
    if (gpioSetMode(pin, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        return 1;
    }
    if (gpioWrite(pin, value) < 0) {
        perror("gpioWrite");
        return 1;
    }
    return 0;
}

int activate_solenoid(int pin, int duration_ms) {
    if (gpioSetMode(pin, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        return 1;
    }
    if (gpioWrite(pin, 1) < 0) {
        perror("gpioWrite");
        return 1;
    }
    gpioDelay(duration_ms * 1000);
    gpioWrite(pin, 0);
    return 0;
}

int log_dispense(int solenoid1, int solenoid2, int duration_ms) {
    FILE *log_file;
    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        perror("fopen");
        return 1;
    }
    struct timeval now;
    gettimeofday(&now, NULL);
    fprintf(log_file, LOG_FORMAT, now.tv_sec, now.tv_usec / 1000000, solenoid1, solenoid2, duration_ms);
    fclose(log_file);
    return 0;
}

void sigint_handler(int signum) {
    gpioTerminate();
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);

    if (init_pigpio() != 0) {
        fprintf(stderr, "pigpioInitialise failed\n");
        return 1;
    }

    if (set_gpio_output(GPIO17, 0) != 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        return 1;
    }
    if (set_gpio_output(GPIO27, 0) != 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        return 1;
    }

    while (1) {
        if (activate_solenoid(GPIO17, 500) != 0) {
            fprintf(stderr, "activate_solenoid failed\n");
            return 1;
        }
        if (activate_solenoid(GPIO27, 500) != 0) {
            fprintf(stderr, "activate_solenoid failed\n");
            return 1;
        }
        if (log_dispense(GPIO17, GPIO27, 1000) != 0) {
            fprintf(stderr, "log_dispense failed\n");
            return 1;
        }
        sleep(5);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define LOG_FILE "balance_log.txt"
#define PID_KP 1.0
#define PID_KI 0.01
#define PID_KD 0.1
#define CONTROL_INTERVAL_MS 5000
#define MOTOR_SPEED_LIMIT 255
#define OBSTACLE_DISTANCE_THRESHOLD 20.0

typedef struct {
    float tilt_error;
    float distance;
    int motor_a_speed;
    int motor_b_speed;
} ControlState;

ControlState control_state;

void handle_sigint(int signum) {
    printf("Received SIGINT signal. Stopping motors and exiting.\n");
    gpioTerminate();
    exit(0);
}

void log_control_cycle(const char *filename, const char *format, ...) {
    FILE *log_file = fopen(filename, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpioTerminate();
        exit(1);
    }
    va_list args;
    va_start(args, format);
    vfprintf(log_file, format, args);
    va_end(args);
    fclose(log_file);
}

void init_pigpio() {
    if (gpioInitialise() < 0) {
        perror("pigpioInitialise failed");
        return 1;
    }
    gpioSetMode(17, PI_OUTPUT);
    gpioSetMode(18, PI_OUTPUT);
    gpioSetMode(22, PI_OUTPUT);
    gpioSetMode(23, PI_OUTPUT);
    gpioSetMode(24, PI_OUTPUT);
    gpioSetMode(25, PI_OUTPUT);
    gpioSetPWMfreq(17, 1000);
    gpioSetPWMfreq(18, 1000);
    gpioSetPWMfreq(22, 1000);
    gpioSetPWMfreq(23, 1000);
    gpioSetPWMrange(17, MOTOR_SPEED_LIMIT);
    gpioSetPWMrange(18, MOTOR_SPEED_LIMIT);
    gpioSetPWMrange(22, MOTOR_SPEED_LIMIT);
    gpioSetPWMrange(23, MOTOR_SPEED_LIMIT);
}

void update_motor_speeds() {
    float kp = PID_KP;
    float ki = PID_KI;
    float kd = PID_KD;
    float dt = CONTROL_INTERVAL_MS / 1000.0;
    float integral = 0.0;
    float derivative = 0.0;

    control_state.motor_a_speed = 0;
    control_state.motor_b_speed = 0;

    // Simulate tilt error
    control_state.tilt_error = (float)rand() / RAND_MAX * 20.0 - 10.0;

    // Simulate ultrasonic distance sensor
    control_state.distance = (float)rand() / RAND_MAX * 398.0 + 2.0;

    if (control_state.distance < OBSTACLE_DISTANCE_THRESHOLD) {
        control_state.motor_a_speed = -128; // 50% speed
        control_state.motor_b_speed = -128; // 50% speed
    } else {
        // PID controller
        integral += control_state.tilt_error * dt;
        derivative = (control_state.tilt_error - control_state.tilt_error_prev) / dt;
        control_state.tilt_error_prev = control_state.tilt_error;

        float error = control_state.tilt_error;
        float output = kp * error + ki * integral + kd * derivative;

        control_state.motor_a_speed = (int)(output * MOTOR_SPEED_LIMIT);
        control_state.motor_b_speed = (int)(-output * MOTOR_SPEED_LIMIT);
    }
}

void run_control_loop() {
    while (1) {
        update_motor_speeds();
        log_control_cycle(LOG_FILE, "%s %f %f %d %d\n", 
            ctime(&time(NULL)), 
            control_state.tilt_error, 
            control_state.distance, 
            control_state.motor_a_speed, 
            control_state.motor_b_speed);

        gpioPWM(17, control_state.motor_a_speed);
        gpioPWM(18, control_state.motor_a_speed * -1);
        gpioPWM(22, control_state.motor_b_speed);
        gpioPWM(23, control_state.motor_b_speed * -1);

        gpioDelay(CONTROL_INTERVAL_MS);
    }
}

int main() {
    signal(SIGINT, handle_sigint);

    init_pigpio();

    run_control_loop();

    return 0;
}

