#include <sys/types.h>
#include <sys/time.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_DEVICE "/dev/i2c-1"
#define ADXL345_ADDR 0x53
#define DATAX0 0x32
#define DATAY0 0x33
#define DATAZ0 0x34
#define DATAX1 0x35
#define DATAY1 0x36
#define DATAZ1 0x37
#define DATAX2 0x38
#define DATAY2 0x39
#define DATAZ2 0x3A
#define DATA_FORMAT 0x31
#define POWER_CTL 0x2D
#define SCALE 256

#define FREEFALL_THRESHOLD 0.2
#define FREEFALL_DURATION 0.5
#define ALARM_DURATION 5

int i2c_fd;
int i2c_handle;
int gpio27_fd;
int freefall_detected = 0;
int freefall_start_time = 0;
int freefall_count = 0;
int freefall_log_file = -1;

void sigint_handler(int signum) {
    if (freefall_log_file != -1) {
        close(freefall_log_file);
    }
    if (i2c_handle != -1) {
        i2c_close(i2c_handle);
    }
    if (gpio27_fd != -1) {
        gpio_close(gpio27_fd);
    }
    exit(0);
}

int i2c_open() {
    struct i2c_msg msg[1];
    struct i2c_rdwr_ioctl_msg ioctl_msg;
    int ret;

    msg[0].addr = ADXL345_ADDR;
    msg[0].flags = I2C_M_RD;
    msg[0].len = 1;
    msg[0].buf[0] = DATA_FORMAT;
    ret = ioctl(i2c_fd, I2C_RDWR, (unsigned long)&ioctl_msg, (unsigned long)&msg, 1);
    if (ret < 0) {
        fprintf(stderr, "I2C error: %d\n", errno);
        return -1;
    }

    msg[0].addr = ADXL345_ADDR;
    msg[0].flags = I2C_M_RD;
    msg[0].len = 6;
    msg[0].buf = (unsigned char*)malloc(6 * sizeof(char));
    ret = ioctl(i2c_fd, I2C_RDWR, (unsigned long)&ioctl_msg, (unsigned long)&msg, 1);
    if (ret < 0) {
        fprintf(stderr, "I2C error: %d\n", errno);
        return -1;
    }

    i2c_handle = i2c_open(i2c_fd, ADXL345_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C error: %d\n", errno);
        return -1;
    }

    return 0;
}

int i2c_close() {
    if (i2c_handle < 0) {
        return 0;
    }
    i2c_close(i2c_handle);
    i2c_handle = -1;
    return 0;
}

int i2c_read_data() {
    struct i2c_msg msg[1];
    struct i2c_rdwr_ioctl_msg ioctl_msg;
    int ret;

    msg[0].addr = ADXL345_ADDR;
    msg[0].flags = I2C_M_RD;
    msg[0].len = 6;
    msg[0].buf = (unsigned char*)malloc(6 * sizeof(char));
    ret = ioctl(i2c_fd, I2C_RDWR, (unsigned long)&ioctl_msg, (unsigned long)&msg, 1);
    if (ret < 0) {
        fprintf(stderr, "I2C error: %d\n", errno);
        return -1;
    }

    ret = i2c_read(i2c_handle, msg[0]);
    if (ret < 0) {
        fprintf(stderr, "I2C error: %d\n", errno);
        return -1;
    }

    free(msg[0].buf);
    return 0;
}

int i2c_write_data() {
    struct i2c_msg msg[1];
    struct i2c_rdwr_ioctl_msg ioctl_msg;
    int ret;

    msg[0].addr = ADXL345_ADDR;
    msg[0].flags = I2C_M_WRITE;
    msg[0].len = 1;
    msg[0].buf[0] = DATA_FORMAT;
    ret = ioctl(i2c_fd, I2C_RDWR, (unsigned long)&ioctl_msg, (unsigned long)&msg, 1);
    if (ret < 0) {
        fprintf(stderr, "I2C error: %d\n", errno);
        return -1;
    }

    msg[0].addr = ADXL345_ADDR;
    msg[0].flags = I2C_M_WRITE;
    msg[0].len = 1;
    msg[0].buf[0] = POWER_CTL;
    ret = ioctl(i2c_fd, I2C_RDWR, (unsigned long)&ioctl_msg, (unsigned long)&msg, 1);
    if (ret < 0) {
        fprintf(stderr, "I2C error: %d\n", errno);
        return -1;
    }

    return 0;
}

