#include <sys/ioctl.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <pigpio.h>

#define MOTOR_STEPS_PER_MM 10
#define MOTOR_STEPS_PER_REV 2048
#define MICROSECOND_STEP_DELAY 1000
#define STEPS_TO_DRAW 50 * MOTOR_STEPS_PER_MM * 2

int main() {
    if (gpioInitialise() < 0) {
        perror("pigpio init failed");
        return 1;
    }

    if (gpioSetMode(4, PI_OUTPUT) < 0) {
        perror("GPIO4 not set as output");
        return 1;
    }
    if (gpioSetMode(17, PI_OUTPUT) < 0) {
        perror("GPIO17 not set as output");
        return 1;
    }
    if (gpioSetMode(27, PI_OUTPUT) < 0) {
        perror("GPIO27 not set as output");
        return 1;
    }
    if (gpioSetMode(22, PI_OUTPUT) < 0) {
        perror("GPIO22 not set as output");
        return 1;
    }
    if (gpioSetMode(5, PI_OUTPUT) < 0) {
        perror("GPIO5 not set as output");
        return 1;
    }
    if (gpioSetMode(6, PI_OUTPUT) < 0) {
        perror("GPIO6 not set as output");
        return 1;
    }
    if (gpioSetMode(13, PI_OUTPUT) < 0) {
        perror("GPIO13 not set as output");
        return 1;
    }
    if (gpioSetMode(19, PI_OUTPUT) < 0) {
        perror("GPIO19 not set as output");
        return 1;
    }

    int motor1_steps[4] = {1, 0, 0, 0};
    int motor2_steps[4] = {0, 1, 0, 0};

    for (int i = 0; i < STEPS_TO_DRAW; i++) {
        for (int j = 0; j < 4; j++) {
            if (motor1_steps[j]) {
                gpioWrite(4, 1);
                gpioWrite(17, 0);
                gpioWrite(27, 0);
                gpioWrite(22, 0);
            } else {
                gpioWrite(4, 0);
            }
            if (motor2_steps[j]) {
                gpioWrite(5, 1);
                gpioWrite(6, 0);
                gpioWrite(13, 0);
                gpioWrite(19, 0);
            } else {
                gpioWrite(5, 0);
            }
            usleep(MICROSECOND_STEP_DELAY);
        }
        for (int j = 0; j < 4; j++) {
            if (motor1_steps[j]) {
                gpioWrite(4, 0);
            }
            if (motor2_steps[j]) {
                gpioWrite(5, 0);
            }
            usleep(MICROSECOND_STEP_DELAY);
        }
        for (int j = 3; j >= 0; j--) {
            if (motor1_steps[j]) {
                gpioWrite(4, 1);
                gpioWrite(17, 0);
                gpioWrite(27, 0);
                gpioWrite(22, 0);
            } else {
                gpioWrite(4, 0);
            }
            if (motor2_steps[j]) {
                gpioWrite(5, 1);
                gpioWrite(6, 0);
                gpioWrite(13, 0);
                gpioWrite(19, 0);
            } else {
                gpioWrite(5, 0);
            }
            usleep(MICROSECOND_STEP_DELAY);
        }
        for (int j = 3; j >= 0; j--) {
            if (motor1_steps[j]) {
                gpioWrite(4, 0);
            }
            if (motor2_steps[j]) {
                gpioWrite(5, 0);
            }
            usleep(MICROSECOND_STEP_DELAY);
        }
    }

    gpioTerminate();
    return 0;
}

void signalHandler(int signum) {
    if (signum == SIGINT) {
        printf("Received SIGINT, stopping motors...\n");
        gpioTerminate();
    }
}

int main() {
    signal(SIGINT, signalHandler);
    // Rest of the code...
    return 0;
}

