#include <pigpio/gpiod.h>

#define RELAY_GPIO 18
#define RELAY_LOG_FILE "relay_log.txt"
#define RELAY_LOG_FORMAT "%Y-%m-%d %H:%M:%S %d %s"

int relay_state = 0;
int relay_fd;
int socket_fd;
struct sockaddr_in server_addr;
struct sockaddr_in client_addr;
socklen_t client_len = sizeof(client_addr);
char command[256];
char log_buffer[256];

void handle_sigint(int signum) {
    if (socket_fd > 0) {
        close(socket_fd);
    }
    if (relay_fd > 0) {
        close(relay_fd);
    }
    if (fopen(relay_log_file, "a") == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    fclose(fopen(relay_log_file, "a"));
    if (gpioTerminate() != 0) {
        perror("Failed to terminate pigpio");
        exit(EXIT_FAILURE);
    }
    exit(EXIT_SUCCESS);
}

void handle_sigterm(int signum) {
    handle_sigint(signum);
}

int main() {
    struct gpiod_handle handle;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_event *event;
    int ret;

    // Initialize signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    // Initialize GPIO
    ret = gpioInit();
    if (ret < 0) {
        perror("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }

    // Set GPIO pin to output
    ret = gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    if (ret < 0) {
        perror("Failed to set GPIO mode");
        exit(EXIT_FAILURE);
    }

    // Open GPIO line
    ret = gpiodOpen(&handle);
    if (ret < 0) {
        perror("Failed to open GPIO line");
        exit(EXIT_FAILURE);
    }
    if ((chip = gpiodGetChip(&handle)) == NULL) {
        perror("Failed to get GPIO chip");
        exit(EXIT_FAILURE);
    }
    if ((line = gpiodGetLine(chip, RELAY_GPIO)) == NULL) {
        perror("Failed to get GPIO line");
        exit(EXIT_FAILURE);
    }

    // Set GPIO line to input
    ret = gpiodSetMode(line, PI_INPUT);
    if (ret < 0) {
        perror("Failed to set GPIO mode");
        exit(EXIT_FAILURE);
