#define PIR_PIN 4
#define FLOODLIGHT_PIN 17
#define LOG_FILE "security_log.txt"
#define LOG_FORMAT "%Y-%m-%d %H:%M:%S,%ld,%ld\n"

int floodlight_on = 0;
int log_fd = -1;
int pi = -1;

void handle_sigint(int signum) {
    if (floodlight_on) {
        gpioWrite(FLOODLIGHT_PIN, 0);
    }
    pi GIRPpioTerminate();
    exit(0);
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    if (gpioInitialise() < 0) {
        perror("pigpio init failed");
        return 1;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) < 0) {
        perror("PIR mode set failed");
        return 1;
    }

    if (gpioSetMode(FLOODLIGHT_PIN, PI_OUTPUT) < 0) {
        perror("FLOODLIGHT mode set failed");
        return 1;
    }

    if ((log_fd = fopen(LOG_FILE, "a")) == -1) {
        perror("log file open failed");
        gpioWrite(FLOODLIGHT_PIN, 0);
        pi GIRPpioTerminate();
        return 1;
    }

    while (1) {
        if (gpioRead(PIR_PIN) == 1 && !floodlight_on) {
            floodlight_on = 1;
            char timestamp[128];
            time_t now = time(NULL);
            struct tm *ltm = localtime(&now);
            strftime(timestamp, sizeof(timestamp), LOG_FORMAT, ltm);
            fprintf(log_fd, "%s,%ld\n", timestamp, 60);
            if (fputs(timestamp, log_fd) == -1) {
                perror("log write failed");
                floodlight_on = 0;
                gpioWrite(FLOODLIGHT_PIN, 0);
                break;
            }
            if (fputs(",60\n", log_fd) == -1) {
                perror("log write failed");
                floodlight_on = 0;
                gpioWrite(FLOODLIGHT_PIN, 0);
                break;
            }
            if (fputc('\n', log_fd) == -1) {
                perror("log write failed");
                floodlight_on = 0;
                gpioWrite(FLOODLIGHT_PIN, 0);
                break;
            }
            if (fclose(log_fd) == -1) {
                perror("log file close failed");
                floodlight_on = 0;
                gpioWrite(FLOODLIGHT_PIN, 0);
                break;
            }
            if (gpioWrite(FLOODLIGHT_PIN, 1) < 0) {
                perror("FLOODLIGHT write failed");
                floodlight_on = 0;
                gpioWrite(FLOODLIGHT_PIN, 0);
                break;
            }
            usleep(100000);
        } else if (floodlight_on) {
            floodlight_on = 0;
            time_t now = time(NULL);
            struct tm *ltm = localtime(&now);
            char timestamp[128];
            strftime(timestamp, sizeof(timestamp), LOG_FORMAT, ltm);
            fprintf(log_fd, "%s,%ld\n", timestamp, 0);
            if (fputs(timestamp, log_fd) == -1) {
                perror("log write failed");
                gpioWrite(FLOODLIGHT_PIN, 0);
                break;
            }
            if (fputs(",0\n", log_fd) == -1) {
                perror("log write failed");
                gpioWrite(FLOODLIGHT_PIN, 0);
                break;
            }
            if (fputc('\n', log_fd) == -1) {
                perror("log write failed");
                gpioWrite(FLOODLIGHT_PIN, 0);
                break;
            }
            if (fclose(log_fd) == -1) {
                perror("log file close failed");
                gpioWrite(FLOODLIGHT_PIN, 0);
                break;
            }
            if (gpioWrite(FLOODLIGHT_PIN, 0) < 0) {
                perror("FLOODLIGHT write failed");
                gpioWrite(FLOODLIGHT_PIN, 0);
                break;
            }
            usleep(100000);
        }
        usleep(100000);
    }

    if (log_fd != -1) {
        if (fclose(log_fd) == -1) {
            perror("log file close failed");
        }
    }

    if (pi != -1) {
        pi GIRPpioTerminate();
    }

    return 0;
}

