typedef struct {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int channel;
    int gain;
    int tare_count;
    int tare_offset;
    int last_raw;
    int last_weight;
} HX711;

void hx711_init(HX711 *hx, int channel, int gain) {
    hx->channel = channel;
    hx->gain = gain;
    hx->tare_count = 0;
    hx->tare_offset = 0;
    hx->last_raw = 0;
    hx->last_weight = 0;

    hx->fd = open("/dev/gpiod", O_RDONLY);
    if (hx->fd < 0) {
        perror("open /dev/gpiod");
        exit(EXIT_FAILURE);
    }

    hx->chip = gpiod_chip_open(hx->fd);
    if (!hx->chip) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }

    hx->line = gpiod_chip_new_line(hx->chip, GPIOHANDLE_INITIALIZER);
    if (!hx->line) {
        perror("gpiod_chip_new_line");
        exit(EXIT_FAILURE);
    }

    hx->line->direction = GPIOF_DIR_IN;
    if (gpiod_line_request_edge(hx->line, GPIO_EDGE_FALL, NULL)) {
        perror("gpiod_line_request_edge");
        exit(EXIT_FAILURE);
    }

    hx->line->number = channel;
    if (gpiod_chip_request_line(hx->chip, hx->line)) {
        perror("gpiod_chip_request_line");
        exit(EXIT_FAILURE);
    }

