#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <signal.h>
#include <mosquitto.h>
#include <pigpio.h>

#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_QOS 0
#define MQTT_KEEPALIVE 60
#define MQTT_CLEANSESSION 1
#define MQTT_LOG_USER 1

#define GPIO_PIN 17
#define GPIO_MODE_OUTPUT 1
#define GPIO_LOW 0
#define GPIO_HIGH 1

void mqtt_callback(struct mosquitto *mosq, void *userdata, int reason) {
    char *payload;
    size_t payload_len;
    int ret;

    if (mosquitto_message_get_payload(mosq, &payload, &payload_len) == MOSQ_ERR_SUCCESS) {
        if (strcmp(payload, "ON") == 0) {
            gpioSetValue(GPIO_PIN, GPIO_HIGH);
        } else if (strcmp(payload, "OFF") == 0) {
            gpioSetValue(GPIO_PIN, GPIO_LOW);
        } else {
            syslog(LOG_ERR, "Invalid payload: %s", payload);
        }
    } else {
        syslog(LOG_ERR, "Failed to get payload: %d", ret);
    }
    mosquitto_message_destroy(mosq, &payload);
}

void mqtt_connect_handler(struct mosquitto *mosq, int ret) {
    if (ret == MOSQ_ERR_SUCCESS) {
        syslog(LOG_USER, "Connected to MQTT broker");
        mosquitto_subscribe(mosq, NULL, "home/lights/control", MQTT_QOS);
    } else {
        syslog(LOG_USER, "Failed to connect to MQTT broker: %s", mosquitto_connack_string(mosq));
        // Keep the process alive for retry
    }
}

void mqtt_loop(int *running) {
    int ret;
    struct mosquitto *mosq;

    if ((mosq = mosquitto_new(NULL, MQTT_CLEANSESSION, NULL)) == NULL) {
        syslog(LOG_ERR, "Failed to create mosquitto client");
        return;
    }

    if ((ret = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, MQTT_KEEPALIVE)) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_USER, "Failed to connect to MQTT broker: %s", mosquitto_connack_string(mosq));
        goto cleanup;
    }

    if ((ret = mosquitto_set_callback(mosq, MQTT_CALLBACK_FUNCTION, mqtt_callback, NULL)) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to set MQTT callback: %d", ret);
        goto cleanup;
    }

    if ((ret = mosquitto_loop_start(mosq)) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to start MQTT loop: %d", ret);
        goto cleanup;
    }

    *running = 1;

    cleanup:
    mosquitto_destroy(mosq);
    return;
}

void mqtt_loop_cleanup(int *running) {
    if (*running) {
        mosquitto_loop_stop(mosq);
        mosquitto_destroy(mosq);
    }
}

void gpio_init() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialise pigpio: %d", gpioInitialise());
        exit(EXIT_FAILURE);
    }
    if (gpioSetMode(GPIO_PIN, GPIO_MODE_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO mode: %d", gpioSetMode(GPIO_PIN, GPIO_MODE_OUTPUT));
        exit(EXIT_FAILURE);
    }
    if (gpioWrite(GPIO_PIN, GPIO_LOW) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO to LOW: %d", gpioWrite(GPIO_PIN, GPIO_LOW));
        exit(EXIT_FAILURE);
    }
}

void gpio_cleanup() {
    gpioTerminate();
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        syslog(LOG_USER, "Received signal %d, shutting down", signum);
        gpio_cleanup();
        mosquitto_loop_destroy(NULL);
        closelog();
        exit(EXIT_SUCCESS);
    }
}

int main() {
    int running = 1;
    struct sigaction sa;

    sa.sa_handler = signal_handler;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set signal handler");
        exit(EXIT_FAILURE);
    }

    gpio_init();

    if (mosquitto_lib_init() < 0) {
        syslog(LOG_ERR, "Failed to initialise mosquitto library: %d", mosquitto_lib_init());
        exit(EXIT_FAILURE);
    }

    if ((running = mqtt_loop(&running)) != 0) {
        syslog(LOG_ERR, "Failed to start MQTT loop: %d", running);
        exit(EXIT_FAILURE);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

int main() {
    int ret;

    // Initialize pigpio
    ret = gpioInitialise();
    if (ret < 0) {
        perror("pigpioInitialise");
        exit(EXIT_FAILURE);
    }

    // Set PWM frequency to 50 Hz (20 ms period)
    ret = setServoPulsewidthResolution(1000); // Ensure resolution is sufficient
    if (ret < 0) {
        perror("setServoPulsewidthResolution");
        exit(EXIT_FAILURE);
    }

    // Set PWM frequency to 50 Hz
    ret = setClockDivider(20); // 20 ms period
    if (ret < 0) {
        perror("setClockDivider");
        exit(EXIT_FAILURE);
    }

    // Set PWM range to 500-2500 microseconds
    ret = setServoPulsewidthRange(500, 2500);
    if (ret < 0) {
        perror("setServoPulsewidthRange");
        exit(EXIT_FAILURE);
    }

    // Set PWM frequency and range for each pin
    for (int i = 0; i < 5; i++) {
        int pin = 7 + i;
        int pulse_width = 1000 + (i * 500); // 1000, 1500, 2000, 500, 2500

        // Set PWM frequency and range for the pin
        ret = setServoPulsewidthResolution(1000); // Ensure resolution is sufficient
        if (ret < 0) {
            perror("setServoPulsewidthResolution");
            exit(EXIT_FAILURE);
        }

        ret = setClockDivider(20); // 20 ms period
        if (ret < 0) {
            perror("setClockDivider");
            exit(EXIT_FAILURE);
        }

        ret = setServoPulsewidthRange(500, 2500);
        if (ret < 0) {
            perror("setServoPulsewidthRange");
            exit(EXIT_FAILURE);
        }

        // Set pulse width for the pin
        ret = servoWrite(pin, pulse_width);
        if (ret < 0) {
            perror("servoWrite");
            exit(EXIT_FAILURE);
        }

        // Wait for 3 seconds
        usleep(300000000); // 3 seconds in microseconds
    }

    // Cleanly stop the PWM
    for (int i = 0; i < 5; i++) {
        int pin = 7 + i;
        ret = servoWrite(pin, 0);
        if (ret < 0) {
            perror("servoWrite");
            exit(EXIT_FAILURE);
        }
    }

    // Release resources
    ret = gpioTerminate();
    if (ret < 0) {
        perror("gpioTerminate");
        exit(EXIT_FAILURE);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <math.h>

#define PWM_FREQ 10000
#define PWM_RESOLUTION 255
#define Kp 0.5
#define Ki 0.05
#define ENC_STALL_TIME 2000  // 2 seconds
#define ENC_STALL_THRESHOLD 0

typedef struct {
    uint32_t count;
    uint32_t last_count;
    uint32_t last_time;
    uint32_t last_error;
    uint32_t integral;
    uint32_t derivative;
    uint32_t pwm;
} EncoderState;

EncoderState encA, encB;

void init_encoder(EncoderState *state, int gpioA, int gpioB) {
    state->count = 0;
    state->last_count = 0;
    state->last_time = 0;
    state->last_error = 0;
    state->integral = 0;
    state->derivative = 0;
    state->pwm = 0;

    gpio_set_mode(gpioA, PI_INPUT);
    gpio_set_mode(gpioB, PI_INPUT);
    gpio_pull_up(gpioA, 1);
    gpio_pull_up(gpioB, 1);

    gpio_hot_add(gpioA, gpioB, NULL, NULL, NULL, NULL, NULL, NULL);
}

void update_encoder(EncoderState *state, int gpioA, int gpioB) {
    int a = gpio_get_value(gpioA);
    int b = gpio_get_value(gpioB);

    if (a != state->last_count % 2) {
        state->count++;
    }

    if (b != state->last_count % 2) {
        state->count--;
    }

    state->last_count = state->count;
    state->last_time = micros();
}

void compute_error(EncoderState *state, int target_rpm) {
    int rpm = (state->count / 64) * 60;
    int error = rpm - target_rpm;

    state->derivative = (state->last_error - error) / 1000000.0;
    state->integral += error * (micros() - state->last_time) / 1000000.0;
    state->last_error = error;
}

void compute_pwm(EncoderState *state) {
    state->pwm = (int)(Kp * state->last_error + Ki * state->integral);
    if (state->pwm < 0) state->pwm = 0;
    if (state->pwm > PWM_RESOLUTION) state->pwm = PWM_RESOLUTION;
}

void set_pwm(int gpio, int pwm) {
    gpio_write(gpio, 1);
    gpio_set_pwm(gpio, 0, pwm);
}

void stop_motors() {
    set_pwm(17, 0);
    set_pwm(22, 0);
}

void handle_sigint(int sig) {
    stop_motors();
    exit(0);
}

int main() {
    atexit(stop_motors);
    signal(SIGINT, handle_sigint);

    if (gpio_initialise() < 0) {
        perror("pigpio init failed");
        return 1;
    }

    init_encoder(&encA, 4, 5);
    init_encoder(&encB, 6, 12);

    int target_rpm = 50;
    int period = 100000; // 100 ms

    while (1) {
        update_encoder(&encA, 4, 5);
        update_encoder(&encB, 6, 12);

        compute_error(&encA, target_rpm);
        compute_error(&encB, target_rpm);

        compute_pwm(&encA);
        compute_pwm(&encB);

        set_pwm(17, encA.pwm);
        set_pwm(22, encB.pwm);

        printf("Motor A RPM: %d, PWM: %d\n", encA.count / 64 * 60, encA.pwm);
        printf("Motor B RPM: %d, PWM: %d\n", encB.count / 64 * 60, encB.pwm);
        printf("\n");

        usleep(period);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>

#define BH1750_ADDR 0x23
#define BH1750_REG 0x00
#define BH1750_CONTROL 0x01
#define BH1750_ONE_TIME_HIGH_RESOLUTION_MODE_2 0x21
#define BH1750_MEASUREMENT_CONTROL 0x13
#define BH1750_MEASUREMENT_RESULT 0x13
#define BH1750_MEASUREMENT_RESULT_LOW 0x14
#define BH1750_MEASUREMENT_RESULT_HIGH 0x15
#define BH1750_MEASUREMENT_RESULT_HIGH_2 0x16
#define BH1750_MEASUREMENT_RESULT_LOW_2 0x17
#define BH1750_MEASUREMENT_RESULT_HIGH_3 0x18
#define BH1750_MEASUREMENT_RESULT_LOW_3 0x19
#define BH1750_MEASUREMENT_RESULT_HIGH_4 0x1A
#define BH1750_MEASUREMENT_RESULT_LOW_4 0x1B
#define BH1750_MEASUREMENT_RESULT_HIGH_5 0x1C
#define BH1750_MEASUREMENT_RESULT_LOW_5 0x1D
#define BH1750_MEASUREMENT_RESULT_HIGH_6 0x1E
#define BH1750_MEASUREMENT_RESULT_LOW_6 0x1F

#define LOG_FILE "chicken_coop_log.txt"
#define LOG_FORMAT "%Y-%m-%d %H:%M:%S: Lux = %d, Relay = %s"

int i2c_fd;
int i2c_handle;
int relay_gpio;
int sensor_status;
int sensor_readings[2];
int lux;
int relay_state;
int last_lux;
int last_lux_time;
int last_relay_time;
int last_relay_state;
int log_file_fd;
int log_file_status;

void log_sensor_reading(int lux, int relay_state) {
    char log_buffer[256];
    struct tm *log_time;
    time_t now = time(NULL);
    log_time = localtime(&now);
    strftime(log_buffer, sizeof(log_buffer), LOG_FORMAT, log_time);
    log_buffer[strcspn(log_buffer, "\n")] = '\0';
    if (log_file_status == 0) {
        log_file_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
        if (log_file_fd < 0) {
            perror("Failed to open log file");
            exit(EXIT_FAILURE);
        }
        log_file_status = 1;
    }
    if (write(log_file_fd, log_buffer, strlen(log_buffer)) < 0) {
        perror("Failed to write to log file");
        exit(EXIT_FAILURE);
    }
}

void log_relay_state_change(int relay_state) {
    char log_buffer[256];
    struct tm *log_time;
    time_t now = time(NULL);
    log_time = localtime(&now);
    strftime(log_buffer, sizeof(log_buffer), LOG_FORMAT, log_time);
    log_buffer[strcspn(log_buffer, "\n")] = '\0';
    if (log_file_status == 0) {
        log_file_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
        if (log_file_fd < 0) {
            perror("Failed to open log file");
            exit(EXIT_FAILURE);
        }
        log_file_status = 1;
    }
    if (write(log_file_fd, log_buffer, strlen(log_buffer)) < 0) {
        perror("Failed to write to log file");
        exit(EXIT_FAILURE);
    }
}

void init_i2c() {
    if ((i2c_fd = open("/dev/i2c-"I2C_BUS_NUMBER", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }
    i2c_handle = 0;
}

void init_sensor() {
    if (sensor_status == 0) {
        sensor_status = 1;
        if (ioctl(i2c_fd, I2C_RDWR, &i2c_handle) < 0) {
            perror("Failed to get I2C handle");
            exit(EXIT_FAILURE);
        }
        if (write(i2c_handle, &BH1750_CONTROL, 1) < 0) {
            perror("Failed to set control register");
            exit(EXIT_FAILURE);
        }
        if (write(i2c_handle, &BH1750_ONE_TIME_HIGH_RESOLUTION_MODE_2, 1) < 0) {
            perror("Failed to set high-resolution mode");
            exit(EXIT_FAILURE);
        }
        if (write(i2c_handle, &BH1750_MEASUREMENT_CONTROL, 1) < 0) {
            perror("Failed to set measurement control");
            exit(EXIT_FAILURE);
        }
        if (read(i2c_handle, &sensor_readings[0], 1) < 0) {
            perror("Failed to read measurement result");
            exit(EXIT_FAILURE);
        }
        if (read(i2c_handle, &sensor_readings[1], 1) < 0) {
            perror("Failed to read measurement result");
            exit(EXIT_FAILURE);
        }
        lux = (sensor_readings[0] << 8) | sensor_readings[1];
        lux /= 1.2;
    }
}

void init_relay() {
    if ((relay_gpio = gpio_open(GPIO_NUM_RELAY)) < 0) {
        perror("Failed to open relay GPIO");
        exit(EXIT_FAILURE);
    }
    if (gpio_set_mode(relay_gpio, PI_OUTPUT)) {
        perror("Failed to set relay GPIO mode");
        exit(EXIT_FAILURE);
    }
    if (gpio setwpi_value(relay_gpio, 0)) {
        perror("Failed to set relay GPIO value");
        exit(EXIT_FAILURE);
    }
}

void init_log() {
    if ((log_file_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644)) < 0) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    log_file_status = 1;
}

void cleanup() {
    if (log_file_status == 1) {
        if (close(log_file_fd) < 0) {
            perror("Failed to close log file");
            exit(EXIT_FAILURE);
        }
    }
    if (sensor_status == 1) {
        if (close(i2c_fd) < 0) {
            perror("Failed to close I2C bus");
            exit(EXIT_FAILURE);
        }
    }
    if (relay_gpio >= 0) {
        if (gpio_close(relay_gpio) < 0) {
            perror("Failed to close relay GPIO");
            exit(EXIT_FAILURE);
        }
    }
}

void handle_sensor_failure() {
    if (sensor_status == 1) {
        sensor_status = 0;
        if (gpio setwpi_value(relay_gpio, 0)) {
            perror("Failed to set relay GPIO value");
            exit(EXIT_FAILURE);
        }
        log_sensor_reading(lux, "OFF");
        log_relay_state_change("OFF");
    }
}

void handle_relay_state_change() {
    if (relay_state != last_relay_state) {
        last_relay_state = relay_state;
        if (relay_state == 1) {
            if (gpio setwpi_value(relay_gpio, 1)) {
                perror("Failed to set relay GPIO value");
                exit(EXIT_FAILURE);
            }
            log_relay_state_change("ON");
        } else {
            if (gpio setwpi_value(relay_gpio, 0)) {
                perror("Failed to set relay GPIO value");
                exit(EXIT_FAILURE);
            }
            log_relay_state_change("OFF");
        }
    }
}

void handle_sensor_readings() {
    if (sensor_status == 1) {
        if (read(i2c_handle, &sensor_readings[0], 1) < 0) {
            perror("Failed to read measurement result");
            handle_sensor_failure();
        }
        if (read(i2c_handle, &sensor_readings[1], 1) < 0) {
            perror("Failed to read measurement result");
            handle_sensor_failure();
        }
        lux = (sensor_readings[0] << 8) | sensor_readings[1];
        lux /= 1.2;
        if (lux < 50 && last_lux > 50) {
            if (last_lux_time < now - 180) {
                if (gpio setwpi_value(relay_gpio, 1)) {
                    perror("Failed to set relay GPIO value");
                    exit(EXIT_FAILURE);
                }
                log_sensor_reading(lux, "ON");
                log_relay_state_change("ON");
                last_lux = lux;
                last_lux_time = now;
            }
        } else if (lux > 200 && last_lux < 200) {
            if (last_lux_time < now - 180) {
                if (gpio setwpi_value(relay_gpio, 0)) {
                    perror("Failed to set relay GPIO value");
                    exit(EXIT_FAILURE);
                }
                log_sensor_reading(lux, "OFF");
                log_relay_state_change("OFF");
                last_lux = lux;
                last_lux_time = now;
            }
        }
    }
}

void main_loop() {
    while (1) {
        if (sensor_status == 1) {
            if (read(i2c_handle, &sensor_readings[0], 1) < 0) {
                perror("Failed to read measurement result");
                handle_sensor_failure();
            }
            if (read(i2c_handle, &sensor_readings[1], 1) < 0) {
                perror("Failed to read measurement result");
                handle_sensor_failure();
            }
            lux = (sensor_readings[0] << 8) | sensor_readings[1];
            lux /= 1.2;
            if (lux < 50 && last_lux > 50) {
                if (last_lux_time < now - 180) {
                    if (gpio setwpi_value(relay_gpio, 1)) {
                        perror("Failed to set relay GPIO value");
                        exit(EXIT_FAILURE);
                    }
                    log_sensor_reading(lux, "ON");
                    log_relay_state_change("ON");
                    last_lux = lux;
                    last_lux_time = now;
                }
            } else if (lux > 200 && last_lux < 200) {
                if (last_lux_time < now - 180) {
                    if (gpio setwpi_value(relay_gpio, 0)) {
                        perror("Failed to set relay GPIO value");
                        exit(EXIT_FAILURE);
                    }
                    log_sensor_reading(lux, "OFF");
                    log_relay_state_change("OFF");
                    last_lux = lux;
                    last_lux_time = now;
                }
            }
        }
        usleep(500000); // 5 seconds
    }
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <gpio-relay>\n", argv[0]);
        exit(EXIT_FAILURE);
    }
    if (gpio_init() < 0) {
        perror("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }
    if (gpio setwpi_value(17, 0)) {
        perror("Failed to set GPIO 17 to output");
        exit(EXIT_FAILURE);
    }
    if ((relay_gpio = gpio_open(argv[1])) < 0) {
        perror("Failed to open relay GPIO");
        exit(EXIT_FAILURE);
    }
    if (gpio_set_mode(relay_gpio, PI_OUTPUT)) {
        perror("Failed to set relay GPIO mode");
        exit(EXIT_FAILURE);
    }
    if (gpio setwpi_value(relay_gpio, 0)) {
        perror("Failed to set relay GPIO value");
        exit(EXIT_FAILURE);
    }
    init_i2c();
    init_sensor();
    init_relay();
    init_log();
    main_loop();
    cleanup();
    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN_TOUCH 4
#define GPIO_PIN_RELAY 17
#define DEBOUNCE_TIME_MS 50
#define SLEEP_TIME_MS 10

int main() {
    int ret;
    char buf[256];
    struct timespec ts;

    if ((ret = gpioInitialise()) < 0) {
        perror("gpioInitialise");
        return 1;
    }

    if ((ret = gpioSetMode(GPIO_PIN_TOUCH, PI_INPUT)) < 0) {
        perror("gpioSetMode");
        goto cleanup;
    }

    if ((ret = gpioSetMode(GPIO_PIN_RELAY, PI_OUTPUT)) < 0) {
        perror("gpioSetMode");
        goto cleanup;
    }

    if ((ret = gpioSetPullUp(GPIO_PIN_TOUCH, PI_PUD_OFF)) < 0) {
        perror("gpioSetPullUp");
        goto cleanup;
    }

    if ((ret = gpioSetPullUp(GPIO_PIN_RELAY, PI_PUD_OFF)) < 0) {
        perror("gpioSetPullUp");
        goto cleanup;
    }

    for (;;) {
        if (clock_gettime(CLOCK_MONOTONIC, &ts) < 0) {
            perror("clock_gettime");
            goto cleanup;
        }

        if (ts.tv_sec % 2 == 0) {
            if ((ret = gpioGetRelayState(GPIO_PIN_RELAY)) < 0) {
                perror("gpioGetRelayState");
                goto cleanup;
            }
            if (ret) {
                printf("%s Relay: ON\n", ctime(&ts.tv_sec));
            } else {
                printf("%s Relay: OFF\n", ctime(&ts.tv_sec));
            }
        }

        if ((ret = gpioGet(GPIO_PIN_TOUCH)) < 0) {
            perror("gpioGet");
            goto cleanup;
        }

        if (ret) {
            if ((ret = gpioGet(GPIO_PIN_TOUCH)) < 0) {
                perror("gpioGet");
                goto cleanup;
            }
            if (ret) {
                if ((ret = gpioDelay(DEBOUNCE_TIME_MS)) < 0) {
                    perror("gpioDelay");
                    goto cleanup;
                }
                if ((ret = gpioGet(GPIO_PIN_TOUCH)) < 0) {
                    perror("gpioGet");
                    goto cleanup;
                }
                if (ret) {
                    if ((ret = gpioGet(GPIO_PIN_TOUCH)) < 0) {
                        perror("gpioGet");
                        goto cleanup;
                    }
                    if (ret) {
                        if ((ret = gpioToggle(GPIO_PIN_RELAY)) < 0) {
                            perror("gpioToggle");
                            goto cleanup;
                        }
                        if (ret) {
                            printf("%s Relay: ON\n", ctime(&ts.tv_sec));
                        } else {
                            printf("%s Relay: OFF\n", ctime(&ts.tv_sec));
                        }
                    }
                }
            }
        }

        if ((ret = gpioDelay(SLEEP_TIME_MS)) < 0) {
            perror("gpioDelay");
            goto cleanup;
        }
    }

cleanup:
    if ((ret = gpioTerminate()) < 0) {
        perror("gpioTerminate");
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <pigpio.h>
#include <unistd.h>
#include <fcntl.h>
#include <syslog.h>
#include <signal.h>

#define PULSE_COUNTER_MAX 1000000
#define PULSE_COUNTER_INIT 0
#define PULSE_COUNTER_RESET 1
#define PULSE_COUNTER_SAMPLE 2
#define PULSE_COUNTER_SHUTDOWN 3

#define LOG_FILE "water_flow.log"
#define LOG_LEVEL DEBUG

pthread_mutex_t pulse_counter_mutex = PTHREAD_MUTEX_INITIALIZER;
int pulse_counter = PULSE_COUNTER_INIT;
int flow_sensor_pin = 17;
int solenoid_pin = 27;
int log_fd = -1;
int solenoid_state = 1; // 1 = HIGH, 0 = LOW

void* pulse_counter_thread(void* arg) {
    while (1) {
        pthread_mutex_lock(&pulse_counter_mutex);
        int current_state = gpio_get_isr_num(flow_sensor_pin);
        if (current_state == PULSE_COUNTER_SAMPLE) {
            pulse_counter = 0;
            int pulses = gpio_get_count(flow_sensor_pin);
            if (pulses > 0) {
                pulse_counter = pulses;
            }
            pthread_mutex_unlock(&pulse_counter_mutex);
            double lpm = (pulse_counter / 450.0) * 60.0;
            if (lpm > 5.0) {
                solenoid_state = 0;
            } else if (lpm < 4.5) {
                solenoid_state = 1;
            }
            pthread_mutex_unlock(&pulse_counter_mutex);
            if (log_fd != -1) {
                char buffer[256];
                struct tm* timeinfo;
                time_t rawtime;
                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
                fprintf(log_fd, "%s LPM: %.2f, Solenoid: %d\n", buffer, lpm, solenoid_state);
            }
        } else if (current_state == PULSE_COUNTER_SHUTDOWN) {
            pthread_mutex_unlock(&pulse_counter_mutex);
            if (log_fd != -1) {
                char buffer[256];
                struct tm* timeinfo;
                time_t rawtime;
                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
                fprintf(log_fd, "%s Shutting down\n", buffer);
            }
            pthread_mutex_destroy(&pulse_counter_mutex);
            gpioTerminate();
            exit(EXIT_SUCCESS);
        }
        usleep(1000000); // 1-second delay
    }
    return NULL;
}

void* signal_handler(void* arg) {
    int* pid = (int*) arg;
    syslog(LOG_LEVEL, "Received signal %d", *pid);
    pthread_mutex_lock(&pulse_counter_mutex);
    if (log_fd != -1) {
        char buffer[256];
        struct tm* timeinfo;
        time_t rawtime;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(log_fd, "%s Received signal %d\n", buffer, *pid);
    }
    pthread_mutex_unlock(&pulse_counter_mutex);
    solenoid_state = 1; // Open solenoid to safe state
    if (log_fd != -1) {
        char buffer[256];
        struct tm* timeinfo;
        time_t rawtime;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(log_fd, "%s Reopening solenoid\n", buffer);
    }
    pthread_mutex_destroy(&pulse_counter_mutex);
    if (log_fd != -1) {
        close(log_fd);
    }
    pthread_exit(NULL);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioSetMode(flow_sensor_pin, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting flow sensor mode: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(solenoid_pin, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting solenoid mode: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(flow_sensor_pin, PI_EDGE_BOTH, 0, pulse_counter_thread) < 0) {
        fprintf(stderr, "Error setting flow sensor ISR: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(flow_sensor_pin, PI_PRESENT) < 0) {
        fprintf(stderr, "Error setting flow sensor present mode: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if ((log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644)) < 0) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    pthread_create(&pulse_counter_thread, NULL, pulse_counter_thread, NULL);

    while (1) {
        if (solenoid_state == 0) {
            gpioWrite(solenoid_pin, 0);
        } else {
            gpioWrite(solenoid_pin, 1);
        }
        usleep(1000000); // 1-second delay
    }

    return EXIT_SUCCESS;
}

