#define JSON_HEADER "{\"date\":\"%Y-%m-%d %H:%M:%S\",\"target_weight\":%d,\"actual_weight\":%d,\"error\":\"\"}"
#define JSON_SEPARATOR ","
#define JSON_END "}"

void sigint_handler(int signum) {
    syslog(LOG_INFO, "Received SIGINT signal. Shutting down.");
    pi_stop();
    close(sock);
    exit(0);
}

void sigterm_handler(int signum) {
    syslog(LOG_INFO, "Received SIGTERM signal. Shutting down.");
    pi_stop();
    close(sock);
    exit(0);
}

int main() {
    // Initialize signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Read configuration from config.ini
    hx711_config_t config;
    config.dac_gain = 128;
    config.data_rate = 800;
    config.calibration_factor = CALIBRATION_FACTOR;
    hx711_t hx711;
    if (hx711_init(&hx711, &config) < 0) {
        syslog(LOG_ERR, "Failed to initialize HX711 sensor.");
        return 1;
    }

    // Initialize GPIO
    if (pi_init(NULL) < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO.");
        return 1;
    }

    // Set up servo motor
    int servo_pin = 18;
    if (pi_set_mode(servo_pin, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set servo pin mode.");
        return 1;
    }
    if (pi_set_pull_up(servo_pin, 1) < 0) {
        syslog(LOG_ERR, "Failed to set servo pin pull-up.");
        return 1;
    }
    if (pi_set_servo_pulsewidth(servo_pin, SERVO_MIN_PULSE) < 0) {
        syslog(LOG_ERR, "Failed to set servo minimum pulse width.");
        return 1;
    }
    if (pi_set_servo_pulsewidth(servo_pin, SERVO_MAX_PULSE) < 0) {
        syslog(LOG_ERR, "Failed to set servo maximum pulse width.");
        return 1;
    }

    // Open socket
    int sock;
    struct sockaddr_in server_addr;
    socklen_t server_len = sizeof(server_addr);
    if ((sock = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        syslog(LOG_ERR, "Failed to create socket.");
        return 1;
    }
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = inet_addr(SERVER_IP);
    server_addr.sin_port = htons(SERVER_PORT);
    if (bind(sock, (struct sockaddr *)&server_addr, server_len) < 0) {
        syslog(LOG_ERR, "Failed to bind socket.");
        return 1;
    }
    if (listen(sock, 1) < 0) {
        syslog(LOG_ERR, "Failed to listen on socket.");
        return 1;
    }

    // Read config.ini
    FILE *config_file = fopen(CONFIG_FILE, "r");
    if (!config_file) {
        syslog(LOG_INFO, "Config file not found. Using defaults.");
        config.calibration_factor = CALIBRATION_FACTOR;
    } else {
        char line[256];
        while (fgets(line, sizeof(line), config_file)) {
            if (sscanf(line, "calibration_factor=%lf", &config.calibration_factor) == 1) {
                break;
            }
        }
        fclose(config_file);
    }

    // Main loop
    while (1) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_sock;
        if ((client_sock = accept(sock, (struct sockaddr *)&client_addr, &client_len)) < 0) {
            syslog(LOG_ERR, "Failed to accept client connection.");
            continue;
        }

        // Read target weight from client
        int target_weight;
        if (recv(client_sock, &target_weight, sizeof(target_weight), 0) < 0) {
            syslog(LOG_ERR, "Failed to read target weight from client.");
            continue;
        }
        target_weight = ntohl(target_weight);

        // Open dispensing_log.json
        FILE *disp_log_file = fopen("dispensing_log.json", "a");
        if (!disp_log_file) {
            syslog(LOG_ERR, "Failed to open dispensing log file.");
            continue;
        }

        // Open servo
        if (pi_set_servo_pulsewidth(servo_pin, target_weight) < 0) {
            syslog(LOG_ERR, "Failed to open servo.");
            continue;
        }

        // Wait for load cell to stabilize
        usleep(1000000);

        // Read actual weight from HX711
        int actual_weight;
        int attempts = 0;
        while (attempts < MAX_ATTEMPTS) {
            if (hx711_get_value(&hx711) < 0) {
                syslog(LOG_ERR, "Failed to read HX711 value.");
                break;
            }
            actual_weight = hx711_get_value(&hx711);
            attempts++;
            if (attempts >= MAX_ATTEMPTS) {
                syslog(LOG_ERR, "Load cell not ready. Exiting.");
                break;
            }
        }

        // Send actual weight back to client
        if (send(client_sock, &actual_weight, sizeof(actual_weight), 0) < 0) {
            syslog(LOG_ERR, "Failed to send actual weight to client.");
            continue;
        }
        actual_weight = ntohl(actual_weight);

        // Log dispensing event
        char log_line[256];
        snprintf(log_line, sizeof(log_line), JSON_HEADER, target_weight, actual_weight);
        strcat(log_line, JSON_SEPARATOR);
        strcat(log_line, JSON_END);
        if (fprintf(disp_log_file, "%s\n", log_line) < 0) {
            syslog(LOG_ERR, "Failed to log dispensing event.");
            continue;
        }

        // Close client socket
        if (close(client_sock) < 0) {
            syslog(LOG_ERR, "Failed to close client socket.");
            continue;
        }

        // Close disp_log_file
        if (fclose(disp_log_file) < 0) {
            syslog(LOG_ERR, "Failed to close dispensing log file.");
            continue;
        }
    }

    // Clean up
    pi_stop();
    close(sock);
    return 0;
}

