#define SPI_CHANNEL 0
#define SPI_FREQ 100000
#define RFID_TAG_SIZE 10
#define RFID_TAG_VALID {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A}

#define GPIO17 17
#define GPIO27 27
#define GPIO22 22

#define LOG_FILE "/var/log/door_access.log"

#define LOG_LEVEL DEBUG

void log_message(const char *tag, const char *action, const char *message) {
    char buffer[256];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S ", localtime(&now));
    snprintf(buffer + strlen(buffer), sizeof(buffer) - strlen(buffer), "%s %s %s\n", buffer, tag, message);
    syslog(LOG_LEVEL, buffer);
    if (fputs(buffer, log_file) < 0) {
        perror("Failed to write to log file");
    }
}

void handle_sigint(int signum) {
    if (spiOpen(SPI_CHANNEL, SPI_FREQ) < 0) {
        log_message("SPI", "SIGINT", "Failed to open SPI channel");
    }
    gpioTerminate();
    close(log_file);
    exit(0);
}

int main() {
    int log_file = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_file < 0) {
        perror("Failed to open log file");
        return 1;
    }
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    if (gpioInitialise() < 0) {
        log_message("GPIO", "SIGINT", "Failed to initialise GPIO");
        return 1;
    }

    if (gpioSetPullUp(GPIO22, 1) < 0) {
        log_message("GPIO", "SIGINT", "Failed to set GPIO22 pull-up");
        return 1;
    }

    if (gpioSetMode(GPIO17, PI_OUTPUT) < 0) {
        log_message("GPIO", "SIGINT", "Failed to set GPIO17 as output");
        return 1;
    }

    if (gpioSetMode(GPIO27, PI_OUTPUT) < 0) {
        log_message("GPIO", "SIGINT", "Failed to set GPIO27 as output");
        return 1;
    }

    if (gpioSetMode(GPIO22, PI_INPUT) < 0) {
        log_message("GPIO", "SIGINT", "Failed to set GPIO22 as input");
        return 1;
    }

    if (spiOpen(SPI_CHANNEL, SPI_FREQ) < 0) {
        log_message("SPI", "SIGINT", "Failed to open SPI channel");
        return 1;
    }

    int rfid_tag[RFID_TAG_SIZE];
    int rfid_tag_valid = 0;

    while (1) {
        int button_pressed = 0;
        int rfid_read = 0;
        int rfid_read_error = 0;

        // Read RFID tag
        if (spiXfer(SPI_CHANNEL, 0, rfid_tag, RFID_TAG_SIZE) < 0) {
            log_message("SPI", "SIGINT", "SPI read error");
            rfid_read_error = 1;
        } else {
            if (memcmp(rfid_tag, RFID_TAG_VALID, RFID_TAG_SIZE) == 0) {
                rfid_tag_valid = 1;
            }
        }

        // Read button press
        if (gpioRead(GPIO22) == 0) {
            button_pressed = 1;
        }

        // Log access attempt
        if (rfid_read_error) {
            log_message("RFID", "SIGINT", "RFID read error");
        } else if (!rfid_tag_valid) {
            log_message("RFID", "SIGINT", "Invalid RFID tag");
        } else if (button_pressed) {
            log_message("RFID", "SIGINT", "Button pressed");
        } else {
            log_message("RFID", "SIGINT", "No RFID tag present");
        }

        // Unlock locks
        if (rfid_tag_valid && button_pressed) {
            gpioWrite(GPIO17, 0);
            gpioWrite(GPIO27, 0);
            gpioDelay(5000);
            gpioWrite(GPIO17, 1);
            gpioWrite(GPIO27, 1);
        }

        // Poll for 100ms
        gpioDelay(100);
    }

    return 0;
}

