#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <syslog.h>
#include <gpiod.h>

#define VALVE_1_RELAY_GPIO 17
#define VALVE_2_RELAY_GPIO 18
#define VALVE_LOG_FILE "valve_log.txt"
#define VALVE_1_DURATION_MS 500
#define VALVE_2_DURATION_MS 1000
#define VALVE_1_PAUSE_MS 5000
#define VALVE_2_PAUSE_MS 10000

typedef struct {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int state;
} Valve;

void handle_sigint(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        // Release all GPIO lines
        for (int i = 0; i < 2; i++) {
            if (valves[i].line) {
                gpiod_line_request_free(valves[i].line);
            }
        }
        // Close the log file
        if (valve_log_fd != -1) {
            close(valve_log_fd);
        }
        // Exit the program
        exit(EXIT_SUCCESS);
    }
}

int main() {
    // Initialize signal handlers
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize log file
    valve_log_fd = open(VALVE_LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (valve_log_fd == -1) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Initialize GPIO lines
    int err;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    Valve valves[2] = {{0}, {0}};

    // Initialize Valve 1
    valves[0].fd = open("/dev/gpiod", O_RDONLY | O_NONBLOCK);
    if (valves[0].fd == -1) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }
    chip = gpiod_chip_open(valves[0].fd);
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }
    line = gpiod_chip_get_line(chip, VALVE_1_RELAY_GPIO);
    if (line == NULL) {
        perror("Failed to find GPIO line");
        return EXIT_FAILURE;
    }
    valves[0].line = line;
    err = gpiod_line_request_output(line, 0);
    if (err < 0) {
        perror("Failed to request output");
        return EXIT_FAILURE;
    }
    edge = gpiod_line_request_edge(line, GPIOD_EDGE_BOTH);
    if (edge == NULL) {
        perror("Failed to request edge");
        return EXIT_FAILURE;
    }
    gpiod_chip_request_line(chip, line, edge, 0);
    valves[0].state = 0;

    // Initialize Valve 2
    valves[1].fd = open("/dev/gpiod", O_RDONLY | O_NONBLOCK);
    if (valves[1].fd == -1) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }
    chip = gpiod_chip_open(valves[1].fd);
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }
    line = gpiod_chip_get_line(chip, VALVE_2_RELAY_GPIO);
    if (line == NULL) {
        perror("Failed to find GPIO line");
        return EXIT_FAILURE;
    }
    valves[1].line = line;
    err = gpiod_line_request_output(line, 0);
    if (err < 0) {
        perror("Failed to request output");
        return EXIT_FAILURE;
    }
    edge = gpiod_line_request_edge(line, GPIOD_EDGE_BOTH);
    if (edge == NULL) {
        perror("Failed to request edge");
        return EXIT_FAILURE;
    }
    gpiod_chip_request_line(chip, line, edge, 0);
    valves[1].state = 0;

    // Schedule valve activations
    while (1) {
        // Log current time
        struct tm *now = localtime(&time(NULL));
        char buffer[128];
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", now);
        fprintf(valve_log_fd, "%s %d\n", buffer, getpid());
        fflush(valve_log_fd);

        // Activate Valve 1
        if (valves[0].state == 0) {
            valves[0].state = 1;
            gpiod_line_set_value(valves[0].line, 1);
            usleep(VALVE_1_DURATION_MS * 1000);
            valves[0].state = 0;
            gpiod_line_set_value(valves[0].line, 0);
            usleep(VALVE_1_PAUSE_MS * 1000);
        }

        // Activate Valve 2
        if (valves[1].state == 0) {
            valves[1].state = 1;
            gpiod_line_set_value(valves[1].line, 1);
            usleep(VALVE_2_DURATION_MS * 1000);
            valves[1].state = 0;
            gpiod_line_set_value(valves[1].line, 0);
            usleep(VALVE_2_PAUSE_MS * 1000);
        }
    }

    return EXIT_SUCCESS;
}

