#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define GPIO17 17
#define GPIO2 2
#define GPIO3 3
#define MPR121_I2C 0x5A
#define MPR121_STOP 0x00
#define MPR121_RUN 0x01
#define MPR121_ELE_EN 0x20
#define MPR121_TOUCH_STATUS 0x00
#define MPR121_RELEASE_STATUS 0x01
#define MPR121_FILTER 0x20
#define MPR121_ELE_CURRENT 0x01

#define TOUCH_THRESHOLD 0x10
#define RELEASE_THRESHOLD 0x0A
#define FILTER_TIME 0x20
#define ELE_CURRENT 0x01

#define DELAY 100
#define MAX_TOUCH 12

int i2c_fd;
int gpio_fd;
int touch_status[MAX_TOUCH];
int touch_count = 0;
int touch_detected = 0;
int touch_status_buffer[2];
int touch_status_buffer_size = 2;

void handle_sigint(int signum) {
    if (i2c_fd > 0) {
        close(i2c_fd);
    }
    if (gpio_fd > 0) {
        close(gpio_fd);
    }
    exit(0);
}

void handle_sigterm(int signum) {
    handle_sigint(signum);
}

int main() {
    struct i2c_msg i2c_msg[2];
    struct i2c_rdma_msg i2c_rdma_msg[2];
    struct i2c_rdma_handle i2c_rdma_handle;
    struct timespec timeout;
    int ret;
    int i;
    int touch_count = 0;
    int touch_detected = 0;
    int status;
    int touch_status_buffer[2];
    int touch_status_buffer_size = 2;

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C address
    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C address");
        exit(EXIT_FAILURE);
    }

    // Initialize MPR121
    i2c_msg[0].addr = I2C_ADDR;
    i2c_msg[0].flags = I2C_M_RD;
    i2c_msg[0].len = 1;
    i2c_msg[0].buf = (unsigned char *) &status;
    ret = ioctl(i2c_fd, I2C_RDWR, i2c_msg);
    if (ret < 0) {
        perror("Failed to read MPR121 status");
        exit(EXIT_FAILURE);
    }

    if (status != MPR121_STOP) {
        printf("MPR121 is not in stop mode\n");
        exit(EXIT_FAILURE);
    }

    // Set touch threshold
    i2c_msg[0].addr = I2C_ADDR;
    i2c_msg[0].flags = I2C_M_RD | I2C_M_RDACC;
    i2c_msg[0].len = 1;
    i2c_msg[0].buf = (unsigned char *) &status;
    i2c_msg[1].addr = I2C_ADDR;
    i2c_msg[1].flags = I2C_M_RD | I2C_M_RDACC;
    i2c_msg[1].len = 1;
    i2c_msg[1].buf = (unsigned char *) &status;
    i2c_msg[0].buf[0] = TOUCH_THRESHOLD;
    i2c_msg[1].buf[0] = TOUCH_THRESHOLD;
    ret = ioctl(i2c_fd, I2C_RDWR, i2c_msg);
    if (ret < 0) {
        perror("Failed to set touch threshold");
        exit(EXIT_FAILURE);
    }

    // Set release threshold
    i2c_msg[0].addr = I2C_ADDR;
    i2c_msg[0].flags = I2C_M_RD | I2C_M_RDACC;
    i2c_msg[0].len = 1;
    i2c_msg[0].buf = (unsigned char *) &status;
    i2c_msg[1].addr = I2C_ADDR;
    i2c_msg[1].flags = I2C_M_RD | I2C_M_RDACC;
    i2c_msg[1].len = 1;
    i2c_msg[1].buf = (unsigned char *) &status;
    i2c_msg[0].buf[0] = RELEASE_THRESHOLD;
    i2c_msg[1].buf[0] = RELEASE_THRESHOLD;
    ret = ioctl(i2c_fd, I2C_RDWR, i2c_msg);
    if (ret < 0) {
        perror("Failed to set release threshold");
        exit(EXIT_FAILURE);
    }

    // Set filter/charge time
    i2c_msg[0].addr = I2C_ADDR;
    i2c_msg[0].flags = I2C_M_RD | I2C_M_RDACC;
    i2c_msg[0].len = 1;
    i2c_msg[0].buf = (unsigned char *) &status;
    i2c_msg[1].addr = I2C_ADDR;
    i2c_msg[1].flags = I2C_M_RD | I2C_M_RDACC;
    i2c_msg[1].len = 1;
    i2c_msg[1].buf = (unsigned char *) &status;
    i2c_msg[0].buf[0] = FILTER_TIME;
    i2c_msg[1].buf[0] = FILTER_TIME;
    ret = ioctl(i2c_fd, I2C_RDWR, i2c_msg);
    if (ret < 0) {
        perror("Failed to set filter/charge time");
        exit(EXIT_FAILURE);
    }

    // Set electrode current
    i2c_msg[0].addr = I2C_ADDR;
    i2c_msg[0].flags = I2C_M_RD | I2C_M_RDACC;
    i2c_msg[0].len = 1;
    i2c_msg[0].buf = (unsigned char *) &status;
    i2c_msg[1].addr = I2C_ADDR;
    i2c_msg[1].flags = I2C_M_RD | I2C_M_RDACC;
    i2c_msg[1].len = 1;
    i2c_msg[1].buf = (unsigned char *) &status;
    i2c_msg[0].buf[0] = ELE_CURRENT;
    i2c_msg[1].buf[0] = ELE_CURRENT;
    ret = ioctl(i2c_fd, I2C_RDWR, i2c_msg);
    if (ret < 0) {
        perror("Failed to set electrode current");
        exit(EXIT_FAILURE);
    }

    // Enter run mode
    i2c_msg[0].addr = I2C_ADDR;
    i2c_msg[0].flags = I2C_M_RD | I2C_M_RDACC;
    i2c_msg[0].len = 1;
    i2c_msg[0].buf = (unsigned char *) &status;
    i2c_msg[1].addr = I2C_ADDR;
    i2c_msg[1].flags = I2C_M_RD | I2C_M_RDACC;
    i2c_msg[1].len = 1;
    i2c_msg[1].buf = (unsigned char *) &status;
    i2c_msg[0].buf[0] = MPR121_RUN;
    i2c_msg[1].buf[0] = MPR121_RUN;
    ret = ioctl(i2c_fd, I2C_RDWR, i2c_msg);
    if (ret < 0) {
        perror("Failed to enter run mode");
        exit(EXIT_FAILURE);
    }

    // Set ELE_EN
    i2c_msg[0].addr = I2C_ADDR;
    i2c_msg[0].flags = I2C_M_RD | I2C_M_RDACC;
    i2c_msg[0].len = 1;
    i2c_msg[0].buf = (unsigned char *) &status;
    i2c_msg[1].addr = I2C_ADDR;
    i2c_msg[1].flags = I2C_M_RD | I2C_M_RDACC;
    i2c_msg[1].len = 1;
    i2c_msg[1].buf = (unsigned char *) &status;
    i2c_msg[0].buf[0] = MPR121_ELE_EN;
    i2c_msg[1].buf[0] = MPR121_ELE_EN;
    ret = ioctl(i2c_fd, I2C_RDWR, i2c_msg);
    if (ret < 0) {
        perror("Failed to set ELE_EN");
        exit(EXIT_FAILURE);
    }

    // Wait for stabilization
    usleep(100000);

    // Set GPIO17 as output
    gpio_fd = gpio_open(gpio_num=GPIO17, gpio_mode=PI_OUTPUT);
    if (gpio_fd < 0) {
        perror("Failed to set GPIO17 as output");
        exit(EXIT_FAILURE);
    }

    // Initialize touch status
    for (i = 0; i < MAX_TOUCH; i++) {
        touch_status[i] = 0;
    }

    // Initialize touch status buffer
    for (i = 0; i < touch_status_buffer_size; i++) {
        touch_status_buffer[i] = 0;
    }

    // Initialize epoll
    int epfd = epoll_create(1);
    if (epfd < 0) {
        perror("Failed to create epoll");
        exit(EXIT_FAILURE);
    }

    // Add GPIO17 to epoll
    struct epoll_event event;
    event.events = EPOLLIN | EPOLLPRI | EPOLLRDHUP | EPOLLOUT | EPOLLRDHUP;
    event.data.fd = gpio_fd;
    epoll_ctl(epfd, EPOLL_CTL_ADD, gpio_fd, &event);

    // Main loop
    while (1) {
        // Read touch status
        i2c_rdma_msg[0].addr = I2C_ADDR;
        i2c_rdma_msg[0].flags = I2C_RDMA_RD;
        i2c_rdma_msg[0].len = 2;
        i2c_rdma_msg[0].buf = (unsigned char *) touch_status_buffer;
        ret = i2c_rdma_read(&i2c_rdma_handle, i2c_rdma_msg[0]);
        if (ret < 0) {
            perror("Failed to read touch status");
            exit(EXIT_FAILURE);
        }

        // Check touch status
        for (i = 0; i < MAX_TOUCH; i++) {
            if (touch_status[i] > 0) {
                touch_detected = 1;
                break;
            }
        }

        // Toggle relay if touched
        if (touch_detected) {
            gpio_write(gpio_fd, 1);
            printf("Relay toggled\n");
            touch_detected = 0;
        } else {
            gpio_write(gpio_fd, 0);
        }

        // Sleep for 100 ms
        usleep(100000);

        // Check for SIGINT or SIGTERM
        if (epoll_wait(epfd, NULL, 0) > 0) {
            break;
        }
    }

    // Close I2C and GPIO
    close(i2c_fd);
    close(gpio_fd);
    close(epfd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
