#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <pigpio.h>

#define DT_PIN 23
#define SCK_PIN 24
#define SOL_PIN 17
#define LOG_FILE "stock_events.txt"

#define HX711_TIMEOUT 1000000  // 1 second
#define HX711_DATA_LINE_STUCK_HIGH_THRESHOLD 1000000  // 1 second

typedef struct {
    int dt_pin;
    int sck_pin;
    int sol_pin;
    int log_fd;
} HX711Config;

void hx711_read(int fd, double *value) {
    int i = 0;
    int sum = 0;
    int timeout = HX711_TIMEOUT;

    while (timeout > 0) {
        if (read(fd, &sum, sizeof(sum)) < 0) {
            if (errno == EINTR) {
                continue;
            }
            printf("Error reading HX711 data: %s\n", strerror(errno));
            return;
        }

        if (sum < 0) {
            printf("Error reading HX711 data: %s\n", strerror(errno));
            return;
        }

        if (i < 3) {
            sum += sum >> 8;
            sum += sum >> 4;
            sum += sum >> 2;
            sum += sum >> 1;
        }

        if (sum > 0) {
            *value = (double)sum / 4096.0;
            return;
        }

        timeout--;
    }

    printf("Hx711 read timeout\n");
}

void hx711_data_line_stuck_high(int fd) {
    printf("Hx711 data line stuck high\n");
}

void hx711_error_handler(int fd, int error_code) {
    if (error_code == EAGAIN) {
        printf("Hx711 read error: EAGAIN\n");
    } else if (error_code == EIO) {
        printf("Hx711 read error: EIO\n");
    } else if (error_code == ENOENT) {
        printf("Hx711 read error: ENOENT\n");
    } else if (error_code == EBADF) {
        printf("Hx711 read error: EBADF\n");
    } else if (error_code == ENOTTY) {
        printf("Hx711 read error: ENOTTY\n");
    } else if (error_code == EINTR) {
        printf("Hx711 read error: EINTR\n");
    } else {
        printf("Hx711 read error: %s\n", strerror(error_code));
    }
}

void hx711_init(HX711Config *config) {
    int dt_fd = gpio_open(config->dt_pin);
    if (dt_fd < 0) {
        printf("Error opening GPIO%d: %s\n", config->dt_pin, strerror(dt_fd));
        exit(EXIT_FAILURE);
    }

    int sck_fd = gpio_open(config->sck_pin);
    if (sck_fd < 0) {
        printf("Error opening GPIO%d: %s\n", config->sck_pin, strerror(sck_fd));
        exit(EXIT_FAILURE);
    }

    int sol_fd = gpio_open(config->sol_pin);
    if (sol_fd < 0) {
        printf("Error opening GPIO%d: %s\n", config->sol_pin, strerror(sol_fd));
        exit(EXIT_FAILURE);
    }

    int dt_err = gpio_set_mode(dt_fd, PI_INPUT);
    if (dt_err < 0) {
        printf("Error setting GPIO%d to input: %s\n", config->dt_pin, strerror(dt_err));
        exit(EXIT_FAILURE);
    }

    int sck_err = gpio_set_mode(sck_fd, PI_INPUT);
    if (sck_err < 0) {
        printf("Error setting GPIO%d to input: %s\n", config->sck_pin, strerror(sck_err));
        exit(EXIT_FAILURE);
    }

    int sol_err = gpio_set_mode(sol_fd, PI_OUTPUT);
    if (sol_err < 0) {
        printf("Error setting GPIO%d to output: %s\n", config->sol_pin, strerror(sol_err));
        exit(EXIT_FAILURE);
    }

    int dt_err = gpio_claim(dt_fd, 0);
    if (dt_err < 0) {
        printf("Error claiming GPIO%d: %s\n", config->dt_pin, strerror(dt_err));
        exit(EXIT_FAILURE);
    }

    int sck_err = gpio_claim(sck_fd, 0);
    if (sck_err < 0) {
        printf("Error claiming GPIO%d: %s\n", config->sck_pin, strerror(sck_err));
        exit(EXIT_FAILURE);
    }

    int sol_err = gpio_claim(sol_fd, 0);
    if (sol_err < 0) {
        printf("Error claiming GPIO%d: %s\n", config->sol_pin, strerror(sol_err));
        exit(EXIT_FAILURE);
    }

    config->dt_pin = dt_fd;
    config->sck_pin = sck_fd;
    config->sol_pin = sol_fd;

    int dt_err = gpio_pull_up(config->dt_pin);
    if (dt_err < 0) {
        printf("Error setting GPIO%d to pull-up: %s\n", config->dt_pin, strerror(dt_err));
        exit(EXIT_FAILURE);
    }

    int sck_err = gpio_pull_up(config->sck_pin);
    if (sck_err < 0) {
        printf("Error setting GPIO%d to pull-up: %s\n", config->sck_pin, strerror(sck_err));
        exit(EXIT_FAILURE);
    }

    config->log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (config->log_fd < 0) {
        printf("Error opening log file: %s\n", strerror(config->log_fd));
        exit(EXIT_FAILURE);
    }
}

void hx711_cleanup(HX711Config *config) {
    close(config->dt_pin);
    close(config->sck_pin);
    close(config->sol_pin);
    close(config->log_fd);
    gpio_unclaim(config->dt_pin);
    gpio_unclaim(config->sck_pin);
    gpio_unclaim(config->sol_pin);
    gpio_close(config->dt_pin);
    gpio_close(config->sck_pin);
    gpio_close(config->sol_pin);
    close(config->log_fd);
}

void log_event(const char *event, const char *timestamp) {
    char buffer[256];
    struct timeval tv;
    gettimeofday(&tv, NULL);
    sprintf(buffer, "%s %s\n", timestamp, event);
    write(config->log_fd, buffer, strlen(buffer));
}

void handle_sigint(int signum) {
    hx711_cleanup(&config);
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    HX711Config config;
    config.dt_pin = DT_PIN;
    config.sck_pin = SCK_PIN;
    config.sol_pin = SOL_PIN;
    config.log_fd = 0;

    hx711_init(&config);

    double weight;
    char timestamp[256];

    while (1) {
        gettimeofday(&tv, NULL);
        sprintf(timestamp, "%ld.%06ld", tv.tv_sec, tv.tv_usec);

        hx711_read(config.dt_pin, &weight);

        if (weight < 100.0) {
            gpio_write(config.sol_pin, 1);
            usleep(500000); // 5 seconds
            gpio_write(config.sol_pin, 0);
            log_event("Lock activated", timestamp);
        }

        usleep(1000000); // 1 second
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/ioctl.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define HX711_CALIBRATION_FILE "/home/pi/calibration.txt"
#define HX711_SECURITY_LOG "/home/pi/security.log"
#define HX711_SOLINOID_PIN 27
#define HX711_CALIBRATION_WEIGHT_KG 1.0
#define HX711_TIMEOUT_MS 100
#define HX711_CLOCK_DELAY_US 1000
#define HX711_DATA_DELAY_US 1000
#define HX711_SAMPLE_COUNT 3

typedef struct {
    int fd;
    int calibration_factor;
    int solinoid_state;
    struct timeval start_time;
    struct timeval current_time;
} HX711State;

void sigint_handler(int signum) {
    if (HX711State.state != NULL) {
        HX711State.state->solinoid_state = 0;
        HX711State.state->fd = 0;
        HX711State.state->calibration_factor = 0;
        HX711State.state->solinoid_state = 0;
        HX711State.state->start_time.tv_sec = 0;
        HX711State.state->start_time.tv_usec = 0;
        HX711State.state->current_time.tv_sec = 0;
        HX711State.state->current_time.tv_usec = 0;
        close(HX711State.state->fd);
        piLock();
        piUnexport(HX711_CLOCK_PIN);
        piUnexport(HX711_DATA_PIN);
        piUnexport(HX711_SOLINOID_PIN);
        piLock();
        piTerminate();
    }
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    HX711State state;
    state.fd = 0;
    state.calibration_factor = 0;
    state.solinoid_state = 0;
    state.start_time.tv_sec = 0;
    state.start_time.tv_usec = 0;
    state.current_time.tv_sec = 0;
    state.current_time.tv_usec = 0;

    if (piInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    if (piLock() < 0) {
        fprintf(stderr, "pigpio lock failed\n");
        return 1;
    }

    if (piUnexport(HX711_CLOCK_PIN) < 0) {
        fprintf(stderr, "unable to unexport HX711_CLOCK_PIN\n");
        return 1;
    }

    if (piUnexport(HX711_DATA_PIN) < 0) {
        fprintf(stderr, "unable to unexport HX711_DATA_PIN\n");
        return 1;
    }

    if (piUnexport(HX711_SOLINOID_PIN) < 0) {
        fprintf(stderr, "unable to unexport HX711_SOLINOID_PIN\n");
        return 1;
    }

    if (piLock() < 0) {
        fprintf(stderr, "pigpio lock failed\n");
        return 1;
    }

    state.fd = open(HX711_CALIBRATION_FILE, O_RDWR | O_CREAT, 0644);
    if (state.fd < 0) {
        perror("open calibration file");
        return 1;
    }

    if (read(state.fd, &state.calibration_factor, sizeof(state.calibration_factor)) < 0) {
        perror("read calibration factor");
        return 1;
    }

    if (close(state.fd) < 0) {
        perror("close calibration file");
        return 1;
    }

    if (piLock() < 0) {
        fprintf(stderr, "pigpio lock failed\n");
        return 1;
    }

    if (piExport(HX711_CLOCK_PIN) < 0) {
        fprintf(stderr, "unable to export HX711_CLOCK_PIN\n");
        return 1;
    }

    if (piExport(HX711_DATA_PIN) < 0) {
        fprintf(stderr, "unable to export HX711_DATA_PIN\n");
        return 1;
    }

    if (piExport(HX711_SOLINOID_PIN) < 0) {
        fprintf(stderr, "unable to export HX711_SOLINOID_PIN\n");
        return 1;
    }

    if (piLock() < 0) {
        fprintf(stderr, "pigpio lock failed\n");
        return 1;
    }

    piSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    piSetMode(HX711_DATA_PIN, PI_INPUT);
    piSetMode(HX711_SOLINOID_PIN, PI_OUTPUT);

    piSetClockSpeed(HX711_CLOCK_PIN, 1000000); // 1 MHz

    piDelayMicroseconds(HX711_CLOCK_DELAY_US);
    piDelayMicroseconds(HX711_DATA_DELAY_US);

    if (piSetPullUpLevel(HX711_DATA_PIN, 1) < 0) {
        fprintf(stderr, "unable to set pull-up level on HX711_DATA_PIN\n");
        return 1;
    }

    if (piSetPullUpLevel(HX711_SOLINOID_PIN, 1) < 0) {
        fprintf(stderr, "unable to set pull-up level on HX711_SOLINOID_PIN\n");
        return 1;
    }

    state.solinoid_state = 0;
    state.fd = open(HX711_SECURITY_LOG, O_RDWR | O_CREAT, 0644);
    if (state.fd < 0) {
        perror("open security log");
        return 1;
    }

    state.solinoid_state = 0;
    state.start_time.tv_sec = 0;
    state.start_time.tv_usec = 0;

    while (1) {
        struct timeval now;
        gettimeofday(&now, NULL);
        state.current_time.tv_sec = now.tv_sec;
        state.current_time.tv_usec = now.tv_usec;

        if (state.solinoid_state == 1) {
            piSetLow(HX711_SOLINOID_PIN);
            state.solinoid_state = 0;
        }

        if (state.solinoid_state == 0) {
            piSetHigh(HX711_SOLINOID_PIN);
            state.solinoid_state = 1;
            state.start_time.tv_sec = now.tv_sec;
            state.start_time.tv_usec = now.tv_usec;
        }

        if (state.solinoid_state == 1) {
            gettimeofday(&now, NULL);
            state.current_time.tv_sec = now.tv_sec;
            state.current_time.tv_usec = now.tv_usec;

            if ((state.current_time.tv_sec - state.start_time.tv_sec) > 5) {
                piSetLow(HX711_SOLINOID_PIN);
                state.solinoid_state = 0;
                state.start_time.tv_sec = 0;
                state.start_time.tv_usec = 0;
            }
        }

        if (state.solinoid_state == 0) {
            int i;
            int sum = 0;
            for (i = 0; i < HX711_SAMPLE_COUNT; i++) {
                piDelayMicroseconds(HX711_CLOCK_DELAY_US);
                piSetHigh(HX711_CLOCK_PIN);
                piDelayMicroseconds(HX711_DATA_DELAY_US);
                piSetLow(HX711_CLOCK_PIN);
                piDelayMicroseconds(HX711_DATA_DELAY_US);

                if (piRead(HX711_DATA_PIN) == 1) {
                    gettimeofday(&now, NULL);
                    state.current_time.tv_sec = now.tv_sec;
                    state.current_time.tv_usec = now.tv_usec;
                    if ((state.current_time.tv_sec - state.start_time.tv_sec) > HX711_TIMEOUT_MS) {
                        break;
                    }
                } else {
                    gettimeofday(&now, NULL);
                    state.current_time.tv_sec = now.tv_sec;
                    state.current_time.tv_usec = now.tv_usec;
                    if ((state.current_time.tv_sec - state.start_time.tv_sec) > HX711_TIMEOUT_MS) {
                        break;
                    }
                }
            }

            if (i < HX711_SAMPLE_COUNT) {
                fprintf(stderr, "HX711 communication timeout\n");
                continue;
            }

            int raw = 0;
            for (i = 0; i < HX711_SAMPLE_COUNT; i++) {
                raw += (int)piRead(HX711_DATA_PIN);
            }

            raw = raw / HX711_SAMPLE_COUNT;
            double weight_kg = (double)raw * state.calibration_factor / 4096.0;

            if (weight_kg > 5.0) {
                char timestamp[100];
                gettimeofday(&now, NULL);
                sprintf(timestamp, "%ld:%06ld,%f", now.tv_sec, now.tv_usec / 1000000.0, weight_kg);
                fprintf(state.fd, "%s,%f\n", timestamp, weight_kg);
            }
        }

        usleep(1000);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO16 "gpiochip0/gpio16"
#define GPIO20 "gpiochip0/gpio20"
#define LOG_FILE "relay_events.log"

int main() {
    int chip_fd, line_fd, ret;
    gpiod_chip_t *chip;
    gpiod_line_t *line;
    gpiod_line_request_t request;
    struct gpiod_chip_info info;
    struct gpiod_line_info info2;
    char line_name[32];
    char timestamp[32];
    char log_buffer[256];
    struct timespec ts;

    // Open the GPIO chip
    chip_fd = gpiod_chip_open_by_name(GPIO16, &info);
    if (chip_fd < 0) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Get the chip info
    if (gpiod_chip_get_info(chip_fd, &info) < 0) {
        perror("Failed to get chip info");
        goto cleanup;
    }

    // Open the GPIO line
    line_fd = gpiod_chip_get_line(chip_fd, 0, &info2);
    if (line_fd < 0) {
        perror("Failed to open GPIO line");
        goto cleanup;
    }

    // Create a line request
    request.line = line_fd;
    request.request_type = GPIOD_LINE_REQUEST_BULK_INPUT;
    request.request_count = 1;
    request.request_offset = 0;

    // Request the line
    ret = gpiod_line_request_bulk_inputs(chip_fd, &request);
    if (ret < 0) {
        perror("Failed to request line");
        goto cleanup;
    }

    // Get the line info
    if (gpiod_line_get_info(line_fd, &info2) < 0) {
        perror("Failed to get line info");
        goto cleanup;
    }

    // Open the line
    line = gpiod_line_open(line_fd, GPIOD_LINE_OPEN_NONBLOCKING);
    if (line == NULL) {
        perror("Failed to open line");
        goto cleanup;
    }

    // Set the line request to bulk input
    if (gpiod_line_request_bulk_inputs(line_fd, &request) < 0) {
        perror("Failed to set line request to bulk input");
        goto cleanup;
    }

    // Initialize the log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        goto cleanup;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = [](int sig) {
        if (sig == SIGINT || sig == SIGTERM) {
            // Release all GPIO lines
            gpiod_chip_close(chip_fd);
            gpiod_line_release(line_fd);
            gpiod_line_close(line);
            fclose(log_file);
            exit(0);
        }
    };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handler");
        goto cleanup;
    }

    // Main loop
    while (1) {
        // Get the current time
        clock_gettime(CLOCK_MONOTONIC, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&ts.tv_sec));

        // Read the line value
        int value = gpiod_line_get_value(line_fd);
        if (value < 0) {
            perror("Failed to read line value");
            goto cleanup;
        }

        // Toggle the relay state
        if (value == 0) {
            // Obstacle detected, toggle relay from ON to OFF
            if (gpiod_line_set_value(line_fd, 1) < 0) {
                perror("Failed to set relay value");
                goto cleanup;
            }
        } else {
            // No obstacle, toggle relay from OFF to ON
            if (gpiod_line_set_value(line_fd, 0) < 0) {
                perror("Failed to set relay value");
                goto cleanup;
            }
        }

        // Log the new relay state
        snprintf(log_buffer, sizeof(log_buffer), "%s,%s\n", timestamp, (value == 0) ? "ON" : "OFF");
        if (fprintf(log_file, "%s", log_buffer) < 0) {
            perror("Failed to write to log file");
            goto cleanup;
        }

        // Sleep for 1 second
        nanosleep(&ts.tv_nsec, &ts.tv_sec);
    }

cleanup:
    // Release all GPIO lines
    gpiod_chip_close(chip_fd);
    gpiod_line_release(line_fd);
    gpiod_line_close(line);
    fclose(log_file);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <syslog.h>
#include <gpiod.h>

#define GPIO17 17
#define GPIO18 18
#define LOG_FILE "motion_log.txt"
#define BUZZER_ON_TIME 2000000  // 2 seconds in microseconds

int main() {
    int chip_fd, line_fd, log_fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_edge *edge;
    struct timespec ts;
    char timestamp[20];

    // Open GPIO chip
    chip_fd = gpiod_chip_open("/dev/gpiod");
    if (chip_fd < 0) {
        perror("gpiod_chip_open");
        return 1;
    }

    // Open GPIO17 line
    line_fd = gpiod_chip_request_line(chip_fd, GPIO17, GPIOD_LINE_INPUT);
    if (line_fd < 0) {
        perror("gpiod_chip_request_line");
        goto error;
    }

    // Open GPIO18 line
    line_fd = gpiod_chip_request_line(chip_fd, GPIO18, GPIOD_LINE_OUTPUT);
    if (line_fd < 0) {
        perror("gpiod_chip_request_line");
        goto error;
    }

    // Set GPIO17 line to input
    if (gpiod_line_request_input(line_fd) < 0) {
        perror("gpiod_line_request_input");
        goto error;
    }

    // Set GPIO18 line to output
    if (gpiod_line_request_output(line_fd) < 0) {
        perror("gpiod_line_request_output");
        goto error;
    }

    // Set GPIO18 line to high (active-high)
    if (gpiod_line_set_value(line_fd, 1) < 0) {
        perror("gpiod_line_set_value");
        goto error;
    }

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        perror("open");
        goto error;
    }

    // Set up signal handlers
    signal(SIGINT, [](int sig) {
        if (line_fd >= 0) {
            gpiod_line_set_value(line_fd, 0);
            close(log_fd);
            close(line_fd);
            close(chip_fd);
            gpiod_chip_close(chip_fd);
            return 0;
        }
        return 1;
    });

    signal(SIGTERM, [](int sig) {
        if (line_fd >= 0) {
            gpiod_line_set_value(line_fd, 0);
            close(log_fd);
            close(line_fd);
            close(chip_fd);
            gpiod_chip_close(chip_fd);
            return 0;
        }
        return 1;
    });

    while (1) {
        // Read GPIO17 line
        if (gpiod_line_request_value(line_fd, &ts.tv_sec, &ts.tv_nsec) < 0) {
            perror("gpiod_line_request_value");
            goto error;
        }

        // Check if GPIO17 line is high
        if (ts.tv_sec > 0) {
            // Record timestamp
            strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
            fprintf(log_fd, "%s\n", timestamp);

            // Set GPIO18 line to high
            if (gpiod_line_set_value(line_fd, 1) < 0) {
                perror("gpiod_line_set_value");
                goto error;
            }

            // Sleep for 2 seconds
            usleep(BUZZER_ON_TIME);

            // Set GPIO18 line to low
            if (gpiod_line_set_value(line_fd, 0) < 0) {
                perror("gpiod_line_set_value");
                goto error;
            }
        }
    }

    error:
    if (line_fd >= 0) {
        gpiod_line_set_value(line_fd, 0);
        close(log_fd);
        close(line_fd);
        close(chip_fd);
        gpiod_chip_close(chip_fd);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_LINE 18
#define VALVE_ON 1
#define VALVE_OFF 0

volatile sig_atomic_t sigint_received = 0;
volatile sig_atomic_t sigterm_received = 0;

void handle_sigint(int signum) {
    sigint_received = 1;
}

void handle_sigterm(int signum) {
    sigterm_received = 1;
}

int main() {
    if (access("watering.conf", F_OK) == -1) {
        fprintf(stderr, "Error: watering.conf not found\n");
        return 1;
    }

    FILE *config_file = fopen("watering.conf", "r");
    if (!config_file) {
        fprintf(stderr, "Error: failed to open watering.conf\n");
        return 1;
    }

    char line[256];
    if (fgets(line, sizeof(line), config_file) == NULL) {
        fprintf(stderr, "Error: failed to read watering.conf\n");
        fclose(config_file);
        return 1;
    }

    if (strstr(line, "duration=") == NULL) {
        fprintf(stderr, "Error: invalid format in watering.conf\n");
        fclose(config_file);
        return 1;
    }

    char *end;
    long duration = strtol(strstr(line, "duration=") + strlen("duration="), &end, 10);
    if (duration <= 0 || duration > 3600) {
        fprintf(stderr, "Error: invalid duration in watering.conf\n");
        fclose(config_file);
        return 1;
    }

    if (*end != '\n') {
        fprintf(stderr, "Error: invalid format in watering.conf\n");
        fclose(config_file);
        return 1;
    }

    fclose(config_file);

    int chip_fd = gpiod_chip_open("/dev/gpiod");
    if (chip_fd < 0) {
        fprintf(stderr, "Error: failed to open chip\n");
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_new(chip_fd);
    if (!chip) {
        fprintf(stderr, "Error: failed to create chip\n");
        gpiod_chip_close(chip_fd);
        return 1;
    }

    struct gpiod_line *line_fd = gpiod_chip_request_line(chip, GPIO_LINE);
    if (!line_fd) {
        fprintf(stderr, "Error: failed to request line\n");
        gpiod_chip_close(chip);
        gpiod_chip_close(chip_fd);
        return 1;
    }

    if (gpiod_line_request_mode(line_fd, GPIOD_MODE_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set mode\n");
        gpiod_line_free(line_fd);
        gpiod_chip_close(chip);
        gpiod_chip_close(chip_fd);
        return 1;
    }

    if (gpiod_line_request_value(line_fd, VALVE_OFF) < 0) {
        fprintf(stderr, "Error: failed to set value\n");
        gpiod_line_free(line_fd);
        gpiod_chip_close(chip);
        gpiod_chip_close(chip_fd);
        return 1;
    }

    gpiod_line_request_callback(line_fd, SIGINT, handle_sigint);
    gpiod_line_request_callback(line_fd, SIGTERM, handle_sigterm);

    printf("Watering duration: %ld seconds\n", duration);

    while (!sigint_received && !sigterm_received) {
        usleep(duration * 1000);
        if (gpiod_line_get_value(line_fd) == VALVE_ON) {
            printf("Valve activated\n");
        } else {
            printf("Valve deactivated\n");
        }
    }

    if (sigint_received || sigterm_received) {
        printf("Valve deactivated due to signal\n");
    }

    gpiod_line_free(line_fd);
    gpiod_chip_close(chip);
    gpiod_chip_close(chip_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define LOG_FILE "trace_log.txt"
#define BASE_SPEED 150
#define MAX_SPEED 255
#define LEFT_GPIO 22
#define RIGHT_GPIO 23
#define LEFT_MOTOR 24
#define RIGHT_MOTOR 25
#define IR_GPIO4 4
#define IR_GPIO17 17
#define IR_GPIO27 27

int left_motor_speed = 0;
int right_motor_speed = 0;
int left_sensor = 0;
int right_sensor = 0;
int middle_sensor = 0;

void handle_sigint(int signum) {
    printf("SIGINT received, stopping motors and exiting...\n");
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

int main() {
    struct timespec ts;
    char log_buffer[256];
    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        fprintf(log_file, "%s,%d,%d,%d,%d,%d,%d\n", 
                asctime(localtime(&ts.tv_sec)), 
                left_sensor, right_sensor, middle_sensor, 
                left_motor_speed, right_motor_speed, 0);
        fflush(log_file);

        // Read sensors
        left_sensor = gpioRead(IR_GPIO4);
        right_sensor = gpioRead(IR_GPIO17);
        middle_sensor = gpioRead(IR_GPIO27);

        // Apply control law
        if (middle_sensor == 0) {
            left_motor_speed = BASE_SPEED;
            right_motor_speed = BASE_SPEED;
        } else if (left_sensor == 0 && right_sensor == 1) {
            left_motor_speed = BASE_SPEED / 2;
            right_motor_speed = BASE_SPEED;
        } else if (left_sensor == 1 && right_sensor == 0) {
            left_motor_speed = BASE_SPEED;
            right_motor_speed = BASE_SPEED / 2;
        } else {
            left_motor_speed = 0;
            right_motor_speed = 0;
        }

        // Set motor speeds
        gpioSetPWMCb(LEFT_GPIO, NULL, NULL);
        gpioSetPWMCb(RIGHT_GPIO, NULL, NULL);
        gpioSetPWM(LEFT_GPIO, left_motor_speed);
        gpioSetPWM(RIGHT_GPIO, right_motor_speed);

        // Wait 10 ms
        nanosleep(&ts, &ts);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PULSE_MIN 500
#define PULSE_MAX 2500
#define PULSE_LOCK 1000
#define PULSE_UNLOCK 2000

void handle_sigint(int signum) {
