#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>
#include <signal.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x28
#define I2C_TIMEOUT 100  // ms
#define I2C_RETRIES 3

typedef struct {
    int fd;
    int flow;
} SensorData;

void sigint_handler(int signum) {
    if (SensorData.flow) {
        close(SensorData.fd);
        fflush(stdout);
        fflush(stderr);
        fflush(SensorData.flow);
    }
    exit(0);
}

int main() {
    struct i2c_msg msg[2];
    struct i2c_rdwr_ioctl_data ioctl_data;
    SensorData sensor_data;
    char buffer[3];
    char log_buffer[256];
    int flow;
    int i;
    int ret;

    signal(SIGINT, sigint_handler);

    sensor_data.fd = open(I2C_DEV, O_RDWR);
    if (sensor_data.fd == -1) {
        perror("Failed to open I2C device");
        return 1;
    }

    ret = ioctl(sensor_data.fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("Failed to set slave address");
        goto cleanup;
    }

    for (i = 0; i < I2C_RETRIES; i++) {
        msg[0].addr = I2C_ADDR;
        msg[0].flags = I2C_M_RD;
        msg[0].data[0] = 0x00;
        msg[1].addr = I2C_ADDR;
        msg[1].flags = I2C_M_RD;
        msg[1].data[0] = 0x02;
        msg[1].data[1] = 0x00;

        ret = ioctl(sensor_data.fd, I2C_RDWR, msg, &ioctl_data);
        if (ret < 0) {
            if (errno == EIO) {
                fprintf(stderr, "I2C bus error\n");
            } else if (errno == ENXIO) {
                fprintf(stderr, "Sensor absent\n");
            } else {
                perror("I2C ioctl failed");
            }
            goto cleanup;
        }

        if (read(sensor_data.fd, buffer, 2) < 0) {
            perror("Failed to read I2C data");
            goto cleanup;
        }

        flow = (buffer[0] << 8) | buffer[1];
        flow = (flow - 3277) * 0.1;
        snprintf(log_buffer, sizeof(log_buffer), "%ld, %ld SLPM\n", (long)time(NULL), (long)flow);
        write(sensor_data.flow, log_buffer, strlen(log_buffer));
        usleep(1000000); // 1 second delay
    }

cleanup:
    close(sensor_data.fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <string.h>
#include <time.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_SLAVE 0x3 << 3
#define I2C_ADDR 0x39
#define WHO_AM_I 0x24
#define ENABLE 0x80
#define CFG6 0xAF
#define SP_EN 0x40
#define F1 0x60
#define F2 0x61
#define F3 0x62
#define F4 0x63
#define F5 0x64
#define F6 0x65
#define F7 0x66
#define F8 0x67
#define CLEAR 0x68
#define NIR 0x69

#define LOG_FILE "spectral_log.csv"

void i2c_open(int *fd) {
    *fd = open(I2C_DEV, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }
}

void i2c_set_address(int fd, int addr) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C address");
        exit(EXIT_FAILURE);
    }
}

void i2c_read(int fd, int reg, int *buf, int size) {
    if (read(fd, buf, size) < 0) {
        perror("Failed to read I2C register");
        exit(EXIT_FAILURE);
    }
}

void i2c_write(int fd, int reg, int val) {
    if (write(fd, &val, 1) < 0) {
        perror("Failed to write I2C register");
        exit(EXIT_FAILURE);
    }
}

void i2c_power_on(int fd) {
    int reg = 0;
    i2c_read(fd, ENABLE, &reg, 1);
    reg |= SP_EN;
    i2c_write(fd, ENABLE, reg);
}

void i2c_configure(int fd) {
    int reg = 0;
    i2c_read(fd, CFG6, &reg, 1);
    reg |= 0x01; // Enable F1-F8
    i2c_write(fd, CFG6, reg);
}

int i2c_read_lux(int fd, int *lux) {
    int reg = 0;
    i2c_read(fd, F1, &reg, 1);
    *lux = reg;
    return 0;
}

int main() {
    int fd;
    i2c_open(&fd);
    i2c_set_address(fd, I2C_ADDR);
    i2c_power_on(fd);
    i2c_configure(fd);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    while (1) {
        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);

        int lux[F1 + F2 + F3 + F4 + F5 + F6 + F7 + F8 + CLEAR + NIR];
        for (int i = 0; i < 10; i++) {
            i2c_read_lux(fd, &lux[i]);
        }

        double lux_approx = 0.0;
        for (int i = 0; i < 10; i++) {
            lux_approx += lux[i] * 0.1; // Simplified approximation
        }

        fprintf(log_file, "%s,%f\n", timestamp, lux_approx);

        if (ferror(log_file)) {
            perror("Failed to write to log file");
            exit(EXIT_FAILURE);
        }

        sleep(5);
    }

    fclose(log_file);
    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
