#include <signal.h>
#include <errno.h>
#include <stdint.h>
#include <math.h>

#define I2C_SLAVE   0x3 << 7
#define I2C_RESTART 0x1 << 7
#define I2C_WRITE   0x0 << 7
#define I2C_READ    0x1 << 7
#define I2C_STOP    0x2 << 7

#define I2C_ADDR 0x37
#define I2C_REG 0x28
#define I2C_DATA_SIZE 6
#define I2C_G_CONVERSION 0.000244

#define MAX_RETRIES 3
#define RETRY_DELAY 10

#define SEISMIC_DATA_FILENAME "seismic_data.csv"
#define SEISMIC_ERROR_FILENAME "seismic_error.log"

typedef struct {
    int fd;
    int interval;
    int address;
    char *filename;
} Seismicsensor;

void log_error(const char *message, const char *filename, int line) {
    FILE *error_file = fopen(SEISMIC_ERROR_FILENAME, "a");
    if (!error_file) {
        perror("Failed to open error file");
        exit(EXIT_FAILURE);
    }
    fprintf(error_file, "%s: %s (%d)\n", message, filename, line);
    fclose(error_file);
}

void log_data(double x, double y, double z) {
    FILE *data_file = fopen(SEISMIC_DATA_FILENAME, "a");
    if (!data_file) {
        perror("Failed to open data file");
        exit(EXIT_FAILURE);
    }
    fprintf(data_file, "%ld,%.6f,%.6f,%.6f\n", (long)time(NULL), x, y, z);
    fclose(data_file);
}

void handle_i2c_error(int err) {
    if (err == -EIO) {
        log_error("I2C bus error", __FILE__, __LINE__);
        exit(EXIT_FAILURE);
    }
    if (err == -EBUSY) {
        log_error("I2C bus busy", __FILE__, __LINE__);
        exit(EXIT_FAILURE);
    }
    if (err == -ENODEV) {
        log_error("I2C device not found", __FILE__, __LINE__);
        exit(EXIT_FAILURE);
    }
}

void handle_i2c_write_error(int err) {
    if (err == -EIO) {
        log_error("I2C write error", __FILE__, __LINE__);
        exit(EXIT_FAILURE);
    }
    if (err == -ENODEV) {
        log_error("I2C device not found", __FILE__, __LINE__);
        exit(EXIT_FAILURE);
    }
}

void handle_i2c_read_error(int err) {
    if (err == -EIO) {
        log_error("I2C read error", __FILE__, __LINE__);
        exit(EXIT_FAILURE);
    }
    if (err == -ENODEV) {
        log_error("I2C device not found", __FILE__, __LINE__);
        exit(EXIT_FAILURE);
    }
}

void handle_i2c_open_error(int err) {
    if (err == -EIO) {
        log_error("I2C open error", __FILE__, __LINE__);
        exit(EXIT_FAILURE);
    }
    if (err == -ENODEV) {
        log_error("I2C device not found", __FILE__, __LINE__);
        exit(EXIT_FAILURE);
    }
}

void handle_i2c_close_error(int err) {
    if (err == -EIO) {
        log_error("I2C close error", __FILE__, __LINE__);
        exit(EXIT_FAILURE);
    }
    if (err == -ENODEV) {
        log_error("I2C device not found", __FILE__, __LINE__);
        exit(EXIT_FAILURE);
    }
}

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (seismicsensor.fd > 0) {
            close(seismicsensor.fd);
        }
        if (seismicsensor.filename) {
            fclose(seismicsensor.filename);
        }
        exit(EXIT_SUCCESS);
    }
}

int main(int argc, char *argv[]) {
    Seismicsensor sensor;
    struct iocb iocb;
    struct iovec iovec;
    int i, ret;
    double x, y, z;
    char *filename = SEISMIC_DATA_FILENAME;
    int interval = 1;
    int address = I2C_ADDR;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (argc > 1) {
        if (strcmp(argv[1], "-a") == 0) {
            address = strtoul(argv[2], NULL, 0);
        } else if (strcmp(argv[1], "-i") == 0) {
            interval = atoi(argv[2]);
        } else if (strcmp(argv[1], "-f") == 0) {
            filename = argv[2];
        }
    }

    sensor.fd = open("/dev/i2c-1", O_RDWR);
    if (sensor.fd < 0) {
        handle_i2c_open_error(errno);
    }

    ret = ioctl(sensor.fd, I2C_SLAVE, address);
    if (ret < 0) {
        handle_i2c_open_error(errno);
    }

    iocb.iovlen = I2C_DATA_SIZE;
    iovec.iovlen = I2C_DATA_SIZE;
    iovec.iovbuf = malloc(I2C_DATA_SIZE * sizeof(char));
    iocb.ioctlen = I2C_DATA_SIZE;
    iocb.mapped_io = &iovec;
    iocb.mapped_io_offset = 0;
    iocb.mapped_io_iov = &iocb.iov;

    for (;;) {
        ret = ioctl(sensor.fd, I2C_WRITE | I2C_READ, &iocb);
        if (ret < 0) {
            handle_i2c_write_error(errno);
        }

        for (i = 0; i < MAX_RETRIES; i++) {
            ret = read(sensor.fd, iovec.iovbuf, I2C_DATA_SIZE);
            if (ret == I2C_DATA_SIZE) {
                break;
            } else if (ret < 0) {
                handle_i2c_read_error(errno);
            } else {
                usleep(RETRY_DELAY);
            }
        }

        if (ret == I2C_DATA_SIZE) {
            x = *(double *)(&iovec.iovbuf[0]);
            y = *(double *)(&iovec.iovbuf[2]);
            z = *(double *)(&iovec.iovbuf[4]);

            x *= I2C_G_CONVERSION;
            y *= I2C_G_CONVERSION;
            z *= I2C_G_CONVERSION;

            log_data(x, y, z);
        } else {
            handle_i2c_read_error(errno);
        }

        usleep(interval * 1000000);
    }

    free(iovec.iovbuf);
    close(sensor.fd);
    return 0;
}

