            if (retries < 3) {
                sleep(1);
                retries++;
            } else {
                printf("Sensor not responding after 3 retries, exiting...\n");
                cleanup();
                exit(EXIT_FAILURE);
            }
        } else {
            raw_value = msg[0].data[0] << 8 | msg[0].data[1];
            lux = (float) raw_value / 1.2;
            snprintf(buffer, sizeof(buffer), "%f", lux);

            sock = socket(AF_INET, SOCK_DGRAM, 0);
            if (sock < 0) {
                perror("Failed to create socket");
                cleanup();
                exit(EXIT_FAILURE);
            }

            struct sockaddr_in server;
            server.sin_family = AF_INET;
            server.sin_port = htons(I2C_MULTICAST_PORT);
            inet_pton(AF_INET, I2C_MULTICAST_IP, &server.sin_addr);

            if (sendto(sock, buffer, strlen(buffer), 0, (struct sockaddr *)&server, sizeof(server)) < 0) {
                perror("Failed to send multicast message");
                cleanup();
                exit(EXIT_FAILURE);
            }

            close(sock);
        }
    }

    return 0;
